L14_1.Text_KOREA = "강하지역 안전 확인!\n엄호해 드리겠습니다, 대장님!"
L14_1.Value = 2
L14_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_NA_YUBIN"
L14_1.Text_JPN = "降下地域の安全確認！\n援護します、隊長！"
L14_1.Text_ENG = [[
Landing point secure!
I'll cover you, Commander!]]
L14_1.Text_SCN = "降落地区已安全！\n我来掩护你吧，队长！"
L14_1.Text_TWN = "降落地區已安全！\n我來掩護你吧，隊長！"
L14_1.Text_THA = "เคลียร์พื้นที่จุดจอดแล้ว!\nฉันจะคุ้มกันให้คุณเอง ผู้บัญชาการ!"
L14_1.Text_VTN = "Điểm đổ bộ an toàn!\nTôi sẽ yểm hộ cho Tổng Tư Lệnh!"
L14_1.Text_DEU = [[
Landepunkt gesichert!
Ich gebe dir Deckung, Kommandantin!]]
L14_1.Text_FRA = "Point d'atterrissage sécurisé !\nJe vous couvre, commandante !"
