L16_1.GameEventStrID = "GameEvent_10106_2"
L16_1.ProcessKey = 2
L16_1.EventID = 10106
L16_1.EventType = "MESSAGE_BOX"
L16_1.Text_KOREA = "앗?! 야, 멀대! 새치기하지 마!\n스승님이랑 콤비는 나라고!"
L16_1.Value = 2
L16_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_LEE_SUYEON"
L16_1.Text_JPN = "あっ！？ちょっとヒョロガリ、割り込まないでよ！\n師匠の相棒は私なの！"
L16_1.Text_ENG = "Huh? Hey, Beanstalk! Don't cut in!\nI'm the Master's partner—not you!"
L16_1.Text_SCN = "哎？! 喂，傻大个儿！别插队！\n老师跟我才是一队的！"
L16_1.Text_TWN = "咦？! 喂，傻大個！別插隊！\n師父跟我才是一隊的！"
L16_1.Text_THA = "หืม? นี่ เจ้าถั่วงอก! อย่าขัดจังหวะสิ!\nฉันคือพาร์ทเนอร์ของอาจารย์นะ ไม่ใช่นาย!"
L16_1.Text_VTN = "Hử? Này, Cây Đậu! Đừng xen ngang!\nTôi là bạn tác chiến của Sếp-không phải anh!"
L16_1.Text_DEU = "Hm? Hey, Bohnenstange! Mach mal langsam!\nIch bin die Partnerin der Meisterin – nicht du!"
L16_1.Text_FRA = "Hé, haricot ! Viens pas t'incruster !\nC'est moi, sa partenaire, pas toi !"
