L20_1.EventType = "MESSAGE_BOX"
L20_1.Text_KOREA = "엇 갑자기 침식 코어가?!..."
L20_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_NA_YUBIN"
L20_1.Text_JPN = "あっ､急に侵食コアが……！？"
L20_1.Text_ENG = "The Corruption Core appeared!"
L20_1.Text_SCN = "哎，侵蚀核心怎么？!……"
L20_1.Text_TWN = "咦，侵蝕核心怎麼？!"
L20_1.Text_THA = "แกนคอร์รัปชั่นปรากฏแล้ว!"
L20_1.Text_VTN = "Lõi Mòn đã xuất hiện!"
L20_1.Text_DEU = "Der Verderbniskern ist erschienen!"
L20_1.Text_FRA = "Voilà le noyau de corruption !"
L21_1 = {}
L21_1.GameEventStrID = "GameEvent_10107_3"
L21_1.ProcessKey = 3
L21_1.EventID = 10107
L21_1.EventType = "MESSAGE_BOX"
L21_1.Text_KOREA = "스승님 대단해요!"
L21_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_LEE_SUYEON"
L21_1.Text_JPN = "師匠、すごいですよ！"
L21_1.Text_ENG = "Master, that was amazing!"
L21_1.Text_SCN = "老师，你好厉害！"
L21_1.Text_TWN = "師父，妳好厲害！"
L21_1.Text_THA = "อาจารย์ เมื่อกี้สุดยอดไปเลย!"
L21_1.Text_VTN = "Sếp, thật tuyệt vời!"
L21_1.Text_DEU = "Meisterin, das war fantastisch!"
L21_1.Text_FRA = "Impressionnant, maître !"
L22_1 = {}
L22_1.GameEventStrID = "GameEvent_10107_4"
L22_1.ProcessKey = 4
L22_1.EventID = 10107
L22_1.EventType = "MESSAGE_BOX"
L22_1.Text_KOREA = "… 꾸물거릴 시간 없다. 어서 가자."
L22_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_HILDE_ADMIN"
L22_1.Text_JPN = "……もたもたしてる暇はない。さっさと行くぞ。"
L22_1.Text_ENG = "There is no time to waste. Let's go."
L22_1.Text_SCN = "……没有时间可以浪费了，快走吧。"
L22_1.Text_TWN = "……沒有時間可以浪費了，快走吧。"
L22_1.Text_THA = "ไม่มีเวลาให้โอ้เอ้แล้ว ไปกันเถอะ"
L22_1.Text_VTN = "Không có thì giờ để lãng phí đâu. Đi thôi."
L22_1.Text_DEU = "Wir dürfen keine Zeit verlieren. Los."
L22_1.Text_FRA = "Il n'y a pas de temps à perdre. Allons-y !"
