L24_1 = {}
L24_1.GameEventStrID = "GameEvent_10202_1"
L24_1.ProcessKey = 1
L24_1.EventID = 10202
L24_1.EventType = "MESSAGE_BOX"
L24_1.Text_KOREA = "다수의 침식 쐐기 탓에 병력 진입이 어렵습니다.\n주포로 진격로를 확보해야겠어요."
L24_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_NA_YUBIN"
L24_1.Text_JPN = "多数の侵食楔のせいで、兵力の進入が困難です。\n主砲で進撃路を確保する必要があります。"
L24_1.Text_ENG = [[
Multiple Corrupted Wedges are blocking our entry.
We must use the main cannon to clear the path.]]
L24_1.Text_SCN = "侵蚀钉太多了，战况有点困难。\n要用主炮开辟一条新的道路。"
L24_1.Text_TWN = "侵蝕體太多了，戰況有點棘手。\n要用主炮開闢一條新的道路。"
L24_1.Text_THA = "เวดจ์คอร์รัปต์หลายอันขวางทางเข้าเราอยู่\nเราต้องใช้ปืนใหญ่หลักเพื่อเคลียร์เส้นทาง"
L24_1.Text_VTN = "Nhiều Chốt Mòn đang chặn lối vào của chúng ta.\nChúng ta phải sử dụng đại bác chính để dọn đường."
L24_1.Text_DEU = "Mehrere Verderbniskeile blockieren den Zugang.\nWir müssen den Weg mit der Hauptkanone frei machen."
L24_1.Text_FRA = "Plusieurs bestioles corrompues nous bloquent la route.\nNous pourrions nettoyer le passage à l'aide du canon principal."
