L28_1 = {}
L28_1.GameEventStrID = "GameEvent_10203_2"
L28_1.ProcessKey = 2
L28_1.EventID = 10203
L28_1.EventType = "MESSAGE_BOX"
L28_1.Text_KOREA = "침식 쐐기, 반응 소멸!\n교전 지대로 병력 진입이 가능합니다!"
L28_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_NA_YUBIN"
L28_1.Text_JPN = "侵食楔、反応消滅！\n交戦地帯に兵力の進入が可能になりました！"
L28_1.Text_ENG = [[
Corrupted Wedges obliterated!
Our forces can now enter the combat area!]]
L28_1.Text_SCN = "侵蚀钉无反应！\n可以向交战地区投入更多战斗人员了！"
L28_1.Text_TWN = "侵蝕體無反應！\n可以向交戰地區投入更多戰鬥人員了！"
L28_1.Text_THA = "เวดจ์คอร์รัปต์ถูกทำลายแล้ว!\nกองกำลังของเราเข้าไปในพื้นที่ต่อสู้ได้แล้ว!"
L28_1.Text_VTN = "Chốt Mòn đã bị tiêu diệt!\nGiờ thì các lực lượng của chúng ta có thể vào khu vực chiến đấu!"
L28_1.Text_DEU = "Verderbniskeile zerstört!\nUnsere Streitkräfte können den Kampfbereich jetzt erreichen!"
L28_1.Text_FRA = "Les bestioles corrompues ont été éliminées !\nNos forces peuvent pénétrer dans la zone des combats !"
L29_1 = {}
L29_1.GameEventStrID = "GameEvent_10203_3"
L29_1.ProcessKey = 3
L29_1.EventID = 10203
L29_1.EventType = "MESSAGE_BOX"
L29_1.Text_KOREA = "좋아! 이제부턴 나랑 스승님 차례네!"
L29_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_LEE_SUYEON"
L29_1.Text_JPN = "よし！これからは私と師匠の出番ね！"
L29_1.Text_ENG = "Alright! It's me and my Master's turn!"
L29_1.Text_SCN = "好！轮到老师和我了！"
L29_1.Text_TWN = "好！輪到我和師父了！"
L29_1.Text_THA = "เอาละ! ถึงตาของฉันกับอาจารย์แล้ว!"
L29_1.Text_VTN = "Được rồi! Đã đến lượt của tôi và Sếp!"
L29_1.Text_DEU = "Okay! Meine Meisterin und ich sind jetzt dran!"
L29_1.Text_FRA = "Allez ! À mon tour et celui de mon maître !"
