L33_1 = {}
L33_1.GameEventStrID = "GameEvent_10203_7"
L33_1.ProcessKey = 7
L33_1.EventID = 10203
L33_1.EventType = "MESSAGE_BOX"
L33_1.Text_KOREA = "목표는 얼터 타입 침식 코어다!\n공세 차단에 성공한 부대는 역공에 가세하도록!"
L33_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_HILDE_ADMIN"
L33_1.Text_JPN = "目標はアルタータイプの侵食コアだ！\n防衛に成功した部隊は、逆攻に加われ！"
L33_1.Text_ENG = [[
Our target is the Alter-type Corruption Core!
Any units succeeded in blocking enemy attacks join in the counterattack!]]
L33_1.Text_SCN = "目标是可替代类型的侵蚀核心！\n聚集部队，一起反攻！"
L33_1.Text_TWN = "目標是可替代類型的侵蝕核心！\n集結活下來的部隊，一起反攻！"
L33_1.Text_THA = "เป้าหมายของเราคือแกนคอร์รัปชั่นประเภทอัลเทอร์!\nหน่วยรบที่สกัดการโจมตีของศัตรูได้จะร่วมโจมตีสวนกลับ!"
L33_1.Text_VTN = "Mục tiêu của chúng ta là Lõi Mòn loại Thay Thế!\nBất kỳ đơn vị nào chặn đứng thành công các đòn tấn công của kẻ thù sẽ tham gia phản công!"
L33_1.Text_DEU = "Unser Ziel ist der Alternativ-Typus-Verderbniskern!\nAlle Einheiten, die gegnerische Angriffe aufhalten konnten, schließen sich dem Gegenangriff an!"
L33_1.Text_FRA = "Notre cible est le noyau de corruption de type alter !\nQue toutes les unités qui ont pu résister aux assauts ennemis participent à la contre-attaque !"
