L36_1.EventType = "MESSAGE_BOX"
L36_1.Text_KOREA = "전대장님! 여기는 저희에게 맡겨 주십시오!\n반드시 코어를 파괴하겠습니다!"
L36_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_S_ADMIN_SHIELD"
L36_1.Text_JPN = "戦隊長！ここは私たちにお任せください！\n必ずコアを破壊します！"
L36_1.Text_ENG = [[
Commander! Leave this place to us.
We'll destroy the Core!]]
L36_1.Text_SCN = "队长！这里就交给我们吧！\n我们一定会摧毁核心的！"
L36_1.Text_TWN = "隊長！這裡就交給我們吧！\n我們一定會摧毀核心的！"
L36_1.Text_THA = "ผู้บัญชาการ! ที่นี่เราจัดการเอง\nเราจะทำลายแกนให้ได้!"
L36_1.Text_VTN = "Tổng Tư Lệnh! Hãy để chỗ này cho chúng tôi.\nChúng tôi sẽ phá hủy Lõi!"
L36_1.Text_DEU = "Kommandantin! Überlass das uns.\nWir werden den Kern zerstören!"
L36_1.Text_FRA = "Commandante ! On peut s'en charger !\nLaissez-nous détruire le noyau !"
