L44_1.Text_KOREA = L45_1
L44_1.Value = 3
L44_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_HILDE_ADMIN"
L45_1 = "歩兵戦力だけで侵食コアを破壊することは難しい。急ごう！"
L44_1.Text_JPN = L45_1
L45_1 = "Infantry units can't destroy the Core alone. Let's hurry!"
