L10_1 = "GameEvent_10312_2"
L9_1.GameEventStrID = L10_1
L9_1.ProcessKey = 2
L10_1 = 10312
L9_1.EventID = L10_1
L9_1.EventType = "MESSAGE_BOX"
L10_1 = "좋아… 먼저 갑니다! 미아 되지 않게 잘 따라와, 멀대!"
L9_1.Text_KOREA = L10_1
L9_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_LEE_SUYEON"
L10_1 = "よし……お先！迷子にならないようにちゃんとついて来て、ヒョロガリ！"
L9_1.Text_JPN = L10_1
L10_1 = "Alright, I'm going first! Stay close, Beanstalk, so you won't get lost!"
L9_1.Text_ENG = L10_1
L10_1 = "好……我先去了！跟紧一点，别把自己弄丢了，傻大个儿！"
L9_1.Text_SCN = L10_1
L10_1 = "好…先去了！跟緊一點，別把自己弄丟了，傻大個兒！"
L9_1.Text_TWN = L10_1
L10_1 = "เอาละ ฉันไปก่อน! อยู่ใกล้ๆ ฉันไว้นะ เจ้าถั่วงอก จะได้ไม่หลงทาง!"
L9_1.Text_THA = L10_1
L10_1 = "Được rồi, tôi đi trước! Theo sát tôi, Cây Đậu, nếu không sẽ bị lạc đấy!"
L9_1.Text_VTN = L10_1
L10_1 = "Okay, ich gehe vor! Bleib bei mir, Bohnenstange, damit du nicht verloren gehst!"
L9_1.Text_DEU = L10_1
L10_1 = "OK, j'y vais ! Suis-moi de près si tu veux pas te perdre, haricot !"
L9_1.Text_FRA = L10_1
L10_1 = {}
L11_1 = "GameEvent_10312_3"
L10_1.GameEventStrID = L11_1
L10_1.ProcessKey = 3
L11_1 = 10312
L10_1.EventID = L11_1
L10_1.EventType = "MESSAGE_BOX"
L11_1 = "수연아! 혼자 너무 앞으로 가지 말라니까!"
L10_1.Text_KOREA = L11_1
L10_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_NA_YUBIN"
L11_1 = "キズナ！一人でそんなに突っ走らないで！"
L10_1.Text_JPN = L11_1
L11_1 = "Sooyeon! I told you not to start off alone!"
L10_1.Text_ENG = L11_1
L11_1 = "秀妍！不要自己一个人那么靠前！"
L10_1.Text_SCN = L11_1
L11_1 = "秀妍！不要自己一個人那麼靠前！"
L10_1.Text_TWN = L11_1
L11_1 = "ซูยอน! บอกแล้วไงว่าอย่าเริ่มคนเดียว!"
L10_1.Text_THA = L11_1
L11_1 = "Sooyeon! Tôi đã nói là cô không được bắt đầu một mình!"
L10_1.Text_VTN = L11_1
L11_1 = "Sooyeon! Du solltest doch nicht alleine anfangen!"
L10_1.Text_DEU = L11_1
L11_1 = "Sooyeon ! Je t'ai déjà dit d'attendre !"
L10_1.Text_FRA = L11_1
L11_1 = {}
L12_1 = "GameEvent_10312_4"
L11_1.GameEventStrID = L12_1
L11_1.ProcessKey = 4
L12_1 = 10312
L11_1.EventID = L12_1
L11_1.EventType = "MESSAGE_BOX"
L12_1 = "나도 가겠다. \n뒤쳐지지 말고 따라오도록."
L11_1.Text_KOREA = L12_1
L11_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_HILDE_ADMIN"
L12_1 = "私も行く。\nちゃんとついて来るんだ。"
L11_1.Text_JPN = L12_1
L12_1 = [[
I'm on my way, too. 
Don't fall behind.]]
L11_1.Text_ENG = L12_1
L12_1 = "我也过去了。\n不要掉队，跟紧点。"
L11_1.Text_SCN = L12_1
L12_1 = "我也過去了。\n不要掉隊，跟緊點。"
L11_1.Text_TWN = L12_1
L12_1 = "ฉันก็กำลังไปเหมือนกัน\nตามให้ทันล่ะ"
L11_1.Text_THA = L12_1
L12_1 = "Tôi cũng đang trên đường đây.\nĐừng để rớt lại phía sau."
L11_1.Text_VTN = L12_1
L12_1 = "Ich bin auch unterwegs.\nBleib nicht zurück."
L11_1.Text_DEU = L12_1
L12_1 = [[
J'arrive aussi.
Gardez le rythme.]]
L11_1.Text_FRA = L12_1
