L25_1.EventID = L26_1
L25_1.EventType = "MESSAGE_BOX"
L26_1 = "공간이 일그러지고 있어…!\n큰게 옵니다, 다들 조심하세요!"
L25_1.Text_KOREA = L26_1
L25_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_NA_YUBIN"
L26_1 = "空間が歪んでいる……！\n大きな何かが来ます。みなさん、気をつけてください！"
L25_1.Text_JPN = L26_1
L26_1 = [[
Space is warping!
Something big is coming. Watch out!]]
L25_1.Text_ENG = L26_1
L26_1 = "空间被扭曲了……!\n大家伙来了，都小心点！"
L25_1.Text_SCN = L26_1
L26_1 = "空間被扭曲了…!\n大傢伙來了，小心點！"
L25_1.Text_TWN = L26_1
L26_1 = "มิติกำลังบิดเบี้ยว!\nบางสิ่งที่มีขนาดใหญ่กำลังมา ระวังด้วย!"
L25_1.Text_THA = L26_1
L26_1 = "Không gian đang bị bóp méo!\nCó thứ gì đó to lớn tiến ra. Hãy coi chừng!"
L25_1.Text_VTN = L26_1
L26_1 = "Der Raum verformt sich!\nDa kommt was Großes. Achtung!"
L25_1.Text_DEU = L26_1
L26_1 = "Attention ! L'espace se déforme !\nÇa annonce quelque chose de massif."
L25_1.Text_FRA = L26_1
