L32_1 = "Is it dead?!"
L31_1.Text_ENG = L32_1
L32_1 = "干掉了吗？!……"
L31_1.Text_SCN = L32_1
L32_1 = "幹掉了嗎？!"
L31_1.Text_TWN = L32_1
L32_1 = "มันตายรึยัง?!"
L31_1.Text_THA = L32_1
L32_1 = "Nó chết chưa?!"
L31_1.Text_VTN = L32_1
L32_1 = "Ist es tot?!"
L31_1.Text_DEU = L32_1
L32_1 = "C'est bon ? Il est mort ?"
L31_1.Text_FRA = L32_1
L32_1 = {}
L33_1 = "GameEvent_10307_4"
L32_1.GameEventStrID = L33_1
L32_1.ProcessKey = 4
L33_1 = 10307
L32_1.EventID = L33_1
L32_1.EventType = "MESSAGE_BOX"
L33_1 = "잠깐! 10시 방향에서 이상침식파 다수 접근 중!\n전원 전투 태세로!"
L32_1.Text_KOREA = L33_1
L32_1.Value = 2
L32_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_S_ADMIN_SHIELD"
L33_1 = "待て！10時方向に異常侵食波が多数接近中！\n全員、戦闘態勢をとれ！"
L32_1.Text_JPN = L33_1
L33_1 = [[
Wait! Multiple Corruption Rays incoming at 10 o'clock!
Everyone, get ready to fight!]]
L32_1.Text_ENG = L33_1
L33_1 = "等等！10点钟方向有异常侵蚀波接近中！\n所有人员，准备战斗！"
L32_1.Text_SCN = L33_1
L33_1 = "等等！10點鐘方向有異常侵蝕波接近中！\n所有人員，準備戰鬥！"
L32_1.Text_TWN = L33_1
L33_1 = "เดี๋ยว! รังสีคอร์รัปชั่นจำนวนมากกำลังพุ่งมาทางทิศ 10 นาฬิกา!\nทุกคนเตรียมต่อสู้!"
L32_1.Text_THA = L33_1
L33_1 = "Khoan! Có nhiều Tia Ăn Mòn đang đến từ góc 10 giờ!\nMọi người, sẵn sàng chiến đấu!"
L32_1.Text_VTN = L33_1
L33_1 = "Moment! Mehrere Verderbniswellen auf 10 Uhr!\nAlle kampfbereit machen!"
L32_1.Text_DEU = L33_1
L33_1 = "Plusieurs rayons de corruption en approche à dix heures !\nPréparez-vous au combat !"
L32_1.Text_FRA = L33_1
L33_1 = {}
