L39_1.Text_JPN = L40_1
L40_1 = "Deploying units requires <color=#ffd34c>Deployment Resources</color>."
L39_1.Text_ENG = L40_1
L40_1 = "要想让单位出击，需要 <color=#ffd34c>出击资源</color>。"
L39_1.Text_SCN = L40_1
L40_1 = "想要出擊單位，就需要足夠的 <color=#ffd34c>出擊資源</color>。"
L39_1.Text_TWN = L40_1
L40_1 = "การวางทัพหน่วยรบต้องใช้<color=#ffd34c>คะแนนวางทัพ</color>"
L39_1.Text_THA = L40_1
L40_1 = "Để triển khai đơn vị bắt buộc phải có <color=#ffd34c>Tài Nguyên Triển Khai</color>."
L39_1.Text_VTN = L40_1
L40_1 = "Der Einsatz von Einheiten erfordert <color=#ffd34c>Einsatzressourcen</color>."
L39_1.Text_DEU = L40_1
L40_1 = "Déployer des unités nécessite des <color=#ffd34c>ressources de déploiement</color>."
L39_1.Text_FRA = L40_1
