L47_1 = "GameEvent_10402_3"
L46_1.GameEventStrID = L47_1
L46_1.ProcessKey = 3
L47_1 = 10402
L46_1.EventID = L47_1
L46_1.EventType = "MESSAGE_BOX"
L47_1 = "좋아, 바로 따라갈게.\n내 몫도 남겨두라고."
L46_1.Text_KOREA = L47_1
L47_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L46_1.StringValue = L47_1
L47_1 = "よし、今すぐ行く。\n私の分も残しておいてね。"
L46_1.Text_JPN = L47_1
L47_1 = [[
Alright, I'll be right behind you.
Don't finish without me.]]
L46_1.Text_ENG = L47_1
L47_1 = "好，马上跟上。\n也给我留点活。"
L46_1.Text_SCN = L47_1
L47_1 = "好，馬上跟上。\n也給我留一點。"
L46_1.Text_TWN = L47_1
L47_1 = "เอาละ ฉันจะตามไปติดๆ เลย\nอย่าทำให้เสร็จโดยไม่มีฉันนะ"
L46_1.Text_THA = L47_1
L47_1 = "Được rồi, tôi bám sát theo ngay sau đây.\nChừa phần cho tôi với nhé."
L46_1.Text_VTN = L47_1
L47_1 = [[
Okay, ich bin direkt hinter dir.
Beende es nicht ohne mich.]]
L46_1.Text_DEU = L47_1
L47_1 = "Entendu, commandante.\nAttendez-moi pour la petite fête."
L46_1.Text_FRA = L47_1
