L48_1.EventID = L49_1
L48_1.EventType = "HIGHLIGHT_UI"
L49_1 = "<color=#ffd34c>적 보스</color>를 처치하면 전투에서 승리합니다."
L48_1.Text_KOREA = L49_1
L49_1 = "NKM_UI_HUD_MAIN_GAGE_RED"
L48_1.StringValue = L49_1
L49_1 = "<color=#ffd34c>敵のボス</color>を倒すと戦闘に勝利します。"
L48_1.Text_JPN = L49_1
L49_1 = "Defeat the <color=#ffd34c>enemy Boss</color> to win the battle."
L48_1.Text_ENG = L49_1
L49_1 = "击杀<color=#ffd34c>敌方BOSS</color>即可获得战斗胜利。"
L48_1.Text_SCN = L49_1
L49_1 = "消滅<color=#ffd34c>敵人BOSS</color>後便獲得勝利。"
L48_1.Text_TWN = L49_1
L49_1 = "ปราบ<color=#ffd34c>บอสศัตรู</color>เพื่อชนะการต่อสู้"
L48_1.Text_THA = L49_1
L49_1 = "Hãy đánh bại <color=#ffd34c>Boss kẻ thù</color> để thắng trận chiến."
L48_1.Text_VTN = L49_1
L49_1 = "Besiege den <color=#ffd34c>gegnerischen Boss</color>, um die Schlacht zu gewinnen."
L48_1.Text_DEU = L49_1
L49_1 = "Éliminez le <color=#ffd34c>boss ennemi</color> pour remporter la victoire."
