L4_1.EventID = L5_1
L4_1.EventType = "MESSAGE_BOX"
L5_1 = "저걸 처치하면 되는거지?"
L4_1.Text_KOREA = L5_1
L4_1.Value = 1
L5_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L4_1.StringValue = L5_1
L5_1 = "あれを倒せばいいんだよね？"
L4_1.Text_JPN = L5_1
L5_1 = "You want me to take care of that, right?"
L4_1.Text_ENG = L5_1
L5_1 = "消灭那个就可以了吧？"
L4_1.Text_SCN = L5_1
L5_1 = "消滅那個就可以了吧？"
L4_1.Text_TWN = L5_1
L5_1 = "อยากให้ฉันเป็นคนจัดการใช่มั้ย?"
L4_1.Text_THA = L5_1
L5_1 = "Muốn tôi xử lý tên đó đúng không?"
L4_1.Text_VTN = L5_1
L5_1 = "Ich soll mich darum kümmern, ja?"
L4_1.Text_DEU = L5_1
L5_1 = "Vous voulez que je m'en charge, c'est ça ?"
L4_1.Text_FRA = L5_1
