L6_1 = "GameEvent_10403_3"
L5_1.GameEventStrID = L6_1
L5_1.ProcessKey = 3
L6_1 = 10403
L5_1.EventID = L6_1
L5_1.EventType = "MESSAGE_BOX"
L6_1 = "좋아 <color=#ffd34c>타겟</color>을 파괴한다, 화력을 집중해라."
L5_1.Text_KOREA = L6_1
L5_1.Value = 1
L6_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L5_1.StringValue = L6_1
L6_1 = "よし。<color=#ffd34c>ターゲット</color>を破壊する。火力を集中させろ。"
L5_1.Text_JPN = L6_1
L6_1 = "Alright, let's destroy the <color=#ffd34c>target</color>. Concentrate your fire."
L5_1.Text_ENG = L6_1
L6_1 = "很好，破坏 <color=#ffd34c>目标</color>，集中火力。"
L5_1.Text_SCN = L6_1
L6_1 = "沒錯，破壞 <color=#ffd34c>目標</color>，集中火力。"
L5_1.Text_TWN = L6_1
L6_1 = "เอาละ มาทำลาย<color=#ffd34c>เป้าหมาย</color>กัน ควบคุมการโจมตีให้ดี"
L5_1.Text_THA = L6_1
L6_1 = "Được rồi, hãy tiêu diệt <color=#ffd34c>mục tiêu</color>. Tập trung hỏa lực."
L5_1.Text_VTN = L6_1
L6_1 = "Okay, wir zerstören das <color=#ffd34c>Ziel</color>. Konzentriert euer Feuer."
L5_1.Text_DEU = L6_1
L6_1 = "Il est temps de détruire la <color=#ffd34c>cible</color>. Concentrez vos tirs."
L5_1.Text_FRA = L6_1
