L9_1 = "중앙에 <color=#ffd34c>디펜더</color> 타입의 침식체가 등장했다."
L8_1.Text_KOREA = L9_1
L9_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L8_1.StringValue = L9_1
L9_1 = "中央に<color=#ffd34c>ディフェンダー</color>クラスの侵食体が登場した。"
L8_1.Text_JPN = L9_1
L9_1 = "A <color=#ffd34c>Defender</color>-type C.O. has appeared in the center."
