L9_1 = "战场中央出现 <color=#ffd34c>护卫</color> 型侵蚀体"
L8_1.Text_SCN = L9_1
L9_1 = "戰場中央出現 <color=#ffd34c>護衛</color> 型侵蝕體"
L8_1.Text_TWN = L9_1
L9_1 = "วัตถุคอร์รัปต์ประเภท<color=#ffd34c>ตั้งรับ</color>ปรากฏตัวอยู่ตรงกลาง"
L8_1.Text_THA = L9_1
L9_1 = "<color=#ffd34c></color>Vật Thể Bị Ăn Mòn loại Lính Phòng Vệ đã xuất hiện ở trung tâm."
L8_1.Text_VTN = L9_1
