L9_1.EventID = L10_1
L9_1.EventType = "MESSAGE_BOX"
L10_1 = "여기는 <color=#ffd34c>레인저</color> 대원들에게 맡기지."
L9_1.Text_KOREA = L10_1
L10_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L9_1.StringValue = L10_1
L10_1 = "ここは<color=#ffd34c>レンジャー</color>隊員たちに任せる。"
L9_1.Text_JPN = L10_1
L10_1 = "Let's leave this place to the <color=#ffd34c>Rangers</color>."
