L10_1 = "这儿就交给 <color=#ffd34c>突击队员</color> 们吧。"
L9_1.Text_SCN = L10_1
L10_1 = "這裡就交給 <color=#ffd34c>突擊隊員</color> 們吧。"
L9_1.Text_TWN = L10_1
L10_1 = "เราปล่อยให้<color=#ffd34c>พลยิงจู่โจม</color>จัดการที่นี่เถอะ"
L9_1.Text_THA = L10_1
L10_1 = "Hãy để chỗ này cho <color=#ffd34c>Lính Cơ Động</color>."
L9_1.Text_VTN = L10_1
L10_1 = "Überlassen wir diesen Ort den <color=#ffd34c>Rangern</color>."
