L12_1 = 10501
L11_1.EventID = L12_1
L12_1 = "TEXT"
L11_1.EventType = L12_1
L12_1 = "모든 유닛은 하나의 <color=#ffd34c>클래스</color>를 가집니다."
L11_1.Text_KOREA = L12_1
L12_1 = "すべてのユニットは一つの<color=#ffd34c>クラス</color>を持ちます。"
L11_1.Text_JPN = L12_1
L12_1 = "Each unit has a <color=#ffd34c>role</color>."
L11_1.Text_ENG = L12_1
L12_1 = "所有单位都拥有自己的 <color=#ffd34c>类型</color>。"
L11_1.Text_SCN = L12_1
L12_1 = "所有單位都擁有自己的 <color=#ffd34c>職階</color>。"
L11_1.Text_TWN = L12_1
L12_1 = "แต่ละหน่วยรบมี<color=#ffd34c>คลาส</color>ของตัวเอง"
L11_1.Text_THA = L12_1
L12_1 = "Mỗi đơn vị đều có <color=#ffd34c>vai trò</color>."
L11_1.Text_VTN = L12_1
L12_1 = "Jede Einheit hat eine <color=#ffd34c>Rolle</color>."
L11_1.Text_DEU = L12_1
L12_1 = "Chaque unité a une <color=#ffd34c>classe</color>."
L11_1.Text_FRA = L12_1
