L14_1 = "GameEvent_10501_8"
L13_1.GameEventStrID = L14_1
L13_1.ProcessKey = 8
L14_1 = 10501
L13_1.EventID = L14_1
L13_1.EventType = "MESSAGE_BOX"
L14_1 = "<color=#ffd34c>디펜더</color>는 <color=#ffd34c>레인저</color>로 상대하란 말이지, 좋아. 나에게 맡겨!"
L13_1.Text_KOREA = L14_1
L14_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L13_1.StringValue = L14_1
L14_1 = "<color=#ffd34c>ディフェンダー</color>は<color=#ffd34c>レンジャー</color>で相手するのね。よし、私に任せて！"
L13_1.Text_JPN = L14_1
L14_1 = "So, us <color=#ffd34c>Rangers</color> are effective against <color=#ffd34c>Defenders</color>, right? Leave it to me!"
L13_1.Text_ENG = L14_1
L14_1 = "就是说，要用<color=#ffd34c>突击队员</color>去应对 <color=#ffd34c>护卫</color>对吧，好。交给我吧！"
L13_1.Text_SCN = L14_1
L14_1 = "也就是說，要用<color=#ffd34c>突擊隊員</color>對付<color=#ffd34c>護衛</color>對吧？好。交給我！"
L13_1.Text_TWN = L14_1
L14_1 = "<color=#ffd34c>พลยิงจู่โจม</color>อย่างเราจะมีประสิทธิภาพเมื่อต่อสู้กับ<color=#ffd34c>พลตั้งรับ</color>ใช่มั้ยล่ะ? ให้ฉันจัดการเอง!"
L13_1.Text_THA = L14_1
L14_1 = "Do đó, <color=#ffd34c>Lính Cơ Động</color> chúng tôi rất hiệu quả trước <color=#ffd34c>Lính Phòng Vệ</color>, đúng không? Cứ để cho tôi!"
L13_1.Text_VTN = L14_1
L14_1 = "Wir, die <color=#ffd34c>Ranger</color>, sind effektiv gegen <color=#ffd34c>Verteidiger</color>, richtig? Überlass das mir!"
L13_1.Text_DEU = L14_1
L14_1 = "Si je comprends bien, les <color=#ffd34c>rangers</color> comme moi sont plus efficaces contre les <color=#ffd34c>défenseurs</color> ? Je m'en occupe, alors !"
L13_1.Text_FRA = L14_1
