L14_1.EventType = "TUTORIAL_UNIT_SUMMON_GUIDE"
L15_1 = "<color=#ffd34c>레인저</color> 클래스인 유미나를 출격시키세요."
L14_1.Text_KOREA = L15_1
L15_1 = 325
L14_1.Value = L15_1
L15_1 = "<color=#ffd34c>レンジャー</color>クラスであるヤナギ・ミナを出撃させてください。"
