L15_1.EventID = L16_1
L15_1.EventType = "TUTORIAL_UNIT_SKILL_GUIDE"
L16_1 = "유닛 머리 위에 HP와 <color=#ffd34c>스킬 게이지</color>가 표시됩니다."
L15_1.Text_KOREA = L16_1
L16_1 = 325
L15_1.Value = L16_1
L16_1 = "ユニットの頭上にHPと<color=#ffd34c>スキルゲージが</color>表示されます。"
L15_1.Text_JPN = L16_1
L16_1 = "Units display HP and <color=#ffd34c>Skill Gauges</color> above their heads."
L15_1.Text_ENG = L16_1
L16_1 = "战斗人员的上方会显示体力和 <color=#ffd34c>技能蓄力</color>状态。"
L15_1.Text_SCN = L16_1
L16_1 = "戰鬥單位的上方會顯示HP和 <color=#ffd34c>技能蓄力</color>狀態。"
L15_1.Text_TWN = L16_1
L16_1 = "หน่วยรบจะแสดงพลังชีวิตและ<color=#ffd34c>มาตรวัดสกิล</color>อยู่เหนือศีรษะ"
L15_1.Text_THA = L16_1
L16_1 = "HP và <color=#ffd34c>Thanh Kỹ Năng</color> của đơn vị được hiển thị trên đầu của họ."
L15_1.Text_VTN = L16_1
L16_1 = "Über den Köpfen der Einheiten werden LP- und <color=#ffd34c>Fähigkeitsleisten</color> angezeigt."
L15_1.Text_DEU = L16_1
L16_1 = "Les <color=#ffd34c>barres de compétence</color> et de PV des unités sont affichées au-dessus d'elles."
L15_1.Text_FRA = L16_1
