L22_1 = "GameEvent_10506_3"
L21_1.GameEventStrID = L22_1
L21_1.ProcessKey = 3
L22_1 = 10506
L21_1.EventID = L22_1
L21_1.EventType = "MESSAGE_BOX"
L22_1 = "적이 <color=#ffd34c>특수기</color>를 준비하고 있다, 조심해!"
L21_1.Text_KOREA = L22_1
L22_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L21_1.StringValue = L22_1
L22_1 = "敵が<color=#ffd34c>特殊スキル</color>を準備している、気をつけろ！"
L21_1.Text_JPN = L22_1
L22_1 = "The enemy's preparing a <color=#ffd34c>Special Skill</color>. Watch out!"
L21_1.Text_ENG = L22_1
L22_1 = "敌人正在准备释放 <color=#ffd34c>特殊技能</color>，小心！"
L21_1.Text_SCN = L22_1
L22_1 = "敵人正在釋放 <color=#ffd34c>特殊技能</color>，小心！"
L21_1.Text_TWN = L22_1
L22_1 = "ศัตรูกำลังเตรีนม<color=#ffd34c>สกิลพิเศษ</color> ระวังตัวด้วย!"
L21_1.Text_THA = L22_1
L22_1 = "Quân địch đang chuẩn bị <color=#ffd34c>Kỹ Năng Đặc Biệt</color>. Hãy coi chừng!"
L21_1.Text_VTN = L22_1
L22_1 = "Der Gegner bereitet eine <color=#ffd34c>Spezialfähigkeit</color> vor. Achtung!"
L21_1.Text_DEU = L22_1
L22_1 = "Attention ! L'ennemi prépare une <color=#ffd34c>compétence spéciale</color>."
L21_1.Text_FRA = L22_1
