L24_1 = "GameEvent_10506_5"
L23_1.GameEventStrID = L24_1
L23_1.ProcessKey = 5
L24_1 = 10506
L23_1.EventID = L24_1
L24_1 = "TEXT"
L23_1.EventType = L24_1
L24_1 = "일부 유닛은 <color=#ffd34c>반격</color>과 같은 특수기를 갖고 있습니다"
L23_1.Text_KOREA = L24_1
L24_1 = "一部ユニットは<color=#ffd34c>反撃</color>のような特殊スキルを持っています。"
L23_1.Text_JPN = L24_1
L24_1 = "Certain units have Special Skills like <color=#ffd34c>Counterattack</color>."
L23_1.Text_ENG = L24_1
L24_1 = "一些单位拥有类似<color=#ffd34c>反击</color>的特殊技能。"
L23_1.Text_SCN = L24_1
L24_1 = "一些單位擁有類似<color=#ffd34c>反擊</color>的特殊技能"
L23_1.Text_TWN = L24_1
L24_1 = "บางหน่วยรบมีสกิลพิเศษเช่น<color=#ffd34c>โจมตีสวนกลับ</color>"
L23_1.Text_THA = L24_1
L24_1 = "Một số đơn vị nhất định sẽ có Kỹ Năng Đặc Biệt như <color=#ffd34c>Phản Công</color>."
L23_1.Text_VTN = L24_1
L24_1 = "Bestimmte Einheiten haben Spezialfähigkeiten wie den <color=#ffd34c>Gegenangriff</color>."
L23_1.Text_DEU = L24_1
L24_1 = "Certaines unités disposent de compétences spéciales telles que <color=#ffd34c>Contre-attaque</color>."
L23_1.Text_FRA = L24_1
L24_1 = {}
L25_1 = "GameEvent_10506_6"
L24_1.GameEventStrID = L25_1
L24_1.ProcessKey = 6
L25_1 = 10506
L24_1.EventID = L25_1
L24_1.EventType = "TUTORIAL_UNIT_SUMMON_GUIDE"
L25_1 = "<color=#ffd34c>주시윤</color>을 출격시켜 적의 특수기를 반격하세요."
L24_1.Text_KOREA = L25_1
L25_1 = 326
L24_1.Value = L25_1
L25_1 = "<color=#ffd34c>アキヤマ・シリュウ</color>を出撃させ、敵の特殊スキルに反撃してください。"
L24_1.Text_JPN = L25_1
L25_1 = "Deploy <color=#ffd34c>Joo Shiyoon</color> to counter the enemy's Special skill."
L24_1.Text_ENG = L25_1
L25_1 = "请使用<color=#ffd34c>周时云</color>出击，反击敌人的特殊技能。"
L24_1.Text_SCN = L25_1
L25_1 = "出擊<color=#ffd34c>周時雲</color>來反擊敵人的特殊技。"
L24_1.Text_TWN = L25_1
L25_1 = "วางทัพ<color=#ffd34c>จู ชิยุน</color>เพื่อตอบโต้สกิลพิเศษของศัตรู"
L24_1.Text_THA = L25_1
L25_1 = "Triển khai <color=#ffd34c>Joo Shiyoon</color> để chống lại kỹ năng Đặc Biệt của kẻ thù."
L24_1.Text_VTN = L25_1
L25_1 = "Setze <color=#ffd34c>Joo Shiyoon</color> ein, um die Spezialfähigkeit des Gegners zu kontern."
L24_1.Text_DEU = L25_1
L25_1 = "Déployez <color=#ffd34c>Charles Joo</color> pour contrer la compétence spéciale de l'ennemi."
