L26_1.EventID = L27_1
L26_1.EventType = "MESSAGE_BOX"
L27_1 = "어이쿠~ 큰일 날 뻔 했네요."
L26_1.Text_KOREA = L27_1
L27_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L26_1.StringValue = L27_1
L27_1 = "おっと、危ないところでしたね。"
L26_1.Text_JPN = L27_1
L27_1 = "Oopsie, that was close."
L26_1.Text_ENG = L27_1
L27_1 = "哎呦~差点出大事儿了。"
L26_1.Text_SCN = L27_1
L27_1 = "唉哟~差點出大事了。"
L26_1.Text_TWN = L27_1
L27_1 = "โอ๊ะ เกือบไปแล้ว"
L26_1.Text_THA = L27_1
L27_1 = "Ối chà chà, suýt nữa thì."
L26_1.Text_VTN = L27_1
L27_1 = "Ups, das war knapp."
L26_1.Text_DEU = L27_1
L27_1 = "Oups… C'est pas passé loin."
