L28_1 = "GameEvent_10507_3"
L27_1.GameEventStrID = L28_1
L27_1.ProcessKey = 3
L28_1 = 10507
L27_1.EventID = L28_1
L27_1.EventType = "MESSAGE_BOX"
L28_1 = "자, 나온 김에 한방 더!..."
L27_1.Text_KOREA = L28_1
L28_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L27_1.StringValue = L28_1
L28_1 = "さあ、せっかくだからもう一発……！"
L27_1.Text_JPN = L28_1
L28_1 = "While I'm at it, I'll give it another blow!"
L27_1.Text_ENG = L28_1
L28_1 = "好，既然都出场了，那就再来一发！……"
L27_1.Text_SCN = L28_1
L28_1 = "好，既然都出場了，那就再來一發!"
L27_1.Text_TWN = L28_1
L28_1 = "ไหนๆ ฉันก็ลุยแล้ว ฉันจะอัดมันอีกครั้งแล้วกัน!"
L27_1.Text_THA = L28_1
L28_1 = "Được đà hãy tiến tới, tôi sẽ cho nó một phát nữa!"
L27_1.Text_VTN = L28_1
L28_1 = "Wenn ich schon dabei bin, greif ich noch mal an!"
L27_1.Text_DEU = L28_1
L28_1 = "Je vais en profiter pour frapper de nouveau !"
L27_1.Text_FRA = L28_1
