L32_1.EventID = L33_1
L33_1 = "TUTORIAL_CLICK_UNIT_HYPER"
L32_1.EventType = L33_1
L33_1 = "<color=#ffd34c>궁극기 아이콘</color>을 터치하여, 명령을 내리십시오."
L32_1.Text_KOREA = L33_1
L33_1 = 326
L32_1.Value = L33_1
L33_1 = "<color=#ffd34c>究極スキルアイコン</color>をタップし、命令を下してください。"
L32_1.Text_JPN = L33_1
L33_1 = "Tap the <color=#ffd34c>Ultimate Skill icon</color> to use it."
L32_1.Text_ENG = L33_1
L33_1 = "请点击<color=#ffd34c>奥义按钮</color>，发动奥义。"
L32_1.Text_SCN = L33_1
