L45_1 = {}
L46_1 = "GameEvent_10602_2"
L45_1.GameEventStrID = L46_1
L45_1.ProcessKey = 2
L46_1 = 10602
L45_1.EventID = L46_1
L45_1.EventType = "MESSAGE_BOX"
L46_1 = "이야~ 깔끔해 졌는걸요."
L45_1.Text_KOREA = L46_1
L46_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L45_1.StringValue = L46_1
L46_1 = "おお～キレイになりましたね。"
L45_1.Text_JPN = L46_1
L46_1 = "Whoop, it's all clear now."
L45_1.Text_ENG = L46_1
L46_1 = "咿呀~变得好干净啊。"
L45_1.Text_SCN = L46_1
L46_1 = "哇~變得好乾淨喔。"
L45_1.Text_TWN = L46_1
L46_1 = "ว้าว ทางสะดวกแล้ว"
L45_1.Text_THA = L46_1
L46_1 = "Tuyệt, mọi thứ đã dọn dẹp xong."
L45_1.Text_VTN = L46_1
L46_1 = "Zack, alles ist frei."
L45_1.Text_DEU = L46_1
L46_1 = "Et hop ! La voie est libre."
L45_1.Text_FRA = L46_1
L46_1 = {}
L47_1 = "GameEvent_10602_3"
L46_1.GameEventStrID = L47_1
L46_1.ProcessKey = 3
L47_1 = 10602
L46_1.EventID = L47_1
L46_1.EventType = "MESSAGE_BOX"
L47_1 = "가자, 우리가 선봉을 맡는다.\n신입은 후방을 맡도록."
L46_1.Text_KOREA = L47_1
L47_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L46_1.StringValue = L47_1
L47_1 = "行こう。私たちが先頭に立つ。\n新入りは後方を頼む。"
L46_1.Text_JPN = L47_1
L47_1 = [[
Let's go. We'll take the lead.
Rookie, bring up the rear.]]
L46_1.Text_ENG = L47_1
L47_1 = "走吧，我们来打头阵。\n新人殿后。"
L46_1.Text_SCN = L47_1
L47_1 = "走吧，由我們擔任先鋒。\n新人墊後。"
L46_1.Text_TWN = L47_1
L47_1 = "ไปกันเถอะ เราจะนำเอง\nเด็กมา คอยคุมท้ายนะ"
L46_1.Text_THA = L47_1
L47_1 = "Đi thôi. Chúng tôi sẽ đi trước.\nTân binh, cậu đi phía sau nhé."
L46_1.Text_VTN = L47_1
L47_1 = "Los. Wir übernehmen die Führung.\nFrischling, du bildest die Nachhut."
L46_1.Text_DEU = L47_1
L47_1 = "Charles, devant avec moi.\nLa bleue, vous couvrez nos arrières."
L46_1.Text_FRA = L47_1
L47_1 = {}
