L2_1 = "GameEvent_10603_2"
L1_1.GameEventStrID = L2_1
L1_1.ProcessKey = 2
L2_1 = 10603
L1_1.EventID = L2_1
L1_1.EventType = "MESSAGE_BOX"
L2_1 = "스승님 명령이니 어쩔 수 없네요."
L1_1.Text_KOREA = L2_1
L2_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L1_1.StringValue = L2_1
L2_1 = "師匠の命令なら仕方ありませんね。"
L1_1.Text_JPN = L2_1
L2_1 = "If it's your command, Master."
L1_1.Text_ENG = L2_1
L2_1 = "既然是老师的命令，那就没办法了。"
L1_1.Text_SCN = L2_1
L2_1 = "既然是師父的命令，那就沒辦法了。"
L1_1.Text_TWN = L2_1
L2_1 = "ตามสั่งเลย มาสเตอร์"
L1_1.Text_THA = L2_1
L2_1 = "Tuân lệnh sếp."
L1_1.Text_VTN = L2_1
L2_1 = "Wenn du das befiehlst, Meisterin."
L1_1.Text_DEU = L2_1
L2_1 = "À vos ordres, maître."
L1_1.Text_FRA = L2_1
