L13_1.EventType = "MESSAGE_BOX"
L14_1 = "저희에게도 출격 명령을 내려주십시오!"
L13_1.Text_KOREA = L14_1
L14_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_RIFLE"
L13_1.StringValue = L14_1
L14_1 = "私たちにも出撃命令を！"
L13_1.Text_JPN = L14_1
L14_1 = "Please let us fight, too!"
L13_1.Text_ENG = L14_1
L14_1 = "请给我们下达出击命令！"
L13_1.Text_SCN = L14_1
L14_1 = "請也對我們下達出擊命令！"
L13_1.Text_TWN = L14_1
L14_1 = "ให้เราสู้ด้วยเถอะ!"
L13_1.Text_THA = L14_1
L14_1 = "Hãy để chúng tôi chiến đấu nữa!"
L13_1.Text_VTN = L14_1
L14_1 = "Bitte! Wir wollen auch kämpfen!"
L13_1.Text_DEU = L14_1
L14_1 = "On veut combattre aussi !"
L13_1.Text_FRA = L14_1
