L15_1.EventType = "TUTORIAL_UNIT_SUMMON_GUIDE"
L16_1 = "일반 병사는 특수한 능력은 없지만, 여러명이 함께 배치됩니다."
L15_1.Text_KOREA = L16_1
L16_1 = 310
L15_1.Value = L16_1
L16_1 = "一般兵士は特殊な能力はありませんが、複数人同時に配置されます。"
L15_1.Text_JPN = L16_1
L16_1 = "Normal soldiers don't have special abilities, but they're deployed in groups."
L15_1.Text_ENG = L16_1
L16_1 = "普通士兵没有特殊能力，但可以同时放置多名。"
L15_1.Text_SCN = L16_1
L16_1 = "普通士兵沒有特殊能力，但可以同時出擊多名士兵。"
L15_1.Text_TWN = L16_1
L16_1 = "ทหารธรรมดาไม่มีความสามารถพิเศษ แต่จะถูกวางทัพเป็นกลุ่ม"
L15_1.Text_THA = L16_1
L16_1 = "Binh lính thường không có khả năng đặc biệt nhưng họ được triển khai theo nhóm."
L15_1.Text_VTN = L16_1
L16_1 = "Normale Soldaten haben keine Spezialfähigkeiten, werden aber in Gruppen eingesetzt."
L15_1.Text_DEU = L16_1
L16_1 = "Les soldats de base n'ont pas de capacités spéciales, mais se déploient en groupes."
L15_1.Text_FRA = L16_1
