L17_1.EventID = L18_1
L17_1.EventType = "MESSAGE_BOX"
L18_1 = "자, 단숨에 목표로 간다!"
L17_1.Text_KOREA = L18_1
L18_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L17_1.StringValue = L18_1
L18_1 = "さあ、一気に目標にたどり着くぞ！"
L17_1.Text_JPN = L18_1
L18_1 = "Alright, let's make a beeline for our target!"
L17_1.Text_ENG = L18_1
L18_1 = "来，一口气冲向目标！"
L17_1.Text_SCN = L18_1
L18_1 = "來，一口氣衝向目標！"
L17_1.Text_TWN = L18_1
L18_1 = "เอาละ เรามาทำทางลัดไปถึงเป้าหมายกันเถอะ!"
L17_1.Text_THA = L18_1
L18_1 = "Được rồi, hãy trực tiếp xông thẳng đến chỗ mục tiêu!"
L17_1.Text_VTN = L18_1
L18_1 = "Okay, wir stürzen uns schnurstracks auf unser Ziel!"
L17_1.Text_DEU = L18_1
L18_1 = "Bien ! Droit sur la cible !"
L17_1.Text_FRA = L18_1
