L20_1.EventID = L21_1
L20_1.EventType = "MESSAGE_BOX"
L21_1 = "후방에 적 출현 감지! 함선이 위험합니다!"
L20_1.Text_KOREA = L21_1
L21_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L20_1.StringValue = L21_1
L21_1 = "後方に敵出現を感知！　艦船が危険です！"
L20_1.Text_JPN = L21_1
L21_1 = "Enemies in the rear! Our ship is in danger!"
L20_1.Text_ENG = L21_1
L21_1 = "侦测到后方来敌！舰船有危险！"
L20_1.Text_SCN = L21_1
L21_1 = "偵測到敵人出現在後方！艦船有危險！"
L20_1.Text_TWN = L21_1
L21_1 = "ศัตรูอยู่ด้านหลัง! ยานรบของเราตกอยู่ในอันตราย!"
L20_1.Text_THA = L21_1
L21_1 = "Quân địch phía sau! Tàu của chúng ta đang gặp nguy!"
L20_1.Text_VTN = L21_1
L21_1 = "Gegner hinter uns! Unser Schiff ist in Gefahr!"
L20_1.Text_DEU = L21_1
L21_1 = "Ennemis à l'arrière ! Notre vaisseau est menacé !"
