L22_1.EventID = L23_1
L22_1.EventType = "MESSAGE_BOX"
L23_1 = "위험인자 소멸 확인. \n수고하셨습니다, 힐데 소대장님."
L22_1.Text_KOREA = L23_1
L23_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L22_1.StringValue = L23_1
L23_1 = "危険因子の消滅を確認。\nお疲れ様でした、ヒルデ小隊長。"
L22_1.Text_JPN = L23_1
L23_1 = [[
All hostiles have been eliminated. 
Thank you, Commander Hilde.]]
L22_1.Text_ENG = L23_1
L23_1 = "危险已清除。\n辛苦了，希尔德队长。"
L22_1.Text_SCN = L23_1
L23_1 = "危險已解除。\n辛苦了，希爾德隊長。"
L22_1.Text_TWN = L23_1
L23_1 = "กำจัดศัตรูทั้งหมดแล้ว\nขอบคุณมาก ผู้บัญชาการฮิลเด้"
L22_1.Text_THA = L23_1
L23_1 = "Toàn bộ quân địch đã bị tiêu diệt. \nCảm ơn Tổng Tư Lệnh Hilde."
L22_1.Text_VTN = L23_1
L23_1 = [[
Alle Feinde wurden eliminiert.
Danke, Kommandantin Hilde.]]
L22_1.Text_DEU = L23_1
L23_1 = "Toute présence ennemie a été éliminée.\nMerci, commandante Hilde."
