L26_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L25_1.StringValue = L26_1
L26_1 = "もうすぐ終わりますよ～。\nそろそろとどめを刺しましょうか？"
L25_1.Text_JPN = L26_1
L26_1 = [[
We're almost done.
Let's finish it, shall we?]]
L25_1.Text_ENG = L26_1
L26_1 = "已经快结束了~\n开始收尾工作吧？"
L25_1.Text_SCN = L26_1
L26_1 = "已經快結束了~\n來收尾吧？"
L25_1.Text_TWN = L26_1
L26_1 = "เกือบเสร็จแล้วละ\nมาจัดการให้เสร็จเลยดีมั้ย?"
L25_1.Text_THA = L26_1
L26_1 = "Chúng tôi sắp xong rồi.\nChúng ta cùng kết liễu nhé?"
L25_1.Text_VTN = L26_1
L26_1 = [[
Wir sind fast fertig.
Bringen wir es zu Ende, okay?]]
