L31_1.EventType = "MESSAGE_BOX"
L32_1 = "또 <color=#ffd34c>디펜더</color> 타입 침식체인가."
L31_1.Text_KOREA = L32_1
L32_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L31_1.StringValue = L32_1
L32_1 = "また<color=#ffd34c>ディフェンダー</color>クラスの侵食体か。"
