L14_1 = 10608
L13_1.EventID = L14_1
L13_1.EventType = "MESSAGE_BOX"
L14_1 = "후방에 적 출현 감지! 함선이 위험합니다!"
L13_1.Text_KOREA = L14_1
L14_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L13_1.StringValue = L14_1
L14_1 = "後方に敵出現を感知！艦船が危険です！"
L13_1.Text_JPN = L14_1
L14_1 = "Enemies in the rear! Our ship is in danger!"
L13_1.Text_ENG = L14_1
L14_1 = "侦测到后方来敌！舰船有危险！"
L13_1.Text_SCN = L14_1
L14_1 = "偵測到敵人出現在後方！艦船有危險！"
L13_1.Text_TWN = L14_1
L14_1 = "ศัตรูอยู่ด้านหลัง! ยานรบของเราตกอยู่ในอันตราย!"
L13_1.Text_THA = L14_1
L14_1 = "Quân địch phía sau! Tàu của chúng ta đang gặp nguy!"
L13_1.Text_VTN = L14_1
L14_1 = "Gegner hinter uns! Unser Schiff ist in Gefahr!"
L13_1.Text_DEU = L14_1
L14_1 = "Ennemis à l'arrière ! Notre vaisseau est menacé !"
L13_1.Text_FRA = L14_1
