L16_1 = "GameEvent_10608_5"
L15_1.GameEventStrID = L16_1
L15_1.ProcessKey = 5
L16_1 = 10608
L15_1.EventID = L16_1
L15_1.EventType = "MESSAGE_BOX"
L16_1 = "내가 맡겠다. 나머지는 침식 쐐기를 처리하도록!"
L15_1.Text_KOREA = L16_1
L16_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L15_1.StringValue = L16_1
L16_1 = "再出撃時はHPが回復し、出撃効果が再び発生する。"
L15_1.Text_JPN = L16_1
L16_1 = "I'll take care of them. The rest of you take care of the Corrupted Wedges."
L15_1.Text_ENG = L16_1
L16_1 = "交给我吧。清除剩下的侵蚀钉！"
L15_1.Text_SCN = L16_1
L16_1 = "交給我吧。你們繼續清除剩下的侵蝕釘！"
L15_1.Text_TWN = L16_1
L16_1 = "ฉันจัดการเอง พวกคุณที่เหลือจัดการเวดจ์คอร์รัปต์ไป"
L15_1.Text_THA = L16_1
L16_1 = "Tôi sẽ xử lý bọn chúng. Mọi người còn lại hãy xử lý lũ Chốt Mòn."
L15_1.Text_VTN = L16_1
L16_1 = "Ich erledige sie. Der Rest von euch kümmert sich um die Verderbniskeile."
L15_1.Text_DEU = L16_1
L16_1 = "Je me charge d'eux. Vous autres, occupez-vous des bestioles corrompues."
L15_1.Text_FRA = L16_1
