L18_1 = "GameEvent_10608_7"
L17_1.GameEventStrID = L18_1
L17_1.ProcessKey = 7
L18_1 = 10608
L17_1.EventID = L18_1
L18_1 = "TEXT"
L17_1.EventType = L18_1
L18_1 = "전투 중인 유닛을 다른 위치에 <color=#ffd34c>재출격</color>시킬 수 있습니다."
L17_1.Text_KOREA = L18_1
L18_1 = "戦闘中のユニットを他の位置から<color=#ffd34c>再出撃</color>させることができます。"
L17_1.Text_JPN = L18_1
L18_1 = "You can <color=#ffd34c>redeploy</color> units that are in combat."
L17_1.Text_ENG = L18_1
L18_1 = "可以<color=#ffd34c>重新出击</color>已在战斗中的单位。"
L17_1.Text_SCN = L18_1
L18_1 = "可以將戰鬥中的單位<color=#ffd34c>重新出擊</color>至其他位置。"
L17_1.Text_TWN = L18_1
L18_1 = "คุณสามารถ<color=#ffd34c>วางทัพ</color>หน่วยรบที่กำลังต่อสู้อยู่ซ้ำได้นะ"
L17_1.Text_THA = L18_1
L18_1 = "Có thể <color=#ffd34c>tái triển khai</color> các đơn vị đang chiến đấu."
L17_1.Text_VTN = L18_1
L18_1 = "Du kannst Einheiten, die sich im Kampf befinden, <color=#ffd34c>neu einsetzen</color>."
L17_1.Text_DEU = L18_1
L18_1 = "Vous pouvez <color=#ffd34c>redéployer</color> des unités en combat."
L17_1.Text_FRA = L18_1
L18_1 = {}
L19_1 = "GameEvent_10608_8"
L18_1.GameEventStrID = L19_1
L18_1.ProcessKey = 8
L19_1 = 10608
L18_1.EventID = L19_1
L19_1 = "TEXT"
L18_1.EventType = L19_1
L19_1 = "재출격 시 HP가 회복되고, 출격효과를 다시 얻습니다."
L18_1.Text_KOREA = L19_1
L19_1 = "再出撃時はHPが回復し、出撃効果が再び発生します。"
L18_1.Text_JPN = L19_1
L19_1 = "Redeploying restores the units' HP and reactivates their Deployment effects."
L18_1.Text_ENG = L19_1
L19_1 = "重新出击时恢复体力，并再次获得出击效果。"
L18_1.Text_SCN = L19_1
L19_1 = "重新出擊時恢復HP，並再次獲得出擊效果。"
L18_1.Text_TWN = L19_1
L19_1 = "การวางทัพซ้ำจะฟื้นฟูพลังชีวิตของหน่วยรบ และทำให้เอฟเฟกต์เมื่อลงสนามรบของหน่วยรบนั้นทำงาน"
L18_1.Text_THA = L19_1
L19_1 = "Việc tái triển khai sẽ hồi phục HP của đơn vị và kích hoạt lại hiệu ứng Triển Khai của họ."
L18_1.Text_VTN = L19_1
L19_1 = "Dadurch werden die LP der Einheiten wiederhergestellt und ihre Einsatzeffekte reaktiviert."
L18_1.Text_DEU = L19_1
L19_1 = "Redéployer une unité lui rend tous ses PV et active de nouveau ses effets de déploiement."
L18_1.Text_FRA = L19_1
L19_1 = {}
L20_1 = "GameEvent_10608_9"
L19_1.GameEventStrID = L20_1
L19_1.ProcessKey = 9
L20_1 = 10608
L19_1.EventID = L20_1
L20_1 = "UNLOCK_TUTORIAL_GAME_RE_RESPAWN"
L19_1.EventType = L20_1
L20_1 = "<color=#ffd34c>힐데<color>를 재출격 시켜 함선을 보호하십시오"
L19_1.Text_KOREA = L20_1
L20_1 = "<color=#ffd34c>ヒルデ<color>を再出撃させて艦船を守ってください。"
L19_1.Text_JPN = L20_1
L20_1 = "Redeploy <color=#ffd34c>Hilde</color> to protect your ship."
L19_1.Text_ENG = L20_1
L20_1 = "请在舰船旁重新出击<color=#ffd34c>希尔德<color>。"
L19_1.Text_SCN = L20_1
L20_1 = "再次出擊<color=#ffd34c>希爾德<color>保護艦船。"
L19_1.Text_TWN = L20_1
L20_1 = "วางทัพ<color=#ffd34c>ฮิลเด้</color>ซ้ำเพื่อปกป้องยานรบของคูณ"
L19_1.Text_THA = L20_1
L20_1 = "Tái triển khai <color=#ffd34c>Hilde</color> để bảo vệ tàu của mình."
L19_1.Text_VTN = L20_1
L20_1 = "Setze <color=#ffd34c>Hilde</color> neu ein, um dein Schiff zu schützen."
L19_1.Text_DEU = L20_1
L20_1 = "Redéployez <color=#ffd34c>Hilde</color> pour protéger votre vaisseau."
L19_1.Text_FRA = L20_1
