L23_1 = "GameEvent_10611_2"
L22_1.GameEventStrID = L23_1
L22_1.ProcessKey = 2
L23_1 = 10611
L22_1.EventID = L23_1
L22_1.EventType = "MESSAGE_BOX"
L23_1 = "후… 이제 다 처리한 거지?\n응? 왜 그래?"
L22_1.Text_KOREA = L23_1
L23_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L22_1.StringValue = L23_1
L23_1 = "ふう……これで終わりよね？\nうん？　どうしたの？"
L22_1.Text_JPN = L23_1
L23_1 = [[
Whew, are we done now?
Mm? What's wrong?]]
L22_1.Text_ENG = L23_1
L23_1 = "呼……这样就完事儿了吧？\n嗯？怎么了?"
L22_1.Text_SCN = L23_1
L23_1 = "呼…這樣就差不多了吧？\n嗯？怎麼了？"
L22_1.Text_TWN = L23_1
L23_1 = "เฮ้อ เราเสร็จแล้วใช่มั้ย?\nหืม? เป็นอะไรไป?"
L22_1.Text_THA = L23_1
L23_1 = "Phù, giờ thì chúng ta xong việc chưa nhỉ?\nHừm? Có gì không ổn à?"
L22_1.Text_VTN = L23_1
L23_1 = [[
Puh, sind wir jetzt fertig?
Mh? Was ist los?]]
L22_1.Text_DEU = L23_1
L23_1 = "C'est bon ? On a fini ?\nHmm ? Un problème ?"
L22_1.Text_FRA = L23_1
L23_1 = {}
L24_1 = "GameEvent_10611_3"
L23_1.GameEventStrID = L24_1
L23_1.ProcessKey = 3
L24_1 = 10611
L23_1.EventID = L24_1
L23_1.EventType = "MESSAGE_BOX"
L24_1 = "스승님, 설마 저게… 그걸까요?"
L23_1.Text_KOREA = L24_1
L24_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L23_1.StringValue = L24_1
L24_1 = "師匠、まさか、あれ……あれでしょうか？"
L23_1.Text_JPN = L24_1
L24_1 = "Master, is that what I think it is?"
L23_1.Text_ENG = L24_1
L24_1 = "老师，那个难道是……？"
L23_1.Text_SCN = L24_1
L24_1 = "師父，那個難道是…？"
L23_1.Text_TWN = L24_1
L24_1 = "มาสเตอร์ นั่นใช่อย่างที่ฉันคิดใช่มั้ย?"
L23_1.Text_THA = L24_1
L24_1 = "Sếp, đó có phải thứ tôi nghĩ không?"
L23_1.Text_VTN = L24_1
L24_1 = "Meisterin, ist es das, was ich denke?"
L23_1.Text_DEU = L24_1
L24_1 = "Maître, c'est bien ce que je pense ?"
L23_1.Text_FRA = L24_1
L24_1 = {}
L25_1 = "GameEvent_10611_4"
L24_1.GameEventStrID = L25_1
L24_1.ProcessKey = 4
L25_1 = 10611
L24_1.EventID = L25_1
L24_1.EventType = "MESSAGE_BOX"
L25_1 = "나도 내 눈을 의심하는 중이다."
L24_1.Text_KOREA = L25_1
L25_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L24_1.StringValue = L25_1
L25_1 = "私も自分の目を疑っている。"
L24_1.Text_JPN = L25_1
L25_1 = "I know, I can hardly believe my eyes."
L24_1.Text_ENG = L25_1
L25_1 = "我也在怀疑我的眼睛。"
L24_1.Text_SCN = L25_1
L25_1 = "我也在懷疑我的眼睛。"
L24_1.Text_TWN = L25_1
L25_1 = "ฉันรู้ ฉันยังแทบไม่เชื่อตาตัวเองเลย"
L24_1.Text_THA = L25_1
L25_1 = "Tôi biết, tôi cũng không tin được vào mắt mình."
L24_1.Text_VTN = L25_1
L25_1 = "Ich weiß, ich kann meinen Augen kaum trauen."
L24_1.Text_DEU = L25_1
L25_1 = "Oui, moi aussi j'ai du mal à y croire."
L24_1.Text_FRA = L25_1
