L29_1 = "GameEvent_10801_3"
L28_1.GameEventStrID = L29_1
L28_1.ProcessKey = 3
L29_1 = 10801
L28_1.EventID = L29_1
L28_1.EventType = "MESSAGE_BOX"
L29_1 = "비스트가 함께 부상한 침식체들과 함선으로 접근 중!"
L28_1.Text_KOREA = L29_1
L29_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L28_1.StringValue = L29_1
L29_1 = "ビーストが浮上した侵食体たちと共に艦船へ接近中！"
L28_1.Text_JPN = L29_1
L29_1 = "The Beast is approaching the ship, along with the other C.O. that appeared with it!"
L28_1.Text_ENG = L29_1
L29_1 = "魔兽与跃出的侵蚀体正在向舰船靠近！"
L28_1.Text_SCN = L29_1
L29_1 = "野獸和一起受傷的侵蝕體接近艦船中!"
L28_1.Text_TWN = L29_1
L29_1 = "บีสต์กำลังเข้าใกล้ยาน เช่นเดียวกับวัตถุคอร์รัปต์อีกตัวที่ปรากฏตัวพร้อมกัน!"
L28_1.Text_THA = L29_1
L29_1 = "Quái Vật đang đi về phía tàu, cùng với các V.T.A.M. khác xuất hiện cùng nó!"
L28_1.Text_VTN = L29_1
L29_1 = "Die Bestie nähert sich zusammen mit anderen C. O.s dem Schiff!"
L28_1.Text_DEU = L29_1
L29_1 = "La bête approche du vaisseau, en compagnie d'autres O.C. !"
L28_1.Text_FRA = L29_1
