L30_1 = "GameEvent_10801_4"
L29_1.GameEventStrID = L30_1
L29_1.ProcessKey = 4
L30_1 = 10801
L29_1.EventID = L30_1
L29_1.EventType = "MESSAGE_BOX"
L30_1 = "함교! 지원사격을 요청한다."
L29_1.Text_KOREA = L30_1
L30_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L29_1.StringValue = L30_1
L30_1 = "艦橋！　支援射撃を要請する。"
L29_1.Text_JPN = L30_1
L30_1 = "Bridge! We need fire support."
L29_1.Text_ENG = L30_1
L30_1 = "舰桥！申请支援。"
L29_1.Text_SCN = L30_1
L30_1 = "艦橋！請求支援射擊。"
L29_1.Text_TWN = L30_1
L30_1 = "ห้องบังคับการ! เราต้องการระบบสนับสนุนการจู่โจม"
L29_1.Text_THA = L30_1
L30_1 = "Đài chỉ huy! Chúng tôi cần yểm trợ hỏa lực."
L29_1.Text_VTN = L30_1
L30_1 = "Brücke! Wir brauchen Feuerunterstützung."
L29_1.Text_DEU = L30_1
L30_1 = "Hilde à la passerelle ! Il nous faut un tir de couverture."
L29_1.Text_FRA = L30_1
