L32_1 = "GameEvent_10801_6"
L31_1.GameEventStrID = L32_1
L31_1.ProcessKey = 6
L32_1 = 10801
L31_1.EventID = L32_1
L32_1 = "TEXT"
L31_1.EventType = L32_1
L32_1 = "<color=#ffd34c>함선이 가진 스킬</color>로 전투를 유리하게 이끌 수 있습니다."
L31_1.Text_KOREA = L32_1
L32_1 = "<color=#ffd34c>艦船が持つスキル</color>で戦闘を有利に導くことができます。"
L31_1.Text_JPN = L32_1
L32_1 = "You can use your <color=#ffd34c>ship's skills</color> to take the upper hand in battle."
L31_1.Text_ENG = L32_1
L32_1 = "合理使用<color=#ffd34c>舰船技能</color>可在战斗中占据优势。"
L31_1.Text_SCN = L32_1
L32_1 = "<color=#ffd34c>艦船本身的技能</color>可以使戰鬥居於優勢。"
L31_1.Text_TWN = L32_1
L32_1 = "คุณสามารถใช้<color=#ffd34c>สกิลยานรบ</color>เพื่อให้ได้เปรียบในการต่อสู้"
L31_1.Text_THA = L32_1
L32_1 = "Sử dụng <color=#ffd34c>kỹ năng của tàu</color> của mình để chiếm thế thượng phong trong trận chiến."
L31_1.Text_VTN = L32_1
L32_1 = "Du kannst die <color=#ffd34c>Fähigkeiten deines Schiffs</color> nutzen, um in einer Schlacht die Oberhand zu gewinnen."
L31_1.Text_DEU = L32_1
L32_1 = "Vous pouvez avoir recours aux <color=#ffd34c>compétences de votre vaisseau</color> pour faire tourner le combat à votre avantage."
L31_1.Text_FRA = L32_1
L32_1 = {}
L33_1 = "GameEvent_10801_7"
L32_1.GameEventStrID = L33_1
L32_1.ProcessKey = 7
L33_1 = 10801
L32_1.EventID = L33_1
L32_1.EventType = "TUTORIAL_SHIP_SKILL_GUIDE"
L33_1 = "적 무리에게 <color=#ffd34c>함선 스킬</color>을 사용하십시오."
L32_1.Text_KOREA = L33_1
L33_1 = 2000101
L32_1.Value = L33_1
L33_1 = "敵に<color=#ffd34c>艦船スキル</color>を使用してください。"
L32_1.Text_JPN = L33_1
L33_1 = "Use a <color=#ffd34c>Ship skill</color> on the enemy group."
L32_1.Text_ENG = L33_1
L33_1 = "请使用<color=#ffd34c>舰船技能</color>攻击敌群。"
L32_1.Text_SCN = L33_1
L33_1 = "請對敵人們使用<color=#ffd34c>艦船技能</color>。"
L32_1.Text_TWN = L33_1
L33_1 = "ใช้<color=#ffd34c>สกิลยานรบ</color>กับกลุ่มศัตรู"
L32_1.Text_THA = L33_1
L33_1 = "Hãy sử dụng một <color=#ffd34c>kỹ năng của Tàu</color> đối với nhóm kẻ thù."
L32_1.Text_VTN = L33_1
L33_1 = "Setze eine <color=#ffd34c>Schifffähigkeit</color> gegen feindliche Gruppen ein."
L32_1.Text_DEU = L33_1
L33_1 = "Utilisez une <color=#ffd34c>compétence de vaisseau</color> sur le groupe d'ennemis."
L32_1.Text_FRA = L33_1
