L36_1 = "GameEvent_10802_3"
L35_1.GameEventStrID = L36_1
L35_1.ProcessKey = 3
L36_1 = 10802
L35_1.EventID = L36_1
L35_1.EventType = "MESSAGE_BOX"
L36_1 = "비스트, 멈추지 않습니다!"
L35_1.Text_KOREA = L36_1
L36_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L35_1.StringValue = L36_1
L36_1 = "ビースト、止まりません！"
L35_1.Text_JPN = L36_1
L36_1 = "The Beast won't stop!"
L35_1.Text_ENG = L36_1
L36_1 = "没法让魔兽停下来！"
L35_1.Text_SCN = L36_1
L36_1 = "野獸沒有停下來！"
L35_1.Text_TWN = L36_1
L36_1 = "บีสต์ไม่ยอมหยุด!"
L35_1.Text_THA = L36_1
L36_1 = "Quái Vật sẽ không ngừng lại!"
L35_1.Text_VTN = L36_1
L36_1 = "Die Bestie ist nicht aufzuhalten!"
L35_1.Text_DEU = L36_1
L36_1 = "La bête est inarrêtable !"
L35_1.Text_FRA = L36_1
L36_1 = {}
L37_1 = "GameEvent_10802_4"
L36_1.GameEventStrID = L37_1
L36_1.ProcessKey = 4
L37_1 = 10802
L36_1.EventID = L37_1
L36_1.EventType = "MESSAGE_BOX"
L37_1 = "칫, 이 정도로는 어림도 없군."
L36_1.Text_KOREA = L37_1
L37_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L36_1.StringValue = L37_1
L37_1 = "チッ、この程度ではびくともしないか。"
L36_1.Text_JPN = L37_1
L37_1 = "Bah, this isn't enough."
L36_1.Text_ENG = L37_1
L37_1 = "切，这样下去可不行。"
L36_1.Text_SCN = L37_1
L37_1 = "嗟！這點程度小意思而已！"
L36_1.Text_TWN = L37_1
L37_1 = "ชิ นี่มันยังไม่พอ"
L36_1.Text_THA = L37_1
L37_1 = "Chậc, thế này không đủ."
L36_1.Text_VTN = L37_1
L37_1 = "Das reicht nicht."
L36_1.Text_DEU = L37_1
L37_1 = "Ça ne suffit pas."
L36_1.Text_FRA = L37_1
