L39_1 = "GameEvent_10802_6"
L38_1.GameEventStrID = L39_1
L38_1.ProcessKey = 6
L39_1 = 10802
L38_1.EventID = L39_1
L38_1.EventType = "MESSAGE_BOX"
L39_1 = "내가 길을 뚫겠다. 바짝 따라붙도록!"
L38_1.Text_KOREA = L39_1
L39_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L38_1.StringValue = L39_1
L39_1 = "私が道を切り開く！　しっかりついて来い！"
L38_1.Text_JPN = L39_1
L39_1 = "I'll cut a path. Stay close!"
L38_1.Text_ENG = L39_1
L39_1 = "我来开路，大家都跟紧我！"
L38_1.Text_SCN = L39_1
L39_1 = "看我殺出一條血路！立刻跟上！"
L38_1.Text_TWN = L39_1
L39_1 = "ฉันจะฝ่าเส้นทางให้ อยู่ใกล้ๆ เอาไว้นะ!"
L38_1.Text_THA = L39_1
L39_1 = "Tôi sẽ mở đường. Đứng gần đây!"
L38_1.Text_VTN = L39_1
L39_1 = "Ich schlage eine Schneise. Bleibt dicht bei mir!"
L38_1.Text_DEU = L39_1
L39_1 = "Je vais ouvrir un passage. Restez près de moi !"
L38_1.Text_FRA = L39_1
