L42_1.EventID = L43_1
L43_1 = "TEXT"
L42_1.EventType = L43_1
L43_1 = "소대원을 출격시켜 비스트를 처치하세요."
L42_1.Text_KOREA = L43_1
L42_1.Value = 2
L43_1 = "小隊員を出撃させてビーストを倒してください。"
L42_1.Text_JPN = L43_1
L43_1 = "Deploy squad members and defeat the Beast."
L42_1.Text_ENG = L43_1
L43_1 = "请使用小队员出击，消灭魔兽。"
L42_1.Text_SCN = L43_1
L43_1 = "出擊隊員消滅野獸。"
L42_1.Text_TWN = L43_1
L43_1 = "วางทัพสมาชิกหน่วยรบและปราบบีสต์"
L42_1.Text_THA = L43_1
L43_1 = "Triển khai thành viên tiểu đội và đánh bại Quái Vật."
