L48_1 = "GameEvent_10804_3"
L47_1.GameEventStrID = L48_1
L47_1.ProcessKey = 3
L48_1 = 10804
L47_1.EventID = L48_1
L47_1.EventType = "MESSAGE_BOX"
L48_1 = "첫 작전부터 고생이 많으시군요, 미나양."
L47_1.Text_KOREA = L48_1
L48_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L47_1.StringValue = L48_1
L48_1 = "ミナさん、初陣から大変な思いをしましたね。"
L47_1.Text_JPN = L48_1
L48_1 = "Good job accomplishing your very first mission, Mina."
L47_1.Text_ENG = L48_1
L48_1 = "第一次战斗辛苦了，米娜。"
L47_1.Text_SCN = L48_1
L48_1 = "米娜小姐第一次作戰就很辛苦呢！"
L47_1.Text_TWN = L48_1
L48_1 = "ทำได้ดีมากในภารกิจแรกนะ มีนา"
L47_1.Text_THA = L48_1
L48_1 = "Chúc mừng đã hoàn thành tốt nhiệm vụ đầu tiên của mình, Mina."
L47_1.Text_VTN = L48_1
L48_1 = "Du hast deine erste Mission erfüllt, Mina. Gut gemacht!"
L47_1.Text_DEU = L48_1
L48_1 = "Félicitations pour ta première mission, Mina."
L47_1.Text_FRA = L48_1
L48_1 = {}
L49_1 = "GameEvent_10804_4"
L48_1.GameEventStrID = L49_1
L48_1.ProcessKey = 4
L49_1 = 10804
L48_1.EventID = L49_1
L48_1.EventType = "MESSAGE_BOX"
L49_1 = "수고했다 제군들. 함교로 돌아간다."
L48_1.Text_KOREA = L49_1
L49_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L48_1.StringValue = L49_1
L49_1 = "ご苦労だった、諸君。艦橋に戻るぞ。"
L48_1.Text_JPN = L49_1
L49_1 = "Good work, guys. Let's go back to the bridge."
L48_1.Text_ENG = L49_1
L49_1 = "大家都辛苦了，现在返回舰桥。"
L48_1.Text_SCN = L49_1
L49_1 = "大家辛苦了！我們回到艦橋去吧！"
L48_1.Text_TWN = L49_1
L49_1 = "เก่งมากทุกคน กลับไปที่ห้องบังคับการกันเถอะ"
L48_1.Text_THA = L49_1
L49_1 = "Tốt lắm, mọi người. Hãy quay lại đài chỉ huy thôi."
L48_1.Text_VTN = L49_1
L49_1 = "Gute Arbeit, Leute. Gehen wir zurück auf die Brücke."
L48_1.Text_DEU = L49_1
L49_1 = "Bravo à tous. Retournons sur la passerelle."
L48_1.Text_FRA = L49_1
