L2_1 = "GameEvent_10901_2"
L1_1.GameEventStrID = L2_1
L1_1.ProcessKey = 2
L2_1 = 10901
L1_1.EventID = L2_1
L1_1.EventType = "MESSAGE_BOX"
L2_1 = "<color=#ffd34c>[바이터]</color> 는 <color=#ffd34c>스트라이커</color> 클래스로, \n무리를 지어다니며 회피율이 높습니다.\n<color=#ffd34c>스나이퍼</color>로 대응하면 효과적입니다."
L1_1.Text_KOREA = L2_1
L2_1 = "AB_INVEN_ICON_NKM_MONSTER_NORMAL_BASIC_BITER"
L1_1.StringValue = L2_1
L2_1 = "<color=#ffd34c>[バイター]</color>は<color=#ffd34c>ストライカー</color>クラスで、\n群れで行動し、回避率が高いです。\n<color=#ffd34c>スナイパー</color>で対応すると効果的です。"
L1_1.Text_JPN = L2_1
L2_1 = [[
The <color=#ffd34c>[Biter]</color> is a <color=#ffd34c>Striker</color> role.
They move in groups and have high EVA.
They're more vulnerable to <color=#ffd34c>Sniper</color> attacks.]]
L1_1.Text_ENG = L2_1
L2_1 = "<color=#ffd34c>【咬合兽】</color>是<color=#ffd34c>前锋</color>职业，\n喜欢成群出没，且闪避率高。\n可使用<color=#ffd34c>狙击手</color>应对。"
L1_1.Text_SCN = L2_1
L2_1 = "<color=#ffd34c>[咬合獸]</color>是<color=#ffd34c>前鋒</color> 職階，\n牠們會成群行動，而且迴避率很高。\n以<color=#ffd34c>狙擊手</color>應對的話效果不錯。"
L1_1.Text_TWN = L2_1
L2_1 = "<color=#ffd34c>[ไบเทอร์]</color> คือคลาส<color=#ffd34c>ปะทะ</color>\nพวกมันเคลื่อนตัวเป็นกลุ่ม และมีการหลบหลีกสูง\nและอ่อนแอต่อ<color=#ffd34c>พลซุ่มยิง</color>มากกว่า"
L1_1.Text_THA = L2_1
L2_1 = "<color=#ffd34c>[Vật Cắn]</color> là một <color=#ffd34c>Lính Tấn Công</color>.\nChúng di chuyển theo nhóm và có EVA cao.\nHọ dễ bị tổn thương hơn do các đòn tấn công của <color=#ffd34c>Lính Bắn Tỉa</color>."
L1_1.Text_VTN = L2_1
L2_1 = "Beim <color=#ffd34c>[Beißer]</color> handelt es sich um eine <color=#ffd34c>Vorhutkämpfer</color>-Rolle. Beißer bewegen sich in Gruppen und haben eine hohe ASW.\nSie sind anfällig für <color=#ffd34c>Scharfschützen</color>-Angriffe."
L1_1.Text_DEU = L2_1
L2_1 = "Les <color=#ffd34c>[dévoreurs]</color> sont des <color=#ffd34c>attaquants</color>.\nIls se déplacent en groupe et possèdent une ESQ élevée. Ils sont particulièrement vulnérables aux attaques de <color=#ffd34c>sniper</color>."
L1_1.Text_FRA = L2_1
