L8_1.ProcessKey = 5
L9_1 = 10902
L8_1.EventID = L9_1
L8_1.EventType = "MESSAGE_BOX"
L9_1 = "대장이 고생이 많구만…"
L8_1.Text_KOREA = L9_1
L9_1 = 1.5
L8_1.Value = L9_1
L9_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L8_1.StringValue = L9_1
L9_1 = "隊長の苦労が目に浮かぶな……"
L8_1.Text_JPN = L9_1
L9_1 = "I feel sorry for the Commander."
L8_1.Text_ENG = L9_1
L9_1 = "队长真是辛苦……"
L8_1.Text_SCN = L9_1
L9_1 = "隊長辛苦了…"
L8_1.Text_TWN = L9_1
L9_1 = "รู้สึกสงสารผู้บัญชาการเลย"
L8_1.Text_THA = L9_1
L9_1 = "Tôi cảm thấy tiếc cho Tổng Tư Lệnh."
L8_1.Text_VTN = L9_1
L9_1 = "Die Kommandantin tut mir leid."
L8_1.Text_DEU = L9_1
L9_1 = "Je plains la commandante."
L8_1.Text_FRA = L9_1
