L11_1 = 11001
L10_1.EventID = L11_1
L10_1.EventType = "MESSAGE_BOX"
L11_1 = "바이터가 작전지역 중앙으로 기습해 옵니다!\n주의하세요!"
L10_1.Text_KOREA = L11_1
L10_1.Value = 2
L11_1 = "AB_INVEN_ICON_NKM_NPC_OPERATOR_LENA"
L10_1.StringValue = L11_1
L11_1 = "バイターが作戦地域の中央に奇襲をかけました！\nご注意ください！"
L10_1.Text_JPN = L11_1
L11_1 = [[
The Biters are converging toward the center of the operation area.
Watch out!]]
L10_1.Text_ENG = L11_1
L11_1 = "咬合兽正向作战区域中心袭来！\n请注意！"
L10_1.Text_SCN = L11_1
L11_1 = "咬合獸突襲作戰區域中央！\n注意！"
L10_1.Text_TWN = L11_1
L11_1 = "ไบเทอร์กำลังมุ่งหน้าไปยังกึ่งกลางพื้นที่ปฏิบัติการ\nระวังด้วยล่ะ!"
L10_1.Text_THA = L11_1
L11_1 = "Các Vật Cắn đang hội tụ về phía trung tâm của khu vực hoạt động.\nCác bạn hãy chú ý theo dõi! "
L10_1.Text_VTN = L11_1
L11_1 = "Die Beißer strömen ins Einsatzgebiet.\nAchtung!"
L10_1.Text_DEU = L11_1
L11_1 = "Les dévoreurs convergent sur le centre de la zone d'opération.\nAttention !"
L10_1.Text_FRA = L11_1
