L13_1 = "GameEvent_11002_2"
L12_1.GameEventStrID = L13_1
L12_1.ProcessKey = 2
L13_1 = 11002
L12_1.EventID = L13_1
L12_1.EventType = "MESSAGE_BOX"
L13_1 = "침식수에서 고 에너지 반응 발생!\n함선을 향해 접근합니다!"
L12_1.Text_KOREA = L13_1
L12_1.Value = 2
L13_1 = "AB_INVEN_ICON_NKM_NPC_OPERATOR_LENA"
L12_1.StringValue = L13_1
L13_1 = "侵食樹から高エネルギー反応発生！\n艦船に向かって接近しています！"
L12_1.Text_JPN = L13_1
L13_1 = [[
High energy responses from the Corrupted Tree!
It's coming toward our ship!]]
L12_1.Text_ENG = L13_1
L13_1 = "在侵蚀树身上出现高能反应！\n正在向舰船靠近！"
L12_1.Text_SCN = L13_1
L13_1 = "從侵蝕樹發出高能量反應！\n往艦船方向靠近！"
L12_1.Text_TWN = L13_1
L13_1 = "มีการตอบสนองพลังงานสูงจากต้นไม้คอร์รัปต์!\nมันกำลังมุ่งหน้ามาที่ยานรบของเรา"
L12_1.Text_THA = L13_1
L13_1 = "Các phản hồi năng lượng cao từ Cây Lụi! \nNó đang tiến về phía con tàu của chúng ta! "
L12_1.Text_VTN = L13_1
L13_1 = [[
Hochenergetische Anzeigen vom Verderbnisbaum!
Es kommt auf unser Schiff zu!]]
L12_1.Text_DEU = L13_1
L13_1 = "L'arbre corrompu émet une grosse signature énergétique !\nIl avance vers notre vaisseau !"
L12_1.Text_FRA = L13_1
L13_1 = {}
L14_1 = "GameEvent_11002_3"
L13_1.GameEventStrID = L14_1
L13_1.ProcessKey = 3
L14_1 = 11002
L13_1.EventID = L14_1
L13_1.EventType = "MESSAGE_BOX"
L14_1 = "접근하게 둬서는 안 된다.\n요격 태세로!"
L13_1.Text_KOREA = L14_1
L13_1.Value = 2
L14_1 = "AB_INVEN_ICON_NKM_UNIT_C_HILDE"
L13_1.StringValue = L14_1
L14_1 = "奴らを近付けるな。\n迎撃態勢につけ！"
L13_1.Text_JPN = L14_1
L14_1 = [[
Don't let it get near us.
Interception mode!]]
L13_1.Text_ENG = L14_1
L14_1 = "不能让它靠近。\n必须拦截！"
L13_1.Text_SCN = L14_1
L14_1 = "不能放任它們靠近！\n阻止它們！"
L13_1.Text_TWN = L14_1
L14_1 = "อย่าให้มันเข้าใกล้เราได้นะ\nเข้าโหมดสกัด!"
L13_1.Text_THA = L14_1
L14_1 = "Đừng để nó đến gần chúng ta.\nChế độ đánh chặn!"
L13_1.Text_VTN = L14_1
L14_1 = [[
Es darf uns nicht zu nahe kommen.
Abfangmodus!]]
L13_1.Text_DEU = L14_1
L14_1 = "Ne le laissez pas approcher.\nOn passe en mode interception !"
L13_1.Text_FRA = L14_1
