L21_1.EventID = L22_1
L21_1.EventType = "MESSAGE_BOX"
L22_1 = "이번 작전만 성공시키면 모두 우리 공적이야."
L21_1.Text_KOREA = L22_1
L22_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALT_SEO_YOON"
L21_1.StringValue = L22_1
L22_1 = "今回の作戦さえ成功させれば、すべて私たちのお手柄だよ。"
L21_1.Text_JPN = L22_1
L22_1 = "If we succeed in this mission, we can take all the credit ourselves."
L21_1.Text_ENG = L22_1
L22_1 = "如果这次作战能够成功，那都是我们的功劳。"
L21_1.Text_SCN = L22_1
L22_1 = "只要這次作戰成功，功勞就全是我們的了！"
L21_1.Text_TWN = L22_1
L22_1 = "ถ้าเราทำภารกิจนี้สำเร็จ เราก็จะได้ความดีความชอบทั้งหมด"
L21_1.Text_THA = L22_1
L22_1 = "Nếu chúng ta hoàn thành nhiệm vụ này thành công, chúng ta có thể lấy tất cả xu vàng cho mình."
L21_1.Text_VTN = L22_1
L22_1 = "Wenn diese Mission erfolgreich ist, heimsen wir alles Lob dafür ein."
L21_1.Text_DEU = L22_1
L22_1 = "Si on réussit cette mission, on s'en attribuera tout le mérite."
L21_1.Text_FRA = L22_1
L22_1 = {}
L23_1 = "GameEvent_11102_4"
L22_1.GameEventStrID = L23_1
L22_1.ProcessKey = 4
L23_1 = 11102
L22_1.EventID = L23_1
L22_1.EventType = "MESSAGE_BOX"
L23_1 = "정식 라이선스까지 앞으로 한 발 남았어. 모두 힘내자!"
L22_1.Text_KOREA = L23_1
L23_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALT_SEO_YOON"
L22_1.StringValue = L23_1
L23_1 = "正式ライセンスまであと一歩よ。みんな、頑張ろう！"
L22_1.Text_JPN = L23_1
L23_1 = "We only have one step left toward getting our official license. Everyone, bear down!"
L22_1.Text_ENG = L23_1
L23_1 = "现在就差最后一步可以获得正式执照了。大家加油！"
L22_1.Text_SCN = L23_1
L23_1 = "距離正式授權只差一步了！大家加油！"
L22_1.Text_TWN = L23_1
L23_1 = "เหลืออีกแค่ขั้นตอนเดียว เราก็จะได้รับใบอนุญาตอย่างเป็นทางการแล้ว ทุกคน ไปเลย!"
L22_1.Text_THA = L23_1
L23_1 = "Chúng ta chỉ còn một bước nữa để có được giấy phép chính thức. Mọi người, hãy chịu khó nhé! "
L22_1.Text_VTN = L23_1
L23_1 = "Wir stehen kurz vor unserer offiziellen Lizenz. Haltet auf das Schiff zu!"
L22_1.Text_DEU = L23_1
L23_1 = "Plus qu'une étape avant d'obtenir notre licence officielle. Appliquez-vous toutes !"
L22_1.Text_FRA = L23_1
L23_1 = {}
L24_1 = "GameEvent_11102_5"
L23_1.GameEventStrID = L24_1
L23_1.ProcessKey = 5
L24_1 = 11102
L23_1.EventID = L24_1
L23_1.EventType = "MESSAGE_BOX"
L24_1 = "알았어 대장! 붙잡아 두는 건 내게 맡겨!"
L23_1.Text_KOREA = L24_1
L24_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALT_YOO_JIN"
L23_1.StringValue = L24_1
L24_1 = "了解した、隊長！　捕縛は俺に任せろ！"
L23_1.Text_JPN = L24_1
L24_1 = "Got it, Cap! I'll keep them busy!"
L23_1.Text_ENG = L24_1
L24_1 = "知道了，队长！我来阻止它！"
L23_1.Text_SCN = L24_1
L24_1 = "沒問題，隊長！抓人這種事就交給我吧！"
L23_1.Text_TWN = L24_1
L24_1 = "รับทราบค่ะ หัวหน้า! ฉันจะดึงดูดความสนใจของพวกมันเอง!"
L23_1.Text_THA = L24_1
L24_1 = "Đã hiểu, Đội trưởng! Tôi sẽ khiến chúng thở không ra hơi!"
L23_1.Text_VTN = L24_1
L24_1 = "Alles klar, Cap! Ich werde sie beschäftigen!"
L23_1.Text_DEU = L24_1
L24_1 = "Compris, cap' ! Je vais les occuper !"
L23_1.Text_FRA = L24_1
L24_1 = {}
