L26_1 = "GameEvent_11102_7"
L25_1.GameEventStrID = L26_1
L25_1.ProcessKey = 7
L26_1 = 11102
L25_1.EventID = L26_1
L26_1 = "TEXT"
L25_1.EventType = L26_1
L26_1 = "이번 스테이지는 웨이브 전투입니다."
L25_1.Text_KOREA = L26_1
L26_1 = "今回のステージはウェーブ戦闘です。"
L25_1.Text_JPN = L26_1
L26_1 = "This stage is a wave battle."
L25_1.Text_ENG = L26_1
L26_1 = "本次战斗为防御战，存在多波进攻。"
L25_1.Text_SCN = L26_1
L26_1 = "這次關卡是攻勢戰鬥。"
L25_1.Text_TWN = L26_1
L26_1 = "นี่เป็นด่านการต่อสู้แบบเป็นระลอก"
L25_1.Text_THA = L26_1
L26_1 = "Giai đoạn này là một trận chiến theo đợt."
L25_1.Text_VTN = L26_1
L26_1 = "Diese Phase der Schlacht besteht aus Gegnerwellen."
L25_1.Text_DEU = L26_1
L26_1 = "Ce niveau consiste en une bataille par vagues."
L25_1.Text_FRA = L26_1
L26_1 = {}
L27_1 = "GameEvent_11102_8"
L26_1.GameEventStrID = L27_1
L26_1.ProcessKey = 8
L27_1 = 11102
L26_1.EventID = L27_1
L27_1 = "TEXT"
L26_1.EventType = L27_1
L27_1 = "출격 영역 제한이 사라지고, 각 웨이브 마다 많은 적이 몰려듭니다."
L26_1.Text_KOREA = L27_1
L27_1 = "出撃エリアの制限がなくなり、ウェーブごとに大量の敵が押し寄せてきます。"
L26_1.Text_JPN = L27_1
L27_1 = "The deployment area restrictions are lifted, and enemies will come in waves."
L26_1.Text_ENG = L27_1
L27_1 = "将取消出击领域的限制，每波攻击都会有大量敌人袭来。"
L26_1.Text_SCN = L27_1
L27_1 = "出擊區域限制消失後，各個攻勢開始聚集許多敵人。"
L26_1.Text_TWN = L27_1
L27_1 = "บริเวณนี้ไม่มีข้อจำกัดพื้นที่วางทัพ และศัตรูจะเข้ามาเป็นระลอก"
L26_1.Text_THA = L27_1
L27_1 = "Các giới hạn của khu vực triển khai được dỡ bỏ và kẻ thù sẽ đến từng đợt. "
L26_1.Text_VTN = L27_1
L27_1 = "Die Beschränkungen für den Einsatzbereich sind aufgehoben, der Gegner kommt in Wellen."
L26_1.Text_DEU = L27_1
L27_1 = "La zone de déploiement n'est pas restreinte, et les ennemis arrivent par vagues."
L26_1.Text_FRA = L27_1
L27_1 = {}
L28_1 = "GameEvent_11102_9"
L27_1.GameEventStrID = L28_1
L27_1.ProcessKey = 9
L28_1 = 11102
L27_1.EventID = L28_1
L27_1.EventType = "HIGHLIGHT_UI"
L28_1 = "시간 안에 적을 모두 처치하지 못해도 다음 웨이브가 시작됩니다."
L27_1.Text_KOREA = L28_1
L28_1 = "UI_HUD_BG_TOP_TIME"
L27_1.StringValue = L28_1
L28_1 = "時間内に敵をすべて倒せなくても次のウェーブは始まります。"
L27_1.Text_JPN = L28_1
L28_1 = "They won't stop coming, even if you don't clear the current wave within the time limit."
L27_1.Text_ENG = L28_1
L28_1 = "即使在限定时间内不能消灭本波的所有敌人，敌人的下一波攻击仍会开始。"
L27_1.Text_SCN = L28_1
L28_1 = "就算沒有在時間內消滅全部敵人，下一波攻勢也會展開。"
L27_1.Text_TWN = L28_1
L28_1 = "พวกมันจะเข้ามาไม่หยุด ต่อให้คุณยังกำจัดระลอกปัจจุบันไม่หมดภายในเวลาที่กำหนด"
L27_1.Text_THA = L28_1
L28_1 = "Chúng sẽ đến không ngừng, ngay cả khi chưa xử lý xong đợt hiện tại trong giới hạn thời gian."
L27_1.Text_VTN = L28_1
L28_1 = "Die Feine kommen ständig nach, sogar wenn du nicht alle im Zeitlimit besiegst."
L27_1.Text_DEU = L28_1
L28_1 = "Ils viendront sans discontinuer, même si vous n'avez pas éliminé la vague actuelle dans le temps imparti."
L27_1.Text_FRA = L28_1
L28_1 = {}
L29_1 = "GameEvent_11102_10"
L28_1.GameEventStrID = L29_1
L28_1.ProcessKey = 10
L29_1 = 11102
L28_1.EventID = L29_1
L28_1.EventType = "HIGHLIGHT_UI"
L29_1 = "모든 웨이브를 클리어 하면 승리합니다."
L28_1.Text_KOREA = L29_1
L29_1 = "NKM_UI_HUD_WAVE"
L28_1.StringValue = L29_1
L29_1 = "すべてのウェーブをクリアすると戦闘に勝利します。"
L28_1.Text_JPN = L29_1
L29_1 = "Clear all the waves to win."
L28_1.Text_ENG = L29_1
L29_1 = "消灭所有波次的敌人后即可获得胜利。"
L28_1.Text_SCN = L29_1
L29_1 = "過關所有攻勢後便獲勝。"
L28_1.Text_TWN = L29_1
L29_1 = "เคลียร์ทุกระลอกเพื่อคว้าชัยชนะ"
L28_1.Text_THA = L29_1
L29_1 = "Hãy tiêu diệt tất cả các đợt để chiến thắng."
L28_1.Text_VTN = L29_1
L29_1 = "Um zu gewinnen, musst du alle Wellen besiegen."
L28_1.Text_DEU = L29_1
L29_1 = "Éliminez toutes les vagues pour gagner."
L28_1.Text_FRA = L29_1
