L31_1 = "GameEvent_11102_12"
L30_1.GameEventStrID = L31_1
L31_1 = 12
L30_1.ProcessKey = L31_1
L31_1 = 11102
L30_1.EventID = L31_1
L30_1.EventType = "MESSAGE_BOX"
L31_1 = "서두르지 않으면 잔챙이들이 다시 몰려들거야.\n모두 공격해!"
L30_1.Text_KOREA = L31_1
L31_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALT_SEO_YOON"
L30_1.StringValue = L31_1
L31_1 = "急がないと雑魚たちがまた湧いてくるはず。\nみんな、攻撃して！"
L30_1.Text_JPN = L31_1
L31_1 = [[
Let's hurry before more enemies show up.
Everyone, attack!]]
L30_1.Text_ENG = L31_1
L31_1 = "我们要加快速度，不然敌人的喽啰就更多了。\n所有人攻击！"
L30_1.Text_SCN = L31_1
L31_1 = "不快點的話那些傢伙會再回來的！\n全部展開攻擊！"
L30_1.Text_TWN = L31_1
L31_1 = "รีบลงมือก่อนที่ศัตรูจะโผล่มาเถอะ\nทุกคน โจมตี!"
L30_1.Text_THA = L31_1
L31_1 = "Hãy nhanh lên trước khi ngày càng nhiều kẻ thù xuất hiện.\nMọi người, tấn công!"
L30_1.Text_VTN = L31_1
L31_1 = [[
Beeilen wir uns, bevor noch mehr Gegner auftauchen.
Angriff!]]
L30_1.Text_DEU = L31_1
L31_1 = "Dépêchons-nous avant que d'autres ennemis arrivent.\nToutes à l'attaque !"
L30_1.Text_FRA = L31_1
