L35_1 = "GameEvent_11103_3"
L34_1.GameEventStrID = L35_1
L34_1.ProcessKey = 3
L35_1 = 11103
L34_1.EventID = L35_1
L34_1.EventType = "MESSAGE_BOX"
L35_1 = "하늘이다! 흩어졌던 침식체들이 돌아왔어!"
L34_1.Text_KOREA = L35_1
L35_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALT_XIAOLIN"
L34_1.StringValue = L35_1
L35_1 = "空だ！　散らばっていた侵食体たちが戻ってきた！"
L34_1.Text_JPN = L35_1
L35_1 = "The sky! The C.O. that scattered are back!"
L34_1.Text_ENG = L35_1
L35_1 = "快看天上！分散的侵蚀体们又回来了！"
L34_1.Text_SCN = L35_1
L35_1 = "看天空！散開的侵蝕體又回來了！"
L34_1.Text_TWN = L35_1
L35_1 = "ท้องฟ้า! วัตถุคอร์รัปต์ที่แตกกระจายกลับมาแล้ว!"
L34_1.Text_THA = L35_1
L35_1 = "Nhìn lên trời kìa! Những V.T.A.M. bị phân tán đã quay lại!"
L34_1.Text_VTN = L35_1
L35_1 = "Der Himmel! Die verstreuten C. O.s sind zurück!"
L34_1.Text_DEU = L35_1
L35_1 = "Regardez en l'air ! Les O.C. qui s'étaient dispersés sont de retour !"
L34_1.Text_FRA = L35_1
L35_1 = {}
L36_1 = "GameEvent_11103_4"
L35_1.GameEventStrID = L36_1
L35_1.ProcessKey = 4
L36_1 = 11103
L35_1.EventID = L36_1
L35_1.EventType = "MESSAGE_BOX"
L36_1 = "칫, 하필 이런 타이밍에…"
L35_1.Text_KOREA = L36_1
L36_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALT_SEO_YOON"
L35_1.StringValue = L36_1
L36_1 = "くっ、よりにもよってこのタイミングで……"
L35_1.Text_JPN = L36_1
L36_1 = "Bah, just our luck!"
L35_1.Text_ENG = L36_1
L36_1 = "切，偏偏在这个时候……"
L35_1.Text_SCN = L36_1
L36_1 = "真是的，真會挑時間…"
L35_1.Text_TWN = L36_1
L36_1 = "หึ โชคช่วยแท้ๆ!"
L35_1.Text_THA = L36_1
L36_1 = "Thật may quá đi!"
L35_1.Text_VTN = L36_1
L36_1 = "Das ist mal wieder typisch!"
L35_1.Text_DEU = L36_1
L36_1 = "Rah, c'est bien notre veine !"
L35_1.Text_FRA = L36_1
L36_1 = {}
L37_1 = "GameEvent_11103_5"
L36_1.GameEventStrID = L37_1
L36_1.ProcessKey = 5
L37_1 = 11103
L36_1.EventID = L37_1
L36_1.EventType = "MESSAGE_BOX"
L37_1 = "하늘의 적은 내게 맡기고, 다들 타겟에 집중해!"
L36_1.Text_KOREA = L37_1
L37_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALT_SEO_YOON"
L36_1.StringValue = L37_1
L37_1 = "空の敵は私に任せて、みんなターゲットに集中して！"
L36_1.Text_JPN = L37_1
L37_1 = "Everyone, focus on the target. I'll take care of the ones in the sky!"
L36_1.Text_ENG = L37_1
L37_1 = "空中的敌人交给我，其他人都集中攻击目标！"
L36_1.Text_SCN = L37_1
L37_1 = "天空的就交給我！大家集中在目標上！"
L36_1.Text_TWN = L37_1
L37_1 = "ทุกคน มุ่งสนใจที่เป้าหมาย ฉันจะจัดการพวกที่อยู่บนฟ้าเอง!"
L36_1.Text_THA = L37_1
L37_1 = "Mọi người, hãy tập trung vào mục tiêu. Tôi sẽ xử lý đám trên trời!"
L36_1.Text_VTN = L37_1
L37_1 = "Konzentriert euch auf das Ziel. Ich kümmere mich um die am Himmel!"
L36_1.Text_DEU = L37_1
L37_1 = "Restez toutes sur la cible. Je vais m'occuper des ennemis aériens !"
L36_1.Text_FRA = L37_1
L37_1 = {}
