L39_1 = "GameEvent_11103_7"
L38_1.GameEventStrID = L39_1
L38_1.ProcessKey = 7
L39_1 = 11103
L38_1.EventID = L39_1
L38_1.EventType = "MESSAGE_BOX"
L39_1 = "<color=#ffd34c>[레이스]</color>는 <color=#ffd34c>비행 타입</color>의 침식체입니다."
L38_1.Text_KOREA = L39_1
L39_1 = "AB_INVEN_ICON_NKM_MONSTER_NORMAL_BASIC_WRAITH"
L38_1.StringValue = L39_1
L39_1 = "<color=#ffd34c>[レイス]</color>は<color=#ffd34c>飛行タイプ</color>の侵食体です。"
L38_1.Text_JPN = L39_1
L39_1 = "The <color=#ffd34c>[Wraith]</color> is a <color=#ffd34c>Flying</color> C.O."
L38_1.Text_ENG = L39_1
L39_1 = "<color=#ffd34c>魅影</color>是<color=#ffd34c>飞行类型</color>的侵蚀体。"
L38_1.Text_SCN = L39_1
L39_1 = "<color=#ffd34c>[魅影]</color>是<color=#ffd34c>飛行類</color>侵蝕體。"
L38_1.Text_TWN = L39_1
L39_1 = "<color=#ffd34c>[เรธ]</color>คือวัตถุคอร์รัปต์<color=#ffd34c>บินได้</color>"
L38_1.Text_THA = L39_1
L39_1 = "<color=#ffd34c>[Bóng Ma]</color> là V.T.A.M. <color=#ffd34c>Bay</color>."
L38_1.Text_VTN = L39_1
L39_1 = "Das <color=#ffd34c>[Gespenst]</color> ist ein <color=#ffd34c>flugfähiges</color> C. O."
L38_1.Text_DEU = L39_1
L39_1 = "Les <color=#ffd34c>[spectres]</color> sont des O.C. <color=#ffd34c>volants</color>."
L38_1.Text_FRA = L39_1
L39_1 = {}
L40_1 = "GameEvent_11103_8"
L39_1.GameEventStrID = L40_1
L39_1.ProcessKey = 8
L40_1 = 11103
L39_1.EventID = L40_1
L40_1 = "TEXT"
L39_1.EventType = L40_1
L40_1 = "<color=#ffd34c>비행 타입</color>은 <color=#ffd34c>전천후, 대공</color>타입 유닛으로 공격할 수 있습니다."
L39_1.Text_KOREA = L40_1
L40_1 = "<color=#ffd34c>飛行タイプ</color>は<color=#ffd34c>万能、対空</color>タイプのユニットで\n攻撃できます。"
L39_1.Text_JPN = L40_1
L40_1 = "The <color=#ffd34c>Flying type</color> can be countered with <color=#ffd34c>All-around and Anti-air</color> units."
L39_1.Text_ENG = L40_1
L40_1 = "可以使用<color=#ffd34c>全地形/对空</color>类型的单位攻击<color=#ffd34c>飞行类型</color>的侵蚀体。"
L39_1.Text_SCN = L40_1
L40_1 = "<color=#ffd34c>飛行類</color>可<color=#ffd34c>全方位攻擊防空</color>類單位。"
L39_1.Text_TWN = L40_1
L40_1 = "ตอบโต้<color=#ffd34c>ประเภทบินได้</color>ด้วย<color=#ffd34c>หน่วยโจมตีโดยรอบและหน่วยโจมตีทางอากาศ</color>"
L39_1.Text_THA = L40_1
L40_1 = "<color=#ffd34c>Loại Bay</color> có thể đối phó với các đơn vị <color=#ffd34c>Toàn Diện và Trên Không</color>."
L39_1.Text_VTN = L40_1
L40_1 = "Der <color=#ffd34c>Flugtyp</color> lässt sich mit <color=#ffd34c>Rundum- und Flugabwehreinheiten</color> abwehren."
L39_1.Text_DEU = L40_1
L40_1 = "Les ennemis de <color=#ffd34c>type volant</color> peuvent être contrés par des unités <color=#ffd34c>polyvalentes et antiaériennes</color>."
L39_1.Text_FRA = L40_1
L40_1 = {}
L41_1 = "GameEvent_11103_9"
L40_1.GameEventStrID = L41_1
L40_1.ProcessKey = 9
L41_1 = 11103
L40_1.EventID = L41_1
L41_1 = "TEXT"
L40_1.EventType = L41_1
L41_1 = "<color=#ffd34c>전천후</color> 유닛인 <color=#ffd34c>서윤</color>으로 대항하세요."
L40_1.Text_KOREA = L41_1
L41_1 = "<color=#ffd34c>万能</color>ユニットの<color=#ffd34c>アオイ・シズカ</color>で対抗してください。"
L40_1.Text_JPN = L41_1
L41_1 = "Use the <color=#ffd34c>All-around</color> unit, <color=#ffd34c>Seo Yoon</color>, to counter it."
L40_1.Text_ENG = L41_1
L41_1 = "请选择<color=#ffd34c>全地形</color>单位<color=#ffd34c>徐芸</color>对抗敌人。"
L40_1.Text_SCN = L41_1
L41_1 = "請派出<color=#ffd34c>全方位</color>單位的<color=#ffd34c>徐芸</color>與之抗衡。"
L40_1.Text_TWN = L41_1
L41_1 = "ใช้หน่วยรบ<color=#ffd34c>โจมตีโดยรอบ</color> <color=#ffd34c>ซอ ยุน</color> ในการต่อสู้กับมัน"
L40_1.Text_THA = L41_1
L41_1 = "Hãy sử dụng đơn vị <color=#ffd34c>Toàn Diện</color>, <color=#ffd34c>Seo Yoon</color>, để phản lại."
L40_1.Text_VTN = L41_1
L41_1 = "Nutze die <color=#ffd34c>Rundum</color>-Einheit <color=#ffd34c>Seo Yoon</color>, um den Flugtyp abzuwehren."
L40_1.Text_DEU = L41_1
L41_1 = "Servez-vous de votre unité <color=#ffd34c>polyvalente</color>, <color=#ffd34c>Seo Yoon</color>, pour les contrer."
L40_1.Text_FRA = L41_1
