L43_1 = "GameEvent_11104_2"
L42_1.GameEventStrID = L43_1
L42_1.ProcessKey = 2
L43_1 = 11104
L42_1.EventID = L43_1
L42_1.EventType = "MESSAGE_BOX"
L43_1 = "…우…우리가 해낸 거야?"
L42_1.Text_KOREA = L43_1
L43_1 = 20
L42_1.Value = L43_1
L43_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALT_KIM_SOBIN"
L42_1.StringValue = L43_1
L43_1 = "……わ、私たちが……勝ったの？"
L42_1.Text_JPN = L43_1
L43_1 = "...D-did we make it?"
L42_1.Text_ENG = L43_1
L43_1 = "我……我们成功了？"
L42_1.Text_SCN = L43_1
L43_1 = "…我…我們贏了嗎？"
L42_1.Text_TWN = L43_1
L43_1 = "ระ-เราทำสำเร็จมั้ย?"
L42_1.Text_THA = L43_1
L43_1 = "...C-chúng ta đã làm được ư?"
L42_1.Text_VTN = L43_1
L43_1 = "Ha-Haben wir überlebt?"
L42_1.Text_DEU = L43_1
L43_1 = "O-On a réussi ?"
L42_1.Text_FRA = L43_1
L43_1 = {}
L44_1 = "GameEvent_11104_3"
L43_1.GameEventStrID = L44_1
L43_1.ProcessKey = 3
L44_1 = 11104
L43_1.EventID = L44_1
L43_1.EventType = "MESSAGE_BOX"
L44_1 = "완전히 쓰러질 때 까지 방심하지 마!"
L43_1.Text_KOREA = L44_1
L44_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALT_SEO_YOON"
L43_1.StringValue = L44_1
L44_1 = "完全に倒れるまで油断しないで！"
L43_1.Text_JPN = L44_1
L44_1 = "Don't let your guard down until it's completely dead!"
L43_1.Text_ENG = L44_1
L44_1 = "在完全消灭之前，别放松警惕！"
L43_1.Text_SCN = L44_1
L44_1 = "在敵人全部倒下前絕不能掉以輕心！"
L43_1.Text_TWN = L44_1
L44_1 = "อย่าเพิ่งวางใจจนกว่ามันจะตายสนิทนะ!"
L43_1.Text_THA = L44_1
L44_1 = "Đừng mất cảnh giác cho đến khi chúng chết hẳn!"
L43_1.Text_VTN = L44_1
L44_1 = "Seid auf der Hut, bis es wirklich tot ist!"
L43_1.Text_DEU = L44_1
L44_1 = "Ne baissez pas votre garde tant qu'il n'est pas mort !"
L43_1.Text_FRA = L44_1
L44_1 = {}
L45_1 = "GameEvent_11104_4"
L44_1.GameEventStrID = L45_1
L44_1.ProcessKey = 4
L45_1 = 11104
L44_1.EventID = L45_1
L44_1.EventType = "MESSAGE_BOX"
L45_1 = "대장, 타겟이 움직인다. 최후의 발악이야!"
L44_1.Text_KOREA = L45_1
L45_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALT_XIAOLIN"
L44_1.StringValue = L45_1
L45_1 = "隊長、ターゲットが動いた。最後のあがきだ！"
L44_1.Text_JPN = L45_1
L45_1 = "Cap, the target is still moving. It's not going to go down easily!"
L44_1.Text_ENG = L45_1
L45_1 = "队长，目标又开始动了，它在做垂死挣扎！"
L44_1.Text_SCN = L45_1
L45_1 = "隊長，目標移動了，在做垂死的掙扎！"
L44_1.Text_TWN = L45_1
L45_1 = "หัวหน้า เป้าหมายยังขยับ มันไม่ยอมตายง่ายๆ!"
L44_1.Text_THA = L45_1
L45_1 = "Đội trưởng, mục tiêu vẫn đang di chuyển. Nó sẽ không dễ dàng bị gục ngã đâu!"
L44_1.Text_VTN = L45_1
L45_1 = "Das Ziel bewegt sich immer noch, Cap! Es ist nicht kleinzukriegen!"
L44_1.Text_DEU = L45_1
L45_1 = "Cap', la cible bouge encore. Elle ne s'avoue pas vaincue aussi facilement !"
L44_1.Text_FRA = L45_1
L45_1 = {}
