L46_1.EventID = L47_1
L46_1.EventType = "MESSAGE_BOX"
L47_1 = "뭐 하는거야 대장!\n빨리 공격해야지!"
L46_1.Text_KOREA = L47_1
L47_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALT_YOO_JIN"
L46_1.StringValue = L47_1
L47_1 = "隊長、何やってるんだ！\n早く攻撃しないと！"
L46_1.Text_JPN = L47_1
L47_1 = [[
Come on, Cap!
Let's attack it already!]]
L46_1.Text_ENG = L47_1
L47_1 = "你在干嘛，队长！\n快攻击啊！"
L46_1.Text_SCN = L47_1
L47_1 = "隊長，你在做什麼！\n趕快攻擊啊！"
L46_1.Text_TWN = L47_1
L47_1 = "เร็วสิ หัวหน้า!\nเรารีบโจมตีมันกันเถอะ!"
L46_1.Text_THA = L47_1
L47_1 = "Thôi nào, Đội trưởng!\nHãy tấn công nó đi đã!"
L46_1.Text_VTN = L47_1
L47_1 = [[
Na los, Cap!
Greifen wir endlich an!]]
L46_1.Text_DEU = L47_1
L47_1 = "Allez, cap' !\nIl faut l'attaquer !"
L46_1.Text_FRA = L47_1
