L22_1 = 722
L21_1.EventID = L22_1
L21_1.EventType = "MESSAGE_BOX"
L22_1 = "이수연 부사장님께서,\n제일 먼저 이곳으로 모시라고 하셨습니다."
L21_1.Text_KOREA = L22_1
L22_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L21_1.StringValue = L22_1
L22_1 = "カナミ副社長から、まず最初に\nこちらに案内するようにと指示を受けています。"
L21_1.Text_JPN = L22_1
L22_1 = [[
The Vice President asked me
to show you here before everywhere else.]]
L21_1.Text_ENG = L22_1
L22_1 = "李秀妍副总说，\n先带您来这里。"
L21_1.Text_SCN = L22_1
L22_1 = "李秀妍副總說\n要先來這個地方。"
L21_1.Text_TWN = L22_1
L22_1 = "รองประธานขอให้ฉัน\nพาคุณมาดูที่นี่เป็นที่แรก"
L21_1.Text_THA = L22_1
L22_1 = "Phó Chủ Tịch đã yêu cầu tôi\nkhông đưa ngài tới đây trước khi tham quan xong những nơi khác."
L21_1.Text_VTN = L22_1
L22_1 = [[
Die Vizevorsitzende hat mich gebeten,
Ihnen das hier zuerst zu zeigen.]]
L21_1.Text_DEU = L22_1
L22_1 = "La vice-présidente m'a demandé\nde vous montrer cet endroit en premier."
L21_1.Text_FRA = L22_1
