L23_1 = "TUTORIAL_NEW_722_7"
L22_1.GameEventStrID = L23_1
L22_1.ProcessKey = 7
L23_1 = 722
L22_1.EventID = L23_1
L22_1.EventType = "MESSAGE_BOX"
L23_1 = "<color=#ffd34c>[테라브레인]</color> 이라니…"
L22_1.Text_KOREA = L23_1
L23_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L22_1.StringValue = L23_1
L23_1 = "<color=#ffd34c>[テラブレイン]</color>……"
L22_1.Text_JPN = L23_1
L23_1 = "<color=#ffd34c>[Terrabrain]</color>..."
L22_1.Text_ENG = L23_1
L23_1 = "<color=#ffd34c>居然是【特拉大脑】</color>……"
L22_1.Text_SCN = L23_1
L23_1 = "<color=#ffd34c>[特拉大腦]</color>…"
L22_1.Text_TWN = L23_1
L23_1 = "<color=#ffd34c>[เทอร์ราเบรน]...</color>"
L22_1.Text_THA = L23_1
L23_1 = "<color=#ffd34c>[Bộ não siêu cấp]</color>..."
L22_1.Text_VTN = L23_1
L23_1 = "<color=#ffd34c>[Terrabrain]</color> …"
L22_1.Text_DEU = L23_1
L23_1 = "<color=#ffd34c>[Thalamus]</color>..."
L22_1.Text_FRA = L23_1
