L24_1 = "TUTORIAL_NEW_722_8"
L23_1.GameEventStrID = L24_1
L23_1.ProcessKey = 8
L24_1 = 722
L23_1.EventID = L24_1
L23_1.EventType = "MESSAGE_BOX"
L24_1 = "사장실에 이런 비밀 방이 있는줄은 꿈에도 몰랐네요."
L23_1.Text_KOREA = L24_1
L24_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L23_1.StringValue = L24_1
L24_1 = "社長室にこんな秘密の部屋があったなんて、夢にも思いませんでした。"
L23_1.Text_JPN = L24_1
L24_1 = "Who knew there was such a secret room inside the CEO's Office?"
L23_1.Text_ENG = L24_1
L24_1 = "我做梦也没想到老板办公室里竟然有密室……"
L23_1.Text_SCN = L24_1
L24_1 = "我作夢也沒想到老闆辦公室裡竟然有密室！"
L23_1.Text_TWN = L24_1
L24_1 = "ใครจะไปรู้ว่ามีห้องลับแบบนี้อยู่ในห้อง CEO?"
L23_1.Text_THA = L24_1
L24_1 = "Ai mà biết lại có một căn phòng bí mật như vậy bên trong văn phòng của CEO chứ?"
L23_1.Text_VTN = L24_1
L24_1 = "Wer hätte gedacht, dass es im Büro vom Chef einen Geheimraum gibt?"
L23_1.Text_DEU = L24_1
L24_1 = "Qui aurait soupçonné l'existence d'une pièce secrète dans le bureau du PDG ?"
L23_1.Text_FRA = L24_1
