L34_1.EventID = L35_1
L34_1.EventType = "MESSAGE_BOX"
L35_1 = "<color=#ffd34c>[테라브레인]</color> 이라니…"
L34_1.Text_KOREA = L35_1
L35_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L34_1.StringValue = L35_1
L35_1 = "<color=#ffd34c>[テラブレイン]</color>……"
L34_1.Text_JPN = L35_1
L35_1 = "<color=#ffd34c>[Terrabrain]</color>..."
L34_1.Text_ENG = L35_1
L35_1 = "<color=#ffd34c>居然是【特拉大脑】</color>……"
L34_1.Text_SCN = L35_1
L35_1 = "<color=#ffd34c>[特拉大腦]</color>…"
L34_1.Text_TWN = L35_1
L35_1 = "<color=#ffd34c>[Terrabrain]</color> …"
L34_1.Text_DEU = L35_1
L35_1 = "<color=#ffd34c>[Thalamus]</color>..."
L34_1.Text_FRA = L35_1
L35_1 = {}
L36_1 = "TUTORIAL_NEW_741_4"
L35_1.GameEventStrID = L36_1
L35_1.ProcessKey = 4
L36_1 = 741
L35_1.EventID = L36_1
L35_1.EventType = "MESSAGE_BOX"
L36_1 = "사장실에 이런 비밀 방이 있는줄은 꿈에도 몰랐네요."
L35_1.Text_KOREA = L36_1
L36_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L35_1.StringValue = L36_1
L36_1 = "社長室にこんな秘密の部屋があったなんて、夢にも思いませんでした。"
L35_1.Text_JPN = L36_1
L36_1 = "Who knew there was such a secret room inside the CEO's Office?"
L35_1.Text_ENG = L36_1
L36_1 = "我做梦也没想到老板办公室里竟然有密室……"
L35_1.Text_SCN = L36_1
L36_1 = "我作夢也沒想到老闆辦公室裡竟然有密室！"
L35_1.Text_TWN = L36_1
L36_1 = "Wer hätte gedacht, dass es im Büro vom Chef einen Geheimraum gibt?"
L35_1.Text_DEU = L36_1
L36_1 = "Qui aurait soupçonné l'existence d'une pièce secrète dans le bureau du PDG ?"
L35_1.Text_FRA = L36_1
