L1_1.EventID = L2_1
L1_1.EventType = "MESSAGE_BOX"
L2_1 = "네 알겠습니다."
L1_1.Text_KOREA = L2_1
L2_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L1_1.StringValue = L2_1
L2_1 = "はい、承知いたしました。"
L1_1.Text_JPN = L2_1
L2_1 = "Yes, sir."
L1_1.Text_ENG = L2_1
