L3_1 = "TUTORIAL_NEW_742_15"
L2_1.GameEventStrID = L3_1
L3_1 = 15
L2_1.ProcessKey = L3_1
L3_1 = 742
L2_1.EventID = L3_1
L2_1.EventType = "MESSAGE_BOX"
L3_1 = "그럼 앞으로 <color=#ffd34c>사장님</color>이 머무르실 공간도 안내 해 드리겠습니다."
L2_1.Text_KOREA = L3_1
L3_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L2_1.StringValue = L3_1
L3_1 = "それでは、<color=#ffd34c>社長</color>の執務室までご案内します。"
L2_1.Text_JPN = L3_1
L3_1 = "Now, let me show you your office, <color=#ffd34c>Boss</color>."
L2_1.Text_ENG = L3_1
L3_1 = "接下来就带您去<color=#ffd34c>老板</color>以后要工作的地方吧。"
L2_1.Text_SCN = L3_1
L3_1 = "接下來跟<color=#ffd34c>老闆</color>介紹之後會停留的空間。"
L2_1.Text_TWN = L3_1
L3_1 = "ฉันจะพาคุณไปดูห้องทำงานของคุณนะคะ <color=#ffd34c>บอส</color>"
L2_1.Text_THA = L3_1
L3_1 = "Giờ hãy để tôi đưa ngài đi tham quan văn phòng, <color=#ffd34c>Ông Chủ</color>."
L2_1.Text_VTN = L3_1
L3_1 = "Und jetzt zeige ich Ihnen Ihr Büro, <color=#ffd34c>Boss</color>."
L2_1.Text_DEU = L3_1
L3_1 = "Je vais vous montrer votre bureau, <color=#ffd34c>monsieur</color>."
L2_1.Text_FRA = L3_1
