L24_1.EventID = L25_1
L24_1.EventType = "MESSAGE_BOX"
L25_1 = "여기가 <color=#ffd34c>사장실</color>입니다."
L24_1.Text_KOREA = L25_1
L25_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L24_1.StringValue = L25_1
L25_1 = "ここが<color=#ffd34c>社長室</color>です。"
L24_1.Text_JPN = L25_1
L25_1 = "This is the <color=#ffd34c>CEO's office</color>."
L24_1.Text_ENG = L25_1
L25_1 = "这里是<color=#ffd34c>老板办公室</color>。"
L24_1.Text_SCN = L25_1
L25_1 = "這裡是<color=#ffd34c>老闆辦公室</color>。"
L24_1.Text_TWN = L25_1
L25_1 = "นี่คือ<color=#ffd34c>ห้อง CEO</color>"
L24_1.Text_THA = L25_1
L25_1 = "Đây là <color=#ffd34c>văn phòng của CEO</color>."
L24_1.Text_VTN = L25_1
L25_1 = "Das ist das <color=#ffd34c>Büro der Geschäftsführung</color>."
L24_1.Text_DEU = L25_1
L25_1 = "Voici le <color=#ffd34c>bureau du PDG</color>."
L24_1.Text_FRA = L25_1
