L15_1.EventID = L16_1
L15_1.EventType = "MESSAGE_BOX"
L16_1 = "찬찬히 살펴 보신 후 결과가 마음에 드시면,\n채용 확정 부탁드립니다."
L15_1.Text_KOREA = L16_1
L16_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L15_1.StringValue = L16_1
L16_1 = "じっくりご覧になり、結果がよろしければ\n採用確定をお願いいたします。"
L15_1.Text_JPN = L16_1
L16_1 = [[
Please take your time to look at the applicants.
If you like them, please confirm your choices.]]
L15_1.Text_ENG = L16_1
L16_1 = "请在精挑细选后，\n作出选择。"
L15_1.Text_SCN = L16_1
L16_1 = "請在精挑細選後，\n作出選擇。"
L15_1.Text_TWN = L16_1
L16_1 = "ค่อยๆ ใช้เวลาดูผู้สมัครนะคะ\nถ้าชอบคนไหนก็ยืนยันตัวเลือกเลย"
L15_1.Text_THA = L16_1
L16_1 = "Hãy dành thời gian nghiên cứu các ứng viên.\nNếu thích họ, hãy xác nhận lựa chọn của ngài."
L15_1.Text_VTN = L16_1
L16_1 = "Nehmen Sie sich Zeit und sehen Sie sich die Bewerber an. Wenn sie Ihnen gefallen, bestätigen Sie bitte Ihre Auswahl."
L15_1.Text_DEU = L16_1
L16_1 = "Prenez le temps d'examiner les différents candidats. Confirmez votre choix lorsque vous en aurez trouvé qui vous satisfont."
L15_1.Text_FRA = L16_1
