L40_1.EventType = "MESSAGE_BOX"
L41_1 = "<color=#ffd34c>일일 미션</color>은 오늘 진행할 업무들로 구성되어 있습니다."
L40_1.Text_KOREA = L41_1
L41_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L40_1.StringValue = L41_1
L41_1 = "<color=#ffd34c>デイリーミッション</color>は、本日遂行する業務で構成されています。"
L40_1.Text_JPN = L41_1
L41_1 = "<color=#ffd34c>Daily missions</color> are the tasks that can be performed today."
