L41_1 = "<color=#ffd34c>ภารกิจรายวัน</color>คืองานที่สามารถทำได้ในวันนี้"
L40_1.Text_THA = L41_1
L41_1 = "<color=#ffd34c>Nhiệm Vụ Hàng Ngày</color> là các nhiệm vụ có thể thực hiện hôm nay."
