L45_1 = "TUTORIAL_NEW_123_12"
L44_1.GameEventStrID = L45_1
L45_1 = 12
L44_1.ProcessKey = L45_1
L45_1 = 123
L44_1.EventID = L45_1
L45_1 = "TUTORIAL_TOUCH_BACK_BUTTON"
L44_1.EventType = L45_1
L45_1 = "앞으로의 회사 성장을 참고할 수 있는 <color=#ffd34c>태스크포스 플랜</color>을 안내 해 드리겠습니다."
L44_1.Text_KOREA = L45_1
L45_1 = "今後の会社の成長のために参考にできる<color=#ffd34c>タスクフォースプラン</color>をご案内します。"
L44_1.Text_JPN = L45_1
L45_1 = "I will be walking you through the <color=#ffd34c>TASKFORCE Plan</color> which can be used for the growth of the company."
L44_1.Text_ENG = L45_1
L45_1 = "现在为您介绍有关公司未来发展的<color=#ffd34c>特遣势力计划</color>项目。"
L44_1.Text_SCN = L45_1
L45_1 = "為老闆介紹可以參考公司未來發展的<color=#ffd34c>特遣勢力計畫</color>。"
L44_1.Text_TWN = L45_1
L45_1 = "เราจะแนะนำคุณเกี่ยวกับ <color=#ffd34c>แผนของทาสก์ฟอร์ส</color> ที่สามารถใช้เป็นข้อมูลอ้างอิงสำหรับการเติบโตในอนาคตของบริษัท"
L44_1.Text_THA = L45_1
L45_1 = "Bây giờ, xin giới thiệu với ngài <color=#ffd34c>Kế Hoạch TASKFORCE</color> liên quan tới sự phát triển của công ty trong tương lai."
L44_1.Text_VTN = L45_1
L45_1 = "Ich erläutere Ihnen den <color=#ffd34c>TASKFORCE-Plan</color>, der das zukünftige Wachstum des Unternehmens skizziert."
L44_1.Text_DEU = L45_1
L45_1 = "Voici des informations sur les <color=#ffd34c>Plans TASKFORCE</color> pour vous aider à progresser."
L44_1.Text_FRA = L45_1
