L48_1 = "GUIDEMISSION"
L47_1.StringValue = L48_1
L48_1 = "こちらです、社長。"
L47_1.Text_JPN = L48_1
L48_1 = "This way, Boss."
L47_1.Text_ENG = L48_1
L48_1 = "请到这边来，老板。"
L47_1.Text_SCN = L48_1
L48_1 = "老闆這邊請。"
L47_1.Text_TWN = L48_1
L48_1 = "มาที่นี่เลยค่ะบอส"
L47_1.Text_THA = L48_1
L48_1 = "Mời Ông Chủ qua bên này!"
L47_1.Text_VTN = L48_1
L48_1 = "Hier lang bitte, Boss."
L47_1.Text_DEU = L48_1
L48_1 = "Par ici s'il vous plaît."
