L50_1.EventType = "HIGHLIGHT_UI"
L51_1 = "<color=#ffd34c>태스크포스 플랜</color>에서는 회사의 당면 과제를 확인할 수 있습니다."
L50_1.Text_KOREA = L51_1
L51_1 = "10001"
L50_1.StringValue = L51_1
L51_1 = "<color=#ffd34c>タスクフォースプラン</color>では会社の当面の課題を確認できます。"
L50_1.Text_JPN = L51_1
L51_1 = "You can check out the company's current missions at <color=#ffd34c>TASKFORCE Plan</color>."
L50_1.Text_ENG = L51_1
L51_1 = "可以在<color=#ffd34c>特遣势力计划</color>中查看公司当前所需完成的任务。"
L50_1.Text_SCN = L51_1
L51_1 = "在<color=#ffd34c>特遣勢力計畫</color>中，可以確認公司目前的任務。"
L50_1.Text_TWN = L51_1
L51_1 = "คุณสามารถตรวจสอบภารกิจที่ต้องการทำใน<color=#ffd34c>แผนของทาสก์ฟอร์ส</color>ได้"
L50_1.Text_THA = L51_1
L51_1 = "Có thể xem nhiệm vụ công ty cần hoàn thành trong <color=#ffd34c>Kế Hoạch TASKFORCE</color>."
L50_1.Text_VTN = L51_1
L51_1 = "Im <color=#ffd34c>TASKFORCE-Plan</color> lassen sich die aktuellen Herausforderungen des Unternehmens einsehen."
L50_1.Text_DEU = L51_1
L51_1 = "Dans les <color=#ffd34c>Plans TASKFORCE</color>, vous pouvez vérifier les défis urgents à résoudre."
L50_1.Text_FRA = L51_1
