L2_1.EventID = L3_1
L2_1.EventType = "MESSAGE_BOX"
L3_1 = "진행 완료된 업무가 있습니다. 결재 부탁드립니다."
L2_1.Text_KOREA = L3_1
L3_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L2_1.StringValue = L3_1
L3_1 = "完了した業務があります。ご確認お願いします。"
L2_1.Text_JPN = L3_1
L3_1 = "There is a completed task. Please complete the transaction."
L2_1.Text_ENG = L3_1
L3_1 = "当前有一项任务已经完成了。请您审核。"
L2_1.Text_SCN = L3_1
L3_1 = "有已完成的任務，請確認。"
L2_1.Text_TWN = L3_1
L3_1 = "มีงานที่ทำเสร็จแล้ว กรุณาตรวจสอบ"
L2_1.Text_THA = L3_1
L3_1 = "Hiện tại có một nhiệm vụ đã hoàn thành. Vui lòng phê duyệt."
L2_1.Text_VTN = L3_1
L3_1 = "Ein Auftrag wurde als abgeschlossen gemeldet. Ich bitte um Ihre finale Bestätigung."
L2_1.Text_DEU = L3_1
L3_1 = "Certaines tâches ont été accomplies. Veuillez les valider."
L2_1.Text_FRA = L3_1
