L6_1 = "TUTORIAL_NEW_124_11"
L5_1.GameEventStrID = L6_1
L5_1.ProcessKey = 11
L6_1 = 124
L5_1.EventID = L6_1
L5_1.EventType = "MESSAGE_BOX"
L6_1 = "감사합니다. 그럼 현장으로 복귀하실까요?"
L5_1.Text_KOREA = L6_1
L6_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L5_1.StringValue = L6_1
L6_1 = "ありがとうございました。それでは、現場に戻りましょう。"
L5_1.Text_JPN = L6_1
L6_1 = "Thank you. Shall we get back to work now?"
L5_1.Text_ENG = L6_1
L6_1 = "谢谢，那我们就回到现场吧？"
L5_1.Text_SCN = L6_1
L6_1 = "謝謝，那就回到現場囉？"
L5_1.Text_TWN = L6_1
L6_1 = "ขอบคุณนะ งั้นเรากลับไปที่สนามกันดีไหม?"
L5_1.Text_THA = L6_1
L6_1 = "Cảm ơn nhé. Chúng ta về hiện trường thôi nhỉ."
L5_1.Text_VTN = L6_1
L6_1 = "Danke sehr. Sollen wir dann wieder zurück vor Ort gehen?"
L5_1.Text_DEU = L6_1
L6_1 = "Merci pour votre attention. On se remet au travail ?"
L5_1.Text_FRA = L6_1
