L11_1 = "TUTORIAL_NEW_460_4"
L10_1.GameEventStrID = L11_1
L10_1.ProcessKey = 4
L11_1 = 460
L10_1.EventID = L11_1
L11_1 = "TUTORIAL_CLICK_WARFARE_TILE"
L10_1.EventType = L11_1
L11_1 = "작전을 이어서 속행하도록 하지\n해야할 일이 많이 있으니, 다들 긴장하도록."
L10_1.Text_KOREA = L11_1
L11_1 = "CLICK_DIVE_POINT"
L10_1.StringValue = L11_1
L11_1 = "作戦を続行するとしよう。\nやることが山ほどあるから、みんな気を引き締めろ。"
L10_1.Text_JPN = L11_1
L11_1 = [[
Let's resume our operation.
Everyone, brace yourself. We've got our work cut out for us.]]
L10_1.Text_ENG = L11_1
L11_1 = "那我们加快速度继续执行作战吧。\n要做的事情还有很多，希望大家都调整好状态。"
L10_1.Text_SCN = L11_1
L11_1 = "繼續進行作戰吧。\n有很多事情要做，大家都要繃緊神經。"
L10_1.Text_TWN = L11_1
L11_1 = "บอกประวัติการดำเนินการของพวกเรา \nทุกคน เตรียมตัว เราได้คัดงานออกสำหรับพวกเราแล้ว"
L10_1.Text_THA = L11_1
L11_1 = "Hãy tiếp tục tác chiến của chúng ta.\nMọi người hãy chuẩn bị tinh thần. Chúng ta cần phải khẩn trương lên."
L10_1.Text_VTN = L11_1
L11_1 = [[
Setzen wir unseren Einsatz fort.
Macht euch alle auf etwas gefasst. Uns steht noch viel Arbeit bevor.]]
L10_1.Text_DEU = L11_1
L11_1 = "Reprenons notre opération.\nQue tout le monde se tienne prêt. On a du pain sur la planche."
L10_1.Text_FRA = L11_1
L11_1 = {}
