L34_1 = "TUTORIAL_NEW_270_3"
L33_1.GameEventStrID = L34_1
L33_1.ProcessKey = 3
L34_1 = 270
L33_1.EventID = L34_1
L33_1.EventType = "MESSAGE_BOX"
L34_1 = "점점 작전을 수행하기에 어려워 지는 것 같네요."
L33_1.Text_KOREA = L34_1
L34_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L33_1.StringValue = L34_1
L34_1 = "だんだん作戦遂行が難しくなっていきますね。"
L33_1.Text_JPN = L34_1
L34_1 = "It's getting more difficult to accomplish operations."
L33_1.Text_ENG = L34_1
L34_1 = "作战难度好像越来越高了。"
L33_1.Text_SCN = L34_1
L34_1 = "之後執行作戰似乎會越來越困難呢！"
L33_1.Text_TWN = L34_1
L34_1 = "การทำปฏิบัติการให้สำเร็จจะยากขึ้นเรื่อยๆ"
L33_1.Text_THA = L34_1
L34_1 = "Hoàn thành tác chiến ngày càng khó khăn hơn."
L33_1.Text_VTN = L34_1
L34_1 = "Es wird immer schwieriger, Operationen zu erledigen."
L33_1.Text_DEU = L34_1
L34_1 = "Les opérations sont de plus en plus difficiles à accomplir."
L33_1.Text_FRA = L34_1
L34_1 = {}
L35_1 = "TUTORIAL_NEW_270_4"
L34_1.GameEventStrID = L35_1
L34_1.ProcessKey = 4
L35_1 = 270
L34_1.EventID = L35_1
L34_1.EventType = "MESSAGE_BOX"
L35_1 = "<color=#ffd34c>연봉협상</color>을 통해서 유닛의 레벨을 빠르게 높일 수 있습니다."
L34_1.Text_KOREA = L35_1
L35_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L34_1.StringValue = L35_1
L35_1 = "<color=#ffd34c>年俸交渉</color>を行うことで、ユニットのレベルを素早く上げることができます。"
L34_1.Text_JPN = L35_1
L35_1 = "You can level your units quickly through <color=#ffd34c>Salary Negotiations</color>."
L34_1.Text_ENG = L35_1
L35_1 = "您可以通过<color=#ffd34c>工资协商</color>快速提高单位的等级。"
L34_1.Text_SCN = L35_1
L35_1 = "透過<color=#ffd34c>薪資協商</color>可加速員工升級喔！"
L34_1.Text_TWN = L35_1
L35_1 = "คุณสามารถเพิ่มเลเวลหน่วยรบได้อย่างรวดเร็วผ่านการ<color=#ffd34c>ต่อรองค่าจ้าง</color>"
L34_1.Text_THA = L35_1
L35_1 = "Ngài có thể thăng cấp cho các đơn vị của mình nhanh chóng thông qua <color=#ffd34c>Đàm Phán Lương</color>."
L34_1.Text_VTN = L35_1
L35_1 = "Sie können Ihre Einheiten durch <color=#ffd34c>Gehaltsverhandlungen schnell aufstufen</color>."
L34_1.Text_DEU = L35_1
L35_1 = "Vous pouvez faire rapidement monter vos unités de niveau via les <color=#ffd34c>négociations de salaire</color>."
L34_1.Text_FRA = L35_1
L35_1 = {}
L36_1 = "TUTORIAL_NEW_270_5"
