L27_1 = "TUTORIAL_NEW_340_4"
L26_1.GameEventStrID = L27_1
L26_1.ProcessKey = 4
L27_1 = 340
L26_1.EventID = L27_1
L26_1.EventType = "MESSAGE_BOX"
L27_1 = "<color=#ffd34c>[모의작전]</color>은 유닛 성장에 필요한 경험치와 재화를 얻을 수 있는 중요한 활동입니다."
L26_1.Text_KOREA = L27_1
L27_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L26_1.StringValue = L27_1
L27_1 = "<color=#ffd34c>[模擬作戦]</color>は、ユニット成長に必要な経験値と通貨を獲得できる大事な活動です。"
L26_1.Text_JPN = L27_1
L27_1 = "<color=#ffd34c>[Simulations]</color> provide the EXP and resources you need to grow your units."
L26_1.Text_ENG = L27_1
L27_1 = "<color=#ffd34c>【模拟作战】</color>是可以获得单位成长所需的经验值和货币的重要活动。"
L26_1.Text_SCN = L27_1
L27_1 = "<color=#ffd34c>[模擬戰]</color>是獲得員工成長所需經驗值和貨幣的重要內容。"
L26_1.Text_TWN = L27_1
L27_1 = "<color=#ffd34c>[ปฏิบัติการจำลอง]</color> ให้ EXP และทรัพยากรที่จำเป็นต่อการเติบโตของหน่วยรบ"
L26_1.Text_THA = L27_1
L27_1 = "<color=#ffd34c>[Mô Phỏng Tác Chiến]</color> cung cấp EXP và tài nguyên mà ngài cần để tăng trưởng các đơn vị của ngài."
L26_1.Text_VTN = L27_1
L27_1 = "Unter <color=#ffd34c>[Simulation]</color> bekommen Sie die ERF und die Ressourcen, mit denen Sie Ihre Einheiten verbessern können."
L26_1.Text_DEU = L27_1
L27_1 = "Les <color=#ffd34c>[simulations]</color> fournissent l'EXP et les ressources nécessaires pour faire progresser vos unités."
L26_1.Text_FRA = L27_1
