L25_1 = "TUTORIAL_NEW_214_5"
L24_1.GameEventStrID = L25_1
L24_1.ProcessKey = 5
L25_1 = 214
L24_1.EventID = L25_1
L24_1.EventType = "MESSAGE_BOX"
L25_1 = "그럼 <color=#ffd34c>코핀</color>함선의 개조를 시작하겠습니다!"
L24_1.Text_KOREA = L25_1
L25_1 = "AB_INVEN_ICON_NKM_NPC_NA_HEE_RIN"
L24_1.StringValue = L25_1
L25_1 = "それでは、<color=#ffd34c>コフィン</color>艦船の改造を開始するのです！"
L24_1.Text_JPN = L25_1
L25_1 = "Okay, then let's start upgrading the <color=#ffd34c>Coffin</color>."
L24_1.Text_ENG = L25_1
L25_1 = "现在开始改造<color=#ffd34c>科芬</color>舰船！"
L24_1.Text_SCN = L25_1
L25_1 = "開始來改造<color=#ffd34c>科芬</color>艦船吧！"
L24_1.Text_TWN = L25_1
L25_1 = "เอาละ มาเริ่มอัปเกรด<color=#ffd34c>คอฟฟิน</color>กัน"
L24_1.Text_THA = L25_1
L25_1 = "Được, hãy bắt đầu nâng cấp <color=#ffd34c>Coffin</color>."
L24_1.Text_VTN = L25_1
L25_1 = "Okay, dann wollen wir mal anfangen, die <color=#ffd34c>Coffin</color> aufzuwerten."
L24_1.Text_DEU = L25_1
L25_1 = "Bien, commençons par améliorer le <color=#ffd34c>Coffin</color>."
L24_1.Text_FRA = L25_1
