L34_1.GameEventStrID = L35_1
L34_1.ProcessKey = 9
L35_1 = 215
L34_1.EventID = L35_1
L34_1.EventType = "MESSAGE_BOX"
L35_1 = "우측 상단의 화살표 버튼을 사용하여,\n여러 단계의 개조를 한번에 진행할 수 도 있습니다."
L34_1.Text_KOREA = L35_1
L35_1 = "AB_INVEN_ICON_NKM_NPC_NA_HEE_RIN"
L34_1.StringValue = L35_1
L35_1 = "右上の矢印ボタンを使用して\n複数段階の改造を一気に行うこともできるのです。"
L34_1.Text_JPN = L35_1
L35_1 = [[
You can use the arrow buttons on the top right
to complete multiple upgrade stages at once.]]
L34_1.Text_ENG = L35_1
L35_1 = "可以使用右上角的箭头按钮，\n一次性完成若干阶段的改造。"
L34_1.Text_SCN = L35_1
L35_1 = "可以使用右上方的箭頭按鈕\n一次進行不同階段的改造。"
L34_1.Text_TWN = L35_1
L35_1 = "คุณสามารถใช้ปุ่มลูกศรที่มุมขวาบน\nเพื่ออัปเกรดหลายๆ ขั้นตอนให้เสร็จได้ในคราวเดียว"
L34_1.Text_THA = L35_1
L35_1 = "Ngài có thể sử dụng nút mũi tên ở trên cùng bên phải\nđể hoàn thành nhiều giai đoạn nâng cấp cùng lúc."
L34_1.Text_VTN = L35_1
L35_1 = "Sie können die Pfeilschaltflächen oben rechts verwenden, um mehrere Aufwertungsstufen gleichzeitig abzuschließen."
L34_1.Text_DEU = L35_1
L35_1 = "Vous pouvez utiliser les flèches en haut à droite\npour effectuer plusieurs étapes d'amélioration d'un coup."
L34_1.Text_FRA = L35_1
