L36_1.EventID = L37_1
L36_1.EventType = "MESSAGE_BOX"
L37_1 = "우선 하는 데까지 해 보겠습니다."
L36_1.Text_KOREA = L37_1
L37_1 = "AB_INVEN_ICON_NKM_NPC_NA_HEE_RIN"
L36_1.StringValue = L37_1
L37_1 = "まずは、できるところまでやってみるのです。"
L36_1.Text_JPN = L37_1
L37_1 = "Let's try as many times as we can at the moment."
L36_1.Text_ENG = L37_1
L37_1 = "现在请先试试吧。"
L36_1.Text_SCN = L37_1
L37_1 = "就先試試能做到什麼程度吧！"
L36_1.Text_TWN = L37_1
L37_1 = "ตอนนี้เรามาลองหลายๆ ครั้งเท่าที่ทำได้กันค่ะ"
L36_1.Text_THA = L37_1
L37_1 = "Hiện tại, hãy thử nhiều lần nếu có thể."
L36_1.Text_VTN = L37_1
L37_1 = "Lassen Sie es uns im Moment so oft versuchen wie möglich."
L36_1.Text_DEU = L37_1
L37_1 = "Faisons ça autant de fois qu'on le peut pour l'instant."
L36_1.Text_FRA = L37_1
