L50_1 = "TUTORIAL_NEW_215_24"
L49_1.GameEventStrID = L50_1
L50_1 = 24
L49_1.ProcessKey = L50_1
L50_1 = 215
L49_1.EventID = L50_1
L49_1.EventType = "MESSAGE_BOX"
L50_1 = "수고 많으셨습니다! 필요하면 또 찾아주세요!"
L49_1.Text_KOREA = L50_1
L50_1 = "AB_INVEN_ICON_NKM_NPC_NA_HEE_RIN"
L49_1.StringValue = L50_1
L50_1 = "お疲れ様でした！　またお越しくださいね！"
L49_1.Text_JPN = L50_1
L50_1 = "Good job. Please come again whenever you need me!"
L49_1.Text_ENG = L50_1
L50_1 = "辛……辛苦了！老板！有需要的话请再来找我吧！"
L49_1.Text_SCN = L50_1
L50_1 = "辛苦囉！有需要再來找我呀！"
L49_1.Text_TWN = L50_1
L50_1 = "ดีมากค่ะ ถ้าต้องการฉันเมื่อไหร่ก็มาได้อีกทุกเมื่อนะคะ!"
L49_1.Text_THA = L50_1
L50_1 = "Tốt lắm. Hãy đến lại bất cứ khi nào ngài cần tôi!"
L49_1.Text_VTN = L50_1
L50_1 = "Gute Arbeit. Geben Sie mir jederzeit Bescheid, wenn Sie mich brauchen!"
L49_1.Text_DEU = L50_1
L50_1 = "Beau travail. Revenez me voir dès que vous aurez besoin de moi !"
L49_1.Text_FRA = L50_1
L50_1 = {}
L51_1 = "TUTORIAL_NEW_215_25"
L50_1.GameEventStrID = L51_1
L51_1 = 25
L50_1.ProcessKey = L51_1
L51_1 = 215
L50_1.EventID = L51_1
L50_1.EventType = "MESSAGE_BOX"
L51_1 = "어, 거… 거기 스톱, 스토옵!"
L50_1.Text_KOREA = L51_1
L51_1 = "AB_INVEN_ICON_NKM_NPC_NA_HEE_RIN"
L50_1.StringValue = L51_1
L51_1 = "あっ、そ……そこの方、ストップ！　ストーップ！"
L50_1.Text_JPN = L51_1
L51_1 = "S-s-stop the transporter! Stop! "
L50_1.Text_ENG = L51_1
L51_1 = "喂，那边……那边的先停一下！"
L50_1.Text_SCN = L51_1
L51_1 = "那個…等，等一下，停！"
L50_1.Text_TWN = L51_1
L51_1 = "ยะ-ยะ-หยุดยานขนส่งก่อน! หยุดดด!"
L50_1.Text_THA = L51_1
L51_1 = "D-d-dừng xe chuyên vận lại! Dừng lại!"
L50_1.Text_VTN = L51_1
L51_1 = "St-st-stoppen Sie den Transporter! Halt! "
L50_1.Text_DEU = L51_1
L51_1 = "A-A-Arrêtez le transporteur ! Stop ! "
L50_1.Text_FRA = L51_1
