L3_1 = "TUTORIAL_NEW_260_2"
L2_1.GameEventStrID = L3_1
L2_1.ProcessKey = 2
L3_1 = 260
L2_1.EventID = L3_1
L2_1.EventType = "MESSAGE_BOX"
L3_1 = "미나양, 본사에서 호출입니다.\n연구소로 와 달라던데요?"
L2_1.Text_KOREA = L3_1
L3_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L2_1.StringValue = L3_1
L3_1 = "ミナさん、本社からの呼び出しです。\n研究所に来てほしいとのことです。"
L2_1.Text_JPN = L3_1
L3_1 = [[
Mina, you've been summoned to HQ.
You're to report to the lab.]]
L2_1.Text_ENG = L3_1
L3_1 = "米娜小姐，总公司那边正在找你呢。\n好像让你去研究所一趟？"
L2_1.Text_SCN = L3_1
L3_1 = "米娜~~總公司正在找妳呢。\n好像是想要妳去研究所一趟？"
L2_1.Text_TWN = L3_1
L3_1 = "มีนา คุณถูกเรียกตัวไปยังศูนย์บัญชาการ\nคุณต้องไปรายงานตัวที่ห้องแล็บ"
L2_1.Text_THA = L3_1
L3_1 = "Mina, có lệnh gọi ngài đến HQ.\nHãy đến Lab."
L2_1.Text_VTN = L3_1
L3_1 = [[
Mina, du wurdest ins HQ gerufen.
Du sollst dich im Labor melden.]]
L2_1.Text_DEU = L3_1
L3_1 = "Mina, on te demande au QG.\nAu labo, plus précisément."
L2_1.Text_FRA = L3_1
