L4_1 = "TUTORIAL_NEW_260_3"
L3_1.GameEventStrID = L4_1
L3_1.ProcessKey = 3
L4_1 = 260
L3_1.EventID = L4_1
L3_1.EventType = "MESSAGE_BOX"
L4_1 = "… 연구소라고? 어디 있는데?"
L3_1.Text_KOREA = L4_1
L4_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L3_1.StringValue = L4_1
L4_1 = "……研究所？　どこにあるの？"
L3_1.Text_JPN = L4_1
L4_1 = "The lab? Where is it?"
L3_1.Text_ENG = L4_1
L4_1 = "……研究所吗？在哪里啊？"
L3_1.Text_SCN = L4_1
L4_1 = "… 研究所嗎？在哪裡啊？"
L3_1.Text_TWN = L4_1
L4_1 = "ห้องแล็บเหรอ? มันอยู่ไหนล่ะ?"
L3_1.Text_THA = L4_1
L4_1 = "Lab ư? Ở đâu vậy?"
L3_1.Text_VTN = L4_1
L4_1 = "Im Labor? Wo ist das?"
L3_1.Text_DEU = L4_1
L4_1 = "Le labo ? C'est où, ça ?"
L3_1.Text_FRA = L4_1
