L6_1 = 260
L5_1.EventID = L6_1
L6_1 = "TUTORIAL_TOUCH_UI"
L5_1.EventType = L6_1
L6_1 = "제가 안내해 드리죠.\n 본사는 전에 한번 가보셨죠?"
L5_1.Text_KOREA = L6_1
L6_1 = "Hamburger"
L5_1.StringValue = L6_1
L6_1 = "僕が案内します。\n本社は前に行ったことありますよね？"
L5_1.Text_JPN = L6_1
L6_1 = [[
Let me show you the way.
You've been to HQ before, right?]]
L5_1.Text_ENG = L6_1
L6_1 = "我来带路吧。\n之前去过总公司吧？"
L5_1.Text_SCN = L6_1
L6_1 = "我來帶路吧。\n妳之前去過總公司吧？"
L5_1.Text_TWN = L6_1
L6_1 = "เดี๋ยวฉันพาไป\nคุณเคยมาที่ศูนย์บัญชาการแล้วใช่มั้ย?"
L5_1.Text_THA = L6_1
L6_1 = "Tôi sẽ chỉ đường cho ngài.\nngài từng đến HQ rồi đúng không?"
L5_1.Text_VTN = L6_1
L6_1 = [[
Ich zeige dir den Weg.
Du warst schon mal im HQ, oder?]]
L5_1.Text_DEU = L6_1
L6_1 = "Je vais te montrer.\nTu es déjà venue au QG, non ?"
L5_1.Text_FRA = L6_1
