L12_1 = "연구소는 본사를 통해 입장 할 수 있답니다."
L11_1.Text_KOREA = L12_1
L12_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L11_1.StringValue = L12_1
L12_1 = "研究所は、本社から入ることができます。"
L11_1.Text_JPN = L12_1
L12_1 = "You can enter the lab from HQ."
L11_1.Text_ENG = L12_1
L12_1 = "研究所的入口就在总公司里。"
