L19_1.ProcessKey = 7
L20_1 = 262
L19_1.EventID = L20_1
L19_1.EventType = "MESSAGE_BOX"
L20_1 = "에이 너무 그러지 마세요. 같이 가 드리죠.\n재밌을 것 같거든요."
L19_1.Text_KOREA = L20_1
L20_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L19_1.StringValue = L20_1
L20_1 = "まぁまぁ、そんなこと言わないでください。ご一緒しますよ。\n面白そうなので。"
L19_1.Text_JPN = L20_1
L20_1 = [[
Come on, don't be frightened. I'll go with you.
I have a feeling something fun is about to happen.]]
L19_1.Text_ENG = L20_1
L20_1 = "哎呀，不是这样啦。我陪你去吧，\n应该会很有趣呢。"
L19_1.Text_SCN = L20_1
L20_1 = "哎呀，不是這樣啦。我陪妳去吧。\n應該會很有趣呢。"
L19_1.Text_TWN = L20_1
L20_1 = "ไม่เอาน่า อย่ากลัวเลย ฉันจะไปด้วย\nฉันรู้สึกตะหงิดๆ ว่าจะได้เห็นอะไรสนุกๆ นะ"
L19_1.Text_THA = L20_1
L20_1 = "Thôi nào, đừng sợ. Tôi sẽ đi với ngài.\nTôi có cảm giác sắp có chuyện vui xảy ra."
L19_1.Text_VTN = L20_1
L20_1 = "Keine Angst. Ich werde dich begleiten.\nIch glaube, das wird ein großer Spaß."
L19_1.Text_DEU = L20_1
L20_1 = "Ne t'inquiète pas. Je reste avec toi.\nJe sens que ça va être intéressant."
L19_1.Text_FRA = L20_1
L20_1 = {}
L21_1 = "TUTORIAL_NEW_262_8"
L20_1.GameEventStrID = L21_1
L20_1.ProcessKey = 8
L21_1 = 262
L20_1.EventID = L21_1
L20_1.EventType = "MESSAGE_BOX"
L21_1 = "…선배 정말 성격 나쁘구만."
L20_1.Text_KOREA = L21_1
L21_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L20_1.StringValue = L21_1
L21_1 = "……先輩、性格悪っ。"
L20_1.Text_JPN = L21_1
L21_1 = "You're nasty, do you know that?"
L20_1.Text_ENG = L21_1
L21_1 = "……前辈人真好。"
L20_1.Text_SCN = L21_1
L21_1 = "……前輩性格真糟呢。"
L20_1.Text_TWN = L21_1
L21_1 = "ใจร้ายชะมัด รู้ตัวมั้ย?"
L20_1.Text_THA = L21_1
L21_1 = "ngài thật là bựa đấy ngài có biết không?"
L20_1.Text_VTN = L21_1
L21_1 = "Du bist widerlich, weißt du das?"
L20_1.Text_DEU = L21_1
L21_1 = "T'es un sale type, tu le sais, ça ?"
L20_1.Text_FRA = L21_1
L21_1 = {}
L22_1 = "TUTORIAL_NEW_262_9"
L21_1.GameEventStrID = L22_1
L21_1.ProcessKey = 9
L22_1 = 262
L21_1.EventID = L22_1
L21_1.EventType = "MESSAGE_BOX"
L22_1 = "하하, 칭찬 고마워요 미나양."
L21_1.Text_KOREA = L22_1
L22_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L21_1.StringValue = L22_1
L22_1 = "ハハ、褒めてくれてありがとうございます、ミナさん。"
L21_1.Text_JPN = L22_1
L22_1 = "Hah hah. Thanks for the compliment."
L21_1.Text_ENG = L22_1
L22_1 = "哈哈，谢谢夸奖呢，米娜小姐。"
L21_1.Text_SCN = L22_1
L22_1 = "哈哈，多謝誇獎，米娜小姐。"
L21_1.Text_TWN = L22_1
L22_1 = "ฮ่าๆ ขอบคุณสำหรับคำชมนะ"
L21_1.Text_THA = L22_1
L22_1 = "Ha ha. Cảm ơn ngài đã qúa khen."
L21_1.Text_VTN = L22_1
L22_1 = "Haha. Danke für das Kompliment."
L21_1.Text_DEU = L22_1
L22_1 = "Ha ha ha. Merci du compliment."
L21_1.Text_FRA = L22_1
