L24_1 = "TUTORIAL_NEW_262_11"
L23_1.GameEventStrID = L24_1
L23_1.ProcessKey = 11
L24_1 = 262
L23_1.EventID = L24_1
L24_1 = "OFFICE_TOUCH"
L23_1.EventType = L24_1
L24_1 = "아, 저쪽에 사장님도 계시네요.\n조교님~ 유미나양 모셔왔습니다~"
L23_1.Text_KOREA = L24_1
L24_1 = 20101
L23_1.Value = L24_1
L24_1 = "あ、あちらに社長もいらっしゃるんですね。\n助手、ヤナギ・ミナさんをお連れしましたよ～。"
L23_1.Text_JPN = L24_1
L24_1 = [[
Ah, the Boss is over there.
Yoonjung, I've brought Mina.]]
L23_1.Text_ENG = L24_1
L24_1 = "啊，老板也在呢。\n助教大人~我已经把刘米娜亲请来了~"
L23_1.Text_SCN = L24_1
L24_1 = "啊，老闆也在呢。\n助教大人~我已經把米娜請來了~"
L23_1.Text_TWN = L24_1
L24_1 = "อ๊ะ บอสอยู่ทางนั้นแน่ะ\nยุนจอง ฉันพามีนามาแล้ว"
L23_1.Text_THA = L24_1
L24_1 = "A, Sếp kia rồi.\nYoonjung ơi, tôi đã đem Mina đến đây."
L23_1.Text_VTN = L24_1
L24_1 = "Ah, da drüben ist der Boss.\nYoonjung, hier ist Mina."
L23_1.Text_DEU = L24_1
L24_1 = "Ah, le patron est là.\nVoilà Mina, Yoonjung."
L23_1.Text_FRA = L24_1
