L29_1 = "TUTORIAL_NEW_263_5"
L28_1.GameEventStrID = L29_1
L28_1.ProcessKey = 5
L29_1 = 263
L28_1.EventID = L29_1
L28_1.EventType = "MESSAGE_BOX"
L29_1 = "자, 여기 앉으세요.\n조교야, 빨리 모시렴."
L28_1.Text_KOREA = L29_1
L29_1 = "AB_INVEN_ICON_NKM_NPC_PROFESSOR_OLIVIA"
L28_1.StringValue = L29_1
L29_1 = "さぁ、こちらにどうぞ。\n助手、早く応接して。"
L28_1.Text_JPN = L29_1
L29_1 = [[
Please have a seat.
Yoonjung, hurry up and help her.]]
L28_1.Text_ENG = L29_1
L29_1 = "好，请坐吧。\n助教，快来接待。"
L28_1.Text_SCN = L29_1
L29_1 = "好，請坐吧。\n助教，快來接待一下。"
L28_1.Text_TWN = L29_1
L29_1 = "นั่งสิ\nยุนจอง รีบมาช่วยเธอเร็ว"
L28_1.Text_THA = L29_1
L29_1 = "Mời ngồi.\nYoonjung, nhanh lên, giúp cô ấy một tay."
L28_1.Text_VTN = L29_1
L29_1 = [[
Bitte setz dich.
Yoonjung, beeil dich und hilf ihr.]]
L28_1.Text_DEU = L29_1
L29_1 = "Veuillez vous asseoir.\nQu'attendez-vous pour l'assister, Yoonjung ?"
L28_1.Text_FRA = L29_1
