L32_1 = "TUTORIAL_NEW_263_8"
L31_1.GameEventStrID = L32_1
L31_1.ProcessKey = 8
L32_1 = 263
L31_1.EventID = L32_1
L31_1.EventType = "MESSAGE_BOX"
L32_1 = "아무 설명 없이 뭐 하자는 건데?"
L31_1.Text_KOREA = L32_1
L32_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L31_1.StringValue = L32_1
L32_1 = "何の説明もなしにどういうつもり？"
L31_1.Text_JPN = L32_1
L32_1 = "Is anyone going to explain what's going on?"
L31_1.Text_ENG = L32_1
L32_1 = "也不告诉我是什么事，是想干什么？"
L31_1.Text_SCN = L32_1
L32_1 = "也不告訴我是什麼事，是想幹什麼？"
L31_1.Text_TWN = L32_1
L32_1 = "จะมีใครอธิบายมั้ยว่าเกิดอะไรขึ้น?"
L31_1.Text_THA = L32_1
L32_1 = "Có ai giải thích cho tôi biết chuyện gì đang xảy ra được không?"
L31_1.Text_VTN = L32_1
L32_1 = "Will mir niemand erklären, was los ist?"
L31_1.Text_DEU = L32_1
L32_1 = "Quelqu'un peut m'expliquer ce qui se passe ?"
L31_1.Text_FRA = L32_1
