L46_1 = "TUTORIAL_NEW_265_10"
L45_1.GameEventStrID = L46_1
L45_1.ProcessKey = 10
L46_1 = 265
L45_1.EventID = L46_1
L46_1 = "TUTORIAL_TOUCH_UI"
L45_1.EventType = L46_1
L46_1 = "아마도요. 그럼 실...시술을 시작하겠습니다."
L45_1.Text_KOREA = L46_1
L46_1 = "LIMITBREAK_START_BUTTON"
L45_1.StringValue = L46_1
L46_1 = "おそらくそうでしょう。\nそれでは、実……いや、施術を始めます……"
L45_1.Text_JPN = L46_1
L46_1 = "Probably. Now, let the experi—procedure begin."
L45_1.Text_ENG = L46_1
L46_1 = "应该是吧。那么开始……手术吧。"
L45_1.Text_SCN = L46_1
L46_1 = "應該是吧。那麼開始…手術吧。"
L45_1.Text_TWN = L46_1
L46_1 = "ก็อาจจะ เอาละ เรามาเริ่มการทด... กระบวนการกันดีกว่า"
L45_1.Text_THA = L46_1
L46_1 = "Chắc rồi. Còn bây giờ, hãy để thử ng—thủ thật bắt đầu."
L45_1.Text_VTN = L46_1
L46_1 = "Wahrscheinlich. Beginnen wir jetzt mit dem Experi– mit dem Verfahren."
L45_1.Text_DEU = L46_1
L46_1 = "En principe, oui. Bien, on va lancer l'expéri… euh, le traitement."
L45_1.Text_FRA = L46_1
