L49_1 = "TUTORIAL_NEW_265_13"
L48_1.GameEventStrID = L49_1
L49_1 = 13
L48_1.ProcessKey = L49_1
L49_1 = 265
L48_1.EventID = L49_1
L48_1.EventType = "MESSAGE_BOX"
L49_1 = "이건… 이전과 확실히 달라.\n굉장한데? 박사님!"
L48_1.Text_KOREA = L49_1
L49_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L48_1.StringValue = L49_1
L49_1 = "これは…今までと全然違う。\nすごい、博士！"
L48_1.Text_JPN = L49_1
L49_1 = [[
I'm... different from before.
Great job, Doctor!]]
L48_1.Text_ENG = L49_1
L49_1 = "这个……和以前完全不一样。\n很厉害啊？博士！"
L48_1.Text_SCN = L49_1
L49_1 = "這個…和以前完全不一樣。\n很厲害喔，博士！"
L48_1.Text_TWN = L49_1
L49_1 = "ฉัน... รู้สึกต่างไปจากเดิม\nสุดยอดเลยค่ะหมอ!"
L48_1.Text_THA = L49_1
L49_1 = "Tôi... đã khác trước rồi.\nThật tuyệt vời, Tiến Sĩ!"
L48_1.Text_VTN = L49_1
L49_1 = "Ich … fühle mich anders als zuvor.\nGut gemacht, Doktor!"
L48_1.Text_DEU = L49_1
L49_1 = "Je me sens… différente.\nBien joué, docteur !"
L48_1.Text_FRA = L49_1
L49_1 = {}
L50_1 = "TUTORIAL_NEW_265_14"
L49_1.GameEventStrID = L50_1
L50_1 = 14
L49_1.ProcessKey = L50_1
L50_1 = 265
L49_1.EventID = L50_1
L49_1.EventType = "MESSAGE_BOX"
L50_1 = "교. 수. 랍니다, 미나양.\n후후, 그리고 아직 끝이 아니라구요."
L49_1.Text_KOREA = L50_1
L50_1 = "AB_INVEN_ICON_NKM_NPC_PROFESSOR_OLIVIA"
L49_1.StringValue = L50_1
L50_1 = "「教授」です、ミナさん。\nふふ。それに、まだ終わってませんよ。"
L49_1.Text_JPN = L50_1
L50_1 = [[
Please call me Professor, Mina.
And I'm not done with you yet.]]
L49_1.Text_ENG = L50_1
L50_1 = "是教.授，米娜小姐。\n哈哈，而且还没结束呢。"
L49_1.Text_SCN = L50_1
L50_1 = "請叫我教．授，米娜小姐。\n呵呵，而且還沒結束呢。"
L49_1.Text_TWN = L50_1
L50_1 = "เรียกฉันว่าศาสตราจารย์นะ มีนา\nและฉันก็ยังจัดการกับคุณไม่เสร็จเลย"
L49_1.Text_THA = L50_1
L50_1 = "Hãy gọi tôi là Giáo Sư, Mina.\nMà tôi vẫn chưa xong đâu."
L49_1.Text_VTN = L50_1
L50_1 = [[
Mina, bitte nenne mich Professorin.
Und ich bin noch nicht mit dir fertig.]]
L49_1.Text_DEU = L50_1
L50_1 = "Pas « docteur », Mina. « Professeur. »\nEt je n'en ai pas encore terminé avec vous."
L49_1.Text_FRA = L50_1
