L4_1.EventType = "HIGHLIGHT_UI"
L5_1 = "동일한 유닛을 이용해, 최대 여섯 번의 전술 업데이트를 할 수 있습니다."
L4_1.Text_KOREA = L5_1
L5_1 = "Btn"
L4_1.StringValue = L5_1
L5_1 = "同じユニットを使って、最大6回の戦術アップデートができます。"
L4_1.Text_JPN = L5_1
L5_1 = "You can use identical units to perform up to six Tactical Updates."
L4_1.Text_ENG = L5_1
L5_1 = "可使用相同的单位，最多进行六次战术升级。"
L4_1.Text_SCN = L5_1
L5_1 = "利用相同的單位，最多可進行6次戰術升級。"
L4_1.Text_TWN = L5_1
L5_1 = "คุณใช้หน่วยรบที่เหมือนกันมาอัปเดตเชิงยุทธวิธีได้หกขั้นนะคะ"
L4_1.Text_THA = L5_1
L5_1 = "Có thể sử dụng các đơn vị giống hệt nhau để thực hiện tối đa sáu lần Cập Nhật Chiến Thuật."
L4_1.Text_VTN = L5_1
L5_1 = "Mit derselben Einheit können bis zu sechs taktische Updates vorgenommen werden."
L4_1.Text_DEU = L5_1
L5_1 = "Vous pouvez utiliser jusqu'à 6 mises à jour tactiques en utilisant les doublons d'une même unité."
L4_1.Text_FRA = L5_1
