L5_1.Text_THA = L6_1
L6_1 = "Mỗi cấp độ Cập Nhật Chiến Thuật đều mang thêm các thông số bổ sung."
L5_1.Text_VTN = L6_1
L6_1 = "Es werden zusätzliche Werte für jede Stufe des Taktischen Updates erhalten."
