L18_1 = "TUTORIAL_NEW_250_7"
L17_1.GameEventStrID = L18_1
L17_1.ProcessKey = 7
L18_1 = 250
L17_1.EventID = L18_1
L17_1.EventType = "HIGHLIGHT_UI"
L18_1 = "기술훈련은 훈련 자료를 토대로 맞춤형 기술향상 플랜을 제공합니다."
L17_1.Text_KOREA = L18_1
L18_1 = "Training_Cost"
L17_1.StringValue = L18_1
L18_1 = "スキル訓練は訓練資料に基づいたオーダーメイド型スキル向上プランを提供します……"
L17_1.Text_JPN = L18_1
L18_1 = "We've prepared a customized plan for you, based on your training data."
L17_1.Text_ENG = L18_1
L18_1 = "根据训练资料内容，制定专门的技能强化计划。"
L17_1.Text_SCN = L18_1
L18_1 = "根據訓練資料內容，制定專門的技能強化計畫。"
L17_1.Text_TWN = L18_1
L18_1 = "เราเตรียมแผนการที่ทำขึ้นสำหรับคุณโดยเฉพาะ โดยอิงจากข้อมูลการฝึกของคุณ"
L17_1.Text_THA = L18_1
L18_1 = "Chúng tôi đã chuẩn bị kế hoạch tùy chỉnh cho ngài, căn cứ theo dữ liệu huấn luyện của ngài."
L17_1.Text_VTN = L18_1
L18_1 = "Wir haben basierend auf deinen Trainingsdaten einen speziellen Plan für dich aufgestellt."
L17_1.Text_DEU = L18_1
L18_1 = "On vous a préparé un programme personnalisé basé sur vos résultats d'entraînement."
L17_1.Text_FRA = L18_1
L18_1 = {}
L19_1 = "TUTORIAL_NEW_250_8"
L18_1.GameEventStrID = L19_1
L18_1.ProcessKey = 8
L19_1 = 250
L18_1.EventID = L19_1
L19_1 = "TUTORIAL_TOUCH_UI"
L18_1.EventType = L19_1
L19_1 = "미나양, 스크린에 뜬 대로 해 보세요."
L18_1.Text_KOREA = L19_1
L19_1 = "TRAINING_START_BUTTON"
L18_1.StringValue = L19_1
L19_1 = "ミナさん、スクリーンに表示されたとおりにしてみてください。"
L18_1.Text_JPN = L19_1
L19_1 = "Mina, follow the instructions on the screen."
L18_1.Text_ENG = L19_1
L19_1 = "米娜小姐，跟着屏幕上的提示去做一下吧。"
L18_1.Text_SCN = L19_1
L19_1 = "米娜小姐，跟著螢幕上的提示去做一下吧。"
L18_1.Text_TWN = L19_1
L19_1 = "มีนา ทำตามคำสั่งบนหน้าจอนะ"
L18_1.Text_THA = L19_1
L19_1 = "Mina, hãy làm theo hướng dẫn trên màn hình."
L18_1.Text_VTN = L19_1
L19_1 = "Mina, befolge die Anweisungen auf dem Bildschirm."
L18_1.Text_DEU = L19_1
L19_1 = "Veuillez suivre les instructions sur l'écran, Mina."
L18_1.Text_FRA = L19_1
