L25_1 = 14
L24_1.ProcessKey = L25_1
L25_1 = 250
L24_1.EventID = L25_1
L24_1.EventType = "MESSAGE_BOX"
L25_1 = "하아…네, 올리비에 교수님."
L24_1.Text_KOREA = L25_1
L25_1 = "AB_INVEN_ICON_NKM_NPC_ASSISTANT_LEE_YOON_JUNG"
L24_1.StringValue = L25_1
L25_1 = "は……はい、オリヴィエ教授。"
L24_1.Text_JPN = L25_1
L25_1 = "*Sigh* Sure, Professor Olivie."
L24_1.Text_ENG = L25_1
L25_1 = "哎……是的，奥利维亚教授。"
L24_1.Text_SCN = L25_1
L25_1 = "唉…是的，奧利維亞教授。"
L24_1.Text_TWN = L25_1
L25_1 = "*เฮ้อ* แน่นอนค่ะ ศาสตราจารย์โอลิวี่"
L24_1.Text_THA = L25_1
L25_1 = "*Thở dài* Được rồi, Giáo Sư Olivie."
L24_1.Text_VTN = L25_1
L25_1 = "*Seufz* Sicher, Professorin Olivie."
L24_1.Text_DEU = L25_1
L25_1 = "*soupir* Si, professeur Olivie. Bien sûr."
