L28_1 = 345
L27_1.EventID = L28_1
L28_1 = "TUTORIAL_TOUCH_UI"
L27_1.EventType = L28_1
L28_1 = "안녕하세요, 사장님.\n모의작전 프로그램이 확장되어서 보고 드립니다."
L27_1.Text_KOREA = L28_1
L28_1 = "NKM_UI_OPERATION_MENU_02"
L27_1.StringValue = L28_1
L28_1 = "こんにちは、社長。\n模擬作戦プログラムが拡張されたため、ご報告します。"
L27_1.Text_JPN = L28_1
L28_1 = [[
Good day, Boss.
The Simulation program has been expanded.]]
L27_1.Text_ENG = L28_1
L28_1 = "您好，老板。\n模拟作战的内容扩充了，特此向您报告。"
L27_1.Text_SCN = L28_1
L28_1 = "老闆好～\n跟老闆報告一下，模擬戰計畫擴大了。"
L27_1.Text_TWN = L28_1
L28_1 = "สวัสดีค่ะ บอส\nเราเพิ่งขยับขยายโครงการปฏิบัติการจำลอง"
L27_1.Text_THA = L28_1
L28_1 = "Chúc một ngày tốt lành, Ông Chủ.\nChương trình Mô Phỏng Tác Chiến đã được mở rộng."
L27_1.Text_VTN = L28_1
L28_1 = [[
Guten Tag, Boss.
Das Simulationsprogramm wurde erweitert.]]
L27_1.Text_DEU = L28_1
L28_1 = "Bonjour, monsieur.\nLe programme de simulation a été amélioré."
L27_1.Text_FRA = L28_1
