L29_1 = "TUTORIAL_NEW_345_4"
L28_1.GameEventStrID = L29_1
L28_1.ProcessKey = 4
L29_1 = 345
L28_1.EventID = L29_1
L28_1.EventType = "MESSAGE_BOX"
L29_1 = "<color=#ffd34c>대공 훈련</color>은 적성핵을 입수할 수 있는 필수 훈련 코스라고 하네요."
L28_1.Text_KOREA = L29_1
L29_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L28_1.StringValue = L29_1
L29_1 = "<color=#ffd34c>対空訓練</color>は適性コアを入手できる必須訓練コースらしいです。"
L28_1.Text_JPN = L29_1
L29_1 = "<color=#ffd34c>Anti-air Training</color> is an essential training course that offers Aptitude Cores."
L28_1.Text_ENG = L29_1
L29_1 = "<color=#ffd34c>防空训练</color>是可以获得适能核的必备训练课程。"
L28_1.Text_SCN = L29_1
L29_1 = "<color=#ffd34c>防空訓練</color>是獲得適能核不可或缺的訓練課程！"
L28_1.Text_TWN = L29_1
L29_1 = "<color=#ffd34c>การฝึกต้านอากาศยาน</color>เป็นการฝึกสำคัญที่ให้แกนถนัด"
L28_1.Text_THA = L29_1
L29_1 = "<color=#ffd34c>Huấn Luyện Phòng Không</color> là khóa huấn luyện quan trọng giúp thu thập Lõi APT."
L28_1.Text_VTN = L29_1
L29_1 = "Die <color=#ffd34c>Flugabwehrausbildung</color> ist ein wichtiger Kurs, der Eignungskerne anbietet."
L28_1.Text_DEU = L29_1
L29_1 = "L'<color=#ffd34c>entraînement antiaérien</color> est un programme essentiel qui permet d'obtenir des noyaux d'aptitude."
L28_1.Text_FRA = L29_1
L29_1 = {}
