L29_1.GameEventStrID = L30_1
L29_1.ProcessKey = 5
L30_1 = 345
L29_1.EventID = L30_1
L29_1.EventType = "MESSAGE_BOX"
L30_1 = "<color=#ffd34c>올리비에</color> 교수님이 좋아하시겠는걸요?"
L29_1.Text_KOREA = L30_1
L30_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L29_1.StringValue = L30_1
L30_1 = "<color=#ffd34c>オリヴィエ</color>教授も喜びそうですね。"
L29_1.Text_JPN = L30_1
L30_1 = "Professor <color=#ffd34c>Olivie Park</color> would love this."
L29_1.Text_ENG = L30_1
L30_1 = "<color=#ffd34c>奥利维亚</color>教授应该会很喜欢。"
L29_1.Text_SCN = L30_1
L30_1 = "<color=#ffd34c>奧利維亞</color>教授一定會喜歡！"
L29_1.Text_TWN = L30_1
L30_1 = "ศาสตราจารย์<color=#ffd34c>โอลิวี่ พัค</color>ต้องชอบแน่"
L29_1.Text_THA = L30_1
L30_1 = "Giáo sư <color=#ffd34c>Olivie Park</color> sẽ thích điều này."
L29_1.Text_VTN = L30_1
L30_1 = "Professor <color=#ffd34c>Olivie Park</color> wäre ganz begeistert."
L29_1.Text_DEU = L30_1
L30_1 = "La professeure <color=#ffd34c>Olivie Park</color> adorerait ça."
L29_1.Text_FRA = L30_1
