L32_1[L33_1] = L34_1
L33_1 = "TUTORIAL_NEW_325_3"
L32_1.GameEventStrID = L33_1
L32_1.ProcessKey = 3
L33_1 = 325
L32_1.EventID = L33_1
L32_1.EventType = "MESSAGE_BOX"
L33_1 = "사장님 이번에 수행하는 작전 의 <color=#ffd34c>[렐릭 장비]</color> 는 <color=#ffd34c>[잠재개방]</color> 이라는 특수한 가공 처리가 필요해."
L32_1.Text_KOREA = L33_1
L33_1 = "AB_INVEN_ICON_NKM_NPC_BLACKSMITH_ANASTASIA"
L32_1.StringValue = L33_1
L33_1 = "社長、今回遂行する作戦の<color=#ffd34c>[レリック装備]</color>は<color=#ffd34c>[潜在開放]</color>という特殊な加工処理が必要よ。"
L32_1.Text_JPN = L33_1
L33_1 = "Boss, the <color=#ffd34c>[Relic gear]</color> for your upcoming operation requires a special treatment to unlock its <color=#ffd34c>[Latent Abilities]</color>."
L32_1.Text_ENG = L33_1
L33_1 = "老板，这次作战要使用的<color=#ffd34c>圣物装备</color>，需要进行<color=#ffd34c>【开启潜能】</color>的特殊加工处理。"
L32_1.Text_SCN = L33_1
L33_1 = "老闆此次作戰中的<color=#ffd34c>[遺跡裝備]</color>需要進行<color=#ffd34c>[開放潛能]</color>的特殊加工。"
L32_1.Text_TWN = L33_1
L33_1 = "บอสคะ <color=#ffd34c>[อุปกรณ์เครื่องราง]</color> สำหรับปฏิบัติการต่อไปของคุณต้องได้รับการดำเนินการพิเศษเพื่อปลดล็อก <color=#ffd34c>[พลังแฝง]</color> ของมัน"
L32_1.Text_THA = L33_1
L33_1 = "Thưa ông chủ, <color=#ffd34c>[trang bị Di Tích]</color> cho tác chiến sắp tới của ngài cần biện pháp xử lý đặc biệt để mở khóa <color=#ffd34c>[Khả Băng Tiềm Tàng]</color> của nó."
L32_1.Text_VTN = L33_1
L33_1 = "Boss, die <color=#ffd34c>[Relikt-Ausrüstung]</color> für deine bevorstehende Operation muss speziell behandelt werden, damit die <color=#ffd34c>[verborgenen Fähigkeiten]</color> entsperrt werden."
L32_1.Text_DEU = L33_1
L33_1 = "Monsieur, l'<color=#ffd34c>[équipement de relique]</color> pour votre prochaine opération a besoin d'un traitement spécial pour débloquer ses <color=#ffd34c>[capacités latentes]</color>."
L32_1.Text_FRA = L33_1
