L34_1 = "TUTORIAL_NEW_325_4"
L33_1.GameEventStrID = L34_1
L33_1.ProcessKey = 4
L34_1 = 325
L33_1.EventID = L34_1
L33_1.EventType = "MESSAGE_BOX"
L34_1 = "마침 관리국에서 견본품을 보내줬는데, 한번 확인해보겠어?"
L33_1.Text_KOREA = L34_1
L34_1 = "AB_INVEN_ICON_NKM_NPC_BLACKSMITH_ANASTASIA"
L33_1.StringValue = L34_1
L34_1 = "ちょうど管理局からサンプルが届いているから、見てみる？"
L33_1.Text_JPN = L34_1
L34_1 = "We've just received sample gear from the Administration. Want to check?"
L33_1.Text_ENG = L34_1
L34_1 = "正好管理局发来了样品，要查看一下吗？"
L33_1.Text_SCN = L34_1
L34_1 = "正巧管理局有送來一批樣本，要看一下嗎？"
L33_1.Text_TWN = L34_1
L34_1 = "เราเพิ่งได้รับอุปกรณ์ตัวอย่างมาจากองค์การบริหารโลก อยากมาดูมั้ยคะ?"
L33_1.Text_THA = L34_1
L34_1 = "Chúng tôi vừa nhận được trang bị mẫu từ Cục Quản Lý. Ngài muốn kiểm tra qua không?"
L33_1.Text_VTN = L34_1
L34_1 = "Wir haben eine Musterausrüstung von der Administration erhalten. Willst du sie dir ansehen?"
L33_1.Text_DEU = L34_1
L34_1 = "Nous avons reçu des pièces d'équipement de la part de l'Administration. Vous voulez regarder ?"
L33_1.Text_FRA = L34_1
