L46_1.EventID = L47_1
L47_1 = "TEXT"
L46_1.EventType = L47_1
L47_1 = "[장비 튜닝] 을 통해 장비의 [부가 옵션] 을 향상시킬 수 있습니다."
L46_1.Text_KOREA = L47_1
L47_1 = "[装備チューニング]によって装備の[付加オプション]を向上させることができます。"
L46_1.Text_JPN = L47_1
L47_1 = "You can increase gear's [additional options] through [Gear Tuning]."
L46_1.Text_ENG = L47_1
L47_1 = "通过[装备改造]，可以提升装备的[附加选项]。"
L46_1.Text_SCN = L47_1
L47_1 = "通過[裝備改造]，可以提升裝備的[附加屬性]。"
L46_1.Text_TWN = L47_1
L47_1 = "คุณสามารถเพิ่ม [ออปชั่นเพิ่มเติม] ของอุปกรณ์ได้ผ่าน [การปรับจูนอุปกรณ์]"
L46_1.Text_THA = L47_1
L47_1 = "ngài có thể tăng [tùy chọn bổ sung] của trang bị thông qua [Hiệu Chỉnh Trang Bị]."
L46_1.Text_VTN = L47_1
L47_1 = "Mit der [Ausrüstungsanpassung] kannst du die [Zusatzoptionen] von Ausrüstung verbessern."
L46_1.Text_DEU = L47_1
L47_1 = "La [personnalisation d'équipement] vous permet d'en améliorer les [options additionnelles]."
L46_1.Text_FRA = L47_1
