L48_1 = 520
L47_1.EventID = L48_1
L47_1.EventType = "HIGHLIGHT_UI"
L48_1 = "[정밀화] 를 통해, 부가 옵션의 수치를 높여주는 작업이 가능합니다."
L47_1.Text_KOREA = L48_1
L48_1 = "SUBMENU_TUNING_PRECISIOIN_ON"
L47_1.StringValue = L48_1
L48_1 = "[精密化]を通じて付加オプションの数値を上げることができます。"
L47_1.Text_JPN = L48_1
L48_1 = "[Precision] increases additional option values."
L47_1.Text_ENG = L48_1
L48_1 = "可以通过进行[精密化]，提升附加选项。"
L47_1.Text_SCN = L48_1
L48_1 = "可以通過進行[精密化]，提升附加屬性。"
L47_1.Text_TWN = L48_1
L48_1 = "[ความแม่นยำ] จะเพิ่มค่าออปชั่นเพิ่มเติม"
L47_1.Text_THA = L48_1
L48_1 = "[Độ Chính Xác] sẽ tăng các giá trị tùy chọn bổ sung."
L47_1.Text_VTN = L48_1
L48_1 = "[Präzision] erhöht die Werte der Zusatzoption."
L47_1.Text_DEU = L48_1
L48_1 = "L'[affinage] augmente les variables d'une option additionnelle."
L47_1.Text_FRA = L48_1
