L49_1 = 520
L48_1.EventID = L49_1
L49_1 = "TUTORIAL_TOUCH_UI"
L48_1.EventType = L49_1
L49_1 = "[옵션 변경]은 장비의 부가 옵션의 종류를 바꿔주는 작업입니다."
L48_1.Text_KOREA = L49_1
L49_1 = "NKM_UI_FACTORY_TUNING_OPTION_CHANGE"
L48_1.StringValue = L49_1
L49_1 = "[オプション変更]は、装備の付加オプションの種類を変更できます。"
L48_1.Text_JPN = L49_1
L49_1 = "[Option Change] changes the types of additional gear options."
L48_1.Text_ENG = L49_1
L49_1 = "[更改选项]可以改变装备附加选项的类型。"
L48_1.Text_SCN = L49_1
L49_1 = "[更改屬性]可以變更裝備附加屬性的類型。"
L48_1.Text_TWN = L49_1
L49_1 = "[การเปลี่ยนออปชั่น] จะเปลี่ยนประเภทของออปชั่นอุปกรณ์เสริม"
L48_1.Text_THA = L49_1
L49_1 = "[Thay Đổi Tùy Chọn] sẽ thay đổi loại tùy chọn trang bị bổ sung."
L48_1.Text_VTN = L49_1
L49_1 = "[Option ändern] ändert die Typen der Zusatzoptionen von Ausrüstung."
L48_1.Text_DEU = L49_1
L49_1 = "Le [changement d'option] modifie le type des options d'équipement additionnelles."
L48_1.Text_FRA = L49_1
