L3_1 = "TUTORIAL_NEW_301_3"
L2_1.GameEventStrID = L3_1
L2_1.ProcessKey = 3
L3_1 = 301
L2_1.EventID = L3_1
L3_1 = "TEXT"
L2_1.EventType = L3_1
L3_1 = "전략전은 미리 편성한 소대와 전투를 겨루게 됩니다."
L2_1.Text_KOREA = L3_1
L3_1 = "戦略戦ではあらかじめ編成しておいた小隊と戦闘を行います。"
L2_1.Text_JPN = L3_1
L3_1 = "In Strategy Battle, users compete in automatic battles between preselected squads."
L2_1.Text_ENG = L3_1
L3_1 = "在战略对抗战中，将与对方预设好的小队进行战斗。"
L2_1.Text_SCN = L3_1
L3_1 = "戰略對抗戰中將和已編組的小隊進行較量。"
L2_1.Text_TWN = L3_1
L3_1 = "ในศึกยุทธวิธี ผู้ใช้จะแข่งขันในการต่อสู้อัตโนมัติระหว่างหน่วยที่เลือกไว้ล่วงหน้า"
L2_1.Text_THA = L3_1
L3_1 = "ในการต่อสู้ คุณจะต้องแข่งขันกับหน่วยที่คู่ต่อสู้ตั้งไว้ล่วงหน้า \n"
L2_1.Text_VTN = L3_1
L3_1 = "Im Strategiekampf treten Spieler in Kämpfen gegen vorausgewählte Trupps an."
L2_1.Text_DEU = L3_1
L3_1 = "En combat stratégique, les joueurs s'affrontent dans des combats automatiques entre des escouades préalablement choisies."
L2_1.Text_FRA = L3_1
L3_1 = {}
L4_1 = "TUTORIAL_NEW_301_4"
L3_1.GameEventStrID = L4_1
L3_1.ProcessKey = 4
L4_1 = 301
L3_1.EventID = L4_1
L3_1.EventType = "HIGHLIGHT_UI"
L4_1 = "도전 가능한 상대 목록과 편성 정보를 확인하세요."
L3_1.Text_KOREA = L4_1
L4_1 = "NKM_UI_GAUNTLET_RANK_ASYNC_SCROLL"
L3_1.StringValue = L4_1
L4_1 = "挑戦可能な相手リストと編成情報をご確認ください。"
L3_1.Text_JPN = L4_1
L4_1 = "You can check and select the currently available opponents and their squads,"
L3_1.Text_ENG = L4_1
L4_1 = "可事先查看当前的对手及其小队，进行挑战。"
L3_1.Text_SCN = L4_1
L4_1 = "可以事先查看當前的對手及對方的小隊編組，進行挑戰。"
L3_1.Text_TWN = L4_1
L4_1 = "คุณสามารถดูและเลือกศัตรูกับหน่วยศัตรูที่มีอยู่ตอนนี้"
L3_1.Text_THA = L4_1
L4_1 = "ngài có thể kiểm tra và chọn các đối thủ hiện có thể chọn và tiểu đội của họ,"
L3_1.Text_VTN = L4_1
L4_1 = "Du kannst die derzeit verfügbaren Gegner und ihre Trupps überprüfen und auswählen"
L3_1.Text_DEU = L4_1
L4_1 = "Vous pouvez consulter et choisir les adversaires actuellement disponibles ainsi que leurs escouades."
L3_1.Text_FRA = L4_1
