L5_1 = "TUTORIAL_NEW_301_5"
L4_1.GameEventStrID = L5_1
L4_1.ProcessKey = 5
L5_1 = 301
L4_1.EventID = L5_1
L4_1.EventType = "HIGHLIGHT_UI"
L5_1 = "내 방어 소대는 이곳에서 구성할 수 있습니다."
L4_1.Text_KOREA = L5_1
L5_1 = "NKM_UI_GAUNTLET_DEFENSEDECK_MAKE"
L4_1.StringValue = L5_1
L5_1 = "自分の防御小隊はこちらで編成できます。"
L4_1.Text_JPN = L5_1
L5_1 = "and also create an impregnable Defense squad for yourself."
L4_1.Text_ENG = L5_1
L5_1 = "并可以编辑一支属于您的防守小队。"
L4_1.Text_SCN = L5_1
L5_1 = "並可以編組一支屬於您的防守小隊。"
L4_1.Text_TWN = L5_1
L5_1 = "แล้วก็สร้างหน่วยตั้งรับที่ไม่มีใครเจาะทะลุได้ของตัวเอง"
L4_1.Text_THA = L5_1
L5_1 = "và đồng thời tạo ra một tiểu đội Phòng Thủ bất khả đánh bại cho bản thân ngài."
L4_1.Text_VTN = L5_1
L5_1 = "und deinen eigenen unbezwingbaren Verteidigungstrupp erstellen."
L4_1.Text_DEU = L5_1
L5_1 = "Il vous est également possible de créer votre propre escouade défensive."
L4_1.Text_FRA = L5_1
