L8_1.EventID = L9_1
L9_1 = "TEXT"
L8_1.EventType = L9_1
L9_1 = "랭크전에 오신 것을 환영합니다."
L8_1.Text_KOREA = L9_1
L9_1 = "ランク戦へようこそ。"
L8_1.Text_JPN = L9_1
L9_1 = "Welcome to the Gauntlet."
L8_1.Text_ENG = L9_1
L9_1 = "欢迎来到圣铠。"
L8_1.Text_SCN = L9_1
L9_1 = "歡迎來到聖鎧。"
L8_1.Text_TWN = L9_1
L9_1 = "ยินดีต้อนรับสู่กอนต์เล็ต"
L8_1.Text_THA = L9_1
L9_1 = "Chào mừng đến với Găng Tay."
L8_1.Text_VTN = L9_1
L9_1 = "Willkommen zur Fehde."
L8_1.Text_DEU = L9_1
L9_1 = "Bienvenue en compétition."
L8_1.Text_FRA = L9_1
