L33_1 = "TUTORIAL_NEW_290_19"
L32_1.GameEventStrID = L33_1
L33_1 = 19
L32_1.ProcessKey = L33_1
L33_1 = 290
L32_1.EventID = L33_1
L33_1 = "TUTORIAL_SELECT_UNITLIST_UNIT"
L32_1.EventType = L33_1
L33_1 = "뭐야 왜 또 나야?"
L32_1.Text_KOREA = L33_1
L33_1 = 1001
L32_1.Value = L33_1
L33_1 = "HIGHEST_LEVEL,INCLUDE_DECKED_UNIT,INCLUDE_LOCKED_UNIT"
L32_1.StringValue = L33_1
L33_1 = "何？何でまた私なの？"
L32_1.Text_JPN = L33_1
L33_1 = "What? Me again?"
L32_1.Text_ENG = L33_1
L33_1 = "什么呀，又是我？"
L32_1.Text_SCN = L33_1
L33_1 = "什麼，又是我？"
L32_1.Text_TWN = L33_1
L33_1 = "ว่าไงนะ? ฉันอีกแล้วเหรอ?"
L32_1.Text_THA = L33_1
L33_1 = "Cái gì? Lại là tôi à?"
L32_1.Text_VTN = L33_1
L33_1 = "Was? Schon wieder ich?"
L32_1.Text_DEU = L33_1
L33_1 = "Mais… Pourquoi toujours moi ?"
L32_1.Text_FRA = L33_1
