L39_1 = "TUTORIAL_NEW_110_2"
L38_1.GameEventStrID = L39_1
L38_1.ProcessKey = 2
L39_1 = 110
L38_1.EventID = L39_1
L39_1 = "TEXT"
L38_1.EventType = L39_1
L39_1 = "<color=#ffd34c>전역</color>은 한 번에 여러 소대를 이용해 승리 목표를 달성하는 모드입니다."
L38_1.Text_KOREA = L39_1
L39_1 = "<color=#ffd34c>戦域</color>は一度に複数の小隊を使い、勝利目標を達成するモードです。"
L38_1.Text_JPN = L39_1
L39_1 = "The <color=#ffd34c>Battlefield</color> is a mode in which you use multiple squads to meet the winning conditions."
L38_1.Text_ENG = L39_1
L39_1 = "<color=#ffd34c>战役</color>是一次利用多个小队达成胜利目标的模式。"
L38_1.Text_SCN = L39_1
L39_1 = "<color=#ffd34c>戰役</color>是可以一次利用多個小隊達成勝利的模式。"
L38_1.Text_TWN = L39_1
L39_1 = "<color=#ffd34c>สนามรบ</color>คือโหมดที่คุณสามารถใช้หลายหน่วยเพื่อให้ตรงตามเงื่อนไขการชนะ"
L38_1.Text_THA = L39_1
L39_1 = "<color=#ffd34c>Chiến trường</color> là chế độ mà ngài có thể sử dụng nhiều tiểu đội để hoàn thành điều kiện chiến thắng."
L38_1.Text_VTN = L39_1
L39_1 = "Im <color=#ffd34c>Schlachtfeldmodus</color> setzen sie mehrere Trupps ein, um die Siegesvoraussetzungen zu erfüllen."
L38_1.Text_DEU = L39_1
L39_1 = "Le <color=#ffd34c>champ de bataille</color> est un mode dans lequel vous utilisez plusieurs escouades pour remplir les conditions de victoire."
L38_1.Text_FRA = L39_1
