L31_1.ProcessKey = L32_1
L32_1 = 204
L31_1.EventID = L32_1
L31_1.EventType = "MESSAGE_BOX"
L32_1 = "새로운 아이가 우리 격납고에 들어왔네요!"
L31_1.Text_KOREA = L32_1
L32_1 = "AB_INVEN_ICON_NKM_NPC_NA_HEE_RIN"
L31_1.StringValue = L32_1
L32_1 = "新しい子が我が格納庫に入りましたね！"
L31_1.Text_JPN = L32_1
L32_1 = "A new ship has joined our Hangar!"
L31_1.Text_ENG = L32_1
L32_1 = "新舰船已经入库了！"
L31_1.Text_SCN = L32_1
L32_1 = "有新生兒進到我們的機庫囉!"
L31_1.Text_TWN = L32_1
L32_1 = "ยานรบลำใหม่อยู่ในโรงจอดยานของเราแล้ว!"
L31_1.Text_THA = L32_1
L32_1 = "Một con tàu mới đã đến Xưởng bảo lưu của chúng ta!"
L31_1.Text_VTN = L32_1
L32_1 = "Wir haben ein neues Schiff im Hangar!"
L31_1.Text_DEU = L32_1
L32_1 = "Un nouveau vaisseau rejoint notre hangar !"
L31_1.Text_FRA = L32_1
