L49_1.EventType = "MESSAGE_BOX"
L50_1 = "사장님, <color=#ffd34c>전역의 작전 목표</color>에 대해서는 확인 하셨나요?"
L49_1.Text_KOREA = L50_1
L50_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L49_1.StringValue = L50_1
L50_1 = "社長、<color=#ffd34c>戦域の作戦目標</color>のチェックはお済みでしょうか？"
L49_1.Text_JPN = L50_1
L50_1 = "Boss, did you check the <color=#ffd34c>Battlefield Objectives</color>?"
L49_1.Text_ENG = L50_1
L50_1 = "老板，您确认过本次<color=#ffd34c>战役的作战目标</color>了吗？"
L49_1.Text_SCN = L50_1
L50_1 = "老闆，你確認過<color=#ffd34c>戰役的作戰目標</color>了嗎？"
L49_1.Text_TWN = L50_1
L50_1 = "บอสคะ คุณได้ดู<color=#ffd34c>เป้าหมายสนามรบ</color>รึยังคะ?"
L49_1.Text_THA = L50_1
L50_1 = "Ông Chủ, ngài đã kiểm tra <color=#ffd34c>Mục Tiêu Chiến Trường</color> chưa?"
L49_1.Text_VTN = L50_1
L50_1 = "Boss, haben Sie sich schon die <color=#ffd34c>Schlachtfeldziele</color> angesehen?"
L49_1.Text_DEU = L50_1
L50_1 = "Monsieur, avez-vous consulté les <color=#ffd34c>objectifs du champ de bataille</color> ?"
L49_1.Text_FRA = L50_1
