L2_1 = "TUTORIAL_NEW_470_6"
L1_1.GameEventStrID = L2_1
L1_1.ProcessKey = 6
L2_1 = 470
L1_1.EventID = L2_1
L1_1.EventType = "HIGHLIGHT_UI"
L2_1 = "전역의 <color=#ffd34c>승리 목표</color>와 <color=#ffd34c>패배 조건</color>은 항상 확인해 두시는게 좋아요."
L1_1.Text_KOREA = L2_1
L2_1 = "NUF_WARFARE_INFO_MEDALINFO_DETAIL"
L1_1.StringValue = L2_1
L2_1 = "戦域の<color=#ffd34c>勝利目標</color>と<color=#ffd34c>敗北条件</color>は常にチェックしておくことをオススメします。"
L1_1.Text_JPN = L2_1
L2_1 = "You should always check the <color=#ffd34c>winning</color> and <color=#ffd34c>losing conditions</color> of your operations in the Battlefield."
L1_1.Text_ENG = L2_1
L2_1 = "战役的<color=#ffd34c>胜利目标</color>和<color=#ffd34c>失败条件</color>最好经常确认一下。"
L1_1.Text_SCN = L2_1
L2_1 = "建議老闆要常常確認戰役的<color=#ffd34c>勝利目標</color>和<color=#ffd34c>失敗條件</color>喔！"
L1_1.Text_TWN = L2_1
L2_1 = "คุณควรจะดู<color=#ffd34c>เงื่อนไขการชนะ</color>และ<color=#ffd34c>การแพ้</color>ของปฏิบัติการในสนามรบเสมอ"
L1_1.Text_THA = L2_1
L2_1 = "Ngài lúc nào cũng phải kiểm tra các điều kiện <color=#ffd34c>thắng</color> và <color=#ffd34c>thua</color> của các tác chiến trong Chiến Trường."
L1_1.Text_VTN = L2_1
L2_1 = "Sie sollten sich immer die <color=#ffd34c>Sieg- und Niederlagebedingungen</color> Ihrer Operationen auf Schlachtfeldern ansehen."
L1_1.Text_DEU = L2_1
L2_1 = "Il faut toujours vérifier les conditions de <color=#ffd34c>victoire</color> et de <color=#ffd34c>défaite</color> de vos opérations sur le champ de bataille."
L1_1.Text_FRA = L2_1
