L2_1.EventID = L3_1
L2_1.EventType = "HIGHLIGHT_UI"
L3_1 = "특히, 처음 수행하는 작전일 수록 말이죠."
L2_1.Text_KOREA = L3_1
L3_1 = "NUF_WARFARE_INFO_MEDALINFO_DETAIL"
L2_1.StringValue = L3_1
L3_1 = "特に、初めて遂行する作戦はなおさらです。"
L2_1.Text_JPN = L3_1
L3_1 = "Especially if it's an operation you've never done before."
L2_1.Text_ENG = L3_1
L3_1 = "尤其是您第一次进行的作战。"
L2_1.Text_SCN = L3_1
L3_1 = "尤其是當您第一次進行作戰的時候。"
L2_1.Text_TWN = L3_1
L3_1 = "โดยเฉพาะถ้านั่นเป็นปฏิบัติการที่คุณไม่เคยทำมาก่อน"
L2_1.Text_THA = L3_1
L3_1 = "Đặc biệt là khi đó là chiến dịch ngài chưa từng thực hiện trước đó."
L2_1.Text_VTN = L3_1
L3_1 = "Besonders wenn es sich um einen Einsatz handelt, der neu für Sie ist."
L2_1.Text_DEU = L3_1
L3_1 = "En particulier pour une opération que vous faites pour la première fois."
L2_1.Text_FRA = L3_1
