L28_1 = "TUTORIAL_NEW_781_4"
L27_1.GameEventStrID = L28_1
L27_1.ProcessKey = 4
L28_1 = 781
L27_1.EventID = L28_1
L27_1.EventType = "MESSAGE_BOX"
L28_1 = "<color=#ffd34c>기숙사</color>는 직원 편의를 고려해 <color=#ffd34c>본사</color>와 연결해 두었습니다."
L27_1.Text_KOREA = L28_1
L28_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L27_1.StringValue = L28_1
L28_1 = "<color=#ffd34c>寮</color>は社員の便宜を考慮し、<color=#ffd34c>本社</color>と繋がる構造となっています。"
L27_1.Text_JPN = L28_1
L28_1 = "For our employees' convenience, the <color=#ffd34c>Dorms</color> are connected to <color=#ffd34c>HQ</color>."
L27_1.Text_ENG = L28_1
L28_1 = "为方便员工使用，已将<color=#ffd34c>宿舍</color>和<color=#ffd34c>总公司</color>相互连通了。"
L27_1.Text_SCN = L28_1
L28_1 = "<color=#ffd34c>宿舍</color>的部分，考慮到員工的方便性，是和<color=#ffd34c>總公司</color>連結共構的。"
L27_1.Text_TWN = L28_1
L28_1 = "เพื่อความสะดวกสบายของพนักงาน <color=#ffd34c>หอพัก</color>จะเชื่อมต่อกับ<color=#ffd34c>ศูนย์บัญชาการ</color>"
L27_1.Text_THA = L28_1
L28_1 = "Để giúp nhân viên thuận tiện hơn, <color=#ffd34c>Ký Túc Xá</color> được kết nối với <color=#ffd34c>Trụ Sở</color>."
L27_1.Text_VTN = L28_1
L28_1 = "Für unsere Mitarbeiter sind die <color=#ffd34c>Wohnheime</color> mit dem <color=#ffd34c>HQ</color> verbunden."
L27_1.Text_DEU = L28_1
L28_1 = "Pour le confort de nos employés, les <color=#ffd34c>dortoirs</color> sont directement reliés au <color=#ffd34c>QG</color>."
L27_1.Text_FRA = L28_1
