L38_1.ProcessKey = 5
L39_1 = 783
L38_1.EventID = L39_1
L39_1 = "TUTORIAL_TOUCH_UI"
L38_1.EventType = L39_1
L39_1 = "자 그럼, 정식으로 <color=#ffd34c>기숙사 완공</color>을 승인해 주세요!"
L38_1.Text_KOREA = L39_1
L39_1 = "AB_UI_OFFICE_MAP_HOTKEY_BUTTON"
L38_1.StringValue = L39_1
L39_1 = "さあ、それでは正式に<color=#ffd34c>寮の完工</color>を承認してください！"
L38_1.Text_JPN = L39_1
L39_1 = "Okay, then please approve the <color=#ffd34c>completion of the Dorms</color>."
L38_1.Text_ENG = L39_1
L39_1 = "好了，请您正式批准<color=#ffd34c>宿舍完工</color>吧！"
L38_1.Text_SCN = L39_1
L39_1 = "那就請老闆正式批准<color=#ffd34c>宿舍完工</color>囉！"
L38_1.Text_TWN = L39_1
L39_1 = "โอเคค่ะ ช่วยอนุมัติ<color=#ffd34c>การสร้างหอพักให้เสร็จ</color>ด้วยค่ะ"
L38_1.Text_THA = L39_1
L39_1 = "Được rồi, vậy hãy phê duyệt <color=#ffd34c>hoàn thành Ký Túc Xá</color>."
L38_1.Text_VTN = L39_1
L39_1 = "Okay, dann genehmigen Sie bitte die <color=#ffd34c>Fertigstellung der Wohnheime</color>."
L38_1.Text_DEU = L39_1
L39_1 = "Bien. Dans ce cas, veuillez approuver la <color=#ffd34c>finalisation des dortoirs</color>."
L38_1.Text_FRA = L39_1
