L42_1.EventType = "MESSAGE_BOX"
L43_1 = "<color=#ffd34c>기숙사</color>에 머물 직원들을 직접 선택하실 수 있습니다."
L42_1.Text_KOREA = L43_1
L43_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L42_1.StringValue = L43_1
L43_1 = "<color=#ffd34c>寮</color>に入れる社員を選択できます。"
L42_1.Text_JPN = L43_1
L43_1 = "You can select the employees to add to the <color=#ffd34c>Dorms</color>."
L42_1.Text_ENG = L43_1
L43_1 = "您可以亲自选择要在<color=#ffd34c>宿舍</color>居住的职员。"
L42_1.Text_SCN = L43_1
L43_1 = "可以選擇要住在<color=#ffd34c>宿舍</color>的員工。"
L42_1.Text_TWN = L43_1
L43_1 = "คุณสามารถเลือกพนักงานที่จะเพิ่มเข้าไปใน<color=#ffd34c>หอพัก</color>ได้"
L42_1.Text_THA = L43_1
L43_1 = "Ngài có thể chọn nhân viên để thêm vào <color=#ffd34c>Ký Túc Xá</color>."
L42_1.Text_VTN = L43_1
L43_1 = "Sie können auswählen, welche Mitarbeiter in den <color=#ffd34c>Wohnheimen</color> wohnen sollen."
L42_1.Text_DEU = L43_1
L43_1 = "Vous pouvez choisir quels employés ajouter aux <color=#ffd34c>dortoirs</color>."
L42_1.Text_FRA = L43_1
