L21_1.EventID = L22_1
L21_1.EventType = "MESSAGE_BOX"
L22_1 = "사장님! <color=#ffd34c>법인 카드</color>로 <color=#ffd34c>회식</color>을 진행할 수 있습니다!"
L21_1.Text_KOREA = L22_1
L22_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L21_1.StringValue = L22_1
L22_1 = "社長！　<color=#ffd34c>法人カード</color>で<color=#ffd34c>会食</color>ができます！"
L21_1.Text_JPN = L22_1
L22_1 = "Boss, you can use your <color=#ffd34c>Corporate Credit Card</color> to hold <color=#ffd34c>Company Dinners</color>."
L21_1.Text_ENG = L22_1
L22_1 = "老板! 您可以使用<color=#ffd34c>科芬公司商务卡</color> <color=#ffd34c>组织公司聚餐哦</color>!"
L21_1.Text_SCN = L22_1
L22_1 = "老闆！可以使用<color=#ffd34c>商務卡</color>舉辦<color=#ffd34c>聚餐</color>！"
L21_1.Text_TWN = L22_1
L22_1 = "บอส คุณสามารถใช้<color=#ffd34c>บัตรเครดิตบริษัท</color>เพื่อจัด<color=#ffd34c>งานเลี้ยงบริษัท</color>"
L21_1.Text_THA = L22_1
L22_1 = "Ông chủ, hãy dùng <color=#ffd34c>Thẻ Tín Dụng Công Ty</color> để tổ chức <color=#ffd34c>Bữa Tối Công Ty</color>."
L21_1.Text_VTN = L22_1
L22_1 = "Boss, du kannst deine <color=#ffd34c>Firmenkreditkarte</color> verwenden, um <color=#ffd34c>Unternehmensabendessen</color> zu veranstalten."
L21_1.Text_DEU = L22_1
L22_1 = "Monsieur, vous pouvez utiliser votre <color=#ffd34c>carte de crédit d'entreprise</color> pour organiser <color=#ffd34c>des dîners d'entreprise</color>."
L21_1.Text_FRA = L22_1
L22_1 = {}
L23_1 = "TUTORIAL_NEW_795_7"
L22_1.GameEventStrID = L23_1
L22_1.ProcessKey = 7
L23_1 = 795
L22_1.EventID = L23_1
L22_1.EventType = "MESSAGE_BOX"
L23_1 = "사원분들과 한도 내에서 먹고 싶은 거 마시고 싶은 거 모두 드셔도 됩니다!"
L22_1.Text_KOREA = L23_1
L23_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L22_1.StringValue = L23_1
L23_1 = "社員の皆さんと限度内で食べたいもの、飲みたいものを全て召し上がってくださいね！"
L22_1.Text_JPN = L23_1
L23_1 = "Enjoy eating and drinking with your employees within your credit limit!"
L22_1.Text_ENG = L23_1
L23_1 = "在一定额度以内，可以和员工一起想吃什么吃什么，想喝什么喝什么！"
L22_1.Text_SCN = L23_1
L23_1 = "在額度內，可以盡情地和員工們大吃大喝喔！"
L22_1.Text_TWN = L23_1
L23_1 = "เพลิดเพลินกับพนักงานของคุณในงานเลี้ยงภายในวงเงินเครดิตของคุณ!"
L22_1.Text_THA = L23_1
L23_1 = "Hãy thưởng thức bữa tiệc với nhân viên của mình trong hạn mức tín dụng nhé!"
L22_1.Text_VTN = L23_1
L23_1 = "Genieße gutes Essen und gute Getränke mit deinen Mitarbeitern, aber achte auf das Budget!"
L22_1.Text_DEU = L23_1
L23_1 = "Invitez vos employés à manger ou à boire un verre dans la limite de vos crédits !"
L22_1.Text_FRA = L23_1
