L39_1.Text_KOREA = L40_1
L40_1 = "AB_INVEN_ICON_NKM_NPC_PROFESSOR_OLIVIA"
L39_1.StringValue = L40_1
L40_1 = "<color=#ffd34c>研究所に新施設を追加</color>しました。"
L39_1.Text_JPN = L40_1
L40_1 = "<color=#ffd34c>A new facility has been added to the lab</color>."
