L40_1 = "<color=#ffd34c>研究所有新建了一个设施</color>。"
L39_1.Text_SCN = L40_1
L40_1 = "<color=#ffd34c>研究室有新添設備</color>喔。"
L39_1.Text_TWN = L40_1
L40_1 = "<color=#ffd34c>ห้องแล็บมีสิ่งอำนวยความสะดวกใหม่แล้วนะคะ</color>"
L39_1.Text_THA = L40_1
L40_1 = "<color=#ffd34c>Một cơ sở mới đã được đưa vào phòng thí nghiệm</color>."
