L40_1.EventID = L41_1
L40_1.EventType = "MESSAGE_BOX"
L41_1 = "시간 되시면 확인하러 오시겠어요?"
L40_1.Text_KOREA = L41_1
L41_1 = "AB_INVEN_ICON_NKM_NPC_PROFESSOR_OLIVIA"
L40_1.StringValue = L41_1
L41_1 = "お時間がある時にぜひ一度お越しくださいね。"
L40_1.Text_JPN = L41_1
L41_1 = "How'd you like to come by and take a look?"
L40_1.Text_ENG = L41_1
L41_1 = "有时间的话，过来看一看吧？"
L40_1.Text_SCN = L41_1
L41_1 = "時間方便的話要不要來看一看呢？"
L40_1.Text_TWN = L41_1
L41_1 = "คุณอยากแวะมาดูหน่อยมั้ยล่ะ?"
