L4_1 = "제가 대신 신규 시설을 소개해 드리라 하셨어요."
L3_1.Text_KOREA = L4_1
L4_1 = "AB_INVEN_ICON_NKM_NPC_ASSISTANT_LEE_YOON_JUNG"
L3_1.StringValue = L4_1
L4_1 = "私が代わりに新施設を紹介するようにと言われました。"
L3_1.Text_JPN = L4_1
L4_1 = "She asked me to show you around the new facility in her stead."
L3_1.Text_ENG = L4_1
L4_1 = "她让我替她介绍新设施。"
L3_1.Text_SCN = L4_1
L4_1 = "教授請我代替她介紹新的設備。"
L3_1.Text_TWN = L4_1
L4_1 = "เธอขอให้ฉันพาคุณดูรอบๆ ศูนย์ใหม่แทนเธอค่ะ"
L3_1.Text_THA = L4_1
L4_1 = "Cô ấy yêu cầu tôi hướng dẫn cho ngài xung quanh cơ sở mới thay cho cô ấy."
L3_1.Text_VTN = L4_1
L4_1 = "Ich soll Ihnen an ihrer Stelle die neue Ausstattung zeigen."
L3_1.Text_DEU = L4_1
L4_1 = "Elle m'a demandé de faire la visite à sa place."
L3_1.Text_FRA = L4_1
