L10_1.GameEventStrID = L11_1
L10_1.ProcessKey = 5
L11_1 = 654
L10_1.EventID = L11_1
L10_1.EventType = "MESSAGE_BOX"
L11_1 = "여기서 <color=#ffd34c>현재 재무장시킬 수 있는 사원의 목록을 확인하실 수 있어요.</color>"
L10_1.Text_KOREA = L11_1
L11_1 = "AB_INVEN_ICON_NKM_NPC_ASSISTANT_LEE_YOON_JUNG"
L10_1.StringValue = L11_1
L11_1 = "ここで<color=#ffd34c>現在再武装できる社員のリストを確認できます。</color>"
L10_1.Text_JPN = L11_1
L11_1 = "Here, <color=#ffd34c>you can check the list of employees that can be rearmed.</color>"
L10_1.Text_ENG = L11_1
L11_1 = "在这里，<color=#ffd34c>可以查看到当前能够再武装的职员列表。</color>"
L10_1.Text_SCN = L11_1
L11_1 = "這裡可以查看<color=#ffd34c>目前可進行再武裝的員工名單。</color>"
L10_1.Text_TWN = L11_1
L11_1 = "<color=#ffd34c>ดูรายชื่อพนักงานที่ติดอาวุธใหม่ได้</color>ที่นี่ค่ะ"
L10_1.Text_THA = L11_1
L11_1 = "Tại đây, <color=#ffd34c>ngài có thể kiểm tra danh sách nhân viên có thể được tái vũ trang</color>"
L10_1.Text_VTN = L11_1
L11_1 = "Hier ist die <color=#ffd34c>Liste der Mitarbeiter, die momentan zur Wiederbewaffnung bereitstehen.</color>"
L10_1.Text_DEU = L11_1
L11_1 = "Ici, <color=#ffd34c>vous pouvez vérifier la liste des employés qui peuvent être réarmés.</color>"
L10_1.Text_FRA = L11_1
