L14_1 = 654
L13_1.EventID = L14_1
L13_1.EventType = "MESSAGE_BOX"
L14_1 = "유미나 사원을 선택해보시겠어요?"
L13_1.Text_KOREA = L14_1
L14_1 = "AB_INVEN_ICON_NKM_NPC_ASSISTANT_LEE_YOON_JUNG"
L13_1.StringValue = L14_1
L14_1 = "ヤナギ・ミナさんを選択してみてください。"
L13_1.Text_JPN = L14_1
L14_1 = "Why don't you select Yoo Mina?"
L13_1.Text_ENG = L14_1
L14_1 = "先选择刘米娜职员吧？"
L13_1.Text_SCN = L14_1
L14_1 = "就先從劉米娜員工開始如何？"
L13_1.Text_TWN = L14_1
L14_1 = "ทำไมไม่ลองเลือกยู มีนาล่ะคะ?"
L13_1.Text_THA = L14_1
L14_1 = "Tại sao ngài không chọn Yoo Mina nhỉ?"
L13_1.Text_VTN = L14_1
L14_1 = "Wählen Sie einmal Yoo Mina aus."
L13_1.Text_DEU = L14_1
L14_1 = "Et si vous sélectionniez Yoo Mina ?"
L13_1.Text_FRA = L14_1
