L26_1 = "GameEvent_500_6"
L25_1.GameEventStrID = L26_1
L25_1.ProcessKey = 6
L26_1 = 500
L25_1.EventID = L26_1
L25_1.EventType = "MESSAGE_BOX"
L26_1 = "[다이브] 는 상위 차원에서 하위 차원으로\n도약하는 것을 뜻 합니다."
L25_1.Text_KOREA = L26_1
L26_1 = "AB_INVEN_ICON_NKM_NPC_OPERATOR_CHLOE"
L25_1.StringValue = L26_1
L26_1 = "[ダイブ]は、上位次元から下位次元へ\n跳躍することを意味します。"
L25_1.Text_JPN = L26_1
L26_1 = [[
[Dive] refers to a 'plunge' from an upper dimension
to a lower one.]]
L25_1.Text_ENG = L26_1
L26_1 = "[跃入]是从高位次元跃迁到\n低位次元的操作。"
L25_1.Text_SCN = L26_1
L26_1 = "[躍入]是從高位次元躍遷到\n低位次元的行為。"
L25_1.Text_TWN = L26_1
L26_1 = "[ไดฟ์] หมายถึงการ “โดดลง” จากมิติระดับสูง\nไปยังมิติที่ต่ำกว่า"
L25_1.Text_THA = L26_1
L26_1 = "[Lặn] là \"cú nhảy\" từ chiều không gian cao hơn\nxuống chiều không gian thấp hơn."
L25_1.Text_VTN = L26_1
L26_1 = "[Tauchgang] bezieht sich auf einen „Sprung“ aus einer höheren Dimension\nin eine niedrigere."
L25_1.Text_DEU = L26_1
L26_1 = "Une [plongée] fait référence au déplacement\nd'une dimension vers une autre plus profonde."
L25_1.Text_FRA = L26_1
L26_1 = {}
