L37_1.EventID = L38_1
L37_1.EventType = "MESSAGE_BOX"
L38_1 = "이면세계 탐사 활동은 사장님에게도, 코핀컴퍼니에도 큰 도움이 될겁니다."
L37_1.Text_KOREA = L38_1
L38_1 = "AB_INVEN_ICON_NKM_NPC_OPERATOR_CHLOE"
L37_1.StringValue = L38_1
L38_1 = "裏世界での探査活動は、\n社長にとってもコフィンカンパニーにとっても、大変役立つと思います。"
L37_1.Text_JPN = L38_1
L38_1 = "It will greatly benefit both you and the Coffin Company."
L37_1.Text_ENG = L38_1
L38_1 = "异界探索活动对老板您，还有科芬公司都会有很大的帮助。"
L37_1.Text_SCN = L38_1
L38_1 = "異界探索活動對老闆您，還有科芬公司都會有很大的幫助。"
L37_1.Text_TWN = L38_1
L38_1 = "มันจะมีประโยชน์ต่อทั้งคุณและบริษัทคอฟฟินมาก"
L37_1.Text_THA = L38_1
L38_1 = "Việc đó sẽ đem lại lợi ích to lớn cho cả ngài lẫn Công Ty Coffin."
L37_1.Text_VTN = L38_1
L38_1 = "Das ist für dich und die Coffin Company von großem Vorteil."
L37_1.Text_DEU = L38_1
L38_1 = "Ça vous profitera à vous comme à la Compagnie Coffin."
L37_1.Text_FRA = L38_1
