L1_1.EventType = "HIGHLIGHT_UI"
L2_1 = "소대에 편성된 유닛들은 전투 시작 시, 차례대로 1번 씩 출격 합니다."
L1_1.Text_KOREA = L2_1
L2_1 = "NKM_DECK_VIEW_UNIT_LIST"
L1_1.StringValue = L2_1
L2_1 = "小隊に編成したユニットは、戦闘が開始すると\n順番どおり1回ずつ出撃します。"
L1_1.Text_JPN = L2_1
L2_1 = "The units in the squad take turns attacking."
L1_1.Text_ENG = L2_1
L2_1 = "战斗时，小队里的人员会轮流地各出击一次。"
L1_1.Text_SCN = L2_1
L2_1 = "戰鬥時，小隊裡的角色會輪流各出擊一次。"
L1_1.Text_TWN = L2_1
L2_1 = "หน่วยรบในหน่วยจะผลัดกันโจมตี"
L1_1.Text_THA = L2_1
L2_1 = "Các đơn vị trong tiểu đội sẽ lần lượt tấn công."
L1_1.Text_VTN = L2_1
L2_1 = "Die Einheiten im Trupp greifen der Reihe nach an."
