L12_1 = 515
L11_1.EventID = L12_1
L11_1.EventType = "MESSAGE_BOX"
L12_1 = "코핀 컴퍼니의 지부와 인접한 지점에, 대형 침식체가 등장한 것이 확인 되었습니다."
L11_1.Text_KOREA = L12_1
L12_1 = "AB_INVEN_ICON_NKM_NPC_OPERATOR_LENA"
L11_1.StringValue = L12_1
L12_1 = "コフィンカンパニー支部と隣接した地点に、巨大侵食体の出現が確認されました。"
L11_1.Text_JPN = L12_1
L12_1 = "A large C.O. has appeared near the Coffin Company branch."
L11_1.Text_ENG = L12_1
L12_1 = "我们已经确认，有巨型侵蚀体出现在科芬公司分公司附近。"
L11_1.Text_SCN = L12_1
L12_1 = "我們已經確認有巨型侵蝕體出現在科芬公司分公司附近。"
L11_1.Text_TWN = L12_1
L12_1 = "วัตถุคอร์รัปต์ขนาดใหญ่ปรากฏตัวใกล้สาขาบริษัทคอฟฟิน"
L11_1.Text_THA = L12_1
L12_1 = "Một Vật Thể Bị Ăn Mòn lớn đã xuất hiện gần chi nhánh Công Ty Coffin."
L11_1.Text_VTN = L12_1
L12_1 = "Ein großes C. O. ist in der Nähe der Zweigstelle der Coffin Company aufgetaucht."
L11_1.Text_DEU = L12_1
L12_1 = "Un O.C. de taille imposante vient d'apparaître près de l'annexe de la Compagnie Coffin !"
L11_1.Text_FRA = L12_1
