L12_1.EventID = L13_1
L12_1.EventType = "MESSAGE_BOX"
L13_1 = "시간안에 현장에 해결 소대를 파견하셔야 할 것 같습니다."
L12_1.Text_KOREA = L13_1
L13_1 = "AB_INVEN_ICON_NKM_NPC_OPERATOR_LENA"
L12_1.StringValue = L13_1
L13_1 = "時間内に現場に小隊を派遣しなければなりません。"
L12_1.Text_JPN = L13_1
L13_1 = "You should send a squad within time to take care of it."
L12_1.Text_ENG = L13_1
L13_1 = "我们建议您及时向该地点派出战斗小队。"
L12_1.Text_SCN = L13_1
L13_1 = "我們建議您及時向該地點派出戰鬥小隊。"
L12_1.Text_TWN = L13_1
L13_1 = "คุณควรส่งหน่วยไปจัดการมันทันที"
L12_1.Text_THA = L13_1
L13_1 = "Bạn nên phái một tiểu đội trong tầm thời gian đi xử lý nó."
L12_1.Text_VTN = L13_1
L13_1 = "Du solltest rechtzeitig einen Trupp entsenden, um dich darum zu kümmern."
L12_1.Text_DEU = L13_1
L13_1 = "Vous devriez envoyer une escouade s'en charger au plus vite."
