L24_1.EventID = L25_1
L24_1.EventType = "MESSAGE_BOX"
L25_1 = "전함을 노리는 브리트라에게 공격을 집중하라!"
L24_1.Text_KOREA = L25_1
L24_1.Value = 3
L25_1 = "艦船を狙うブリトラに攻撃を集中せよ！"
L24_1.Text_JPN = L25_1
L25_1 = "Focus attacks on Britra before it destroys the ship!"
L24_1.Text_ENG = L25_1
L25_1 = "布雷特会攻击舰船，集火它！"
L24_1.Text_SCN = L25_1
L25_1 = "佈雷特會攻擊艦船，集火它！"
L24_1.Text_TWN = L25_1
L25_1 = "เน้นโจมตีไปที่บริต้ราก่อนที่มันจะทำลายยาน!"
L24_1.Text_THA = L25_1
L25_1 = "Hãy tấn công tấn công Britra trước khi nó phá hủy con tàu!"
L24_1.Text_VTN = L25_1
L25_1 = "Angriffe auf Britra konzentrieren, bevor das Schiff zerstört wird!"
L24_1.Text_DEU = L25_1
L25_1 = "Concentrez vos attaques sur Britra avant qu'il ne détruise le vaisseau !"
L24_1.Text_FRA = L25_1
