L26_1.EventType = "MESSAGE_BOX"
L27_1 = "머신갑을 도발하여 돌진을 저지하라!"
L26_1.Text_KOREA = L27_1
L26_1.Value = 3
L27_1 = "マシーン-甲-を挑発して突進を阻止せよ！"
L26_1.Text_JPN = L27_1
L27_1 = "Taunt Machine G.A.P. and stop its charge!"
L26_1.Text_ENG = L27_1
L27_1 = "挑衅甲·机器人，防止它冲锋！"
L26_1.Text_SCN = L27_1
L27_1 = "挑釁我超帥·機器人，防止它衝鋒！"
L26_1.Text_TWN = L27_1
L27_1 = "ยั่วยุแมชชีน G.A.P. และหยุดการโจมตีของมันเลย!"
L26_1.Text_THA = L27_1
L27_1 = "Hãy Chế Nhạo G.A.P. Máy và chặn đường tiến công của nó!"
L26_1.Text_VTN = L27_1
L27_1 = "Verspotte den Machine G.A.P und halte seinen Sturmangriff auf!"
L26_1.Text_DEU = L27_1
L27_1 = "Provoquez la machine G.A.P. pour arrêter sa charge !"
