L40_1 = "GameEvent_551_9"
L39_1.GameEventStrID = L40_1
L39_1.ProcessKey = 9
L40_1 = 551
L39_1.EventID = L40_1
L39_1.EventType = "MESSAGE_BOX"
L40_1 = "팔레스를 모두 공략하면, 관리국에서 제공하는 팔레스 공략 보상을 받을 수 있습니다."
L39_1.Text_KOREA = L40_1
L40_1 = "AB_INVEN_ICON_NKM_NPC_LEE_SOO_YEON"
L39_1.StringValue = L40_1
L40_1 = "すべてのパレスを攻略すると、管理局が提供するパレス攻略報酬を獲得ます。"
L39_1.Text_JPN = L40_1
L40_1 = "Clear a Palace, and you can get the special reward from the Administration."
L39_1.Text_ENG = L40_1
L40_1 = "Text_CHN"
L41_1 = "(CHN)팔레스를 모두 공략하면, 관리국에서 제공하는 팔레스 공략 보상을 받을 수 있습니다."
L39_1[L40_1] = L41_1
L40_1 = "通关所有宫殿后，可以得到管理局提供的宫殿通关奖励。"
L39_1.Text_SCN = L40_1
L40_1 = "通關所有宮殿後，可以獲得管理局提供的宮殿通關獎勵。"
L39_1.Text_TWN = L40_1
L40_1 = "เคลียร์วังแล้วคุณจะได้รับรางวัลพิเศษจากองค์การบริหารโลก"
L39_1.Text_THA = L40_1
L40_1 = "Hoàn thành nhiệm vụ Cung Điện có thể nhận phần thưởng đặc biệt từ Cục Quản Lý."
L39_1.Text_VTN = L40_1
L40_1 = "Wenn du einen Palast säuberst, erhältst du die Sonderbelohnung der Administration."
L39_1.Text_DEU = L40_1
L40_1 = "Terminez un palais et l'Administration vous donnera une récompense spéciale."
L39_1.Text_FRA = L40_1
