L42_1.EventType = "MESSAGE_BOX"
L43_1 = "팔레스에 입장 하기위해서는\n<color=#ffd34c>[양자좌표석]</color> 이 필요합니다."
L42_1.Text_KOREA = L43_1
L43_1 = "AB_INVEN_ICON_NKM_NPC_LEE_SOO_YEON"
L42_1.StringValue = L43_1
L43_1 = "パレスに入場するためには\n<color=#ffd34c>[量子座標石]</color>が必要です。"
L42_1.Text_JPN = L43_1
L43_1 = [[
To enter a Palace,
you need a <color=#ffd34c>[Quantum Coords Crystal]</color>.]]
L42_1.Text_ENG = L43_1
L43_1 = "Text_CHN"
L44_1 = "(CHN)팔레스에 입장 하기위해서는\n<color=#ffd34c>[양자좌표석]</color> 이 필요합니다."
L42_1[L43_1] = L44_1
L43_1 = "进入宫殿需要\n<color=#ffd34c>【量子坐标石】</color>。"
L42_1.Text_SCN = L43_1
L43_1 = "進入宮殿需要\n<color=#ffd34c>【量子座標石】</color>。"
L42_1.Text_TWN = L43_1
L43_1 = "เพื่อเข้าสู่วัง\nคุณต้องมี <color=#ffd34c>[ผลึกพิกัดควอนตัม]</color>"
L42_1.Text_THA = L43_1
L43_1 = "Để vào Cung Điện,\n cần <color=#ffd34c>[Tinh Thể Tọa Độ Lượng Tử]</color>."
L42_1.Text_VTN = L43_1
L43_1 = "Um einen Palast zu betreten,\nbenötigst du einen <color=#ffd34c>[Quantenkoordinatenstein]</color>."
L42_1.Text_DEU = L43_1
L43_1 = "Pour entrer dans un palais,\nil vous faut une <color=#ffd34c>[pierre de coordonnées quantiques]</color>."
L42_1.Text_FRA = L43_1
