L48_1.EventType = "MESSAGE_BOX"
L49_1 = "팔레스 공략에 성공한 태스크포스는\n공략시간을 기록하여 남겨두고 있습니다."
L48_1.Text_KOREA = L49_1
L49_1 = "AB_INVEN_ICON_NKM_NPC_LEE_SOO_YEON"
L48_1.StringValue = L49_1
L49_1 = "パレス攻略に成功したタスクフォースカンパニーは\n攻略時間を記録として残しています。"
L48_1.Text_JPN = L49_1
L49_1 = [[
TASKFORCE companies who successfully clear a Palace
will have their records saved.]]
L48_1.Text_ENG = L49_1
L49_1 = "Text_CHN"
L50_1 = "(CHN)팔레스 공략에 성공한 태스크포스는\n공략시간을 기록하여 남겨두고 있습니다."
L48_1[L49_1] = L50_1
L49_1 = "特遣势力成功通关宫殿后\n会记录通关时间。"
L48_1.Text_SCN = L49_1
L49_1 = "成功通關宮殿的特遣勢力，\n將會記錄通關時間。"
L48_1.Text_TWN = L49_1
L49_1 = "บริษัททาสก์ฟอร์สซึ่งเคีลยร์วังได้สำเร็จ\nจะได้รับการบันทึกสถิติไว้"
L48_1.Text_THA = L49_1
L49_1 = "Các công ty TASKFORCE đã hoàn thành thành công nhiệm vụ Cung Điện\nsẽ được lưu hồ sơ."
L48_1.Text_VTN = L49_1
L49_1 = "Für TASKFORCE-Unternehmen, die einen Palast erfolgreich säubern,\nwerden die entsprechenden Rekorde gespeichert."
L48_1.Text_DEU = L49_1
L49_1 = "Les entreprises TASKFORCE qui parviennent à terminer un palais\nvoient leurs résultats enregistrés."
L48_1.Text_FRA = L49_1
