L50_1.EventType = "MESSAGE_BOX"
L51_1 = "팔레스 공략을 최적화하여, 기록 경쟁에서 최고의 기업임을 입증해보시는 것도 좋겠군요."
L50_1.Text_KOREA = L51_1
L51_1 = "AB_INVEN_ICON_NKM_NPC_LEE_SOO_YEON"
L50_1.StringValue = L51_1
L51_1 = "パレス攻略を最適化し、記録競争で最高の企業であることを見せつけてもよいでしょう。"
L50_1.Text_JPN = L51_1
L51_1 = "Find the best way to attack the Palace and aim for a top ranking."
L50_1.Text_ENG = L51_1
L51_1 = "Text_CHN"
L52_1 = "(CHN)팔레스 공략을 최적화하여, 기록 경쟁에서 최고의 기업임을 입증해보시는 것도 좋겠군요."
L50_1[L51_1] = L52_1
L51_1 = "请尽量缩短宫殿通关时间，用记录证明最出色企业的实力。"
L50_1.Text_SCN = L51_1
L51_1 = "請儘量縮短宮殿通關時間，用記錄證明自己是最強的企業吧。"
L50_1.Text_TWN = L51_1
L51_1 = "หาวิธีที่ดีที่สุดในการโจมตีหวังแล้วมุ่งไปให้ถึงอันดับสูงสุด"
L50_1.Text_THA = L51_1
L51_1 = "Tìm cách tốt nhất để tấn công cung điện và đạt được thứ hạng hàng đầu."
L50_1.Text_VTN = L51_1
L51_1 = "Finde die beste Taktik für den Angriff auf den Palast und hol dir eine Top-Platzierung."
L50_1.Text_DEU = L51_1
L51_1 = "Trouvez la meilleure stratégie pour aborder un palais et visez le haut du classement !"
L50_1.Text_FRA = L51_1
