L10_1 = "UNLOCK_SHADOW_PALACE_ON"
L9_1[1] = L10_1
L7_1[L8_1] = L9_1
L8_1 = "GameEvent_555_6"
L7_1.GameEventStrID = L8_1
L7_1.ProcessKey = 6
L8_1 = 555
L7_1.EventID = L8_1
L7_1.EventType = "HIGHLIGHT_UI"
L8_1 = "전투에서 3번 패배 할 경우, 양자좌표석은 기능을 상실하며 팔레스에서 퇴각해야 합니다."
L7_1.Text_KOREA = L8_1
L8_1 = "PALACE_LIFE"
L7_1.StringValue = L8_1
L8_1 = "戦闘で3回敗北した場合、量子座標石はその機能を失い、\nパレスから退却せざるを得ません。"
L7_1.Text_JPN = L8_1
L8_1 = "If you lose 3 battles, the Stone will become completely useless, and you'll have to leave the Palace."
L7_1.Text_ENG = L8_1
L8_1 = "Text_CHN"
L9_1 = "(CHN)전투에서 3번 패배 할 경우, 양자좌표석은 기능을 상실하며 팔레스에서 퇴각해야 합니다."
L7_1[L8_1] = L9_1
L8_1 = "在战斗中落败3次时，量子坐标石会失去效果，必须从宫殿撤退。"
L7_1.Text_SCN = L8_1
L8_1 = "在戰鬥中落敗3次時，量子座標石會失去效果，必須從宮殿撤退。"
L7_1.Text_TWN = L8_1
L8_1 = "หากคุณแพ้การต่อสู้ 3 ครั้ง ผลึกจะไร้ประโยชน์ไปโดยสิ้นเชิง และคุณต้องออกจากวัง"
L7_1.Text_THA = L8_1
L8_1 = "Nếu thua 3 trận chiến, Tinh Thể sẽ hoàn toàn mất tác dụng, và phải rời khỏi Cung Điện."
L7_1.Text_VTN = L8_1
L8_1 = "Wenn du 3 Schlachten verlierst, ist der Stein völlig nutzlos. In diesem Fall musst du den Palast verlassen."
L7_1.Text_DEU = L8_1
L8_1 = "Au bout de 3 défaites, une pierre devient inutilisable, vous forçant à quitter le palais."
L7_1.Text_FRA = L8_1
