L9_1 = 555
L8_1.EventID = L9_1
L9_1 = "TEXT"
L8_1.EventType = L9_1
L9_1 = "양자좌표석의 기능이 상실하기 전까지, 팔레스를 공략 하십시오."
L8_1.Text_KOREA = L9_1
L9_1 = "量子座標石が機能喪失する前に、パレスを攻略してください。"
L8_1.Text_JPN = L9_1
L9_1 = "Attack the Palace until your current Quantum Coords Crystal becomes useless."
L8_1.Text_ENG = L9_1
L9_1 = "Text_CHN"
L10_1 = "(CHN)양자좌표석의 기능이 상실하기 전까지, 팔레스를 공략 하십시오."
L8_1[L9_1] = L10_1
L9_1 = "请在量子坐标石失去效果前抓紧时间通关宫殿。"
L8_1.Text_SCN = L9_1
L9_1 = "請在量子座標石失去效果前，把握時間通關宮殿。"
L8_1.Text_TWN = L9_1
L9_1 = "โจมตีวังไปจนกว่าผลึกพิกัดควอนตัมที่คุณมีในขณะนั้นจะหมดประโยชน์"
L8_1.Text_THA = L9_1
L9_1 = "Tấn công Cung Điện cho đến khi Tinh Thể  Tọa Độ Lượng Tử hiện tại trở nên mất tác dụng."
L8_1.Text_VTN = L9_1
L9_1 = "Greife den Palast an, bis dein aktueller Quantenkoordinatenstein nutzlos ist."
L8_1.Text_DEU = L9_1
L9_1 = "Attaquez le palais tant que votre pierre de coordonnées quantiques est encore utilisable."
L8_1.Text_FRA = L9_1
