L27_1 = "UNLOCK_FIERCE_ON"
L26_1[1] = L27_1
L24_1[L25_1] = L26_1
L25_1 = "GameEvent_600_8"
L24_1.GameEventStrID = L25_1
L24_1.ProcessKey = 8
L25_1 = 600
L24_1.EventID = L25_1
L25_1 = "TEXT"
L24_1.EventType = L25_1
L25_1 = "신중히 소대를 구성하여, 적재적소에 알맞은 인재와 물자를 배치하시길 바랍니다."
L24_1.Text_KOREA = L25_1
L25_1 = "慎重に小隊を編成し、人材と物資を適材適所に配置してください。"
L24_1.Text_JPN = L25_1
L25_1 = "Please take care when you form your squad and put employees and supplies in the right places."
L24_1.Text_ENG = L25_1
L25_1 = "请重组小队，将人才和物资使用在合适的位置。"
L24_1.Text_SCN = L25_1
L25_1 = "請慎重編組小隊，在適當的地方安排人才和物資。"
L24_1.Text_TWN = L25_1
L25_1 = "โปรดระมัดระวังในการสร้างหน่วยและมอบหมายหน้าที่ให้พนักงานและของใช้ของคุณ"
L24_1.Text_THA = L25_1
L25_1 = "Hãy cẩn thận khi bạn thành lập đội của mình và nhớ đặt nhân viên và vật tư vào đúng vị trí."
L24_1.Text_VTN = L25_1
L25_1 = "Achte darauf, wenn du deinen Trupp zusammenstellst, und platziere Mitarbeiter und Nachschub auf den richtigen Positionen."
L24_1.Text_DEU = L25_1
L25_1 = "Réfléchissez bien à la composition de votre escouade et au placement de vos employés et de vos ressources."
L24_1.Text_FRA = L25_1
L25_1 = {}
