L26_1 = "GameEvent_600_9"
L25_1.GameEventStrID = L26_1
L25_1.ProcessKey = 9
L26_1 = 600
L25_1.EventID = L26_1
L25_1.EventType = "HIGHLIGHT_UI"
L26_1 = "각 위험요소들을 처치하고 획득 한 섬멸점수의 총합은 여기에서 확인 가능합니다."
L25_1.Text_KOREA = L26_1
L26_1 = "FIERCE_BATTLE_TOTAL_SCORE"
L25_1.StringValue = L26_1
L26_1 = "各危険要素を排除して獲得した殲滅スコアの合計は、ここで確認できます。"
L25_1.Text_JPN = L26_1
L26_1 = "Here, you can check the total Elimination Points you've earned by eliminating danger elements."
L25_1.Text_ENG = L26_1
L26_1 = "可在此处查看除掉各危险要素后获得的歼灭分数的总和。"
L25_1.Text_SCN = L26_1
L26_1 = "去除各危險要素後，可在此確認獲得的殲滅點數的總合。"
L25_1.Text_TWN = L26_1
L26_1 = "คุณสามารถดูคะแนนกำจัดทั้งหมดที่คุณได้รับจากการกำจัดสิ่งที่เป็นอันตรายได้ที่นี่"
L25_1.Text_THA = L26_1
L26_1 = "Tại đây, ngài có thể kiểm tra tổng số Điểm Tiêu diệt mà ngài đã kiếm được bằng cách tiêu diệt các mối nguy hiểm."
L25_1.Text_VTN = L26_1
L26_1 = "Hier kannst du dir die Eliminierungspunkte ansehen, die du durch das Eliminieren von Gefahrelementen erhalten hast."
L25_1.Text_DEU = L26_1
L26_1 = "Vous pouvez vérifier ici les points d'élimination obtenus en éliminant les éléments dangereux."
L25_1.Text_FRA = L26_1
L26_1 = {}
