L27_1 = "GameEvent_600_10"
L26_1.GameEventStrID = L27_1
L26_1.ProcessKey = 10
L27_1 = 600
L26_1.EventID = L27_1
L26_1.EventType = "HIGHLIGHT_UI"
L27_1 = "섬멸 점수의 총합에 따라 포인트 보상을 수령 하실 수 있으며,"
L26_1.Text_KOREA = L27_1
L27_1 = "FIERCE_BATTLE_BUTTON_SCORE_REWARD"
L26_1.StringValue = L27_1
L27_1 = "殲滅スコアの合計に応じてポイント報酬を獲得でき、"
L26_1.Text_JPN = L27_1
L27_1 = "You can receive Point rewards, depending on your Elimination Points."
L26_1.Text_ENG = L27_1
L27_1 = "可根据歼灭分数的总和领取积分奖励，"
L26_1.Text_SCN = L27_1
L27_1 = "根據殲滅點數的總合可領取積點獎勵，"
L26_1.Text_TWN = L27_1
L27_1 = "คุณสามารถรับรางวัลคะแนนตามคะแนนกำจัดของคุณ"
L26_1.Text_THA = L27_1
L27_1 = "Bạn có thể nhận được Điểm thưởng, tùy thuộc vào Điểm tiêu diệt của bạn."
L26_1.Text_VTN = L27_1
L27_1 = "Je nach deinen Eliminierungspunkten kannst du Punktbelohnungen erhalten."
L26_1.Text_DEU = L27_1
L27_1 = "Engrangez suffisamment de points d'élimination et vous recevrez des récompenses."
L26_1.Text_FRA = L27_1
