L9_1.EventID = L10_1
L9_1.EventType = "MESSAGE_BOX"
L10_1 = "사장님께서 채용하신 오퍼레이터는\n이 패널을 통해 소대에 배치 할 수 있습니다."
L9_1.Text_KOREA = L10_1
L10_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L9_1.StringValue = L10_1
L10_1 = "社長が採用したオペレーターは\nこのパネルを通じて小隊に配置できます。"
L9_1.Text_JPN = L10_1
L10_1 = [[
The Operator you recruited
can be placed in a Squad through this panel.]]
L9_1.Text_ENG = L10_1
L10_1 = "老板您雇佣的机务员\n可以通过这个面板布置到小队。"
L9_1.Text_SCN = L10_1
L10_1 = "老闆您雇傭的領航員\n可透過這個面板部署到小隊。"
L9_1.Text_TWN = L10_1
L10_1 = "วางหน่วยปฏิบัติการที่คุณสรรหามา\nไว้ในทีมผ่านแผงหน้าจอนี้"
L9_1.Text_THA = L10_1
L10_1 = "Người Điều Hành mà ngài đã tuyển\ncó thể được đưa vào Tiểu Đội thông qua khung này."
L9_1.Text_VTN = L10_1
L10_1 = "Der eingestellte Bediener kann\nüber dieses Fenster in einem Trupp platziert werden."
L9_1.Text_DEU = L10_1
L10_1 = "L'opérateur nouvellement recruté\npeut être placé dans une escouade depuis ce menu."
L9_1.Text_FRA = L10_1
