L22_1 = 645
L21_1.EventID = L22_1
L21_1.EventType = "MESSAGE_BOX"
L22_1 = "고용하신 오퍼레이터는 크게\n3가지의 능력을 보유 하고 있습니다."
L21_1.Text_KOREA = L22_1
L22_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L21_1.StringValue = L22_1
L22_1 = "雇用されたオペレーターは主に\n三つの能力を保有しています。"
L21_1.Text_JPN = L22_1
L22_1 = [[
The Operator you have recruited
has 3 types of abilities.]]
L21_1.Text_ENG = L22_1
L22_1 = "雇佣的机务员\n大致拥有3种能力。"
L21_1.Text_SCN = L22_1
L22_1 = "您雇傭的領航員\n具有3種能力。"
L21_1.Text_TWN = L22_1
L22_1 = "หน่วยปฏิบัติการที่คุณสรรหา\nมีความสามารถ 3 ประเภท"
L21_1.Text_THA = L22_1
L22_1 = "Người Điều Hành mà ngài đã tuyển dụng\ncó 3 loại khả năng."
L21_1.Text_VTN = L22_1
L22_1 = "Der von dir eingestellte Bediener\nverfügt über 3 Fähigkeitstypen."
L21_1.Text_DEU = L22_1
L22_1 = "L'opérateur que vous avez recruté\ndispose de 3 types de capacités."
L21_1.Text_FRA = L22_1
