L25_1 = "OPERATOR"
L24_1[1] = L25_1
L22_1[L23_1] = L24_1
L23_1 = "GameEvent_645_6"
L22_1.GameEventStrID = L23_1
L22_1.ProcessKey = 6
L23_1 = 645
L22_1.EventID = L23_1
L22_1.EventType = "HIGHLIGHT_UI"
L23_1 = "함선에 영향을 미치는\n기본적인 <color=#ffd34c>[작전 능력치]</color>"
L22_1.Text_KOREA = L23_1
L23_1 = "NKM_UI_OPERATOR_INFO_DESC_STAT"
L22_1.StringValue = L23_1
L23_1 = "艦船に影響を与える基本的な<color=#ffd34c>[作戦能力値]</color>"
L22_1.Text_JPN = L23_1
L23_1 = [[
The basic <color=#ffd34c>[Operation Stats]</color>
which affect the ship,]]
L22_1.Text_ENG = L23_1
L23_1 = "对舰船产生影响的\n基础<color=#ffd34c>【作战能力值】</color>，"
L22_1.Text_SCN = L23_1
L23_1 = "對艦船產生影響的\n基礎<color=#ffd34c>【作戰能力值】</color>，"
L22_1.Text_TWN = L23_1
L23_1 = "<color=#ffd34c>[ค่าสถานะปฏิบัติการ]</color> พื้นฐาน\nซึ่งจะส่งผลต่อยานรบ"
L22_1.Text_THA = L23_1
L23_1 = "<color=#ffd34c>[Số Liệu Người Điều Hành]</color> cơ bản\n ảnh hưởng đến tàu,"
L22_1.Text_VTN = L23_1
L23_1 = [[
Die grundlegenden <color=#ffd34c>[Einsatzwerte]</color>,
die das Schiff betreffen,]]
L22_1.Text_DEU = L23_1
L23_1 = "Les <color=#ffd34c>[statistiques de manœuvre]</color>\naffectent directement le vaisseau."
L22_1.Text_FRA = L23_1
L23_1 = {}
L24_1 = "listContentsTagAllow"
L25_1 = {}
L26_1 = "OPERATOR"
L25_1[1] = L26_1
L23_1[L24_1] = L25_1
L24_1 = "GameEvent_645_7"
L23_1.GameEventStrID = L24_1
L23_1.ProcessKey = 7
L24_1 = 645
L23_1.EventID = L24_1
L23_1.EventType = "HIGHLIGHT_UI"
L24_1 = "전투에서 출격하는 유닛에 따라,\n효과가 발동되는 <color=#ffd34c>[지휘 기술]</color>"
L23_1.Text_KOREA = L24_1
L24_1 = "NKM_UI_OPERATOR_INFO_DESC_SKILL_01"
L23_1.StringValue = L24_1
L24_1 = "戦闘に出撃するユニットに応じて効果が発動する<color=#ffd34c>[指揮スキル]</color>"
L23_1.Text_JPN = L24_1
L24_1 = [[
the <color=#ffd34c>[Command Skill]</color> which is activated
according to the order of units' deployment in battle,]]
L23_1.Text_ENG = L24_1
L24_1 = "根据战斗中出击的人物\n激活效果的<color=#ffd34c>【指挥技术】</color>，"
L23_1.Text_SCN = L24_1
L24_1 = "根據戰鬥中出擊的單位，\n啟動效果的<color=#ffd34c>【指揮技術】</color>，"
L23_1.Text_TWN = L24_1
L24_1 = "<color=#ffd34c>[สกิลสั่งการ]</color> ซึ่งจะทำงาน\nตามลำดับการวางทัพหน่วยรบในการต่อสู้"
L23_1.Text_THA = L24_1
L24_1 = "<color=#ffd34c>[Kỹ Năng Chỉ Huy]</color> được kích hoạt\ntheo thứ tự triển khai đơn vị trong trận chiến,"
L23_1.Text_VTN = L24_1
L24_1 = "die <color=#ffd34c>[Kommandofähigkeit]</color>, die gemäß der\nEinsatzreihenfolge der Einheiten im Kampf aktiviert wird,"
L23_1.Text_DEU = L24_1
L24_1 = "La <color=#ffd34c>[compétence de commandement]</color>, quant à elle, s'active en fonction\nde l'ordre dans lequel les unités sont déployées en combat."
L23_1.Text_FRA = L24_1
L24_1 = {}
L25_1 = "listContentsTagAllow"
L26_1 = {}
L27_1 = "OPERATOR"
L26_1[1] = L27_1
L24_1[L25_1] = L26_1
L25_1 = "GameEvent_645_8"
L24_1.GameEventStrID = L25_1
L24_1.ProcessKey = 8
L25_1 = 645
L24_1.EventID = L25_1
L24_1.EventType = "HIGHLIGHT_UI"
L25_1 = "전투 전반에 영향을 미치는\n<color=#ffd34c>[보조 기술]</color> 이 있습니다."
L24_1.Text_KOREA = L25_1
L25_1 = "NKM_UI_OPERATOR_INFO_DESC_SKILL_02"
L24_1.StringValue = L25_1
L25_1 = "戦闘全般に影響を与える\n<color=#ffd34c>[補助スキル]</color>があります。"
L24_1.Text_JPN = L25_1
L25_1 = [[
and the <color=#ffd34c>[Side Skill]</color> which takes effect
throughout the battle.]]
L24_1.Text_ENG = L25_1
L25_1 = "对战斗整体产生影响的\n<color=#ffd34c>【辅助技术】</color>。"
L24_1.Text_SCN = L25_1
L25_1 = "還有對戰鬥整體產生影響的\n<color=#ffd34c>【輔助技術】</color>。"
L24_1.Text_TWN = L25_1
L25_1 = "และ <color=#ffd34c>[สกิลเสริม]</color> ซึ่งจะมีผล\nตลอดการต่อสู้"
L24_1.Text_THA = L25_1
L25_1 = "và <color=#ffd34c>[Kỹ Năng Phụ]</color> có hiệu lực\ntrong suốt trận chiến."
L24_1.Text_VTN = L25_1
L25_1 = "und die <color=#ffd34c>[Nebenfähigkeit]</color>, die während des\ngesamten Kampfes wirksam ist."
L24_1.Text_DEU = L25_1
L25_1 = "Enfin, la <color=#ffd34c>[compétence secondaire]</color>\nprend effet au cours du combat."
L24_1.Text_FRA = L25_1
