L28_1[1] = L29_1
L26_1[L27_1] = L28_1
L27_1 = "GameEvent_645_10"
L26_1.GameEventStrID = L27_1
L26_1.ProcessKey = 10
L27_1 = 645
L26_1.EventID = L27_1
L26_1.EventType = "HIGHLIGHT_UI"
L27_1 = "이 중에서도 <color=#ffd34c>[지휘 기술] / [보조 기술]</color> 은\n이쪽 패널의 기술 전수를 통해 보정이 가능합니다."
L26_1.Text_KOREA = L27_1
L27_1 = "BUTTON_SKILLUP"
L26_1.StringValue = L27_1
L27_1 = "この中でも<color=#ffd34c>[指揮スキル]、[補助スキル変更]</color>は\nこちらのパネルの技術伝授を通じて補正が可能です。"
L26_1.Text_JPN = L27_1
L27_1 = [[
Of these, the <color=#ffd34c>[Command Skill] / [Side Skill]</color>
can be calibrated using this panel's Skill Transfer.]]
L26_1.Text_ENG = L27_1
L27_1 = "其中<color=#ffd34c>【指挥技术】/【辅助技术】</color>可以通过这个面板的传授技术功能进行加强。"
L26_1.Text_SCN = L27_1
L27_1 = "其中<color=#ffd34c>【指揮技術】/【輔助技術】</color>可以透過這個面板的傳授技術功能進行加強。"
L26_1.Text_TWN = L27_1
L27_1 = "ในบรรดาความสามารถเหล่านี้ คุณสามารถเร่ง <color=#ffd34c>[สกิลสั่งการ] / [สกิลเสริม]</color> โดยใช้การย้ายสกิลในแผงหน้าจอนี้"
L26_1.Text_THA = L27_1
L27_1 = "Trong đó, <color=#ffd34c>[Kỹ Năng Chỉ Huy]/[Kỹ Năng Phụ]</color>\n có thể được hiệu chỉnh bằng Chuyển Nhượng Kỹ Năng của bảng này."
L26_1.Text_VTN = L27_1
L27_1 = "Die <color=#ffd34c>[Kommandofähigkeit] und die [Nebenfähigkeit]</color>\nkönnen mithilfe der Fähigkeitsübertragung dieses Fensters kalibriert werden."
L26_1.Text_DEU = L27_1
L27_1 = "La <color=#ffd34c>[compétence de commandement]</color> et la <color=#ffd34c>[compétence secondaire]</color>\npeuvent être ajustées en effectuant un transfert de compétence depuis ce menu."
L26_1.Text_FRA = L27_1
L27_1 = {}
L28_1 = "listContentsTagAllow"
L29_1 = {}
L30_1 = "OPERATOR"
L29_1[1] = L30_1
L27_1[L28_1] = L29_1
L28_1 = "GameEvent_645_11"
L27_1.GameEventStrID = L28_1
L27_1.ProcessKey = 11
L28_1 = 645
L27_1.EventID = L28_1
L27_1.EventType = "MESSAGE_BOX"
L28_1 = "<color=#ffd34c>[지휘 기술]</color>을 <color=#ffd34c>향상</color> 시키거나,\n<color=#ffd34c>[보조 기술]</color>을 <color=#ffd34c>향상</color> / <color=#ffd34c>교체</color> 하여 전문인력으로\n육성해보시길 바랍니다."
L27_1.Text_KOREA = L28_1
L28_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L27_1.StringValue = L28_1
L28_1 = "<color=#ffd34c>[指揮スキル]</color>を<color=#ffd34c>向上</color>させたり、\n<color=#ffd34c>[補助スキル]</color>を<color=#ffd34c>向上</color>、 <color=#ffd34c>入れ替え</color>て専門人材を\n育成してみてください。"
L27_1.Text_JPN = L28_1
L28_1 = [[
<color=#ffd34c>Enhance</color> the <color=#ffd34c>[Command Skill]</color>,
or <color=#ffd34c>enhance</color>/<color=#ffd34c>change</color> the <color=#ffd34c>[Side Skill]</color>
to nurture your Operator into a talented warrior.]]
L27_1.Text_ENG = L28_1
L28_1 = "您可以通过<color=#ffd34c>【指挥技术】</color>的<color=#ffd34c>提高</color>或者\n<color=#ffd34c>【辅助技术】</color>的<color=#ffd34c>提高</color>/<color=#ffd34c>替换</color>，培养\n专业人才。"
L27_1.Text_SCN = L28_1
L28_1 = "您可以透過<color=#ffd34c>【指揮技術】</color>的<color=#ffd34c>提高</color>或\n<color=#ffd34c>【輔助技術】</color>的<color=#ffd34c>提高</color>\n進行專業人才的培養。"
L27_1.Text_TWN = L28_1
L28_1 = "<color=#ffd34c>เสริมพลัง</color> <color=#ffd34c>[สกิลสั่งการ]</color>\nหรือ<color=#ffd34c>เสริมพลัง</color>/<color=#ffd34c>เปลี่ยน</color> <color=#ffd34c>[สกิลเสริม]</color>\nเพื่อบ่มเพาะหน่วยปฏิบัติการของคุณให้กลายเป็นนักรบที่มากความสามารถ"
L27_1.Text_THA = L28_1
L28_1 = "<color=#ffd34c>Tăng cường</color> <color=#ffd34c>[Kỹ Năng Chỉ Huy]</color>,\nhoặc <color=#ffd34c> tăng cường</color>/<color=#ffd34c> thay đổi</color><color=#ffd34c> [Kỹ Năng Phụ]</color>\nđể bồi dưỡng Người Điều Hành trở thành chiến binh tài năng."
L27_1.Text_VTN = L28_1
L28_1 = "<color=#ffd34c>Verbessere</color> die <color=#ffd34c>[Kommandofähigkeit]</color>\noder <color=#ffd34c>verbessere</color>/<color=#ffd34c>ändere</color> die <color=#ffd34c>[Nebenfähigkeit]</color>,\num deinen Bediener in einen talentierten Krieger zu verwandeln."
L27_1.Text_DEU = L28_1
L28_1 = "Formez votre opérateur à devenir un combattant hors pair\nen <color=#ffd34c>améliorant</color> sa <color=#ffd34c>[compétence de commandement]</color>,\nou en <color=#ffd34c>améliorant</color>/<color=#ffd34c>modifiant</color> sa <color=#ffd34c>[compétence secondaire]</color>."
L27_1.Text_FRA = L28_1
L28_1 = {}
L29_1 = "listContentsTagAllow"
L30_1 = {}
L31_1 = "OPERATOR"
L30_1[1] = L31_1
L28_1[L29_1] = L30_1
L29_1 = "GameEvent_645_12"
L28_1.GameEventStrID = L29_1
L29_1 = 12
L28_1.ProcessKey = L29_1
L29_1 = 645
L28_1.EventID = L29_1
L28_1.EventType = "MESSAGE_BOX"
L29_1 = "단, 이와 같은 [기술 전수] 시에는 다른 오퍼레이터 인력이 소모되는 점 유의 바랍니다."
L28_1.Text_KOREA = L29_1
L29_1 = "AB_INVEN_ICON_NKM_NPC_KIM_HANA"
L28_1.StringValue = L29_1
L29_1 = "ただし、このような[技術伝授]の際は、他のオペレーターの人手が必要なことにご注意ください。"
L28_1.Text_JPN = L29_1
L29_1 = "However, be careful as [Skill Transfer] will consume another Operator."
L28_1.Text_ENG = L29_1
L29_1 = "但要注意的是想要给机务员【传授技术】，需要消耗其他机务员人力。"
L28_1.Text_SCN = L29_1
L29_1 = "但要注意的是想要給領航員【傳授技術】，需要消耗其他領航員人力。"
L28_1.Text_TWN = L29_1
L29_1 = "แต่ระวังให้ดี เพราะ [การย้ายสกิล] จะต้องใช้หน่วยปฏิบัติการอีกหน่วย"
L28_1.Text_THA = L29_1
L29_1 = "Tuy nhiên, hãy cẩn thận vì [Chuyển Nhượng Kỹ Năng] sẽ khiến mất đi một Người Điều Hành khác."
L28_1.Text_VTN = L29_1
L29_1 = "Beachte aber, dass die [Fähigkeitsübertragung] einen weiteren Bediener verbraucht."
L28_1.Text_DEU = L29_1
L29_1 = "Notez cependant qu'un [transfert de compétence] vous coûtera un autre opérateur en contrepartie."
L28_1.Text_FRA = L29_1
