L49_1.EventType = "MESSAGE_BOX"
L50_1 = "관리자 코드, 생체 정보 확인."
L49_1.Text_KOREA = L50_1
L50_1 = "AB_INVEN_ICON_NKM_UNIT_M_RAS_TOWER_ORIGINAL"
L49_1.StringValue = L50_1
L50_1 = "管理者コード、生体情報確認。"
L49_1.Text_JPN = L50_1
L50_1 = "Administrator code and biometrics identified."
L49_1.Text_ENG = L50_1
L50_1 = "确认管理者代码，详细信息。"
L49_1.Text_SCN = L50_1
L50_1 = "管理者代碼，生物身分確認。"
L49_1.Text_TWN = L50_1
L50_1 = "รหัสผู้บริหารและยืนยันตัวตนตามอัตลักษณ์แล้ว"
L49_1.Text_THA = L50_1
L50_1 = "Mã quản trị viên và sinh trắc học được xác định."
L49_1.Text_VTN = L50_1
L50_1 = "Admin-Code. Biometrische Daten. Erkannt."
L49_1.Text_DEU = L50_1
L50_1 = "Code administrateur, analyse biométrique terminée."
L49_1.Text_FRA = L50_1
L50_1 = {}
L51_1 = "GameEvent_870_4"
L50_1.GameEventStrID = L51_1
L50_1.ProcessKey = 4
L51_1 = 870
L50_1.EventID = L51_1
L50_1.EventType = "MESSAGE_BOX"
L51_1 = "… 리액터 개방 승인.\n절차에 따라 기록 - 0912를 재생합니다."
L50_1.Text_KOREA = L51_1
L51_1 = "AB_INVEN_ICON_NKM_UNIT_M_RAS_TOWER_ORIGINAL"
L50_1.StringValue = L51_1
L51_1 = "……リアクターの解放承認。\n手続きに従い、記録 - 0912を再生します。"
L50_1.Text_JPN = L51_1
L51_1 = [[
...Reactor unlock, approved.
In accordance with procedure, playing Record - 0912.]]
L50_1.Text_ENG = L51_1
L51_1 = "… 黑化晶反应堆开放许可。\n按程序写入 - 播放 0912 。"
L50_1.Text_SCN = L51_1
L51_1 = "… 允許開放電抗器。\n依規定重播紀錄 - 0912。"
L50_1.Text_TWN = L51_1
L51_1 = "...ปลดล็อคเครื่องปฏิกรณ์ อนุมัติแล้ว\nขั้นตอนต่อไป เปิดบันทีกเสียง- 0912"
L50_1.Text_THA = L51_1
L51_1 = "...Mở khóa Lò Phản Ứng, đã được phê duyệt.\nTheo quy trình, đang phát Bản Ghi - 0912."
L50_1.Text_VTN = L51_1
L51_1 = "... Öffnung des Reaktors zugelassen.\nDem Verfahren entsprechend wird Aufzeichnung – 0912 abgespielt."
L50_1.Text_DEU = L51_1
L51_1 = "... Autorisation de l'activation du réacteur.\nLecture de l'enregistrement - 0912."
L50_1.Text_FRA = L51_1
