L46_1 = "GameEvent_20601_1"
L45_1.GameEventStrID = L46_1
L45_1.ProcessKey = 1
L46_1 = 20601
L45_1.EventID = L46_1
L45_1.EventType = "MESSAGE_BOX"
L46_1 = "또 재생하고 있어.\n다시 도망치기 전에 어떻게든...!"
L45_1.Text_KOREA = L46_1
L46_1 = 2.5
L45_1.Value = L46_1
L46_1 = "AB_INVEN_ICON_NKM_UNIT_CA_YOO_MI_NA"
L45_1.StringValue = L46_1
L46_1 = "また再生してる。\n逃げ出す前になんとかしないと……！"
L45_1.Text_JPN = L46_1
L46_1 = [[
She's regenerating again.
I must do something before she gets away!]]
L45_1.Text_ENG = L46_1
L46_1 = "又在再生！\n在它再次逃跑前，无论如何都……！"
L45_1.Text_SCN = L46_1
L46_1 = "又開始再生了。\n 在它再次逃跑之前，無論如何都...！"
L45_1.Text_TWN = L46_1
L46_1 = "เธอเกิดใหม่อีกแล้ว\nฉันต้องทำอะไรสักอย่างก่อนที่เธอจะหนีไปได้!"
L45_1.Text_THA = L46_1
L46_1 = "Cô ấy lại đang tái tạo năng lượng.\nHãy làm điều gì đó trước khi cô ấy chạy thoát!"
L45_1.Text_VTN = L46_1
L46_1 = [[
Sie regeneriert wieder.
Ich muss etwas unternehmen, bevor sie entkommt!]]
L45_1.Text_DEU = L46_1
L46_1 = "Elle se régénère encore.\nIl faut que j'agisse avant qu'elle s'échappe !"
L45_1.Text_FRA = L46_1
L46_1 = {}
L47_1 = "GameEvent_20602_1"
L46_1.GameEventStrID = L47_1
L46_1.ProcessKey = 1
L47_1 = 20602
L46_1.EventID = L47_1
L46_1.EventType = "MESSAGE_BOX"
L47_1 = "아니... \n아직█ 아니야!!!"
L46_1.Text_KOREA = L47_1
L46_1.Value = 2
L47_1 = "AB_INVEN_ICON_NKM_MONSTER_BOSS_BASIC_MINISTRA_MOVE_S"
L46_1.StringValue = L47_1
L47_1 = "いや……\nま█だ！！！"
L46_1.Text_JPN = L47_1
L47_1 = "No...\nNo█ yet!"
L46_1.Text_ENG = L47_1
L47_1 = "不……\n还未█到时候！！！"
L46_1.Text_SCN = L47_1
L47_1 = "不……\n還未█到時候！！！"
L46_1.Text_TWN = L47_1
L47_1 = "ไม่นะ...\nยังไม่ใช่█ตอนนี้!"
L46_1.Text_THA = L47_1
L47_1 = "Không...\nKhông█ hẳn!"
L46_1.Text_VTN = L47_1
L47_1 = "Nein …\nNoc█ nicht!"
L46_1.Text_DEU = L47_1
L47_1 = "Non…\nC'est p█s fini !"
L46_1.Text_FRA = L47_1
L47_1 = {}
L48_1 = "GameEvent_40100_1"
L47_1.GameEventStrID = L48_1
L47_1.ProcessKey = 1
L48_1 = 40100
L47_1.EventID = L48_1
L47_1.EventType = "MESSAGE_BOX"
L48_1 = "큭! 뒤에서 빤히 구경만 할 거야? \n팀전이니까 날 도와야지!"
L47_1.Text_KOREA = L48_1
L47_1.Value = 3
L48_1 = "AB_INVEN_ICON_NKM_UNIT_ACADEMY_C_TWINTAIL"
L47_1.StringValue = L48_1
L48_1 = "くっ！後ろでただ見ているつもり？\nチーム戦でしょ！　手伝え！"
L47_1.Text_JPN = L48_1
L48_1 = "Ngh! Are you just going to sit back and watch? It's a team game, so help me!"
L47_1.Text_ENG = L48_1
L48_1 = "唔！你要一直在后面看热闹吗？现在是团队战，你要帮我啊！"
L47_1.Text_SCN = L48_1
L48_1 = "呃！要在後面眼睜睜地看著嗎？因為是團隊戰，所以應該要幫我！"
L47_1.Text_TWN = L48_1
L48_1 = "อึก! นี่จะเอาแต่ดูอยู่เฉยๆ รึไง? เราต้องแข่งกันเป็นทีมนะ ช่วยฉันสิ!"
L47_1.Text_THA = L48_1
L48_1 = "Ngh! Cô chỉ định khoanh tay đứng nhìn sao? Đây là trò chơi đội nhóm mà, hãy giúp tôi đi!"
L47_1.Text_VTN = L48_1
L48_1 = "Ngh! Willst du nur so rumsitzen und zugucken? Das hier ist ein Teamspiel, also hilf mir gefälligst!"
L47_1.Text_DEU = L48_1
L48_1 = "Argh ! Vous comptez rester assis les bras croisés ? C'est un jeu d'équipe, alors aidez-moi !"
L47_1.Text_FRA = L48_1
L48_1 = {}
L49_1 = "GameEvent_40101_1"
L48_1.GameEventStrID = L49_1
L48_1.ProcessKey = 1
L49_1 = 40101
L48_1.EventID = L49_1
L48_1.EventType = "MESSAGE_BOX"
L49_1 = "각성!? 규칙 위반이야! \n이렇게 된 이상 이쪽도 협공하겠어!"
L48_1.Text_KOREA = L49_1
L48_1.Value = 3
L49_1 = "AB_INVEN_ICON_NKM_UNIT_ACADEMY_C_TWINTAIL"
L48_1.StringValue = L49_1
L49_1 = "覚醒！？　ルール違反よ！　こうなった以上こっちも力を合わせて攻撃させてもらうわ！"
L48_1.Text_JPN = L49_1
L49_1 = "Awakening!? That's against the rules! We are going to work together if it's like this!"
L48_1.Text_ENG = L49_1
L49_1 = "觉醒？！这是犯规！既然如此，那这边也要夹攻了！"
L48_1.Text_SCN = L49_1
L49_1 = "覺醒！？違反規則了！既然這樣，這邊也要夾擊了！"
L48_1.Text_TWN = L49_1
L49_1 = "ปลุกพลังเหรอ!? แบบนั้นมันผิดกฎนะ! ถ้าเป็นแบบนี้เราก็ต้องร่วมมือกัน!"
L48_1.Text_THA = L49_1
L49_1 = "Thức tỉnh?! Như thế là trái luật! Chúng ta sẽ làm việc cùng nhau nếu như vậy!"
L48_1.Text_VTN = L49_1
L49_1 = "Erweckung?! Das ist gegen die Regeln! Wenn das so ist, arbeiten wir zusammen!"
L48_1.Text_DEU = L49_1
L49_1 = "Elle s'éveille ?! C'est de la triche ! Puisque c'est comme ça, on va se serrer les coudes !"
L48_1.Text_FRA = L49_1
