L50_1 = "GameEvent_40102_1"
L49_1.GameEventStrID = L50_1
L49_1.ProcessKey = 1
L50_1 = 40102
L49_1.EventID = L50_1
L49_1.EventType = "MESSAGE_BOX"
L50_1 = "뭐야, 순 잔챙이들 뿐이잖아? \n뒤에서 구경이나 하고 있으라고."
L49_1.Text_KOREA = L50_1
L49_1.Value = 3
L50_1 = "AB_INVEN_ICON_NKM_UNIT_ACADEMY_C_TWINTAIL"
L49_1.StringValue = L50_1
L50_1 = "何よ、雑魚ばかりじゃない！\nあんたは後ろで見てなさい！"
L49_1.Text_JPN = L50_1
L50_1 = "What are these noobs? Just sit back and watch."
L49_1.Text_ENG = L50_1
L50_1 = "什么啊，都是些小喽啰？你就在后面好好看着吧。"
L49_1.Text_SCN = L50_1
L50_1 = "什麼啊，都是無名小卒啊？你們在後面看戲就好啦。"
L49_1.Text_TWN = L50_1
L50_1 = "พวกอ่อนหัดนี่อะไรกัน? คอยดูให้ดีๆ นะ"
L49_1.Text_THA = L50_1
L50_1 = "Những con gà mờ này ở đâu ra thế? Ngồi yên mà xem đi."
L49_1.Text_VTN = L50_1
L50_1 = "Was sind denn das für Noobs? Setz dich und sieh zu."
L49_1.Text_DEU = L50_1
L50_1 = "C'est quoi, ces nuls ? Reculez et laissez-moi faire."
L49_1.Text_FRA = L50_1
