L4_1 = "GameEvent_1007441_2"
L3_1.GameEventStrID = L4_1
L3_1.ProcessKey = 1
L4_1 = 1007441
L3_1.EventID = L4_1
L3_1.EventType = "MESSAGE_BOX"
L4_1 = "하하. 흥을 깨서 죄송합니다만\n살짝 거들어 드리죠."
L3_1.Text_KOREA = L4_1
L4_1 = 2.5
L3_1.Value = L4_1
L4_1 = "AB_INVEN_ICON_NKM_UNIT_CA_JOO_SHI_YOON"
L3_1.StringValue = L4_1
L4_1 = "ハハ、盛り上がっているところ申し訳ないですが\n少しだけお手伝いします。"
L3_1.Text_JPN = L4_1
L4_1 = [[
Hah hah, I'm sorry if I spoiled the mood,
but let me help you.]]
L3_1.Text_ENG = L4_1
L4_1 = "哈哈，抱歉，扫了你的兴致。\n我还是稍微帮你一下吧。"
L3_1.Text_SCN = L4_1
L4_1 = "哈哈～不好意思這麼掃興，\n我就稍微幫個忙吧！"
L3_1.Text_TWN = L4_1
L4_1 = "ฮ่าๆ โทษทีนะ ถ้าผมทําให้เสียอารมณ์\nแต่ให้ผมมาช่วยเธอเถอะ"
L3_1.Text_THA = L4_1
L4_1 = "Ha ha, tôi xin lỗi nếu tôi làm cụt hứng,\nnhưng hãy để tôi giúp cô nhé."
L3_1.Text_VTN = L4_1
L4_1 = [[
Haha, tut mir leid, die Party zu sprengen.
Ich springe kurz mit ein.]]
L3_1.Text_DEU = L4_1
L4_1 = "Ha ha. Désolé de casser l'ambiance,\nmais je crois que je vais devoir m'en mêler."
L3_1.Text_FRA = L4_1
