L5_1 = "GameEvent_23563_1"
L4_1.GameEventStrID = L5_1
L4_1.ProcessKey = 1
L5_1 = 23563
L4_1.EventID = L5_1
L4_1.EventType = "MESSAGE_BOX"
L5_1 = "공연은 구도가 생명이야, 호라이즌"
L4_1.Text_KOREA = L5_1
L5_1 = 3.5
L4_1.Value = L5_1
L5_1 = "AB_INVEN_ICON_NKM_UNIT_HARMONY_C_VIOLIN"
L4_1.StringValue = L5_1
L5_1 = "公演はコンポジションが命よ、ホライズン。"
L4_1.Text_JPN = L5_1
L5_1 = "Stage composition is key when performing, Horizon."
L4_1.Text_ENG = L5_1
L5_1 = "演奏的生命在于演奏因素的构造，地平线。"
L4_1.Text_SCN = L5_1
L5_1 = "地平線，一場演出最重要的就是流程。"
L4_1.Text_TWN = L5_1
L5_1 = "เวลาจะแสดงนะฮอไรซัน สิ่งสำคัญคือองค์ประกอบบนเวที"
L4_1.Text_THA = L5_1
L5_1 = "Bố cục sân khấu là yếu tố then chốt khi trình diễn, Horizon."
L4_1.Text_VTN = L5_1
L5_1 = "Bei Konzerten kommt es ganz auf die Bühnenausrichtung an, Horizon."
L4_1.Text_DEU = L5_1
L5_1 = "La composition est le sel du spectacle, Horizon."
L4_1.Text_FRA = L5_1
