L14_1 = "GameEvent_3236221_3"
L13_1.GameEventStrID = L14_1
L13_1.ProcessKey = 3
L14_1 = 3236221
L13_1.EventID = L14_1
L13_1.EventType = "MESSAGE_BOX"
L14_1 = "자아성찰부터 하시죠. 섬멸당해야 하는 건 그쪽 같습니다만."
L13_1.Text_KOREA = L14_1
L14_1 = 2.5
L13_1.Value = L14_1
L14_1 = "AB_INVEN_ICON_NKM_UNIT_HORIZON_M_LOAN"
L13_1.StringValue = L14_1
L14_1 = "自己省察が必要なようですね。殲滅されるべき側はそちらのようですが。"
L13_1.Text_JPN = L14_1
L14_1 = "Perhaps a little self-reflection is in order. You're the one who'll be annihilated."
L13_1.Text_ENG = L14_1
L14_1 = "还是先自我反省吧，被歼灭的是你们才对。"
L13_1.Text_SCN = L14_1
L14_1 = "先保住你自己吧。會被殲滅的應該是你。"
L13_1.Text_TWN = L14_1
L14_1 = "อาจจะมีการทบทวนตัวเองเล็กน้อยในคำสั่งนะคะ คุณแหละค่ะที่จะถูกกำจัดให้สิ้นซาก"
L13_1.Text_THA = L14_1
L14_1 = "Có lẽ tự ngẫm một chút sẽ đâu vào đấy thôi. Cô mới là người sẽ bị tiêu diệt."
L13_1.Text_VTN = L14_1
L14_1 = "Ich empfehle etwas Selbstreflexion. Ihr seid diejenigen, die annihiliert werden müssen."
L13_1.Text_DEU = L14_1
L14_1 = "Un peu d'introspection ne te ferait pas de mal. C'est toi, qui dois être détruite."
L13_1.Text_FRA = L14_1
