L17_1 = "숙면을 방해해서 죄송하군요. 다시 재워 드리겠습니다."
L16_1.Text_KOREA = L17_1
L17_1 = 2.5
L16_1.Value = L17_1
L17_1 = "AB_INVEN_ICON_NKM_UNIT_HORIZON_M_LOAN"
L16_1.StringValue = L17_1
L17_1 = "熟睡中に邪魔をして申し訳ありません。再び眠らせてあげましょう。"
L16_1.Text_JPN = L17_1
L17_1 = "Sorry to wake you up. Let me help you go back to sleep."
