L21_1.EventID = L22_1
L21_1.EventType = "MESSAGE_BOX"
L22_1 = "하하하. 너희 같은 쥐새끼들이 날 이겨 보겠다고?"
L21_1.Text_KOREA = L22_1
L22_1 = 2.5
L21_1.Value = L22_1
L22_1 = "AB_INVEN_ICON_NKM_MONSTER_BOSS_TRANS_KNIGHT"
L21_1.StringValue = L22_1
L22_1 = "ハハハ、てめえらみたいなネズミどもがこのアタシに勝てるとでも？"
L21_1.Text_JPN = L22_1
L22_1 = "Hah hah hah. You rats think you can beat me, huh?"
L21_1.Text_ENG = L22_1
L22_1 = "哈哈哈。像你们这样的小老鼠还想赢我？"
L21_1.Text_SCN = L22_1
L22_1 = "哈哈哈哈～你們這些鼠輩竟然妄想要打贏我？"
L21_1.Text_TWN = L22_1
L22_1 = "ฮะฮะฮะ  เจ้าหนูคิดว่าเอาชนะฉันได้เหรอ?"
L21_1.Text_THA = L22_1
L22_1 = "Ha ha ha. Lũ chuột nhắt các ngươi nghĩ có thể đánh bại ta à?"
L21_1.Text_VTN = L22_1
L22_1 = "Hahaha. Ihr glaubt, ihr könnt mich besiegen, was?"
L21_1.Text_DEU = L22_1
L22_1 = "Ha ha ha ! Vous pensez pouvoir me battre, petits rats ?"
L21_1.Text_FRA = L22_1
