L23_1 = "GameEvent_10033411_1"
L22_1.GameEventStrID = L23_1
L22_1.ProcessKey = 1
L23_1 = 10033411
L22_1.EventID = L23_1
L22_1.EventType = "MESSAGE_BOX"
L23_1 = "알잖아, 나나 너희들이나,\n이 굴레에서 벗어날 수 없다는 걸."
L22_1.Text_KOREA = L23_1
L23_1 = 3.5
L22_1.Value = L23_1
L23_1 = "AB_INVEN_ICON_NKM_MONSTER_BOSS_BASIC_BISHOP"
L22_1.StringValue = L23_1
L23_1 = "わかるでしょ。私も、お前たちもこの束縛から抜け出せないことを。"
L22_1.Text_JPN = L23_1
L23_1 = [[
You know, neither of us
can escape from this vicious cycle.]]
L22_1.Text_ENG = L23_1
L23_1 = "你们知道吗，无论是谁。\n都不能逃脱这个命运。"
L22_1.Text_SCN = L23_1
L23_1 = "你們也很明白吧？我們任何人\n都無法脫離這個枷鎖。"
L22_1.Text_TWN = L23_1
L23_1 = "ทั้งฉันและเธอ\nเราหนีจากวงจรอุบาทว์นี้ไม่ได้แล้ว"
L22_1.Text_THA = L23_1
L23_1 = "Không ai trong chúng ta có thể thoát khỏi vòng luẩn quẩn này."
L22_1.Text_VTN = L23_1
L23_1 = [[
Keiner von uns kann
diesem Teufelskreis entrinnen.]]
L22_1.Text_DEU = L23_1
L23_1 = "Sachez qu'aucun d'entre nous\nne peut échapper à ce cercle vicieux."
L22_1.Text_FRA = L23_1
