L28_1 = 10053211
L27_1.EventID = L28_1
L27_1.EventType = "MESSAGE_BOX"
L28_1 = "전력을 다해야 할 걸, 유미나.\n이전처럼 당해 줄 생각은 없으니까."
L27_1.Text_KOREA = L28_1
L27_1.Value = 3
L28_1 = "AB_INVEN_ICON_NKM_MONSTER_BOSS_REPLACER_SEO_YOON_LANCE"
L27_1.StringValue = L28_1
L28_1 = "全力でかかってきなさい、ヤナギ・ミナ。前のようにやられるつもりはないから。"
L27_1.Text_JPN = L28_1
L28_1 = [[
You'd better do your best, Mina.
I'm not going to let you beat me like I used to.]]
L27_1.Text_ENG = L28_1
L28_1 = "你可要全力以赴哦，刘米娜。\n我可不会像以前那样输给你的。"
L27_1.Text_SCN = L28_1
L28_1 = "劉米娜，使盡你的全力吧！\n我可不會像上次一樣手下留情！"
L27_1.Text_TWN = L28_1
L28_1 = "มีนา ทำให้เต็มที่นะ\nฉันจะไม่ยอมแพ้เหมือนเมื่อก่อน"
L27_1.Text_THA = L28_1
L28_1 = "Tốt hơn là cô nên cố gắng hết sức đấy Mina ạ.\nTôi sẽ không để cô đánh bại tôi như trước đâu."
L27_1.Text_VTN = L28_1
L28_1 = "Gib bloß dein Bestes, Mina.\nIch lasse dich nicht mehr gewinnen wie früher."
L27_1.Text_DEU = L28_1
L28_1 = "J'espère que tu vas te donner à fond, Mina.\nJe ne compte pas me laisser faire, cette fois."
L27_1.Text_FRA = L28_1
