L29_1.EventType = "MESSAGE_BOX"
L30_1 = "설마 이걸로 끝은 아니시겠지?"
L29_1.Text_KOREA = L30_1
L30_1 = 2.5
L29_1.Value = L30_1
L30_1 = "AB_INVEN_ICON_NKM_MONSTER_BOSS_REPLACER_SEO_YOON_LANCE"
L29_1.StringValue = L30_1
L30_1 = "まさかこれで終わりじゃないでしょ？"
L29_1.Text_JPN = L30_1
L30_1 = "This isn't the best you can do, is it?"
L29_1.Text_ENG = L30_1
L30_1 = "我说你，不会就这么结束了吧？"
L29_1.Text_SCN = L30_1
L30_1 = "就只有這樣嗎？"
L29_1.Text_TWN = L30_1
L30_1 = "เธอทำได้มากกว่านี้ ใช่ไหม?"
L29_1.Text_THA = L30_1
L30_1 = "Đây không phải là thứ tốt nhất cô có thể làm, phải không?"
L29_1.Text_VTN = L30_1
L30_1 = "Na los, mehr hast du nicht drauf?"
L29_1.Text_DEU = L30_1
L30_1 = "Rassure-moi, tu peux faire mieux que ça ?"
L29_1.Text_FRA = L30_1
L30_1 = {}
L31_1 = "GameEvent_10053511_1"
L30_1.GameEventStrID = L31_1
L30_1.ProcessKey = 1
L31_1 = 10053511
L30_1.EventID = L31_1
L30_1.EventType = "MESSAGE_BOX"
L31_1 = "정신 차려, 유미나!\n저 녀석을 죽이지 못하면 우린 끝이야!"
L30_1.Text_KOREA = L31_1
L30_1.Value = 3
L31_1 = "AB_INVEN_ICON_NKM_MONSTER_BOSS_REPLACER_SEO_YOON_LANCE"
L30_1.StringValue = L31_1
L31_1 = "しっかりして、ミナ！　やつを仕留められないと全員ここでおしまいだよ！"
L30_1.Text_JPN = L31_1
L31_1 = [[
Snap out of it, Mina!
We must kill her before she kills us!]]
L30_1.Text_ENG = L31_1
L31_1 = "振作起来，刘米娜！\n干不掉那个家伙，我们就都完蛋了！"
L30_1.Text_SCN = L31_1
L31_1 = "劉米娜，你振作一點！\n不殺死那傢伙我們全都會完蛋的！"
L30_1.Text_TWN = L31_1
L31_1 = "ตั้งสติหน่อยสิ มีนา!\nเราต้องฆ่าเขาก่อนที่เขาจะฆ่าเรา!"
L30_1.Text_THA = L31_1
L31_1 = "Bỏ đi, Mina!\nChúng ta phải giết hắn trước khi hắn giết chúng ta!"
L30_1.Text_VTN = L31_1
L31_1 = "Komm wieder zu Sinnen, Mina!\nJetzt heißt es töten oder getötet werden!"
L30_1.Text_DEU = L31_1
L31_1 = "Secoue-toi, Mina !\nOn doit la tuer, sinon, on va y passer !"
L30_1.Text_FRA = L31_1
