L33_1 = "GameEvent_3264021_1"
L32_1.GameEventStrID = L33_1
L32_1.ProcessKey = 1
L33_1 = 3264021
L32_1.EventID = L33_1
L32_1.EventType = "MESSAGE_BOX"
L33_1 = "끝이다. 신벌을 내려주마."
L32_1.Text_KOREA = L33_1
L33_1 = 2.5
L32_1.Value = L33_1
L33_1 = "AB_INVEN_ICON_NKM_UNIT_JAPAN_C_OROCHI"
L32_1.StringValue = L33_1
L33_1 = "終わりだ。神罰を食らうがいい。"
L32_1.Text_JPN = L33_1
L33_1 = "It’s over now. Time for your punishment."
L32_1.Text_ENG = L33_1
L33_1 = "结束了，这是神罚！"
L32_1.Text_SCN = L33_1
L33_1 = "都結束了，接受天譴吧！"
L32_1.Text_TWN = L33_1
L33_1 = "มันจบแล้ว ได้เวลาลงโทษเจ้าแล้ว"
L32_1.Text_THA = L33_1
L33_1 = "Nó kết thúc rồi. Đã đến lúc các người bị trừng phạt."
L32_1.Text_VTN = L33_1
L33_1 = "Schluss damit. Es wird Zeit für deine Strafe."
L32_1.Text_DEU = L33_1
L33_1 = "Tout est fini, maintenant. L'heure de votre châtiment a sonné."
L32_1.Text_FRA = L33_1
