L34_1 = "GameEvent_3264021_2"
L33_1.GameEventStrID = L34_1
L33_1.ProcessKey = 2
L34_1 = 3264021
L33_1.EventID = L34_1
L33_1.EventType = "MESSAGE_BOX"
L34_1 = "저흰 미나토님이 준비가 끝날 때까지\n시간을 벌겠습니다."
L33_1.Text_KOREA = L34_1
L34_1 = 2.5
L33_1.Value = L34_1
L34_1 = "AB_INVEN_ICON_NKM_UNIT_C_JAPAN_SETSUNA"
L33_1.StringValue = L34_1
L34_1 = "私たちは湊様の準備が終わるまで\n時間を稼ぎます。"
L33_1.Text_JPN = L34_1
L34_1 = "We’ll buy you some time\nuntil you’re ready, Mr. Nayuka."
L33_1.Text_ENG = L34_1
L34_1 = "在峰奈完成准备前，\n我们会争取些时间。"
L33_1.Text_SCN = L34_1
L34_1 = "在南裕夏準備好前，\n我們會負責爭取時間。"
L33_1.Text_TWN = L34_1
L34_1 = "เราจะถ่วงเวลาให้\nจนกว่าคุณจะพร้อมนะคะนายท่านมินาโตะ"
L33_1.Text_THA = L34_1
L34_1 = "Chúng tôi sẽ câu giờ cho cậu một lúc\ncho đến khi cậu sẵn sàng, Chủ Nhân Minato."
L33_1.Text_VTN = L34_1
L34_1 = [[
Wir werden Ihnen etwas Zeit verschaffen, bis Sie bereit sind,
Herr Nayuka.]]
L33_1.Text_DEU = L34_1
L34_1 = "Nous allons essayer de gagner du temps\njusqu'à ce que vous soyez prêt, Minato."
L33_1.Text_FRA = L34_1
