L46_1 = 10084414
L45_1.EventID = L46_1
L45_1.EventType = "MESSAGE_BOX"
L46_1 = "레드 카펫을 깔아 뒀다고, 용병 아가씨."
L45_1.Text_KOREA = L46_1
L46_1 = 2.5
L45_1.Value = L46_1
L46_1 = "AB_INVEN_ICON_NKM_UNIT_DELTA_CA_JAKE"
L45_1.StringValue = L46_1
L46_1 = "さあ、俺が敷いたレッドカーペットに上がってくれ、傭兵のお嬢ちゃん。"
L45_1.Text_JPN = L46_1
L46_1 = "I have the red carpet ready for you, mercenary girl."
L45_1.Text_ENG = L46_1
L46_1 = "已经铺上红地毯了，佣兵小姐。"
L45_1.Text_SCN = L46_1
L46_1 = "傭兵，快幫我鋪好紅地毯！"
L45_1.Text_TWN = L46_1
L46_1 = "ฉันเตรียมพรมแดงไว้ให้เธอแล้วนะ แม่สาวทหารรับจ้าง"
L45_1.Text_THA = L46_1
L46_1 = "Tôi đã chuẩn bị sẵn thảm đỏ cho cô rồi, cô gái lính đánh thuê ạ."
L45_1.Text_VTN = L46_1
L46_1 = "Der rote Teppich steht bereit, Fräulein Söldnerin."
L45_1.Text_DEU = L46_1
L46_1 = "J'ai déployé le tapis rouge pour toi, la mercenaire."
L45_1.Text_FRA = L46_1
