L46_1.Value = L47_1
L47_1 = "AB_INVEN_ICON_NKM_UNIT_CA_YOO_MI_NA"
L46_1.StringValue = L47_1
L47_1 = "冗談はあいつを倒してからにして！"
L46_1.Text_JPN = L47_1
L47_1 = "Crack your jokes after you kill that guy!"
L46_1.Text_ENG = L47_1
L47_1 = "玩笑就等到干掉那家伙再说吧！"
L46_1.Text_SCN = L47_1
L47_1 = "等打倒那傢伙再聊吧！"
L46_1.Text_TWN = L47_1
L47_1 = "ฆ่ามันก่อนแล้วค่อยขายขำเถอะค่ะ!"
L46_1.Text_THA = L47_1
L47_1 = "Hãy thôi ngay những trò đùa ấy sau khi giết hắn ta!"
L46_1.Text_VTN = L47_1
L47_1 = "Witze kannst du machen, nachdem du ihn kaltgemacht hast!"
L46_1.Text_DEU = L47_1
L47_1 = "Garde tes plaisanteries pour quand on aura éliminé ce type !"
