L48_1 = "GameEvent_3281031_1"
L47_1.GameEventStrID = L48_1
L47_1.ProcessKey = 1
L48_1 = 3281031
L47_1.EventID = L48_1
L47_1.EventType = "MESSAGE_BOX"
L48_1 = "걱정마십쇼! 토미 더 다이하드가 저놈을 꼭 잡겠습니다."
L47_1.Text_KOREA = L48_1
L48_1 = 2.5
L47_1.Value = L48_1
L48_1 = "AB_INVEN_ICON_NKM_UNIT_S_SOF_HOGSBACK"
L47_1.StringValue = L48_1
L48_1 = "ご心配なく！　トミー・ザ・ダイハードがあいつを必ず捕まえてみせます。"
L47_1.Text_JPN = L48_1
L48_1 = "Don't worry. Tommy the Die-hard will get that jerk for you."
L47_1.Text_ENG = L48_1
L48_1 = "别担心！顽强·汤米一定会抓到他。"
L47_1.Text_SCN = L48_1
L48_1 = "安啦！頑強·湯米一定會抓到那傢伙！"
L47_1.Text_TWN = L48_1
L48_1 = "ไม่ต้องห่วง ทอมมี่ คนอึดตายยาก จะจับคนชั่วนั่นให้เอง"
L47_1.Text_THA = L48_1
L48_1 = "Đừng lo. Tommy Cứng Đầu sẽ xử lý gã đó cho anh."
L47_1.Text_VTN = L48_1
L48_1 = "Keine Sorge! Tommy, der Hartgesottene, wird ihn auf jeden Fall kriegen."
L47_1.Text_DEU = L48_1
L48_1 = "Aucune inquiétude ! Moi, Tommy le borné, j'attraperai ce type pour vous !"
L47_1.Text_FRA = L48_1
