L6_1 = "GameEvent_3300182_1"
L5_1.GameEventStrID = L6_1
L5_1.ProcessKey = 1
L6_1 = 3300182
L5_1.EventID = L6_1
L5_1.EventType = "MESSAGE_BOX"
L6_1 = "능력을 사용하진 않아...\n아니, 못하는건가?"
L5_1.Text_KOREA = L6_1
L5_1.Value = 3
L6_1 = "AB_INVEN_ICON_NKM_UNIT_C_ALPHA_JIA"
L5_1.StringValue = L6_1
L6_1 = "能力を使ってはいない……\nううん、使えないのかな？"
L5_1.Text_JPN = L6_1
L6_1 = "She’s not using her abilities...\nWait, is she unable to?"
L5_1.Text_ENG = L6_1
L6_1 = "没使用能力……\n不，是不能使用吧？"
L5_1.Text_SCN = L6_1
L6_1 = "不使用能力…\n還是無法用？"
L5_1.Text_TWN = L6_1
L6_1 = "เธอไม่ได้ใช้ความสามารถนี่...\nเดี๋ยวนะ หรือเธอใช้ไม่ได้"
L5_1.Text_THA = L6_1
L6_1 = "Cô ấy không sử dụng khả năng của mình... \n Chờ đã, hay là cô ấy không thể?"
L5_1.Text_VTN = L6_1
L6_1 = "Benutzt sie keine Fähigkeiten ...\nOder kann sie es etwa nicht?"
L5_1.Text_DEU = L6_1
L6_1 = "Elle n'utilise pas ses capacités...\nOu alors en est-elle incapable ?"
L5_1.Text_FRA = L6_1
