L18_1 = "GameEvent_3322114_1"
L17_1.GameEventStrID = L18_1
L17_1.ProcessKey = 1
L18_1 = 3322114
L17_1.EventID = L18_1
L17_1.EventType = "MESSAGE_BOX"
L18_1 = "아군의 바이탈 사인에 이상 발생!\n조치가 늦어지면 돌이킬 수 없습니다!"
L17_1.Text_KOREA = L18_1
L17_1.Value = 2
L18_1 = "AB_INVEN_ICON_OPR_OLD_ALICIA"
L17_1.StringValue = L18_1
L18_1 = "味方のバイタルサインに異常発生！\n至急措置を行わなければ、取り返しのつかないことになります！"
L17_1.Text_JPN = L18_1
L18_1 = "Abnormality detected in friendly vital signals!\nWe need to do something before it’s too late!"
L17_1.Text_ENG = L18_1
L18_1 = "友军的生命体征出现异常！\n请尽快结束战斗，否则结果可能无法挽回！"
L17_1.Text_SCN = L18_1
L18_1 = "我方的生命徵象發生異常！\n不快點處理恐怕會無法挽回！"
L17_1.Text_TWN = L18_1
L18_1 = "ตรวจพบความผิดปกติในสัญญาณชีพของฝ่ายเดียวกันค่ะ!\nเราต้องทำอะไรสักอย่างก่อนจะสายไปนะคะ!"
L17_1.Text_THA = L18_1
L18_1 = "Phát hiện bất thường trong các tín hiệu quan trọng của đồng đội!\nChúng ta cần phải làm gì đó trước khi quá muộn!"
L17_1.Text_VTN = L18_1
L18_1 = "Abnormalität in lebenswichtigen Signalen!\nWir müssen etwas tun, bevor es zu spät ist!"
L17_1.Text_DEU = L18_1
L18_1 = "Anomalie détectée dans les points vitaux des alliés !\nNous devons faire quelque chose avant qu'il ne soit trop tard !"
L17_1.Text_FRA = L18_1
L18_1 = {}
L19_1 = "GameEvent_3322114_2"
L18_1.GameEventStrID = L19_1
L18_1.ProcessKey = 2
L19_1 = 3322114
L18_1.EventID = L19_1
L18_1.EventType = "MESSAGE_BOX"
L19_1 = "스승님! 저희도 돕겠습니다!"
L18_1.Text_KOREA = L19_1
L18_1.Value = 2
L18_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_NA_YUBIN"
L19_1 = "師匠！　私たちも協力します！"
L18_1.Text_JPN = L19_1
L19_1 = "Master! We’ll help too!"
L18_1.Text_ENG = L19_1
L19_1 = "老师！我们也来帮忙！"
L18_1.Text_SCN = L19_1
L19_1 = "師父！我們也來幫忙！"
L18_1.Text_TWN = L19_1
L19_1 = "อาจารย์ครับ! เราก็จะช่วยอีกแรงครับ!"
L18_1.Text_THA = L19_1
L19_1 = "Sếp! Chúng tôi cũng sẽ giúp!"
L18_1.Text_VTN = L19_1
L19_1 = "Meisterin! Wir helfen auch!"
L18_1.Text_DEU = L19_1
L19_1 = "Maître ! Nous allons vous aider !"
L18_1.Text_FRA = L19_1
L19_1 = {}
L20_1 = "GameEvent_3322114_3"
L19_1.GameEventStrID = L20_1
L19_1.ProcessKey = 3
L20_1 = 3322114
L19_1.EventID = L20_1
L19_1.EventType = "MESSAGE_BOX"
L20_1 = "분홍 머리는 놓쳤지만 검은 머리는 확실하게 해치웠어요!"
L19_1.Text_KOREA = L20_1
L19_1.Value = 2
L19_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_LEE_SUYEON"
L20_1 = "ピンク髪は逃がしましたが、黒髪は確実に仕留めました！"
L19_1.Text_JPN = L20_1
L20_1 = "We lost the pink hair, but we got the black one!"
L19_1.Text_ENG = L20_1
L20_1 = "虽然让那个粉色头发的逃掉了，但黑头发的确定已经被消灭！"
L19_1.Text_SCN = L20_1
L20_1 = "被那個粉紅色頭髮的給逃掉，不過黑頭髮的有確實處理掉！"
L19_1.Text_TWN = L20_1
L20_1 = "เราพลาดยัยหัวชมพูไป แต่ยัยหัวดำยังได้นะ!"
L19_1.Text_THA = L20_1
L20_1 = "Chúng tôi đã mất dấu tóc hồng, nhưng chúng tôi đã bắt được tóc đen!"
L19_1.Text_VTN = L20_1
L20_1 = "Wir haben die Rosane verloren, aber dafür haben wir die Schwarzhaarige!"
L19_1.Text_DEU = L20_1
L20_1 = "On a loupé la fille aux cheveux roses, mais on s'est occupé de celle aux cheveux noirs !"
L19_1.Text_FRA = L20_1
L20_1 = {}
L21_1 = "GameEvent_3322114_4"
L20_1.GameEventStrID = L21_1
L20_1.ProcessKey = 4
L21_1 = 3322114
L20_1.EventID = L21_1
L20_1.EventType = "MESSAGE_BOX"
L21_1 = "좋아, 네퀴티아도 무리한 상태다! 전 대원, 화력 집중!"
L20_1.Text_KOREA = L21_1
L20_1.Value = 2
L20_1.StringValue = "AB_INVEN_ICON_NKM_UNIT_C_HILDE_ADMIN"
L21_1 = "よし、ネキティアも大分無理している！　全隊員、火力を集中しろ！"
L20_1.Text_JPN = L21_1
L21_1 = "Good! Nequitia is on her back foot! All personnel, focus fire!"
L20_1.Text_ENG = L21_1
L21_1 = "很好，莉奎蒂亚也快坚持不住了！全员集中火力！"
L20_1.Text_SCN = L21_1
L21_1 = "很好！莉奎蒂亞現在也很虛弱！全員集中火力！"
L20_1.Text_TWN = L21_1
L21_1 = "ดีมาก! เนกีเทียกำลังเสียเปรียบ! ทุกคน ยิง!"
L20_1.Text_THA = L21_1
L21_1 = "Tốt! Nequitia đang ở thế yếu! Tất cả nhân viên, tập trung hỏa lực!"
L20_1.Text_VTN = L21_1
L21_1 = "Gut! Nequitia ist geschwächt! Alle zielen!!!"
L20_1.Text_DEU = L21_1
L21_1 = "Allez, Niquita est en difficulté ! À toutes les unités, feu à volonté !"
L20_1.Text_FRA = L21_1
L21_1 = {}
L22_1 = "GameEvent_3322215_1"
L21_1.GameEventStrID = L22_1
L21_1.ProcessKey = 1
L22_1 = 3322215
L21_1.EventID = L22_1
L21_1.EventType = "MESSAGE_BOX"
L22_1 = "레버넌트 씨! 밖에서 다른 침식체 울음소리도 들려 와요!"
L21_1.Text_KOREA = L22_1
L21_1.Value = 2
L22_1 = "AB_INVEN_ICON_NKM_UNIT_SECURITY_C_ROOKIE"
L21_1.StringValue = L22_1
L22_1 = "レヴナントさん！　外から別の侵食体の鳴き声も聞こえてきます！"
L21_1.Text_JPN = L22_1
L22_1 = "Revenant! I can hear the cries of another C.O. outside!"
L21_1.Text_ENG = L22_1
L22_1 = "亡灵！外边传来了其他侵蚀体的声音！"
L21_1.Text_SCN = L22_1
L22_1 = "亡靈小姐！外面也傳來其他侵蝕體的吼叫聲啦！"
L21_1.Text_TWN = L22_1
L22_1 = "คุณเรเวแนนต์คะ! ฉันได้ยินเสียงวัตถุคอร์รัปต์อีกตัวร้องอยู่ด้านนอกค่ะ!"
L21_1.Text_THA = L22_1
L22_1 = "Cô Revenant! Tôi có thể nghe thấy tiếng kêu của V.T.A.M khác bên ngoài!"
L21_1.Text_VTN = L22_1
L22_1 = "Revenant! Ich kann die Schreie eines anderen C. O. draußen hören!"
L21_1.Text_DEU = L22_1
L22_1 = "Revenant ! J'entends des O.C. à l'extérieur, ici aussi !"
L21_1.Text_FRA = L22_1
L22_1 = {}
L23_1 = "GameEvent_3322215_2"
L22_1.GameEventStrID = L23_1
L22_1.ProcessKey = 2
L23_1 = 3322215
L22_1.EventID = L23_1
L22_1.EventType = "MESSAGE_BOX"
L23_1 = "자기보다 급이 높은 침식체에게 이끌린 거야! 저 녀석만 해치우면 돼!"
L22_1.Text_KOREA = L23_1
L22_1.Value = 2
L23_1 = "AB_INVEN_ICON_NKM_UNIT_SECURITY_S_AGENT"
L22_1.StringValue = L23_1
L23_1 = "自分より格上の侵食体に惹かれて来たんだ！　あいつだけやっつければいい！"
L22_1.Text_JPN = L23_1
L23_1 = "It must be drawn to the stronger C.O.! We just have to take it down!"
L22_1.Text_ENG = L23_1
L23_1 = "可能是被比自己高级的侵蚀体吸引过来的！集中火力消灭那家伙就可以了！"
L22_1.Text_SCN = L23_1
L23_1 = "是階級比較高的侵蝕體在帶領它們的！擒賊先擒王！"
L22_1.Text_TWN = L23_1
L23_1 = "มันอาจโดนวัตถุคอร์รัปต์ที่แข็งแกร่งกว่าดึงมานะ! เราต้องกำจัดมันซะ!"
L22_1.Text_THA = L23_1
L23_1 = "Có lẽ chuyện này đã thu hít V.T.A.M mạnh hơn! Chúng ta phải hạ nó!"
L22_1.Text_VTN = L23_1
L23_1 = "Es muss vom stärkeren C. O. angezogen werden! Wir müssen es erledigen!"
L22_1.Text_DEU = L23_1
L23_1 = "Ils ont sûrement été attirés par l'O.C. alpha ! Occupons-nous de lui en priorité !"
L22_1.Text_FRA = L23_1
L23_1 = {}
L24_1 = "GameEvent_3322215_3"
L23_1.GameEventStrID = L24_1
L23_1.ProcessKey = 3
L24_1 = 3322215
L23_1.EventID = L24_1
L23_1.EventType = "MESSAGE_BOX"
L24_1 = "칫……! 까짓거 해 보죠! 죽으면 알아서 해요!"
L23_1.Text_KOREA = L24_1
L23_1.Value = 2
L24_1 = "AB_INVEN_ICON_NKM_UNIT_SECURITY_C_ROOKIE"
L23_1.StringValue = L24_1
L24_1 = "ちっ……！　やるしかないですね！　死んだら責任取ってくださいよ！"
L23_1.Text_JPN = L24_1
L24_1 = "Tsk...! Let’s do this! Just try to keep us alive!"
L23_1.Text_ENG = L24_1
L24_1 = "……那就拼了！死了就算自己倒霉！"
L23_1.Text_SCN = L24_1
L24_1 = "嘖……！死馬當活馬醫吧！死掉的話就自己看著辦！"
L23_1.Text_TWN = L24_1
L24_1 = "ชิ...! ลุยกันเลยเถอะ! พยายามอย่าให้เราตายก็พอ!"
L23_1.Text_THA = L24_1
L24_1 = "Tsk...! Làm thôi nào! Chỉ cần cố gắng sống sót!"
L23_1.Text_VTN = L24_1
L24_1 = "Pft ...! Lass uns das machen! Versuch einfach, uns am Leben zu halten!"
L23_1.Text_DEU = L24_1
L24_1 = "Tss... ! Bien, on a pas le choix. Essayez de rester en vie !"
L23_1.Text_FRA = L24_1
L24_1 = {}
L25_1 = "GameEvent_3322216_1"
L24_1.GameEventStrID = L25_1
L24_1.ProcessKey = 1
L25_1 = 3322216
L24_1.EventID = L25_1
L24_1.EventType = "MESSAGE_BOX"
L25_1 = "저 여자도 암살자와 공범이 틀림없다! 숨만 붙여 둬라!"
L24_1.Text_KOREA = L25_1
L24_1.Value = 2
L25_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_SHIELD"
L24_1.StringValue = L25_1
L25_1 = "あの女も暗殺者と共犯に違いない！　息の根は止めるなよ！"
L24_1.Text_JPN = L25_1
L25_1 = "That woman must be an accomplice of the assassin! Capture her whatever it takes!"
L24_1.Text_ENG = L25_1
L25_1 = "那个女人和暗杀者是一伙的！给我抓住她，只要留一口气就行！"
L24_1.Text_SCN = L25_1
L25_1 = "那女的肯定也是殺手的共犯！我要她的命！"
L24_1.Text_TWN = L25_1
L25_1 = "ผู้หญิงคนนั้นต้องงสมรู้ร่วมคิดกับมือลอบสังหารแน่! จับตัวเธอมาให้ได้!"
L24_1.Text_THA = L25_1
L25_1 = "Người phụ nữ đó là đồng phạm của tên sát thủ! Bắt cô ấy bằng bất cứ giá nào!"
L24_1.Text_VTN = L25_1
L25_1 = "Diese Frau muss eine Komplizin des Attentäters sein! Fang sie, was auch immer es braucht!"
L24_1.Text_DEU = L25_1
L25_1 = "Cette femme est certainement la complice du tireur ! Capturez-la coûte que coûte !"
L24_1.Text_FRA = L25_1
L25_1 = {}
L26_1 = "GameEvent_3322216_2"
L25_1.GameEventStrID = L26_1
L25_1.ProcessKey = 2
L26_1 = 3322216
L25_1.EventID = L26_1
L25_1.EventType = "MESSAGE_BOX"
L26_1 = "분위기가 살벌하네. 여유 부리다간 험한 꼴 보겠는데?"
L25_1.Text_KOREA = L26_1
L25_1.Value = 2
L26_1 = "AB_INVEN_ICON_NKM_UNIT_SECURITY_S_AGENT"
L25_1.StringValue = L26_1
L26_1 = "恐ろしいったらありゃしない。余裕こいてたら痛い目見そうだね。"
L25_1.Text_JPN = L26_1
L26_1 = "Look at the mood. Best not take this lightly."
L25_1.Text_ENG = L26_1
L26_1 = "气氛很恐怖呢。再不认真点，恐怕会很危险啊？"
L25_1.Text_SCN = L26_1
L26_1 = "氣氛真是緊張，再這樣無關緊要的會很慘吧？"
L25_1.Text_TWN = L26_1
L26_1 = "ดูจากบรรยากาศแล้ว ไม่ทำเป็นเล่นจะดีที่สุดสินะ"
L25_1.Text_THA = L26_1
L26_1 = "Nhìn vào tâm trạng của họ đi. Tốt nhất đừng chủ quan."
L25_1.Text_VTN = L26_1
L26_1 = "Schau dir die Stimmung an. Am besten nimmst du das nicht zu leicht."
L25_1.Text_DEU = L26_1
L26_1 = "Bonjour l'ambiance. Mieux vaut ne pas prendre tout ça à la légère."
L25_1.Text_FRA = L26_1
L26_1 = {}
L27_1 = "GameEvent_3322217_1"
L26_1.GameEventStrID = L27_1
L26_1.ProcessKey = 1
L27_1 = 3322217
L26_1.EventID = L27_1
L26_1.EventType = "MESSAGE_BOX"
L27_1 = "제기랄! 한 명을 못 잡고 놓친다고?! 당장 도로를 봉쇄하라고 해!"
L26_1.Text_KOREA = L27_1
L26_1.Value = 2
L27_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_SHIELD"
L26_1.StringValue = L27_1
L27_1 = "ちっくしょう！　たった一人を捕まえられないだと！？　今すぐ道路を封鎖させろ！"
L26_1.Text_JPN = L27_1
L27_1 = "Dammit! It’s just one person! Seal off the roads now!"
L26_1.Text_ENG = L27_1
L27_1 = "废物！你们连一个人都抓不住？！给我立即封锁道路！"
L26_1.Text_SCN = L27_1
L27_1 = "該死！連一個人也抓不到嗎？！立刻封鎖道路！"
L26_1.Text_TWN = L27_1
L27_1 = "บัดซบเอ๊ย! แค่คนเดียวเองนะ! ปิดถนนเดี๋ยวนี้!"
L26_1.Text_THA = L27_1
L27_1 = "Khỉ thật! Đó chỉ là một người! Phong tỏa các con đường ngay bây giờ!"
L26_1.Text_VTN = L27_1
L27_1 = "Zum Teufel noch mal! Es ist nur eine Person! Sperrt die Straßen!"
L26_1.Text_DEU = L27_1
L27_1 = "Merde ! Elle est seule, bon sang ! Bloquez toutes les issues immédiatement !"
L26_1.Text_FRA = L27_1
L27_1 = {}
L28_1 = "GameEvent_3322217_2"
L27_1.GameEventStrID = L28_1
L27_1.ProcessKey = 2
L28_1 = 3322217
L27_1.EventID = L28_1
L27_1.EventType = "MESSAGE_BOX"
L28_1 = "레버넌트. 합류지점으로 신속하게 이동해라.\n지체할 시 전원 철수하겠다."
L27_1.Text_KOREA = L28_1
L27_1.Value = 2
L28_1 = "AB_INVEN_ICON_NKM_NPC_SUIT"
L27_1.StringValue = L28_1
L28_1 = "レヴナント、速やかに合流地点に移動しろ。\n遅れるなら全員撤収させてもらう。"
L27_1.Text_JPN = L28_1
L28_1 = "Revenant. Proceed to the rendezvous point swiftly.\nI’ll be pulling out all agents if you take too long."
L27_1.Text_ENG = L28_1
L28_1 = "亡灵。尽快移动到会合地点。\n要是迟到，我会撤离全部人员。"
L27_1.Text_SCN = L28_1
L28_1 = "亡靈，立刻移動至會合地點！\n稍有拖延就全員撤退！"
L27_1.Text_TWN = L28_1
L28_1 = "เรเวแนนต์ รีบไปเจอกันที่จุดนัดพบนะ\nถ้าเธอชักช้าฉันจะถอนกำลังทั้งหมดออกมา"
L27_1.Text_THA = L28_1
L28_1 = "Revenant. Nhanh chóng đến điểm hẹn.\nTôi sẽ rút tất cả các đặc vụ nếu cô mất quá nhiều thời gian."
L27_1.Text_VTN = L28_1
L28_1 = "Revenant. Schnell zum Treffpunkt!\nIch ziehe alle Agenten zurück, wenn du zu spät bist."
L27_1.Text_DEU = L28_1
L28_1 = "Rendez-vous à l'endroit convenu, Revenant.\nDépêche-toi, où j'ordonne le repli général."
L27_1.Text_FRA = L28_1
L28_1 = {}
L29_1 = "GameEvent_3322217_3"
L28_1.GameEventStrID = L29_1
L28_1.ProcessKey = 3
L29_1 = 3322217
L28_1.EventID = L29_1
L28_1.EventType = "MESSAGE_BOX"
L29_1 = "투항하는 꼴 보기 싫으면 그만두시죠, 국장님?"
L28_1.Text_KOREA = L29_1
L28_1.Value = 2
L29_1 = "AB_INVEN_ICON_NKM_UNIT_SECURITY_S_AGENT"
L28_1.StringValue = L29_1
L29_1 = "投降されたくなければやめてください、局長。"
L28_1.Text_JPN = L29_1
L29_1 = "Why don’t you leave it at that unless you wanna see me surrender, Chief?"
L28_1.Text_ENG = L29_1
L29_1 = "如果不想看到我投降，就别来这一套了吧。局长？"
L28_1.Text_SCN = L29_1
L29_1 = "不想投降的話，就請住手吧，部長？"
L28_1.Text_TWN = L29_1
L29_1 = "ถ้าไม่ได้อยากเห็นฉันยอมมอบตัวแล้วทำไมปล่อยให้เป็นแบบนี้คะหัวหน้า?"
L28_1.Text_THA = L29_1
L29_1 = "Tại sao ông không để vậy đi trừ khi ông muốn thấy tôi đầu hàng, Cục Trưởng?"
L28_1.Text_VTN = L29_1
L29_1 = "Warum lassen Sie es nicht dabei, es sei denn, Sie möchten mich aufgeben sehen, Chef?"
L28_1.Text_DEU = L29_1
L29_1 = "Pourquoi ne pas en rester là, chef ? À moins que vous ne vouliez me voir rendre les armes ?"
L28_1.Text_FRA = L29_1
L29_1 = {}
L30_1 = "GameEvent_3322218_1"
L29_1.GameEventStrID = L30_1
L29_1.ProcessKey = 1
L30_1 = 3322218
L29_1.EventID = L30_1
L29_1.EventType = "MESSAGE_BOX"
L30_1 = "추격해 오는 병력들의 식별 신호는 반군으로 확인. 일할 때야."
L29_1.Text_KOREA = L30_1
L29_1.Value = 2
L30_1 = "AB_INVEN_ICON_NKM_UNIT_S_FOX_SNIPER"
L29_1.StringValue = L30_1
L30_1 = "追っ手の識別信号が反乱軍のものと確認した。仕事の時間よ。"
L29_1.Text_JPN = L30_1
L30_1 = "The forces in pursuit are all confirmed to be rebels. Time to get to work."
L29_1.Text_ENG = L30_1
L30_1 = "确认了，这些追击的车辆是叛军的。该大干一场了，伙计们！"
L29_1.Text_SCN = L30_1
L30_1 = "追上來兵力的識別訊號確定是叛軍，幹活兒！"
L29_1.Text_TWN = L30_1
L30_1 = "ยืนยันได้แล้วว่ากองกำลังที่กำลังตามล่าเป็นกบฏทั้งหมด ได้เวลาทำงานแล้ว"
L29_1.Text_THA = L30_1
L30_1 = "Các lực lượng truy đuổi đều được xác nhận là phiến quân. Đến lúc làm việc rồi."
L29_1.Text_VTN = L30_1
L30_1 = "Die Streitkräfte zur Verfolgung sind alle als Rebellen bestätigt. Zeit, sich an die Arbeit zu machen."
L29_1.Text_DEU = L30_1
L30_1 = "Les cibles ont toutes été confirmées comme appartenant aux rebelles. Au travail, les gars."
L29_1.Text_FRA = L30_1
L30_1 = {}
L31_1 = "GameEvent_3322218_2"
L30_1.GameEventStrID = L31_1
L30_1.ProcessKey = 2
L31_1 = 3322218
L30_1.EventID = L31_1
L30_1.EventType = "MESSAGE_BOX"
L31_1 = "정찰만 하라더니 나 원. 그로니아에서 일감 받지 말라는 소문이 사실이었군."
L30_1.Text_KOREA = L31_1
L30_1.Value = 2
L31_1 = "AB_INVEN_ICON_NKM_UNIT_S_FOX_RIFLE"
L30_1.StringValue = L31_1
L31_1 = "偵察だけって話じゃなかったのかよ、ったく。グロニアの仕事は受けるもんじゃないって噂は本当だったな。"
L30_1.Text_JPN = L31_1
L31_1 = "I thought this was just going to be a patrol job. Guess I should’ve listened when people told me not to take jobs from Gronia."
L30_1.Text_ENG = L31_1
L31_1 = "什么？不是让我们来侦察吗？难怪别人都说别接格洛尼亚的活。"
L30_1.Text_SCN = L31_1
L31_1 = "竟然只叫我們巡邏？難怪人家說不要接格羅尼亞的活兒！"
L30_1.Text_TWN = L31_1
L31_1 = "นึกว่านี่จะแค่ลาดตระเวนซะอีก สงสัยเวลาใครบอกว่าอย่ารับงานจากโกรเนียต้องหัดฟังซะบ้างแล้วแฮะ"
L30_1.Text_THA = L31_1
L31_1 = "Tôi đã nghĩ đây chỉ là cuộc tuần tra. Chắc rằng tôi nên nghe lời khi mọi người bảo tôi không nên nhận việc từ Gronia."
L30_1.Text_VTN = L31_1
L31_1 = "Ich dachte, das würde nur ein Patrouillenjob werden. Ich schätze, ich hätte zuhören sollen, als die Leute mir sagten, ich solle keine Jobs von Gronia annehmen."
L30_1.Text_DEU = L31_1
L31_1 = "Je m'attendais à une simple mission de patrouille, moi. C'est vrai ce qu'on dit, il ne faut jamais accepter de travail à Gronia..."
L30_1.Text_FRA = L31_1
L31_1 = {}
L32_1 = "GameEvent_3322218_3"
L31_1.GameEventStrID = L32_1
L31_1.ProcessKey = 3
L32_1 = 3322218
L31_1.EventID = L32_1
L31_1.EventType = "MESSAGE_BOX"
L32_1 = "섭섭한 말씀 마세요. 추가 수당은 잔뜩 챙겨 드릴 테니까."
L31_1.Text_KOREA = L32_1
L31_1.Value = 2
L32_1 = "AB_INVEN_ICON_NKM_UNIT_SECURITY_S_AGENT"
L31_1.StringValue = L32_1
L32_1 = "寂しいこと言わないでください。追加の料金はたっぷり支払いますから。"
L31_1.Text_JPN = L32_1
L32_1 = "Hey now, don’t be like that. I’ll make sure you get a hefty bonus."
L31_1.Text_ENG = L32_1
L32_1 = "别这么说啦，朋友。额外的酬劳不会让你失望的。"
L31_1.Text_SCN = L32_1
L32_1 = "別這麼說，我會替你們多爭取些津貼的。"
L31_1.Text_TWN = L32_1
L32_1 = "เฮ้ อย่าทำแบบนั้นสิ เดี๋ยวฉันช่วยให้ได้โบนัสก้อนโตเลยนะ"
L31_1.Text_THA = L32_1
L32_1 = "Này, đừng như vậy. Tôi đảm bảo anh sẽ nhận được một khoản tiền thưởng kếch xù."
L31_1.Text_VTN = L32_1
L32_1 = "Hey jetzt, sei nicht so. Ich werde sicherstellen, dass ihr einen kräftigen Bonus erhaltet."
L31_1.Text_DEU = L32_1
L32_1 = "Bah, dites pas ça. Je ferai en sorte que vous obteniez une prime bien grasse."
L31_1.Text_FRA = L32_1
L32_1 = {}
L33_1 = "GameEvent_3322218_4"
L32_1.GameEventStrID = L33_1
L32_1.ProcessKey = 4
L33_1 = 3322218
L32_1.EventID = L33_1
L32_1.EventType = "MESSAGE_BOX"
L33_1 = "매, 매복입니다! 보안국이 고용한 용병들 같습니다!"
L32_1.Text_KOREA = L33_1
L32_1.Value = 2
L33_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_RIFLE"
L32_1.StringValue = L33_1
L33_1 = "ま、待ち伏せされました！　保安局に雇われた傭兵かと！"
L32_1.Text_JPN = L33_1
L33_1 = "It’s an ambush! They seem to be mercenaries hired by the DNS!"
L32_1.Text_ENG = L33_1
L33_1 = "有、有埋伏！应该是那个女人雇佣的佣兵！"
L32_1.Text_SCN = L33_1
L33_1 = "有…有埋伏！好像是安全局雇用的傭兵！"
L32_1.Text_TWN = L33_1
L33_1 = "เราโดนซุ่มโจมตี! เหมือนจะเป็นทหารรับจ้างจาก DNS นะ!"
L32_1.Text_THA = L33_1
L33_1 = "Đó là một cuộc phục kích! Họ dường như là lính đánh thuê do Cục ANQG thuê!"
L32_1.Text_VTN = L33_1
L33_1 = "Es ist ein Hinterhalt! Sie scheinen Söldner zu sein, die von der Abteilung für nationale Sicherheit eingestellt wurden!"
L32_1.Text_DEU = L33_1
L33_1 = "U-Une embuscade ! On dirait des mercenaires engagés par le Bureau !"
L32_1.Text_FRA = L33_1
L33_1 = {}
L34_1 = "GameEvent_3322218_5"
L33_1.GameEventStrID = L34_1
L33_1.ProcessKey = 5
L34_1 = 3322218
L33_1.EventID = L34_1
L33_1.EventType = "MESSAGE_BOX"
L34_1 = "닥쳐! 숫자도 화력도 우리가 우세하다! 공격해!  "
L33_1.Text_KOREA = L34_1
L33_1.Value = 2
L34_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_SHIELD"
L33_1.StringValue = L34_1
L34_1 = "うるさい！　数も火力もこっちが優勢だ！　撃て！  "
L33_1.Text_JPN = L34_1
L34_1 = "Shut it! We have more men and more guns! Attack!  "
L33_1.Text_ENG = L34_1
L34_1 = "闭嘴！不论是兵力还是人数都是我们占优！给我攻击！  "
L33_1.Text_SCN = L34_1
L34_1 = "閉嘴！無論是人數或是火力，都是我們佔優勢！攻擊！"
L33_1.Text_TWN = L34_1
L34_1 = "หุบปากน่า! เราเยอะกว่าทั้งคนทั้งปืนนะ! ลุยเลย!"
L33_1.Text_THA = L34_1
L34_1 = "Im đi! Chúng ta có nhiều người và nhiều súng hơn! Tấn công!"
L33_1.Text_VTN = L34_1
L34_1 = "Halt die Schnauze! Wir haben mehr Männer und mehr Waffen! Attacke!"
L33_1.Text_DEU = L34_1
L34_1 = "La ferme ! On à l'avantage tactique et numérique, feu !!"
L33_1.Text_FRA = L34_1
L34_1 = {}
L35_1 = "GameEvent_3322219_1"
L34_1.GameEventStrID = L35_1
L34_1.ProcessKey = 1
L35_1 = 3322219
L34_1.EventID = L35_1
L34_1.EventType = "MESSAGE_BOX"
L35_1 = "헤헤……! 자크 대장님…… 아버지의 원수!! 총알로 걸레짝을 만들어 주마!"
L34_1.Text_KOREA = L35_1
L35_1 = 2.5
L34_1.Value = L35_1
L35_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_SHOTGUN"
L34_1.StringValue = L35_1
L35_1 = "へへ……！　ジャック隊長……父の敵！！　ハチの巣にしてやる！"
L34_1.Text_JPN = L35_1
L35_1 = "Heh heh...! You killed Captain Jacques... You killed my father!! Prepare to be filled with lead!"
L34_1.Text_ENG = L35_1
L35_1 = "嘿嘿……！你杀死了扎克队长……杀死了我的父亲！！我要用子弹把你打成筛子！"
L34_1.Text_SCN = L35_1
L35_1 = "嘿嘿……！札克隊長……我終於可以替爸爸報仇！！我要把你打成蜂窩！"
L34_1.Text_TWN = L35_1
L35_1 = "หึหึ...! แกฆ่าหัวหน้าฌักส์... แกฆ่าพ่อฉัน!! จะฝังลูกตะกั่วให้เต็มตัวเลย!"
L34_1.Text_THA = L35_1
L35_1 = "He he...! Cô đã giết Đội trưởng Jacques... Cô đã giết bố tôi!! Chuẩn bị biến thành miếng phô mai đi!"
L34_1.Text_VTN = L35_1
L35_1 = "Heh heh ...! Du hast Kommandant Jacques getötet ... Du hast meinen Vater getötet!! Bereite dich darauf vor, mit Blei gefüllt zu werden!"
L34_1.Text_DEU = L35_1
L35_1 = "Hé hé... ! Tu as tué le capitaine Jacques... Tu as tué mon père !! Prépare-toi à mourir !"
L34_1.Text_FRA = L35_1
L35_1 = {}
L36_1 = "GameEvent_3322219_2"
L35_1.GameEventStrID = L36_1
L35_1.ProcessKey = 2
L36_1 = 3322219
L35_1.EventID = L36_1
L35_1.EventType = "MESSAGE_BOX"
L36_1 = "총에 맞아도 계속 움직이다니 정상이 아니야. 맨션에서 만든 약물인가?"
L35_1.Text_KOREA = L36_1
L36_1 = 2.5
L35_1.Value = L36_1
L36_1 = "AB_INVEN_ICON_NKM_UNIT_SECURITY_S_AGENT"
L35_1.StringValue = L36_1
L36_1 = "銃に撃たれても動き続けるなんてどうかしてる。マンションで作られた薬か？"
L35_1.Text_JPN = L36_1
L36_1 = "He still moved like the bullet wound was nothing. Could it be some new drug made by the Mansion?"
L35_1.Text_ENG = L36_1
L36_1 = "被子弹击中后还在继续移动，这不正常！难道是曼森制造的新药物？"
L35_1.Text_SCN = L36_1
L36_1 = "中槍後竟然還能動？我看他根本不是正常人，是曼森製造的藥嗎？"
L35_1.Text_TWN = L36_1
L36_1 = "เขาไม่สนใจแผลโดนยิงนั่นอย่างกับไม่เป็นไรเลยแฮะ นี่มันยาตัวใหม่ของพวกคฤหาสน์รึเปล่านะ?"
L35_1.Text_THA = L36_1
L36_1 = "Hắn ta vẫn di chuyển như thể vết đạn đó chả là gì cả. Nó là một số loại thuốc mới được sản xuất bởi Biệt Thự sao?"
L35_1.Text_VTN = L36_1
L36_1 = "Er bewegte sich trotz der Schusswunde, als wäre nichts. Könnte es eine neue Droge aus Mansion sein?"
L35_1.Text_DEU = L36_1
L36_1 = "Même après avoir pris toutes ces balles, il continue de bouger ? Serait-ce une nouvelle drogue fabriquée par le Manoir ?"
L35_1.Text_FRA = L36_1
L36_1 = {}
L37_1 = "GameEvent_3322219_3"
L36_1.GameEventStrID = L37_1
L36_1.ProcessKey = 3
L37_1 = 3322219
L36_1.EventID = L37_1
L36_1.EventType = "MESSAGE_BOX"
L37_1 = "하지만 자크가 평의회에 줄이 닿았을 리는 없을 텐데……. 누가 공급한 거지?  "
L36_1.Text_KOREA = L37_1
L37_1 = 2.5
L36_1.Value = L37_1
L37_1 = "AB_INVEN_ICON_NKM_UNIT_SECURITY_S_AGENT"
L36_1.StringValue = L37_1
L37_1 = "でもジャックが評議会にコネがあるとは思えない……いったい誰が与えたんだ？  "
L36_1.Text_JPN = L37_1
L37_1 = "But Jacques couldn’t have connections to the Council... Who could’ve supplied it?  "
L36_1.Text_ENG = L37_1
L37_1 = "但扎克应该接触不到评议会的人才对……是谁提供的呢？  "
L36_1.Text_SCN = L37_1
L37_1 = "不過札克不可能和評議會牽上線……供應的人是誰？"
L36_1.Text_TWN = L37_1
L37_1 = "แต่ฌักส์ไม่น่ามีคอนเนกชันกับสภานี่... แล้วใครหามาให้กัน?"
L36_1.Text_THA = L37_1
L37_1 = "Nhưng Jacques không thể có mối liên hệ với Hội Đồng... Ai có thể cung cấp nó đây?"
L36_1.Text_VTN = L37_1
L37_1 = "Aber Jacques hätte keine Verbindungen zum Rat haben können ... wer hätte es geliefert?"
L36_1.Text_DEU = L37_1
L37_1 = "Mais Jacques n'avait pas de relations avec le Conseil... Qui est derrière tout ça ?"
L36_1.Text_FRA = L37_1
L37_1 = {}
L38_1 = "GameEvent_3322220_1"
L37_1.GameEventStrID = L38_1
L37_1.ProcessKey = 1
L38_1 = 3322220
L37_1.EventID = L38_1
L37_1.EventType = "MESSAGE_BOX"
L38_1 = "더욱 저항하라. 안식을 거부하는 것은 본능. 그로 말미암아 본성이 고개를 들지니. "
L37_1.Text_KOREA = L38_1
L38_1 = 2.5
L37_1.Value = L38_1
L38_1 = "AB_INVEN_ICON_NKM_UNIT_CORRUPTED_M_ARMOR"
L37_1.StringValue = L38_1
L38_1 = "さらに抵抗せよ。安息を拒むのは本能。それにより本性が目を覚まさん。 "
L37_1.Text_JPN = L38_1
L38_1 = "Continue your resistance. To fight against eternal rest is but instinctive. With that as the catalyst, your true nature will soon show its colors. "
L37_1.Text_ENG = L38_1
L38_1 = "继续抵抗吧。发掘你拒绝安息的本能，由此觉醒出本性来！ "
L37_1.Text_SCN = L38_1
L38_1 = "盡情抵抗吧！拒絕安息是本能，這樣就會激發出本性！"
L37_1.Text_TWN = L38_1
L38_1 = "ต่อต้านไปเถอะ การขัดขืนสุคติชั่วนิรันดร์มันเป็นสัญชาตญาณอยู่แล้ว หากมีแรงกระตุ้นเช่นนั้น ไม่ช้าธาตุแท้ของเจ้าย่อมปรากฏแน่"
L37_1.Text_THA = L38_1
L38_1 = "Tiếp tục kháng cự đi. Hãy để bản năng chiến đấu chống lại yên nghỉ được thức tỉnh đi."
L37_1.Text_VTN = L38_1
L38_1 = "Mach ruhig weiter so. Gegen die ewige Ruhe zu kämpfen, ist nur instinktiv. Damit als Katalysator wird deine wahre Natur bald seine Farben zeigen."
L37_1.Text_DEU = L38_1
L38_1 = "Continue de résister. Lutter contre le repos éternel est un réflexe instinctif. Avec un tel catalyseur, tu révéleras bientôt ton vrai visage."
L37_1.Text_FRA = L38_1
L38_1 = {}
L39_1 = "GameEvent_3322220_2"
L38_1.GameEventStrID = L39_1
L38_1.ProcessKey = 2
L39_1 = 3322220
L38_1.EventID = L39_1
L38_1.EventType = "MESSAGE_BOX"
L39_1 = "잘난 듯이 큰소리쳤지만… 이제까지 상대해 본 적 없는 적이야."
L38_1.Text_KOREA = L39_1
L39_1 = 2.5
L38_1.Value = L39_1
L39_1 = "AB_INVEN_ICON_NKM_UNIT_SECURITY_S_AGENT"
L38_1.StringValue = L39_1
L39_1 = "偉そうに大口は叩いたけど……今まで相手したことないタイプの敵だ。"
L38_1.Text_JPN = L39_1
L39_1 = "I talked the talk... But I’ve never fought against such a thing before."
L38_1.Text_ENG = L39_1
L39_1 = "哈，哈……是平时吹牛吹多了吗？这可是至今为止遇到过的最强的敌人了。"
L38_1.Text_SCN = L39_1
L39_1 = "我雖然表現得一副沒在怕的樣子…但對方可是從未交手過的敵人。"
L38_1.Text_TWN = L39_1
L39_1 = "ฉันเคยพูดไปเรื่อยอยู่ก็ใช่... แต่ไม่เคยสู้กับอะไรพรรค์นั้นเลยแฮะ"
L38_1.Text_THA = L39_1
L39_1 = "Tôi đã từng nói chuyện... Nhưng tôi chưa bao giờ chiến đấu chống lại một thứ như vậy trước đây."
L38_1.Text_VTN = L39_1
L39_1 = "Ich habe schon darüber gesprochen ... aber nie gekämpft ..."
L38_1.Text_DEU = L39_1
L39_1 = "J'ai beau dire... Je n'ai jamais rien combattu de tel."
L38_1.Text_FRA = L39_1
L39_1 = {}
L40_1 = "GameEvent_3322220_3"
L39_1.GameEventStrID = L40_1
L39_1.ProcessKey = 3
L40_1 = 3322220
L39_1.EventID = L40_1
L39_1.EventType = "MESSAGE_BOX"
L40_1 = "전차포? 아냐, 그걸로는 부족해. 더 강한 화력을 퍼붓지 않으면……! "
L39_1.Text_KOREA = L40_1
L40_1 = 2.5
L39_1.Value = L40_1
L40_1 = "AB_INVEN_ICON_NKM_UNIT_SECURITY_S_AGENT"
L39_1.StringValue = L40_1
L40_1 = "戦車砲？　いや、それじゃ足りない。もっと強い火力で一気に攻めなければ……！ "
L39_1.Text_JPN = L40_1
L40_1 = "An artillery maybe? No, that’s not enough. We need something bigger than that...! "
L39_1.Text_ENG = L40_1
L40_1 = "坦克炮？不，那个可能没用。需要更强大的火力才行……！ "
L39_1.Text_SCN = L40_1
L40_1 = "坦克砲？不對，光靠那個還不夠，需要加上更強的火力……！ "
L39_1.Text_TWN = L40_1
L40_1 = "ปืนใหญ่จะไหวมั้ยนะ? ไม่ละ ไม่พอหรอก ต้องใช้อะไรที่แรงกว่านั้น...!"
L39_1.Text_THA = L40_1
L40_1 = "Có thể là một khẩu pháo? Không, như vậy là chưa đủ. Chúng ta cần một cái gì đó lớn hơn thế...!"
L39_1.Text_VTN = L40_1
L40_1 = "Eine Artillerie vielleicht? Nein, das ist nicht genug. Wir brauchen etwas Größeres als das ...!"
L39_1.Text_DEU = L40_1
L40_1 = "Un tir de canon ? Non, ça ne suffira pas. On a besoin de quelque chose d'encore plus puissant !"
L39_1.Text_FRA = L40_1
L40_1 = {}
L41_1 = "GameEvent_3322221_1"
L40_1.GameEventStrID = L41_1
L40_1.ProcessKey = 1
L41_1 = 3322221
L40_1.EventID = L41_1
L40_1.EventType = "MESSAGE_BOX"
L41_1 = "후훗. 예하께서 싸우는 모습은 오랜만이네."
L40_1.Text_KOREA = L41_1
L41_1 = 2.5
L40_1.Value = L41_1
L41_1 = "AB_INVEN_ICON_NKM_UNIT_HARMONY_C_VIOLIN"
L40_1.StringValue = L41_1
L41_1 = "ふふっ、猊下の戦う姿なんて久々に見るわね。"
L40_1.Text_JPN = L41_1
L41_1 = "Fuu fuu. To see her eminence take up arms. It has truly been too long."
L40_1.Text_ENG = L41_1
L41_1 = "嘻嘻。好久没见到主教战斗的身姿了。"
L40_1.Text_SCN = L41_1
L41_1 = "呵呵，好久沒欣賞到主教戰鬥的英姿呢～"
L40_1.Text_TWN = L41_1
L41_1 = "หึหึ ไม่ได้เห็นท่านผู้สูงส่งใช้อาวุธมานานแสนนานแล้วนะคะนี่"
L40_1.Text_THA = L41_1
L41_1 = "Phù phù. Đã lâu lắm rồi mới nhìn thấy sự xuất chúng của cô ấy khi nắm quyền."
L40_1.Text_VTN = L41_1
L41_1 = "Haha. Die Eminenz so zu sehen. Das gab es schon lange nicht mehr."
L40_1.Text_DEU = L41_1
L41_1 = "Hu hu. Vous avez pris les armes, Votre Éminence ? Ça faisait longtemps."
L40_1.Text_FRA = L41_1
L41_1 = {}
L42_1 = "GameEvent_3322221_2"
L41_1.GameEventStrID = L42_1
L41_1.ProcessKey = 2
L42_1 = 3322221
L41_1.EventID = L42_1
L41_1.EventType = "MESSAGE_BOX"
L42_1 = "그동안 실력이 얼마나 녹슬었는지 감상해 볼까?"
L41_1.Text_KOREA = L42_1
L42_1 = 2.5
L41_1.Value = L42_1
L42_1 = "AB_INVEN_ICON_NKM_UNIT_HARMONY_C_VIOLIN"
L41_1.StringValue = L42_1
L42_1 = "さて、どれほど実力が衰えたか、お手並み拝見といこうかしら？"
L41_1.Text_JPN = L42_1
L42_1 = "Let’s see how rusty your skills have gotten."
L41_1.Text_ENG = L42_1
L42_1 = "让我来欣赏下实力是否有退步吧？"
L41_1.Text_SCN = L42_1
L42_1 = "就來確認一下你的實力退步多少吧？"
L41_1.Text_TWN = L42_1
L42_1 = "มาดูซิว่าคุณมือตกไปขนาดไหนแล้ว"
L41_1.Text_THA = L42_1
L42_1 = "Để xem kỹ năng của cô đã trở nên tồi tệ như thế nào."
L41_1.Text_VTN = L42_1
L42_1 = "Mal sehen, wie eingerostet Sie sind."
L41_1.Text_DEU = L42_1
L42_1 = "Voyons si vous avez gardé vos réflexes."
L41_1.Text_FRA = L42_1
L42_1 = {}
L43_1 = "GameEvent_3322221_3"
L42_1.GameEventStrID = L43_1
L42_1.ProcessKey = 3
L43_1 = 3322221
L42_1.EventID = L43_1
L42_1.EventType = "MESSAGE_BOX"
L43_1 = "……이 기척은 셰나인가."
L42_1.Text_KOREA = L43_1
L43_1 = 2.5
L42_1.Value = L43_1
L43_1 = "AB_INVEN_ICON_NKM_UNIT_CORRUPTED_M_ARMOR"
L42_1.StringValue = L43_1
L43_1 = "……この気配、シェナか。"
L42_1.Text_JPN = L43_1
L43_1 = "...This presence. Shena?"
L42_1.Text_ENG = L43_1
L43_1 = "这个气息……是赛娜吗。"
L42_1.Text_SCN = L43_1
L43_1 = "……這個感覺是世娜嗎？"
L42_1.Text_TWN = L43_1
L43_1 = "...เจ้าคือ ชีน่ารึ?"
L42_1.Text_THA = L43_1
L43_1 = "...Sự hiện diện này. Shena?"
L42_1.Text_VTN = L43_1
L43_1 = "... diese Präsenz ... Shena?"
L42_1.Text_DEU = L43_1
L43_1 = "... Cette présence. Shena ?"
L42_1.Text_FRA = L43_1
L43_1 = {}
L44_1 = "GameEvent_3322221_4"
L43_1.GameEventStrID = L44_1
L43_1.ProcessKey = 4
L44_1 = 3322221
L43_1.EventID = L44_1
L43_1.EventType = "MESSAGE_BOX"
L44_1 = "가아그셰블라의 산하에 머물고 있다던 몽타뉴의 말이 사실이었구나."
L43_1.Text_KOREA = L44_1
L44_1 = 2.5
L43_1.Value = L44_1
L44_1 = "AB_INVEN_ICON_NKM_UNIT_CORRUPTED_M_ARMOR"
L43_1.StringValue = L44_1
L44_1 = "ガアグシェブラの傘下に入ったというモンターニュの言葉は事実であったか。"
L43_1.Text_JPN = L44_1
L44_1 = "So, it was true that you were under Gha’agsheblah’s wing."
L43_1.Text_ENG = L44_1
L44_1 = "果然现在是为加瓦格舍夫拉效力，蒙塔妮说的没错。"
L43_1.Text_SCN = L44_1
L44_1 = "看來原本在加瓦格舍夫拉底下做事的蒙塔妮說的是真的。"
L43_1.Text_TWN = L44_1
L44_1 = "เช่นนั้นก็เป็นความจริงสินะ ที่ว่าเจ้าไปรับใช้แก๊กชีบลาห์"
L43_1.Text_THA = L44_1
L44_1 = "Vậy là, đúng là cô đã ở dưới trướng của Gha'agsheblah."
L43_1.Text_VTN = L44_1
L44_1 = "Was Montagne gesagt hat, war also wahr. Dass du unter Gha‘agsheblahs Flügel warst."
L43_1.Text_DEU = L44_1
L44_1 = "Alors c'était vrai. Tu étais dans l'ombre de Gha'agsheblah, tout ce temps ?"
L43_1.Text_FRA = L44_1
L44_1 = {}
L45_1 = "GameEvent_3322221_5"
L44_1.GameEventStrID = L45_1
L44_1.ProcessKey = 5
L45_1 = 3322221
L44_1.EventID = L45_1
L44_1.EventType = "MESSAGE_BOX"
L45_1 = "허나……. 지금은 다른 단원보다 마에스트로가 우선일 터."
L44_1.Text_KOREA = L45_1
L45_1 = 2.5
L44_1.Value = L45_1
L45_1 = "AB_INVEN_ICON_NKM_UNIT_CORRUPTED_M_ARMOR"
L44_1.StringValue = L45_1
L45_1 = "だが……今は他の団員よりもマエストロを優先したいはずであろう。"
L44_1.Text_JPN = L45_1
L45_1 = "However... Maestra takes priority over all others."
L44_1.Text_ENG = L45_1
L45_1 = "但是……现在比起对付其他团员，指挥家才是最优先的。"
L44_1.Text_SCN = L45_1
L45_1 = "不過……我現在的重點是指揮家。"
L44_1.Text_TWN = L45_1
L45_1 = "แต่จะเช่นไรก็ตาม... เรื่องมาเอสตราต้องมาก่อน"
L44_1.Text_THA = L45_1
L45_1 = "Tuy nhiên... Maestra được ưu tiên hơn tất cả những người khác."
L44_1.Text_VTN = L45_1
L45_1 = "Allerdings ... hat Maestra Nequitia Vorrang vor allen anderen."
L44_1.Text_DEU = L45_1
L45_1 = "Cependant... Maestra Niquita reste ma priorité absolue."
L44_1.Text_FRA = L45_1
L45_1 = {}
L46_1 = "GameEvent_3322222_1"
L45_1.GameEventStrID = L46_1
L45_1.ProcessKey = 1
L46_1 = 3322222
L45_1.EventID = L46_1
L45_1.EventType = "MESSAGE_BOX"
L46_1 = "보고는 들었다. 여인을 내놓으라고 했다고?"
L45_1.Text_KOREA = L46_1
L46_1 = 2.5
L45_1.Value = L46_1
L46_1 = "AB_INVEN_ICON_NKM_NPC_SUIT"
L45_1.StringValue = L46_1
L46_1 = "報告は聞いた。彼女を返せと要求してきたと。"
L45_1.Text_JPN = L46_1
L46_1 = "I was briefed. They wanted the woman?"
L45_1.Text_ENG = L46_1
L46_1 = "我收到了报告。你让我们交出一个女人？"
L45_1.Text_SCN = L46_1
L46_1 = "我有收到報告，要我把女人交出來？"
L45_1.Text_TWN = L46_1
L46_1 = "ผมฟังมาคร่าวๆ แล้ว พวกเขาต้องการตัวผู้หญิงคนนั้นเหรอ?"
L45_1.Text_THA = L46_1
L46_1 = "Tôi đã được thông báo ngắn gọn. Họ muốn người phụ nữ đó?"
L45_1.Text_VTN = L46_1
L46_1 = "Ich wurde informiert. Sie wollten die Frau?"
L45_1.Text_DEU = L46_1
L46_1 = "J'ai été briefé. C'est la fille que tu veux ?"
L45_1.Text_FRA = L46_1
L46_1 = {}
L47_1 = "GameEvent_3322222_2"
L46_1.GameEventStrID = L47_1
L46_1.ProcessKey = 2
L47_1 = 3322222
L46_1.EventID = L47_1
L46_1.EventType = "MESSAGE_BOX"
L47_1 = "네가 무지막지한 건 알겠다만, 겨우 용병 한 명에게 쩔쩔매면 정부의 권위가 살지 않아."
L46_1.Text_KOREA = L47_1
L47_1 = 2.5
L46_1.Value = L47_1
L47_1 = "AB_INVEN_ICON_NKM_NPC_SUIT"
L46_1.StringValue = L47_1
L47_1 = "君が粗暴なのはわかったが、たかが傭兵一人に手間取るようでは政府の威厳が保たれない。"
L46_1.Text_JPN = L47_1
L47_1 = "I know that you can be... reckless. But not being able to deal with one mercenary doesn’t do the government's image any good."
L46_1.Text_ENG = L47_1
L47_1 = "我知道你很厉害，可如果我们因为一个佣兵的威胁而妥协了，那政府颜面又何在呢？"
L46_1.Text_SCN = L47_1
L47_1 = "我知道你霸道蠻橫，但要是我們因為區區一個傭兵就失去方寸，那政府的面子要往哪裡擺。"
L46_1.Text_TWN = L47_1
L47_1 = "ผมรู้นะว่าคุณเองก็อาจ... สะเพร่า แต่กับอีแค่ทหารรับจ้างคนเดียวยังจัดการไม่ได้นี่ไม่ได้เป็นผลดีกับภาพลักษณ์ของรัฐบาลเลย"
L46_1.Text_THA = L47_1
L47_1 = "Tôi biết rằng cô có thể... liều lĩnh. Nhưng chuyện không thể đối phó với một tên lính đánh thuê không có lợi cho hình ảnh của chính phủ."
L46_1.Text_VTN = L47_1
L47_1 = "Ich weiß, dass Sie viel stärker sind, aber nicht mit einem Söldner umgehen können, was dem Image der Regierung nicht gut tut."
L46_1.Text_DEU = L47_1
L47_1 = "Je sais que tu es très forte, mais on ne peut pas perdre face à un seul ennemi. Le gouvernement pourrait perdre la face."
L46_1.Text_FRA = L47_1
L47_1 = {}
L48_1 = "GameEvent_3322222_3"
L47_1.GameEventStrID = L48_1
L47_1.ProcessKey = 3
L48_1 = 3322222
L47_1.EventID = L48_1
L47_1.EventType = "MESSAGE_BOX"
L48_1 = "필그림에게서 강탈한 게 쓸모가 생겼군.\n병사들에게 지급된 주사를 사용하라고 지시해."
L47_1.Text_KOREA = L48_1
L48_1 = 2.5
L47_1.Value = L48_1
L48_1 = "AB_INVEN_ICON_NKM_NPC_SUIT"
L47_1.StringValue = L48_1
L48_1 = "ピルグリムから強奪したものの使い道ができたな。\n兵士に支給された注射を使うよう指示しろ。"
L47_1.Text_JPN = L48_1
L48_1 = [[
We finally have a use for the thing we stole from the Pilgrims.
Order the soldiers to use the provided shots.]]
L47_1.Text_ENG = L48_1
L48_1 = "看来从朝圣者那里缴获的东西正好能派上用场。\n让士兵们注射发放的药剂。"
L47_1.Text_SCN = L48_1
L48_1 = "從朝聖者那搶來的東西似乎可以派上用場。\n傳下去，命令士兵們注射！"
L47_1.Text_TWN = L48_1
L48_1 = "สุดท้ายเราก็ต้องใช้สิ่งที่ขโมยมาจากพวกนักแสวงบุณสินะ\nออกคำสั่งให้ทหารใช้กระสุนที่ให้ไปซะ"
L47_1.Text_THA = L48_1
L48_1 = "Cuối cùng thì chúng ta cũng có thể sử dụng thứ mà chúng ta đã lấy trộm từ những người Pilgrims.\nRa lệnh cho binh lính sử dụng các súng được cấp."
L47_1.Text_VTN = L48_1
L48_1 = "Wir haben endlich eine Verwendung für das, was wir den Pilgrims gestohlen haben.\nNehmen Sie die Soldaten, um die bereitgestellten Waffen zu verwenden."
L47_1.Text_DEU = L48_1
L48_1 = "On va enfin pouvoir se servir de ce qu'on a pris aux Pèlerins.\nDis aux hommes de continuer de tirer."
L47_1.Text_FRA = L48_1
L48_1 = {}
