L48_1.Text_SCN = L49_1
L49_1 = "呃啊啊啊！！"
L48_1.Text_TWN = L49_1
L49_1 = "กรรรรรร!"
L48_1.Text_THA = L49_1
L49_1 = "KRAAAAA!!"
L48_1.Text_VTN = L49_1
