L50_1 = "GameEvent_3322222_5"
L49_1.GameEventStrID = L50_1
L49_1.ProcessKey = 5
L50_1 = 3322222
L49_1.EventID = L50_1
L49_1.EventType = "MESSAGE_BOX"
L50_1 = "저것은…… <color=#ffd34c>융합체</color>인가."
L49_1.Text_KOREA = L50_1
L50_1 = 2.5
L49_1.Value = L50_1
L50_1 = "AB_INVEN_ICON_NKM_UNIT_CORRUPTED_M_ARMOR"
L49_1.StringValue = L50_1
L50_1 = "あれは……<color=#ffd34c>融合体</color>か。"
L49_1.Text_JPN = L50_1
L50_1 = "That must be... a <color=#ffd34c>Hybrider</color>."
L49_1.Text_ENG = L50_1
L50_1 = "那个是……<color=#ffd34c>融合体</color>？"
L49_1.Text_SCN = L50_1
L50_1 = "那是……<color=#ffd34c>融合體</color>嗎？"
L49_1.Text_TWN = L50_1
L50_1 = "นั่นคงจะเป็น... <color=#ffd34c>ไฮบริเดอร์</color>สินะ"
L49_1.Text_THA = L50_1
L50_1 = "Đó phải là... một <color=#ffd34c>Hybrider</color> ."
L49_1.Text_VTN = L50_1
L50_1 = "Das muss ... ein <color=#ffd34c>Hybride</color> sein."
L49_1.Text_DEU = L50_1
L50_1 = "Cette chose... C'est un <color=#ffd34c>Hybride</color> ?"
L49_1.Text_FRA = L50_1
L50_1 = {}
L51_1 = "GameEvent_3322222_6"
L50_1.GameEventStrID = L51_1
L50_1.ProcessKey = 6
L51_1 = 3322222
L50_1.EventID = L51_1
L50_1.EventType = "MESSAGE_BOX"
L51_1 = "역병을 다스릴 수 있다고 여기다니……. 어리석은 행실이로다."
L50_1.Text_KOREA = L51_1
L51_1 = 2.5
L50_1.Value = L51_1
L51_1 = "AB_INVEN_ICON_NKM_UNIT_CORRUPTED_M_ARMOR"
L50_1.StringValue = L51_1
L51_1 = "疫病を操れると勘違いするとは……愚行なり。"
L50_1.Text_JPN = L51_1
L51_1 = "To think that the plague can be controlled... Foolish."
L50_1.Text_ENG = L51_1
L51_1 = "竟会认为能够控制瘟疫……真是愚蠢的行为。"
L50_1.Text_SCN = L51_1
L51_1 = "竟然認為可以操控瘟疫……真是愚蠢的行為。"
L50_1.Text_TWN = L51_1
L51_1 = "ความคิดว่าจะควบคุมภัยพิบัติได้นั้น... ช่างโง่งมนัก"
L50_1.Text_THA = L51_1
L51_1 = "Cứ nghĩ rằng bệnh dịch có thể được kiểm soát... Ngu ngốc."
L50_1.Text_VTN = L51_1
L51_1 = "Zu denken, dass die Pest kontrolliert werden kann ... dumm."
L50_1.Text_DEU = L51_1
L51_1 = "Imbéciles... Nul ne peut maîtriser le Fléau."
L50_1.Text_FRA = L51_1
