L9_1.EventID = L10_1
L9_1.EventType = "MESSAGE_BOX"
L10_1 = "부전대장님! 폭발물을 발견했습니다."
L9_1.Text_KOREA = L10_1
L10_1 = 2.5
L9_1.Value = L10_1
L10_1 = "AB_INVEN_ICON_NKM_UNIT_S_ADMIN_RIFLE"
L9_1.StringValue = L10_1
L10_1 = "副戦隊長！　爆発物を見つけました。"
L9_1.Text_JPN = L10_1
L10_1 = "Deputy Commander! Explosive identified!"
L9_1.Text_ENG = L10_1
L10_1 = "副队长！发现爆炸物！"
L9_1.Text_SCN = L10_1
L10_1 = "副戰隊長！發現爆裂物！"
L9_1.Text_TWN = L10_1
L10_1 = "รองผู้บัญชาการครับ! พบการระเบิดครับ!"
L9_1.Text_THA = L10_1
L10_1 = "Phó tổng tư lệnh! Đã xác định được chất nổ!"
L9_1.Text_VTN = L10_1
L10_1 = "Stellvertretende Kommandantin! Sprengstoff identifiziert!"
L9_1.Text_DEU = L10_1
L10_1 = "Commandante adjointe ! Nous avons trouvé les explosifs !"
L9_1.Text_FRA = L10_1
