L10_1.EventID = L11_1
L10_1.EventType = "MESSAGE_BOX"
L11_1 = "메이즈 전대……! 알렉스 부전대장이 접근하지 못하게 막아라! "
L10_1.Text_KOREA = L11_1
L11_1 = 2.5
L10_1.Value = L11_1
L11_1 = "AB_INVEN_ICON_NKM_UNIT_S_ADMIN_SWORD"
L10_1.StringValue = L11_1
L11_1 = "メイズ戦隊……！　アレックス副戦隊長を近づけさせるな！ "
L10_1.Text_JPN = L11_1
L11_1 = "Maze Division...! Keep Deputy Commander Alex from approaching!"
L10_1.Text_ENG = L11_1
L11_1 = "是梅兹战队……! 别让亚历克斯副队长靠近，挡住她！ "
L10_1.Text_SCN = L11_1
L11_1 = "梅茲戰隊……！不准讓雅蕾克絲副戰隊長靠近！"
L10_1.Text_TWN = L11_1
L11_1 = "กองพลเขาวงกต...! อย่าให้ใครเข้าใกล้รองผู้บัญชาการอเล็กซ์ได้!"
L10_1.Text_THA = L11_1
L11_1 = "Sư Đoàn Mê Cung...! Không cho Phó tổng tư lệnh Alex đến gần!"
L10_1.Text_VTN = L11_1
L11_1 = "Maze-Division ...! Halten Sie stellvertretende Kommandantin Alex davon ab, sich zu nähern!"
L10_1.Text_DEU = L11_1
L11_1 = "Division Maze... ! Empêchez la commandante adjointe Alex de s'approcher !"
L10_1.Text_FRA = L11_1
