L11_1.GameEventStrID = L12_1
L11_1.ProcessKey = 3
L12_1 = 3322224
L11_1.EventID = L12_1
L11_1.EventType = "MESSAGE_BOX"
L12_1 = "확실히 구 관리국의 전투복이네. "
L11_1.Text_KOREA = L12_1
L12_1 = 2.5
L11_1.Value = L12_1
