L11_1.StringValue = L12_1
L12_1 = "確かに旧管理局の戦闘服だね。 "
L11_1.Text_JPN = L12_1
L12_1 = "Old Administration combat suit. No doubt about it."
L11_1.Text_ENG = L12_1
L12_1 = "确实是旧管理局的战斗服。 "
L11_1.Text_SCN = L12_1
L12_1 = "確實是舊管理局的戰鬥服。"
L11_1.Text_TWN = L12_1
L12_1 = "ชุดรบขององค์การบริหารโลกในอดีต ไม่แปลกใจสักนิด"
L11_1.Text_THA = L12_1
L12_1 = "Bộ đồ chiến đấu của Cục Quản Lý Cũ. Không nghi ngờ về nó chút nào!"
L11_1.Text_VTN = L12_1
L12_1 = "Ein Kampfanzug der Alten Administration. Daran besteht kein Zweifel."
L11_1.Text_DEU = L12_1
L12_1 = "C'est une combinaison de combat de l'Ancienne Administration, ça ne fait aucun doute."
L11_1.Text_FRA = L12_1
