L12_1.EventID = L13_1
L12_1.EventType = "MESSAGE_BOX"
L13_1 = "어디, 회포 좀 풀어 볼까."
L12_1.Text_KOREA = L13_1
L13_1 = 2.5
L12_1.Value = L13_1
L13_1 = "AB_INVEN_ICON_NKM_UNIT_C_ADMIN_GREATSWORD"
L12_1.StringValue = L13_1
L13_1 = "どれ、積もる話に花でも咲かせてみようかな。"
L12_1.Text_JPN = L13_1
L13_1 = "Well then, guess I’ll let loose."
L12_1.Text_ENG = L13_1
L13_1 = "那么，就让我解锁全部火力吧。"
L12_1.Text_SCN = L13_1
L13_1 = "來敘敘舊吧？"
L12_1.Text_TWN = L13_1
