L12_1.Text_THA = L13_1
L13_1 = "Vậy thì, đoán rằng tôi sẽ thả lỏng một chút."
L12_1.Text_VTN = L13_1
L13_1 = "Na dann, ich schätze, ich werde loslassen."
L12_1.Text_DEU = L13_1
