L16_1 = 10093112
L15_1.EventID = L16_1
L15_1.EventType = "MESSAGE_BOX"
L16_1 = "선배, 갑자기 무슨 소리야?"
L15_1.Text_KOREA = L16_1
L16_1 = 2.5
L15_1.Value = L16_1
L16_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L15_1.StringValue = L16_1
L16_1 = "先輩、いきなりどういうこと？"
L15_1.Text_JPN = L16_1
L16_1 = "What do you mean, Shiyoon?"
L15_1.Text_ENG = L16_1
L16_1 = "前辈，为什么突然这么说？"
L15_1.Text_SCN = L16_1
L16_1 = "前輩，你在說什麼？"
L15_1.Text_TWN = L16_1
L16_1 = "หมายถึงอะไรน่ะชิยุน?"
L15_1.Text_THA = L16_1
L16_1 = "Ý anh là gì vậy, Shiyoon?"
L15_1.Text_VTN = L16_1
L16_1 = "Was meinst du damit, Shiyoon?"
L15_1.Text_DEU = L16_1
L16_1 = "Qu'est-ce qui te prend, Charles ?"
