L17_1 = "GameEvent_10093112_3"
L16_1.GameEventStrID = L17_1
L16_1.ProcessKey = 3
L17_1 = 10093112
L16_1.EventID = L17_1
L16_1.EventType = "MESSAGE_BOX"
L17_1 = "아, 미나 양. 별거 아니에요."
L16_1.Text_KOREA = L17_1
L17_1 = 2.5
L16_1.Value = L17_1
L17_1 = "AB_INVEN_ICON_NKM_UNIT_C_JOO_SHI_YOON"
L16_1.StringValue = L17_1
L17_1 = "あ、ミナさん。別に大したことではありません。"
L16_1.Text_JPN = L17_1
L17_1 = "Ah, Mina. It’s nothing."
L16_1.Text_ENG = L17_1
L17_1 = "啊，米娜。没什么。"
L16_1.Text_SCN = L17_1
L17_1 = "喔，米娜，沒什麼。"
L16_1.Text_TWN = L17_1
L17_1 = "อ๊ะ คุณมีนา ไม่มี อะไรหรอกครับ"
L16_1.Text_THA = L17_1
L17_1 = "À, cô Mina. Không có gì."
L16_1.Text_VTN = L17_1
L17_1 = "Ah, Mina. Schon gut. Es ist nichts."
L16_1.Text_DEU = L17_1
L17_1 = "Ah, Mina. Ce n'est rien."
L16_1.Text_FRA = L17_1
