L23_1 = "GameEvent_10094413_2"
L22_1.GameEventStrID = L23_1
L22_1.ProcessKey = 2
L23_1 = 10094413
L22_1.EventID = L23_1
L22_1.EventType = "MESSAGE_BOX"
L23_1 = "……피차 오래 끌고 싶진 않겠지?"
L22_1.Text_KOREA = L23_1
L22_1.Value = 2
L23_1 = "AB_INVEN_ICON_NKM_UNIT_CA_ADMIN_LEE_SUYEON"
L22_1.StringValue = L23_1
L23_1 = "……お互い長びきたくはないだろう？"
L22_1.Text_JPN = L23_1
L23_1 = "Let’s make this quick, okay?"
L22_1.Text_ENG = L23_1
L23_1 = "……彼此都不想浪费时间吧？"
L22_1.Text_SCN = L23_1
L23_1 = "……就別浪費彼此的時間吧？"
L22_1.Text_TWN = L23_1
L23_1 = "ให้มันจบเร็วๆ แล้วกัน โอเค้?"
L22_1.Text_THA = L23_1
L23_1 = "...Cả hai đều không muốn lãng phí thời gian mà nhỉ?"
L22_1.Text_VTN = L23_1
L23_1 = "Lass es uns nicht unnötig herauszögern, okay?"
L22_1.Text_DEU = L23_1
L23_1 = "... Finissons-en vite, d'accord ?"
L22_1.Text_FRA = L23_1
