L24_1 = "GameEvent_3342111_1"
L23_1.GameEventStrID = L24_1
L23_1.ProcessKey = 1
L24_1 = 3342111
L23_1.EventID = L24_1
L23_1.EventType = "MESSAGE_BOX"
L24_1 = "짙은 악몽… 도와줄 아이들이 필요하겠어."
L23_1.Text_KOREA = L24_1
L23_1.Value = 2
L24_1 = "AB_INVEN_ICON_NKM_UNIT_DREAM_C_NIGHTMARE"
L23_1.StringValue = L24_1
L24_1 = "濃い悪夢……助けてくれる子どもたちが必要そう。"
L23_1.Text_JPN = L24_1
L24_1 = "A dark nightmare... Assistance is needed."
L23_1.Text_ENG = L24_1
L24_1 = "好深邃的噩梦……看来需要帮助。"
L23_1.Text_SCN = L24_1
L24_1 = "深層的惡夢…需要有人幫我。"
L23_1.Text_TWN = L24_1
L24_1 = "ฝันร้ายอันมืดมิด... ต้องการความช่วยเหลือ"
L23_1.Text_THA = L24_1
L24_1 = "Một cơn ác mộng đen tối ...Cần được hỗ trợ."
L23_1.Text_VTN = L24_1
L24_1 = "Ein dunkler Albtraum ... Hilfe wird benötigt."
L23_1.Text_DEU = L24_1
L24_1 = "Cauchemar noir ... assistance requise."
L23_1.Text_FRA = L24_1
