L25_1 = "GameEvent_3342121_1"
L24_1.GameEventStrID = L25_1
L24_1.ProcessKey = 1
L25_1 = 3342121
L24_1.EventID = L25_1
L24_1.EventType = "MESSAGE_BOX"
L25_1 = "꿈 속으로 보내 줄게. 마음껏 싸워."
L24_1.Text_KOREA = L25_1
L24_1.Value = 2
L25_1 = "AB_INVEN_ICON_NKM_UNIT_DREAM_C_NIGHTMARE"
L24_1.StringValue = L25_1
L25_1 = "夢の中に送ってあげる。思いっきり戦って。"
L24_1.Text_JPN = L25_1
L25_1 = "I'll send you into your dream. Fight to your heart's content."
L24_1.Text_ENG = L25_1
L25_1 = "我会把你送进你的梦里，你可以随心所欲地战斗。"
L24_1.Text_SCN = L25_1
L25_1 = "要打就到夢裡打！"
L24_1.Text_TWN = L25_1
L25_1 = "ฉันจะส่งคุณเข้าไปในฝันตัวเองนะคะ สู้ได้ตามใจเลย"
L24_1.Text_THA = L25_1
L25_1 = "Ta sẽ đưa các người vào giấc mơ của mình. Chiến đấu với nỗi sợ hãi trong trái tim của chính các người."
L24_1.Text_VTN = L25_1
L25_1 = "Ich werde dich in deinen Traum schicken. Kämpfe so viel du willst."
L24_1.Text_DEU = L25_1
L25_1 = "Luttez tant que vous voulez, je vous envoie dans vos rêves."
L24_1.Text_FRA = L25_1
