L26_1 = "GameEvent_3342121_2"
L25_1.GameEventStrID = L26_1
L25_1.ProcessKey = 2
L26_1 = 3342121
L25_1.EventID = L26_1
L25_1.EventType = "MESSAGE_BOX"
L26_1 = "뭐야… 갑자기 엄청 졸려. 좀 자도 될까?"
L25_1.Text_KOREA = L26_1
L25_1.Value = 2
L26_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_RIFLE"
L25_1.StringValue = L26_1
L26_1 = "何だ……いきなりものすごい眠気が。ちょっと寝ていいか？"
L25_1.Text_JPN = L26_1
L26_1 = "Huh...? I'm so tired. Maybe I should rest a little..."
L25_1.Text_ENG = L26_1
L26_1 = "为什么……突然好困。可以睡觉吗？"
L25_1.Text_SCN = L26_1
L26_1 = "怎麼搞的…突然好睏，可以睡一下嗎？"
L25_1.Text_TWN = L26_1
L26_1 = "หา...? ฉันหนื่อยจะแย่ น่าจะพักสักหน่อย..."
L25_1.Text_THA = L26_1
L26_1 = "Huh...? Tôi mệt quá. Có lẽ tôi nên nghỉ ngơi một chút ..."
L25_1.Text_VTN = L26_1
L26_1 = "Huh ...? Ich bin so müde. Vielleicht sollte ich mich ein bisschen ausruhen ..."
L25_1.Text_DEU = L26_1
L26_1 = "Hein...? Je suis si fatigué... Et si je faisais une pause ?"
L25_1.Text_FRA = L26_1
