L27_1 = "GameEvent_3342121_3"
L26_1.GameEventStrID = L27_1
L26_1.ProcessKey = 3
L27_1 = 3342121
L26_1.EventID = L27_1
L26_1.EventType = "MESSAGE_BOX"
L27_1 = "눈이 막… 감겨… 쟤들 잡아야 되는데…."
L26_1.Text_KOREA = L27_1
L26_1.Value = 2
L27_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_SHIELD"
L26_1.StringValue = L27_1
L27_1 = "まぶたが……重い……あいつらを捕まえないと……"
L26_1.Text_JPN = L27_1
L27_1 = "My eyes... They're closing... But I need to catch those two..."
L26_1.Text_ENG = L27_1
L27_1 = "眼皮……都睁不开……得干掉她们才行……"
L26_1.Text_SCN = L27_1
L27_1 = "眼皮…好沉…必須逮到她們…"
L26_1.Text_TWN = L27_1
L27_1 = "ตาฉัน... จะปิดอยู่แล้วเนี่ย... แต่ต้องจับสองคน..."
L26_1.Text_THA = L27_1
L27_1 = "Đôi mắt của tôi ... Chúng đang nhắm lại ... Nhưng tôi cần phải bắt được hai đứa nó..."
L26_1.Text_VTN = L27_1
L27_1 = "Meine Augen ... Sie schließen sich zwar ... aber ich muss doch diese beiden schnappen ..."
L26_1.Text_DEU = L27_1
L27_1 = "Mes paupières... sont lourdes... mais je dois attraper ces..."
L26_1.Text_FRA = L27_1
