L27_1.StringValue = L28_1
L28_1 = "……しっかりしろ！　何してんだ！　目を覚ませ！"
L27_1.Text_JPN = L28_1
L28_1 = "Snap out of it! What are you doing?! Wake up!!"
L27_1.Text_ENG = L28_1
L28_1 = "……快醒醒！你在干嘛！别睡了！"
L27_1.Text_SCN = L28_1
L28_1 = "…醒醒！你們在做什麼！不能睡！"
L27_1.Text_TWN = L28_1
L28_1 = "ตั้งสติหน่อย! ทำอะไรกันอยู่?! ตื่นสิ!!"
L27_1.Text_THA = L28_1
L28_1 = "Thôi đi! Đang làm gì đấy?! Tỉnh dậy đi!!!"
L27_1.Text_VTN = L28_1
L28_1 = "Reiß dich zusammen! Was machst du denn?! Wach auf!"
L27_1.Text_DEU = L28_1
L28_1 = "Hé ! Fais pas le con, qu'est-ce que tu fous ? Réveille-toi !"
L27_1.Text_FRA = L28_1
