L43_1 = 3372123
L42_1.EventID = L43_1
L42_1.EventType = "MESSAGE_BOX"
L43_1 = "무게, 습도, 바람과 사람들의 입김, 침방울, 거기에 구슬의 회전 속도까지 더하면……."
L42_1.Text_KOREA = L43_1
L42_1.Value = 2
L43_1 = "AB_INVEN_ICON_NKM_NPC_PUPPET"
L42_1.StringValue = L43_1
L43_1 = "重さ、湿度、風向きと人々の吐く息、唾、それに玉の回転速度まで合わせれば……"
L42_1.Text_JPN = L43_1
L43_1 = "Accounting for the weight, humidity, the wind, people's breathing, saliva drops, and the rotation speed of the ball..."
L42_1.Text_ENG = L43_1
L43_1 = "重量，湿度，风速，人们的哈气，唾沫星子，加上小球旋转的速度……"
L42_1.Text_SCN = L43_1
L43_1 = "重量、濕度、風、人的呼吸、口水，再加上珠子旋轉的速度……"
L42_1.Text_TWN = L43_1
L43_1 = "จากน้ำหนัก ความชิ้น ลม ลมหายใจของคน หยดน้ำลาย แล้วก็ความเร็วการหมุนของลูก..."
L42_1.Text_THA = L43_1
L43_1 = "Cân nhắc trọng lượng, độ ẩm, hướng gió, hơi thở của mọi người, giọt nước bọt và tốc độ quay của quả bóng..."
L42_1.Text_VTN = L43_1
L43_1 = "Unter Berücksichtigung von Gewicht, Luftfeuchtigkeit, Wind, Atmung, Speicheltropfen und der Rotationsgeschwindigkeit des Balls, müsste es ..."
L42_1.Text_DEU = L43_1
L43_1 = "Compte tenu du poids, de l'humidité, du vent, de la respiration des gens, des gouttes de salive et de la vitesse de rotation de la bille..."
L42_1.Text_FRA = L43_1
