L11_1 = "GameEvent_3372223_1"
L10_1.GameEventStrID = L11_1
L10_1.ProcessKey = 1
L11_1 = 3372223
L10_1.EventID = L11_1
L10_1.EventType = "MESSAGE_BOX"
L11_1 = "이러다 정말 이기겠어!"
L10_1.Text_KOREA = L11_1
L10_1.Value = 2
L11_1 = "AB_INVEN_ICON_NKM_UNIT_OZ_C_SWORD"
L10_1.StringValue = L11_1
L11_1 = "本当に勝てるかも！"
L10_1.Text_JPN = L11_1
L11_1 = "I think we're going to win this!"
L10_1.Text_ENG = L11_1
L11_1 = "这样下去真的要赢了！"
L10_1.Text_SCN = L11_1
L11_1 = "這樣下去我們真的會贏欸！"
L10_1.Text_TWN = L11_1
L11_1 = "ฉันว่าเรากำลังจะชนะนะ!"
L10_1.Text_THA = L11_1
L11_1 = "Tôi nghĩ chúng ta sẽ thắng trận này!"
L10_1.Text_VTN = L11_1
L11_1 = "Ich denke, wir werden das gewinnen!"
L10_1.Text_DEU = L11_1
L11_1 = "Si ça continue, on va gagner !"
L10_1.Text_FRA = L11_1
L11_1 = {}
L12_1 = "GameEvent_3372223_2"
L11_1.GameEventStrID = L12_1
L11_1.ProcessKey = 2
L12_1 = 3372223
L11_1.EventID = L12_1
L11_1.EventType = "MESSAGE_BOX"
L12_1 = "힘내! 술고래 아줌마!"
L11_1.Text_KOREA = L12_1
L11_1.Value = 2
L12_1 = "AB_INVEN_ICON_NKM_UNIT_M_RAS_TOWER"
L11_1.StringValue = L12_1
L12_1 = "頑張って！　のんべえのおばさん！"
L11_1.Text_JPN = L12_1
L12_1 = "Go! Ms. Hard Drinker!"
L11_1.Text_ENG = L12_1
L12_1 = "加油呀！酒鬼姐姐！"
L11_1.Text_SCN = L12_1
L12_1 = "加油！酒鬼阿姨！"
L11_1.Text_TWN = L12_1
L12_1 = "ลุยเลย! เกรมอรี! ลุย!"
L11_1.Text_THA = L12_1
L12_1 = "Đi đi! Gremory! Đi nào!"
L11_1.Text_VTN = L12_1
L12_1 = "Du schaffst das! Frau Säuferin!"
L11_1.Text_DEU = L12_1
L12_1 = "Allez Gremory, encore un peu !"
L11_1.Text_FRA = L12_1
