L13_1 = "GameEvent_3372223_3"
L12_1.GameEventStrID = L13_1
L12_1.ProcessKey = 3
L13_1 = 3372223
L12_1.EventID = L13_1
L12_1.EventType = "MESSAGE_BOX"
L13_1 = "그러엄~ 당연하지. 누가 흑장민데?"
L12_1.Text_KOREA = L13_1
L12_1.Value = 2
L13_1 = "AB_INVEN_ICON_NKM_UNIT_BAR_C_CEO"
L12_1.StringValue = L13_1
L13_1 = "もちろんよ～。黒バラだもの。"
L12_1.Text_JPN = L13_1
L13_1 = "Well, of course...! I'm the Black Rose, remember?"
L12_1.Text_ENG = L13_1
L13_1 = "那~当然了。也不看看黑玫瑰是谁？"
L12_1.Text_SCN = L13_1
L13_1 = "那～還～用說，我可是黑玫瑰呢！"
L12_1.Text_TWN = L13_1
L13_1 = "แหม ก็แน่ล่ะ...! ฉันคือกุหลาบดำนะ จำได้มั้ย?"
L12_1.Text_THA = L13_1
L13_1 = "Tất nhiên...! Tôi là Hoa Hồng Đen mà, nhớ không?"
L12_1.Text_VTN = L13_1
L13_1 = "Aber natürlich ...! Ich bin schließlich die schwarze Rose."
L12_1.Text_DEU = L13_1
L13_1 = "Tout doux... Je suis la Rose Noire, tu as oublié ?"
L12_1.Text_FRA = L13_1
