L25_1.ProcessKey = 3
L26_1 = 3372313
L25_1.EventID = L26_1
L25_1.EventType = "MESSAGE_BOX"
L26_1 = "……쳇. 역시 겁쟁이잖아."
L25_1.Text_KOREA = L26_1
L25_1.Value = 2
L26_1 = "AB_INVEN_ICON_NKM_UNIT_OZ_S_RUNNER"
L25_1.StringValue = L26_1
L26_1 = "……ちっ。やっぱ臆病者じゃないか。"
L25_1.Text_JPN = L26_1
L26_1 = "Tch! He's just a coward."
L25_1.Text_ENG = L26_1
L26_1 = "……切，果然是个胆小鬼。"
L25_1.Text_SCN = L26_1
L26_1 = "……嘖，果然是膽小鬼。"
L25_1.Text_TWN = L26_1
L26_1 = "ชิ! เขาก็แค่คนขี้ขลาดเท่านั้นแหละ"
L25_1.Text_THA = L26_1
L26_1 = "Tch! Cậu ta chỉ là một kẻ hèn nhát."
L25_1.Text_VTN = L26_1
L26_1 = "... Tz! Er ist nur ein Feigling."
L25_1.Text_DEU = L26_1
L26_1 = "Tss ! C'est bien ce que je pensais, tu n'es qu'un lâche !"
L25_1.Text_FRA = L26_1
