L31_1 = 3372321
L30_1.EventID = L31_1
L30_1.EventType = "MESSAGE_BOX"
L31_1 = "봐 줄 필요 없어! 저 날파리 같은 계집애를 찢어 버려!"
L30_1.Text_KOREA = L31_1
