L31_1 = "AB_INVEN_ICON_NKM_NPC_HERON"
L30_1.StringValue = L31_1
L31_1 = "手加減することないわ！　あの小バエのような子たちを裂いておしまい！"
L30_1.Text_JPN = L31_1
L31_1 = "Get her! Rip that girl in half!"
L30_1.Text_ENG = L31_1
L31_1 = "不必手下留情！把那个苍蝇似的臭丫头撕碎！"
L30_1.Text_SCN = L31_1
L31_1 = "不需要手下留情！把那個像蒼蠅般的丫頭撕爛！"
L30_1.Text_TWN = L31_1
L31_1 = "จับยัยเด็กนั่นให้ได้! ฉีกมันเป็นสองท่อนเลย!"
L30_1.Text_THA = L31_1
L31_1 = "Bắt lấy nó! Xé nó làm đôi!"
L30_1.Text_VTN = L31_1
L31_1 = "Kein Grund, sich zurückzuhalten! Reiß diese Fliegengöre in Stücke!"
