L31_1.StringValue = L32_1
L32_1 = "もう！　子どもの遊びに大人が入っちゃだめ！"
L31_1.Text_JPN = L32_1
L32_1 = "Hey! Adults aren't supposed to interfere in a kids' game!"
L31_1.Text_ENG = L32_1
L32_1 = "不可以！小孩子们在玩，大人不可以总是掺和！"
L31_1.Text_SCN = L32_1
L32_1 = "真是的，小朋友在玩，大人幹嘛一直插嘴啦！"
L31_1.Text_TWN = L32_1
L32_1 = "นี่! เป็นผู้ใหญ่ก็อย่ามายุ่งกับเกมของเด็กๆ สิ!"
L31_1.Text_THA = L32_1
L32_1 = "Này! Người lớn không nên can thiệp vào trò chơi của trẻ em!"
L31_1.Text_VTN = L32_1
L32_1 = "Hey! Erwachsene dürfen sich nicht einmischen, wenn Kinder spielen!"
L31_1.Text_DEU = L32_1
