L51_1 = 3392735
L50_1.EventID = L51_1
L50_1.EventType = "MESSAGE_BOX"
L51_1 = "당신의 모든 걸 알아내겠어요, 에델."
L50_1.Text_KOREA = L51_1
L50_1.Value = 3
L51_1 = "AB_INVEN_ICON_NKM_UNIT_ESPR_CA_FROZEN"
L50_1.StringValue = L51_1
L51_1 = "あなたのすべてを調べつくしますわ、エデル。"
L50_1.Text_JPN = L51_1
L51_1 = "I will find out everything about you, Edel."
L50_1.Text_ENG = L51_1
L51_1 = "我知道你的一切，埃德尔。"
L50_1.Text_SCN = L51_1
L51_1 = "我會弄清楚關於你的一切的，艾瑟兒。"
L50_1.Text_TWN = L51_1
L51_1 = "ฉันจะรู้จักเธอทุกซอกทุกมุมให้ได้เลย เอเดล"
L50_1.Text_THA = L51_1
L51_1 = "Tôi sẽ tìm hiểu mọi thứ về cô, Edel."
L50_1.Text_VTN = L51_1
L51_1 = "Ich werde alles über dich herausfinden, Edel."
L50_1.Text_DEU = L51_1
L51_1 = "Je découvrirais tout sur vous, Edel."
L50_1.Text_FRA = L51_1
