L2_1 = "GameEvent_3392735_2"
L1_1.GameEventStrID = L2_1
L1_1.ProcessKey = 2
L2_1 = 3392735
L1_1.EventID = L2_1
L1_1.EventType = "MESSAGE_BOX"
L2_1 = "쉽지 않을 거예요, 레지나 님."
L1_1.Text_KOREA = L2_1
L1_1.Value = 3
L2_1 = "AB_INVEN_ICON_NKM_UNIT_C_ESPR_SHADOW"
L1_1.StringValue = L2_1
L2_1 = "そう簡単には行きませんよ、レジーナ様。"
L1_1.Text_JPN = L2_1
L2_1 = "It won’t be so easy, Ms. Regina."
L1_1.Text_ENG = L2_1
L2_1 = "他应该不那么容易对付，里贾纳。"
L1_1.Text_SCN = L2_1
L2_1 = "沒那麼容易喔，蕾佳娜。"
L1_1.Text_TWN = L2_1
L2_1 = "มันไม่ง่ายนักหรอกคะ คุณเรจิน่า"
L1_1.Text_THA = L2_1
L2_1 = "Sẽ không dễ dàng vậy đâu, Regina."
L1_1.Text_VTN = L2_1
L2_1 = "Das wird nicht so einfach, Regina."
L1_1.Text_DEU = L2_1
L2_1 = "Ce ne sera pas facile, Regina."
L1_1.Text_FRA = L2_1
