L5_1 = "GameEvent_3402111_1"
L4_1.GameEventStrID = L5_1
L4_1.ProcessKey = 1
L5_1 = 3402111
L4_1.EventID = L5_1
L4_1.EventType = "MESSAGE_BOX"
L5_1 = "진격하라! 물러서지 마라! 적의 고지가 코 앞이다!"
L4_1.Text_KOREA = L5_1
L4_1.Value = 2
L5_1 = "AB_INVEN_ICON_NKM_MOB_BOSS_PALADIN"
L4_1.StringValue = L5_1
L5_1 = "進撃しろ！　引き下がるな！　敵の高地は目の前にあるぞ！"
L4_1.Text_JPN = L5_1
L5_1 = "March! Never retreat! Capture the enemy's high ground!"
L4_1.Text_ENG = L5_1
L5_1 = "进击！别后退！敌人的高地就在眼前！"
L4_1.Text_SCN = L5_1
L5_1 = "進擊！不准撤退！敵人的基地就在前方！"
L4_1.Text_TWN = L5_1
L5_1 = "เดินหน้าไป! อย่าได้ถอย! ยึดพื้นที่ของศัตรูมาให้ได้!"
L4_1.Text_THA = L5_1
L5_1 = "Hành quân! Không bao giờ rút lui! Chiếm đóng căn cứ kẻ thù!"
L4_1.Text_VTN = L5_1
L5_1 = "Vorwärts! Weicht nie zurück! Der Stützpunkt des Gegners befindet sich direkt vor unserer Nase!"
L4_1.Text_DEU = L5_1
L5_1 = "Chargez ! Ne faiblissez pas ! L'ennemi est droit devant !"
L4_1.Text_FRA = L5_1
L5_1 = {}
L6_1 = "GameEvent_3402111_2"
L5_1.GameEventStrID = L6_1
L5_1.ProcessKey = 2
L6_1 = 3402111
L5_1.EventID = L6_1
L5_1.EventType = "MESSAGE_BOX"
L6_1 = "그대들의 희생은 결코 헛된 것이 아니다. 긍지와 명예를 걸고 우리의 적을 섬멸하라!"
L5_1.Text_KOREA = L6_1
L5_1.Value = 2
L6_1 = "AB_INVEN_ICON_NKM_MOB_BOSS_PALADIN"
L5_1.StringValue = L6_1
L6_1 = "君たちの犠牲は、決して無駄ではない。誇りと名誉をかけて、我々の敵を殲滅しろ！"
L5_1.Text_JPN = L6_1
L6_1 = "Your sacrifice will not be in vain! With glory and honor, bring our enemies to their knees!"
L5_1.Text_ENG = L6_1
L6_1 = "你们的牺牲绝非徒劳。赌上骄傲和荣誉，歼灭我们的敌人！"
L5_1.Text_SCN = L6_1
L6_1 = "你們的犧牲絕對不會是白費的，賭上名譽與榮耀殲滅敵人吧！"
L5_1.Text_TWN = L6_1
L6_1 = "การเสียสละของทุกคนจะไม่เสียเปล่า! ด้วยความรุ่งเรืองและเกียรติเคียงคู่ ศัตรูต้องคุกเข่ายอมสยบ!"
L5_1.Text_THA = L6_1
L6_1 = "Sự hy sinh của các cậu sẽ không vô ích! Với vinh quang và danh dự, hãy khiến kẻ địch của chúng ta phải quỳ gối!"
L5_1.Text_VTN = L6_1
L6_1 = "Ihr Opfer war nicht umsonst. Vernichte unsere Gegner mit Stolz und Ehre!"
L5_1.Text_DEU = L6_1
L6_1 = "Votre sacrifice ne sera pas vain. Avancez avec honneur et fierté pour anéantir nos ennemis !"
L5_1.Text_FRA = L6_1
L6_1 = {}
L7_1 = "GameEvent_3402111_3"
L6_1.GameEventStrID = L7_1
L6_1.ProcessKey = 3
L7_1 = 3402111
L6_1.EventID = L7_1
L6_1.EventType = "MESSAGE_BOX"
L7_1 = "윽, 적의 공격이 무척 매섭습니다. 지원 병력이 올 때까지 이 고지를 지켜야 합니다."
L6_1.Text_KOREA = L7_1
L6_1.Value = 2
L7_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_SHOTGUN"
L6_1.StringValue = L7_1
L7_1 = "うっ、敵の攻撃がとても激しいです。応援の兵力が来るまで、この高地を守らなければ。"
L6_1.Text_JPN = L7_1
L7_1 = "Ngh! The enemy's attacks are ferocious! We must hold the high ground until reinforcements arrive!"
L6_1.Text_ENG = L7_1
L7_1 = "呃，敌人的攻击非常猛烈。在支援兵力到达之前，必须守住这个高地。"
L6_1.Text_SCN = L7_1
L7_1 = "唔，敵人的攻擊相當猛烈，在援兵抵達前，千萬要守住基地！"
L6_1.Text_TWN = L7_1
L7_1 = "อึก! การโจมตีของศัตรูร้ายกาจนัก! เราต้องยึดพื้นที่ไว้จนกว่ากำลังเสริมจะมาถึง!"
L6_1.Text_THA = L7_1
L7_1 = "Ngh! Các đợt tấn công của kẻ thù rất khốc liệt! Chúng ta phải thật vững vàng cho tới khi quân tiếp viện đến!"
L6_1.Text_VTN = L7_1
L7_1 = "Urgh, die Angriffe des Gegners sind echt heftig. Wir müssen den Stützpunkt muss bis zum Eintreffen der Verstärkung aufrechterhalten."
L6_1.Text_DEU = L7_1
L7_1 = "Ngh, notre ennemi est particulièrement agressif. Nous devons tenir bon jusqu'à l'arrivée des renforts."
L6_1.Text_FRA = L7_1
L7_1 = {}
L8_1 = "GameEvent_3402111_4"
L7_1.GameEventStrID = L8_1
L7_1.ProcessKey = 4
L8_1 = 3402111
L7_1.EventID = L8_1
L7_1.EventType = "MESSAGE_BOX"
L8_1 = "카운터 여러분! 당신들의 힘을 빌려주십쇼!"
L7_1.Text_KOREA = L8_1
L7_1.Value = 2
L8_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_SHOTGUN"
L7_1.StringValue = L8_1
L8_1 = "カウンターのみなさん！　力を貸してください！"
L7_1.Text_JPN = L8_1
L8_1 = "Counters! Lend us your strength!"
L7_1.Text_ENG = L8_1
L8_1 = "各位制裁者！献出你们的力量吧！"
L7_1.Text_SCN = L8_1
L8_1 = "各位制裁者！想借助各位的力量！"
L7_1.Text_TWN = L8_1
L8_1 = "เคาน์เตอร์! มอบความแข็งแกร่งให้เราด้วย!"
L7_1.Text_THA = L8_1
L8_1 = "Các Counter! Hãy cho chúng tôi mượn sức mạnh!"
L7_1.Text_VTN = L8_1
L8_1 = "An alle Counter! Leihen Sie uns Ihre Kraft!"
L7_1.Text_DEU = L8_1
L8_1 = "Hé, les Counters ! Donnez-nous un coup de main !"
L7_1.Text_FRA = L8_1
