L14_1 = "GameEvent_3402116_1"
L13_1.GameEventStrID = L14_1
L13_1.ProcessKey = 1
L14_1 = 3402116
L13_1.EventID = L14_1
L13_1.EventType = "MESSAGE_BOX"
L14_1 = "<됐다! 추가 지원 병력이 도착했습니다!> - 2W, 대사 붙여넣기"
L13_1.Text_KOREA = L14_1
L13_1.Value = 2
L14_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_SHOTGUN"
L13_1.StringValue = L14_1
L14_1 = "<よし！　追加の応援兵力が到着した！> - 2W、セリフ貼り付け"
L13_1.Text_JPN = L14_1
L14_1 = "<Yes! Reinforcements have arrived!> - 2W, paste dialog"
L13_1.Text_ENG = L14_1
L14_1 = "<很好！支援兵力已经抵达！> - 2W，粘贴台词"
L13_1.Text_SCN = L14_1
L14_1 = "<終於！援兵抵達！> - 2W，貼上台詞"
L13_1.Text_TWN = L14_1
L14_1 = "<เยี่ยม! กำลังเสริมมาถึงแล้ว!> - 2W, วางบทสนทนา"
L13_1.Text_THA = L14_1
L14_1 = "<Tuyệt! Quân tiếp viện đã đến!> - 2W, dán hộp thoại"
L13_1.Text_VTN = L14_1
L14_1 = "<Geschafft! Die zusätzliche Verstärkung ist eingetroffen!> - 2W, Dialog einfügen"
L13_1.Text_DEU = L14_1
L14_1 = "<Ça y est ! Les renforts sont là !> - 2W, Copier le dialogue"
L13_1.Text_FRA = L14_1
L14_1 = {}
L15_1 = "GameEvent_3402116_2"
L14_1.GameEventStrID = L15_1
L14_1.ProcessKey = 2
L15_1 = 3402116
L14_1.EventID = L15_1
L14_1.EventType = "MESSAGE_BOX"
L15_1 = "<조금만 더 힘 내주시면 고지를 탈환할 수 있을겁니다.> - 2W, 대사 붙여넣기"
L14_1.Text_KOREA = L15_1
L14_1.Value = 2
L15_1 = "AB_INVEN_ICON_NKM_UNIT_S_SL_SHOTGUN"
L14_1.StringValue = L15_1
L15_1 = "<あと少し頑張れば高地を奪還できそうです。> - 2W、セリフ貼り付け"
L14_1.Text_JPN = L15_1
L15_1 = "<Just a little more and the high ground will be ours!> - 2W, paste dialog"
L14_1.Text_ENG = L15_1
L15_1 = "<只要再加把劲，就能夺回高地。> - 2W，粘贴台词"
L14_1.Text_SCN = L15_1
L15_1 = "<再加點油，我們一定可以奪回基地的！> - 2W，貼上台詞"
L14_1.Text_TWN = L15_1
L15_1 = "<อีกนิดเดียวชัยพื้นที่จะเป็นของเราแล้ว!> - 2W, วางบทสนทนา"
L14_1.Text_THA = L15_1
L15_1 = "<Chỉ một chút nữa thôi và vinh quang sẽ là của chúng ta!> - 2W, dán hộp thoại"
L14_1.Text_VTN = L15_1
L15_1 = "<Wenn Sie sich etwas mehr anstrengen, können Sie den Stützpunkt zurückerobern.> - 2W, Dialog einfügen"
L14_1.Text_DEU = L15_1
L15_1 = "<Encore un petit effort, et on pourra reprendre le point.> - 2W, Copier le dialogue"
L14_1.Text_FRA = L15_1
L15_1 = {}
L16_1 = "GameEvent_3402116_3"
L15_1.GameEventStrID = L16_1
L15_1.ProcessKey = 3
L16_1 = 3402116
L15_1.EventID = L16_1
L15_1.EventType = "MESSAGE_BOX"
L16_1 = "<크윽! 물러서지 마라! 긍지를 지켜라!> - 2W, 대사 붙여넣기"
L15_1.Text_KOREA = L16_1
L15_1.Value = 2
L16_1 = "AB_INVEN_ICON_NKM_MOB_BOSS_PALADIN"
L15_1.StringValue = L16_1
L16_1 = "<引き下がるな！　誇りを守れ！> - 2W、セリフ貼り付け"
L15_1.Text_JPN = L16_1
L16_1 = "<Kgh! Hold your ground! For honor!> - 2W, paste dialog"
L15_1.Text_ENG = L16_1
L16_1 = "<咳！别后退，为了荣誉而战！> - 2W，粘贴台词"
L15_1.Text_SCN = L16_1
L16_1 = "<唔！不准撤退！堅守榮耀！> - 2W，貼上台詞"
L15_1.Text_TWN = L16_1
L16_1 = "<อึก! หยัดยืนไว้! เพื่อเกียรติยศ!> - 2W, วางบทสนทนา"
L15_1.Text_THA = L16_1
L16_1 = "< Kgh! Giữ nguyên vị trí! Vì danh dự!> - 2W, dán hộp thoại"
L15_1.Text_VTN = L16_1
L16_1 = "<Urgh! Weicht nie zurück! Beschützt den Stolz!> - 2W, Dialog einfügen"
L15_1.Text_DEU = L16_1
L16_1 = "<Urgh ! Ne reculez pas, gardez vos positions !> - 2W, Copier le dialogue"
L15_1.Text_FRA = L16_1
