L18_1 = "GameEvent_3402117_1"
L17_1.GameEventStrID = L18_1
L17_1.ProcessKey = 1
L18_1 = 3402117
L17_1.EventID = L18_1
L17_1.EventType = "MESSAGE_BOX"
L18_1 = "제길! 당했군. 전군 퇴각! 전군 퇴각!"
L17_1.Text_KOREA = L18_1
L17_1.Value = 2
L18_1 = "AB_INVEN_ICON_NKM_MOB_BOSS_PALADIN"
L17_1.StringValue = L18_1
L18_1 = "クソ。やられたな。全軍、退却！　全軍、退却！"
L17_1.Text_JPN = L18_1
L18_1 = "Dammit! They got us! Men, fall back! Retreat!"
L17_1.Text_ENG = L18_1
L18_1 = "可恶！上当了。全军撤退！全军撤退！"
L17_1.Text_SCN = L18_1
L18_1 = "該死！糟糕，全軍撤退！全軍撤退！"
L17_1.Text_TWN = L18_1
L18_1 = "บ้าจริง! เราเสร็จพวกมันแล้ว! ทุกคน ถอย! ถอนกำลัง!"
L17_1.Text_THA = L18_1
L18_1 = "Chết tiệt! Chúng bắt được chúng ta rồi! Mọi người, lùi lại! Rút lui!"
L17_1.Text_VTN = L18_1
L18_1 = "Verdammt! Wir wurden getroffen. Rückzug! Rückzug!"
L17_1.Text_DEU = L18_1
L18_1 = "Merde, ils nous ont eu. À toutes les unités, repli immédiat !"
L17_1.Text_FRA = L18_1
L18_1 = {}
L19_1 = "GameEvent_3402117_2"
L18_1.GameEventStrID = L19_1
L18_1.ProcessKey = 2
L19_1 = 3402117
L18_1.EventID = L19_1
L18_1.EventType = "MESSAGE_BOX"
L19_1 = "다들 힘을 잃어버리기…… 곡꼬미 고꼭꼭 오고곡곡 오꼭꼭꼭시."
L18_1.Text_KOREA = L19_1
L18_1.Value = 2
L19_1 = "AB_INVEN_ICON_NKM_MOB_BOSS_PALADIN"
L18_1.StringValue = L19_1
L19_1 = "みんな力を失っ……ッコココオゴココゴコココ。"
L18_1.Text_JPN = L19_1
L19_1 = "We must retreat... bofaro wo woi wowi wowio."
L18_1.Text_ENG = L19_1
L19_1 = "大家都失去力量了……呃啊啊 哦啊啊 额呃额额 噶啊啊啊。"
L18_1.Text_SCN = L19_1
L19_1 = "留得青山在……不不不不不不不不，怕怕怕怕怕怕怕怕怕。"
L18_1.Text_TWN = L19_1
L19_1 = "เราต้องถอนกำลัง... กดาขดดา กยหา ห่หาหสา...!"
L18_1.Text_THA = L19_1
L19_1 = "Chúng ta phải rút lui... !"
L18_1.Text_VTN = L19_1
L19_1 = "Wir müssen uns zurückziehen ... bofaro wo woi wowi wowio."
L18_1.Text_DEU = L19_1
L19_1 = "Vite, avant qu'on soit à bout de forces...gzzt fzzzkg tsshcgz tspghnbfh"
L18_1.Text_FRA = L19_1
L19_1 = {}
