L32_1 = "GameEvent_3402303_1"
L31_1.GameEventStrID = L32_1
L31_1.ProcessKey = 1
L32_1 = 3402303
L31_1.EventID = L32_1
L31_1.EventType = "MESSAGE_BOX"
L32_1 = "으윽……! 이젠…… 이젠 무리야……"
L31_1.Text_KOREA = L32_1
L31_1.Value = 2
L32_1 = "AB_INVEN_ICON_NKM_UNIT_GAMECIRCLE_C_STAR"
L31_1.StringValue = L32_1
L32_1 = "ううっ……！　もう……もう無理だよ……"
L31_1.Text_JPN = L32_1
L32_1 = "Ngh...! I can't... hold them off much longer..."
L31_1.Text_ENG = L32_1
L32_1 = "呃呃……！再……再也坚持不下去了……"
L31_1.Text_SCN = L32_1
L32_1 = "呃……！完蛋……撐不住啦……"
L31_1.Text_TWN = L32_1
L32_1 = "อึก...! ต้านต่อไป... ไม่ไหวแล้วนิ..."
L31_1.Text_THA = L32_1
L32_1 = "Ngh...! Tôi không thể... cầm cự lâu hơn nữa..."
L31_1.Text_VTN = L32_1
L32_1 = "Urgh ...! Das wird jetzt aber ... zu anstrengend ..."
L31_1.Text_DEU = L32_1
L32_1 = "Urgh... ! Cette fois-ci.. c'est la fin..."
L31_1.Text_FRA = L32_1
