L40_1.EventID = L41_1
L40_1.EventType = "MESSAGE_BOX"
L41_1 = "적신인자를 견뎌내는 그릇이라.\n뜻밖에도 좋은 샘플을 찾았어."
L40_1.Text_KOREA = L41_1
L41_1 = 2.5
L40_1.Value = L41_1
L41_1 = "AB_INVEN_ICON_NKM_NPC_UNION_SCIENTIST"
L40_1.StringValue = L41_1
L41_1 = "クリムゾン・ファクターに耐えうる器か。\n思いがけずいいサンプルが見つかった。"
L40_1.Text_JPN = L41_1
L41_1 = [[
A vessel strong enough to endure the embedded factor? 
What an unexpected surprise.]]
L40_1.Text_ENG = L41_1
L41_1 = "承受适神因子的容器，\n没想到竟然找到了优秀的样本。"
L40_1.Text_SCN = L41_1
L41_1 = "可以承受適神因子的器皿嗎？\n找到預料之外的樣本呢。"
L40_1.Text_TWN = L41_1
L41_1 = "ร่างภาชนะที่แข็งแรงพอจะทนองค์ประกอบฝังได้อย่างนั้นเหรอ?\nเหนือความคาดหมายอยู่นะครับนี่"
L40_1.Text_THA = L41_1
L41_1 = "Một vật chứa đủ mạnh để chịu được nhân tố nhúng? \nQuả là bất ngờ ngoài sức tưởng tượng."
L40_1.Text_VTN = L41_1
L41_1 = "Ein Gefäß, das stark genug ist, um den eingebetteten Faktor zu ertragen?\nÜberraschenderweise habe ich eine gute Probe gefunden."
L40_1.Text_DEU = L41_1
L41_1 = "Un réceptacle assez puissant pour supporter le facteur intégré ?\nC'est inattendu."
L40_1.Text_FRA = L41_1
