L4_1 = 1012331
L3_1.EventID = L4_1
L3_1.EventType = "MESSAGE_BOX"
L4_1 = "세기말 결전병기\n여기 도착했다!"
L3_1.Text_KOREA = L4_1
L3_1.Value = 3
L4_1 = "AB_INVEN_ICON_NKM_UNIT_M_FUTURE_TITAN_RA"
L3_1.StringValue = L4_1
L4_1 = "世紀末決戦兵器\nここに参上！"
L3_1.Text_JPN = L4_1
L4_1 = [[
The ultimate doomsday weapon
has arrived!]]
L3_1.Text_ENG = L4_1
L4_1 = "世纪末决战兵器\n在此！"
L3_1.Text_SCN = L4_1
L4_1 = "世紀末決戰兵器\n在此！"
L3_1.Text_TWN = L4_1
L4_1 = "อาวุธสุดยอดแห่งวันโลกาวินาศ\nมาถึงแล้ว!"
L3_1.Text_THA = L4_1
L4_1 = "Vũ Khí Tận Thế Tối Thượng\nđã xuất hiện!"
L3_1.Text_VTN = L4_1
L4_1 = [[
Die Endzeit-Waffe
ist da!]]
L3_1.Text_DEU = L4_1
L4_1 = "L'arme ultime du Jugement dernier\nest arrivée !"
L3_1.Text_FRA = L4_1
