L5_1 = "GameEvent_6102011_1"
L4_1.GameEventStrID = L5_1
L4_1.ProcessKey = 1
L5_1 = 6102011
L4_1.EventID = L5_1
L4_1.EventType = "MESSAGE_BOX"
L5_1 = "당신의 취향에 솔직해지시죠!"
L4_1.Text_KOREA = L5_1
L4_1.Value = 2
L5_1 = "AB_INVEN_ICON_NKM_UNIT_PUPPET_C_WHIP_WEDDING"
L4_1.StringValue = L5_1
L5_1 = "あなたの好みに正直になってください！"
L4_1.Text_JPN = L5_1
L5_1 = "Be honest with what your tastes are!"
L4_1.Text_ENG = L5_1
L5_1 = "坦诚地面对你的喜好吧！"
L4_1.Text_SCN = L5_1
L5_1 = "坦誠面對你的喜好吧！"
L4_1.Text_TWN = L5_1
L5_1 = "รสนิยมของคุณอะไรที่เป็นการแสดงถึงความซื่อสตย์!"
L4_1.Text_THA = L5_1
L5_1 = "Hãy trung thực với sở thích của mình!"
L4_1.Text_VTN = L5_1
L5_1 = "Seien Sie ehrlich mit Ihrem Geschmack!"
L4_1.Text_DEU = L5_1
L5_1 = "Soyez sincères avec vos désirs !"
L4_1.Text_FRA = L5_1
