L6_1 = "GameEvent_6102011_2"
L5_1.GameEventStrID = L6_1
L5_1.ProcessKey = 2
L6_1 = 6102011
L5_1.EventID = L6_1
L5_1.EventType = "MESSAGE_BOX"
L6_1 = "이 이벤트를 어른의 이벤트로 만들 셈이야?"
L5_1.Text_KOREA = L6_1
L6_1 = 2.5
L5_1.Value = L6_1
L6_1 = "AB_INVEN_ICON_NKM_UNIT_C_STREGA_LAURA_WEDDING"
L5_1.StringValue = L6_1
L6_1 = "このイベントを大人限定のイベントにするつもりか？"
L5_1.Text_JPN = L6_1
L6_1 = "Stop making this an adults-only event!"
L5_1.Text_ENG = L6_1
L6_1 = "这可不是什么仅限成人活动！"
L5_1.Text_SCN = L6_1
L6_1 = "是想把這個活動變成十八禁嗎？"
L5_1.Text_TWN = L6_1
L6_1 = "โปรดหยุดคิดว่ากิจกรรมนี้จะเหมาะสมแค่ผู้ใหญ่เท่านั้น !"
L5_1.Text_THA = L6_1
L6_1 = "Đừng có làm sự kiện này thành thứ chỉ dành cho người lớn!"
L5_1.Text_VTN = L6_1
L6_1 = "Wirst du daraus eine Veranstaltung nur für Erwachsene machen?"
L5_1.Text_DEU = L6_1
L6_1 = "Ce n'est pas un évènement réservé aux adultes, ici !"
L5_1.Text_FRA = L6_1
L6_1 = {}
L7_1 = "GameEvent_6102011_3"
L6_1.GameEventStrID = L7_1
L6_1.ProcessKey = 3
L7_1 = 6102011
L6_1.EventID = L7_1
L6_1.EventType = "MESSAGE_BOX"
L7_1 = "우리 카페는 전연령이 함께 올 수 있는 곳이거든?!"
L6_1.Text_KOREA = L7_1
L7_1 = 2.5
L6_1.Value = L7_1
L7_1 = "AB_INVEN_ICON_NKM_UNIT_C_STREGA_LAURA_WEDDING"
L6_1.StringValue = L7_1
L7_1 = "うちのカフェは子どもから大人まで一緒に楽しめる店なんだぞ！？"
L6_1.Text_JPN = L7_1
L7_1 = "We welcome customers of all ages, okay?!"
L6_1.Text_ENG = L7_1
L7_1 = "我们咖啡店可是全年龄向的？！"
L6_1.Text_SCN = L7_1
L7_1 = "我們咖啡聽是老少咸宜的欸？！"
L6_1.Text_TWN = L7_1
L7_1 = "เรายินดีต้อนรับลูกค้าทุกเพศทุกวัย แบบนี้ดีไหมคะ?!"
L6_1.Text_THA = L7_1
L7_1 = "Chúng tôi chào đón khách hàng ở mọi lứa tuổi, được chứ?!"
L6_1.Text_VTN = L7_1
L7_1 = "Unser Café ist ein Ort, an dem wir Kunden jeden Alters willkommen heißen, okay?!"
L6_1.Text_DEU = L7_1
L7_1 = "Nous accueillons les clients de tous âges, d'accord ?!"
L6_1.Text_FRA = L7_1
