L9_1 = "GameEvent_6102021_2"
L8_1.GameEventStrID = L9_1
L8_1.ProcessKey = 2
L9_1 = 6102021
L8_1.EventID = L9_1
L8_1.EventType = "MESSAGE_BOX"
L9_1 = "화동들을 불러와야겠군요."
L8_1.Text_KOREA = L9_1
L8_1.Value = 2
L9_1 = "AB_INVEN_ICON_NKM_UNIT_HARMONY_CA_CONDUCT_WEDDING"
L8_1.StringValue = L9_1
L9_1 = "花撒きを呼んでこないといけませんね。"
L8_1.Text_JPN = L9_1
L9_1 = "Have the flower girls and boys enter."
L8_1.Text_ENG = L9_1
L9_1 = "花童们，来我身边。"
L8_1.Text_SCN = L9_1
L9_1 = "把花童們找來吧。"
L8_1.Text_TWN = L9_1
L9_1 = "ให้ดอกไม้แก่เด็กผู้หญิงและเด็กผู้ชายเพื่อให้พวกเขาเข้ามา"
L8_1.Text_THA = L9_1
L9_1 = "Hãy gọi các cô bé cậu bé thả hoa tiến vào."
L8_1.Text_VTN = L9_1
L9_1 = "Ich schätze, ich muss die Blumenmädchen rufen."
L8_1.Text_DEU = L9_1
L9_1 = "Faites appeler le garçon et la demoiselle d'honneur."
L8_1.Text_FRA = L9_1
L9_1 = {}
L10_1 = "GameEvent_6102021_3"
L9_1.GameEventStrID = L10_1
L9_1.ProcessKey = 3
L10_1 = 6102021
L9_1.EventID = L10_1
L9_1.EventType = "MESSAGE_BOX"
L10_1 = "하? 화동 뒤에 숨으려고?"
L9_1.Text_KOREA = L10_1
L9_1.Value = 2
L10_1 = "AB_INVEN_ICON_NKM_UNIT_C_STREGA_LAURA_WEDDING"
L9_1.StringValue = L10_1
L10_1 = "は？　その後ろに隠れるつもりか？"
L9_1.Text_JPN = L10_1
L10_1 = "Huh? Are you going to hide behind them?"
L9_1.Text_ENG = L10_1
L10_1 = "哼？你还想藏在花童后面？"
L9_1.Text_SCN = L10_1
L10_1 = "蛤？是想躲在花童後面嗎？"
L9_1.Text_TWN = L10_1
L10_1 = "ฮะ? คุณไปหลบซ่อนอยู่ข้างหลังพวกเขาเองเหรอ?"
L9_1.Text_THA = L10_1
L10_1 = "Hả? Bạn muốn trốn đằng sau chúng sao?"
L9_1.Text_VTN = L10_1
L10_1 = "Hä? Willst du dich hinter ihnen verstecken?"
L9_1.Text_DEU = L10_1
L10_1 = "Pourquoi ? Tu veux te cacher derrière eux ?"
L9_1.Text_FRA = L10_1
L10_1 = {}
L11_1 = "GameEvent_6102021_4"
L10_1.GameEventStrID = L11_1
L10_1.ProcessKey = 4
L11_1 = 6102021
L10_1.EventID = L11_1
L10_1.EventType = "MESSAGE_BOX"
L11_1 = "화동이든 뭐든 얼마든지 상대해 주겠어!"
L10_1.Text_KOREA = L11_1
L11_1 = 2.5
L10_1.Value = L11_1
L11_1 = "AB_INVEN_ICON_NKM_UNIT_C_STREGA_LAURA_WEDDING"
L10_1.StringValue = L11_1
L11_1 = "花撒きでもなんでもいい、相手してやる！"
L10_1.Text_JPN = L11_1
L11_1 = "I'll fight whoever you bring out!"
L10_1.Text_ENG = L11_1
L11_1 = "管他是花童还是什么，都给我消失！"
L10_1.Text_SCN = L11_1
L11_1 = "管他是花童還是什麼的，我都不放過！"
L10_1.Text_TWN = L11_1
L11_1 = "ฉันจะสู้กับทุกๆคนที่คุณส่งมา!"
L10_1.Text_THA = L11_1
L11_1 = "Tôi sẽ đấu với bất cứ ai được cử ra!"
L10_1.Text_VTN = L11_1
L11_1 = "Ich werde kämpfen, egal ob gegen die Blumenmädchen oder wen auch immer!"
L10_1.Text_DEU = L11_1
L11_1 = "Je combattrai quiconque se mettra sur mon chemin, demoiselle d'honneur ou non !"
L10_1.Text_FRA = L11_1
