L13_1 = "GameEvent_6104022_1"
L12_1.GameEventStrID = L13_1
L12_1.ProcessKey = 1
L13_1 = 6104022
L12_1.EventID = L13_1
L12_1.EventType = "MESSAGE_BOX"
L13_1 = "뭐야.\n나랑 장난치는거야?"
L12_1.Text_KOREA = L13_1
L13_1 = 2.5
L12_1.Value = L13_1
L13_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L12_1.StringValue = L13_1
L13_1 = "何。\nからかってるの？"
L12_1.Text_JPN = L13_1
L13_1 = [[
Huh?
Are you kidding me?]]
L12_1.Text_ENG = L13_1
L13_1 = "什么啊。\n你在和我开玩笑吗？"
L12_1.Text_SCN = L13_1
L13_1 = "搞什麼？\n現在是在跟我開玩笑嗎？"
L12_1.Text_TWN = L13_1
L13_1 = "หืม?\nคุณล้อกันเล่นรึไงนี่?"
L12_1.Text_THA = L13_1
L13_1 = "Hả?\nCô đang đùa với tôi à?"
L12_1.Text_VTN = L13_1
L13_1 = "Was hast du gesagt?\nWillst du mich veräppeln?"
L12_1.Text_DEU = L13_1
L13_1 = [[
Quoi ?
Tu te fiches de moi ?]]
L12_1.Text_FRA = L13_1
