L14_1 = "GameEvent_6104023_1"
L13_1.GameEventStrID = L14_1
L13_1.ProcessKey = 1
L14_1 = 6104023
L13_1.EventID = L14_1
L13_1.EventType = "MESSAGE_BOX"
L14_1 = "됐어.\n충분한 것 같으니 끝내도록 하자."
L13_1.Text_KOREA = L14_1
L14_1 = 2.5
L13_1.Value = L14_1
L14_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L13_1.StringValue = L14_1
L14_1 = "もういい。\n十分だから終わりにしよう。"
L13_1.Text_JPN = L14_1
L14_1 = [[
I've seen enough.
Let's end the interview here.]]
L13_1.Text_ENG = L14_1
L14_1 = "行了。\n已经够了，到此为止吧。"
L13_1.Text_SCN = L14_1
L14_1 = "就這樣吧。\n我沒其他問題，面試結束。"
L13_1.Text_TWN = L14_1
L14_1 = "พอได้แล้ว\nมาจบสัมภาษณ์กันที่นี่เลย"
L13_1.Text_THA = L14_1
L14_1 = "Tôi xem xong rồi.\nPhỏng vấn đến đây thôi."
L13_1.Text_VTN = L14_1
L14_1 = "Schon gut.\nIch habe genug gehört. Wir können das Gespräch hier beenden."
L13_1.Text_DEU = L14_1
L14_1 = [[
C'est bon.
J'en ai suffisamment entendu.]]
L13_1.Text_FRA = L14_1
