L30_1 = "GameEvent_1113412_1"
L29_1.GameEventStrID = L30_1
L29_1.ProcessKey = 1
L30_1 = 1113412
L29_1.EventID = L30_1
L29_1.EventType = "MESSAGE_BOX"
L30_1 = "갑주에 의지하는 몸도 한계에 다다랐구나."
L29_1.Text_KOREA = L30_1
L30_1 = 2.5
L29_1.Value = L30_1
L30_1 = "AB_INVEN_ICON_NKM_UNIT_CORRUPTED_M_ARMOR"
L29_1.StringValue = L30_1
L30_1 = "鎧に頼っていた体にも限界が来たのか。"
L29_1.Text_JPN = L30_1
L30_1 = "The armor-dependent body is at its limits."
L29_1.Text_ENG = L30_1
L30_1 = "依靠盔甲的这副身体也已经到达极限了。"
L29_1.Text_SCN = L30_1
L30_1 = "看來倚靠盔甲的身軀也已經到達極限。"
L29_1.Text_TWN = L30_1
L30_1 = "ร่างกายที่ต้องอาศัยเกราะมีขีดจำกัดแล้ว"
L29_1.Text_THA = L30_1
L30_1 = "Cơ thể phụ thuộc vào áo giáp đã đến giới hạn của nó."
L29_1.Text_VTN = L30_1
L30_1 = "Dieser panzerabhängige Körper stößt an seine Grenzen."
L29_1.Text_DEU = L30_1
L30_1 = "Ce corps dépendant de l’armure a atteint ses limites."
L29_1.Text_FRA = L30_1
L30_1 = {}
L31_1 = "GameEvent_1113412_2"
L30_1.GameEventStrID = L31_1
L30_1.ProcessKey = 1
L31_1 = 1113412
L30_1.EventID = L31_1
L30_1.EventType = "MESSAGE_BOX"
L31_1 = "허나 믿는 이들이 있는 한…"
L30_1.Text_KOREA = L31_1
L31_1 = 2.5
L30_1.Value = L31_1
L31_1 = "AB_INVEN_ICON_NKM_UNIT_CORRUPTED_M_ARMOR"
L30_1.StringValue = L31_1
L31_1 = "だが、信じる者たちがいる限り……"
L30_1.Text_JPN = L31_1
L31_1 = "But as long as there are people who have faith in me..."
L30_1.Text_ENG = L31_1
L31_1 = "但只要有信徒……"
L30_1.Text_SCN = L31_1
L31_1 = "但只要有相信的人存在…"
L30_1.Text_TWN = L31_1
L31_1 = "แต่ตราบใดที่ยังมีคนที่ศรัทธาในตัวฉัน..."
L30_1.Text_THA = L31_1
L31_1 = "Nhưng chỉ cần có người tin tưởng tôi..."
L30_1.Text_VTN = L31_1
L31_1 = "Aber solange es Menschen gibt, die an mich glauben ..."
L30_1.Text_DEU = L31_1
L31_1 = "Mais tant qu'il y aura des gens qui auront confiance en moi..."
L30_1.Text_FRA = L31_1
L31_1 = {}
L32_1 = "GameEvent_1113412_3"
L31_1.GameEventStrID = L32_1
L31_1.ProcessKey = 1
L32_1 = 1113412
L31_1.EventID = L32_1
L31_1.EventType = "MESSAGE_BOX"
L32_1 = "나는 몇 번이고 다시 일어서리라."
L31_1.Text_KOREA = L32_1
L32_1 = 2.5
L31_1.Value = L32_1
L32_1 = "AB_INVEN_ICON_NKM_UNIT_CORRUPTED_M_ARMOR"
L31_1.StringValue = L32_1
L32_1 = "我は何度でも立ち上がろう。"
L31_1.Text_JPN = L32_1
L32_1 = "I will rise to my feet time and time again."
L31_1.Text_ENG = L32_1
L32_1 = "我会一次又一次地站起来。"
L31_1.Text_SCN = L32_1
L32_1 = "我就會不斷地東山再起。"
L31_1.Text_TWN = L32_1
L32_1 = "ฉันจะยืนขึ้นอีกครั้งแล้วครั้งเล่า"
L31_1.Text_THA = L32_1
L32_1 = "Tôi sẽ đứng dậy hết lần này đến lần khác."
L31_1.Text_VTN = L32_1
L32_1 = "werde ich immer wieder aufstehen."
L31_1.Text_DEU = L32_1
L32_1 = "Je me lèverai encore et encore."
L31_1.Text_FRA = L32_1
