L39_1.EventType = "MESSAGE_BOX"
L40_1 = "호수의 기사가 침식한 영역에서 벗어나도록 하세요!"
L39_1.Text_KOREA = L40_1
L40_1 = 2.5
L39_1.Value = L40_1
