L39_1.StringValue = L40_1
L40_1 = "湖の騎士が侵食した領域から退避してください！"
L39_1.Text_JPN = L40_1
L40_1 = "Evacuate the Corrupted area created by the Knight of the Lake!"
L39_1.Text_ENG = L40_1
L40_1 = "请撤离湖之骑士的侵蚀领域！"
L39_1.Text_SCN = L40_1
