L44_1.EventType = "MESSAGE_BOX"
L45_1 = "뭐지…? 아직 살아있다고?"
L44_1.Text_KOREA = L45_1
L45_1 = 2.5
L44_1.Value = L45_1
L45_1 = "AB_INVEN_ICON_NKM_MONSTER_BOSS_TOUGH_MINISTRA"
L44_1.StringValue = L45_1
L45_1 = "何だ……？　まだ生きているだと？"
