L14_1 = 2.5
L13_1.Value = L14_1
L14_1 = "AB_INVEN_ICON_NKM_UNIT_SIXWING_CA_ACTOR"
L13_1.StringValue = L14_1
L14_1 = "あなたを見ている観客は、いったいどんな顔なのでしょうか。"
L13_1.Text_JPN = L14_1
L14_1 = "What expression will the audiences' faces make when they see you?"
L13_1.Text_ENG = L14_1
L14_1 = "那个看着你的观众会有什么表情呢？"
L13_1.Text_SCN = L14_1
L14_1 = "那個看著你的觀眾會有什麼表情呢？"
L13_1.Text_TWN = L14_1
L14_1 = "What expression will the audiences' faces make when they see you?"
L13_1.Text_DEU = L14_1
L14_1 = "What expression will the audiences' faces make when they see you?"
L13_1.Text_FRA = L14_1
