L14_1.Value = L15_1
L15_1 = "AB_INVEN_ICON_NKM_UNIT_C_YOO_MI_NA"
L14_1.StringValue = L15_1
L15_1 = "笑ってるんじゃない？　社長の計画は失敗したことがないんだから。"
L14_1.Text_JPN = L15_1
L15_1 = "I think they'll laugh. Boss's plans never fail, you know."
L14_1.Text_ENG = L15_1
L15_1 = "你是在嘲笑吗？老板的计划从来没有失败过。"
L14_1.Text_SCN = L15_1
L15_1 = "你是在嘲笑嗎？老闆的計畫從來沒有失敗過。"
L14_1.Text_TWN = L15_1
L15_1 = "I think they'll laugh. Boss's plans never fail, you know."
L14_1.Text_DEU = L15_1
L15_1 = "I think they'll laugh. Boss's plans never fail, you know."
L14_1.Text_FRA = L15_1
